    /**
     * Verify nonce and login
     */
    private function verify_request($require_login = true)
    {
        if (!check_ajax_referer('sffc_crm_nonce', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid security token'], 403);
        }

        if ($require_login && !is_user_logged_in()) {
            wp_send_json_error(['message' => 'Please log in'], 401);
        }

        return get_current_user_id();
    }

    /**
     * Force schema update - adds missing columns
     */
    public function force_schema_update()
    {
        // Only allow admins
        if (!current_user_can('manage_options')) {
            wp_send_json_error(['message' => 'Admin access required'], 403);
        }

        $db = SFFC_CRM_Database_Schema::get_instance();
        $result = $db->force_schema_update();

        if ($result) {
            wp_send_json_success(['message' => 'Database schema updated successfully']);
        } else {
            wp_send_json_error(['message' => 'Schema update failed']);
        }
    }

    /**
     * Clean up duplicate system templates
     */
    public function cleanup_duplicate_templates()
    {
        // Only allow admins
        if (!current_user_can('manage_options')) {
            wp_send_json_error(['message' => 'Admin access required'], 403);
        }

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_templates';

        // Find and keep only the first (lowest ID) of each system template by name
        $duplicates_removed = $wpdb->query("
            DELETE t1 FROM $table t1
            INNER JOIN $table t2
            WHERE t1.is_system = 1
              AND t2.is_system = 1
              AND t1.name = t2.name
              AND t1.id > t2.id
        ");

        if ($duplicates_removed === false) {
            wp_send_json_error(['message' => 'Failed to remove duplicates: ' . $wpdb->last_error]);
        }

        wp_send_json_success([
            'message' => "Removed $duplicates_removed duplicate system templates",
            'removed' => $duplicates_removed
        ]);
    }

    /**
     * Bulk extract requirements for all existing job posts
     * Admin-only utility to populate nationality requirements and other structured data
     */
    public function bulk_extract_requirements()
    {
        // Only allow admins
        if (!current_user_can('manage_options')) {
            wp_send_json_error(['message' => 'Admin access required'], 403);
        }

        $limit = isset($_POST['limit']) ? intval($_POST['limit']) : 50;
        $offset = isset($_POST['offset']) ? intval($_POST['offset']) : 0;

        if (!class_exists('SFFC_Requirements_Extractor')) {
            wp_send_json_error(['message' => 'Requirements extractor class not found']);
        }

        $extractor = new SFFC_Requirements_Extractor();
        $results = $extractor->bulk_extract_requirements($limit, $offset);

        wp_send_json_success([
            'message' => sprintf(
                'Processed %d posts. Updated: %d, Skipped: %d, Nationality requirements found: %d',
                $results['processed'],
                $results['updated'],
                $results['skipped'],
                $results['nationality_found']
            ),
            'results' => $results
        ]);
    }

    /**
     * Get feed posts
     */
    public function get_feed()
    {
        $user_id = is_user_logged_in() ? get_current_user_id() : 0;

        $post_model = new SFFC_CRM_Post();

        $args = [
            'page' => intval($_POST['page'] ?? 1),
            'per_page' => intval($_POST['per_page'] ?? 20),
            'sector' => sanitize_text_field($_POST['sector'] ?? ''),
            'seniority' => sanitize_text_field($_POST['seniority'] ?? ''),
            'location' => sanitize_text_field($_POST['location'] ?? ''),
            'search' => sanitize_text_field($_POST['search'] ?? ''),
            'user_id' => $user_id,
        ];

        $posts = $post_model->get_feed($args);
        $total = $post_model->get_feed_count($args);

        $has_more = ($args['page'] * $args['per_page']) < $total;

        wp_send_json_success([
            'posts' => $posts,
            'total' => $total,
            'page' => $args['page'],
            'total_pages' => ceil($total / $args['per_page']),
            'has_more' => $has_more,
        ]);
    }

    /**
     * Load posts for a specific group (returns HTML)
     */
    public function load_group_posts()
    {
        // Verify nonce
        $nonce = $_POST['nonce'] ?? '';
        if (!$nonce || !wp_verify_nonce($nonce, 'sffc_crm_nonce')) {
            wp_send_json_error(['message' => 'Invalid nonce'], 403);
        }

        $group_slug = sanitize_text_field($_POST['group_slug'] ?? '');
        $per_page = intval($_POST['per_page'] ?? 50);
        $location_filter = sanitize_text_field($_POST['location'] ?? '');
        $keywords_filter = sanitize_text_field($_POST['keywords'] ?? '');
        $start_date_filter = sanitize_text_field($_POST['start_date'] ?? '');
        $duration_filter = sanitize_text_field($_POST['duration'] ?? '');

        $start_date_value = null;
        if (!empty($start_date_filter)) {
            $dt = date_create($start_date_filter);
            if ($dt) {
                $start_date_value = $dt->format('Y-m-d');
            }
        }

        $user_id = is_user_logged_in() ? get_current_user_id() : 0;

        // Load the post model
        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php';
        $post_model = new SFFC_CRM_Post();

        $duration_months = null;
        if ($duration_filter !== '') {
            $duration_months = SFFC_CRM_Post::parse_duration_input($duration_filter);
        }

        $common_args = [
            'per_page' => $per_page,
            'user_id' => $user_id,
        ];

        if ($location_filter) {
            $common_args['location'] = $location_filter;
        }

        if ($keywords_filter) {
            $common_args['keywords'] = $keywords_filter;
        }

        if ($start_date_value) {
            $common_args['start_date'] = $start_date_value;
        }

        if ($duration_months !== null) {
            $common_args['duration_months'] = $duration_months;
        }

        if ($group_slug) {
            $posts = $post_model->get_feed_by_groups($group_slug, $common_args);
        } else {
            $common_args['page'] = 1;
            $posts = $post_model->get_feed($common_args);
        }

        if (empty($posts)) {
            wp_send_json_success([
                'html' => '<div class="sffc-crm-linkedin-empty" style="padding: 40px; text-align: center; color: #666;"><p>No posts found in this group.</p></div>',
                'count' => 0
            ]);
            return;
        }

        // Get shortcode instance to render the cards
        require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-shortcodes.php';
        $shortcodes = SFFC_CRM_Shortcodes::get_instance();

        // Render the feed cards HTML
        ob_start();
        $shortcodes->render_feed_cards_html($posts, $user_id);
        $html = ob_get_clean();

        wp_send_json_success([
            'html' => $html,
            'count' => count($posts)
        ]);
    }

