    /**
     * Toggle jobs mailbox pin
     */
    public function toggle_mailbox_pin()
    {
        $user_id = $this->verify_request();
        $mailbox_key = sanitize_key((string) ($_POST['mailbox_key'] ?? ''));
        $crm_post_id = absint($_POST['crm_post_id'] ?? 0);
        $jobs_post_id = absint($_POST['jobs_post_id'] ?? 0);
        $wp_post_id = absint($_POST['wp_post_id'] ?? 0);
        $role_title = sanitize_text_field((string) ($_POST['role_title'] ?? ''));
        $company = sanitize_text_field((string) ($_POST['company'] ?? ''));
        $location = sanitize_text_field((string) ($_POST['location'] ?? ''));

        if ($mailbox_key === '') {
            wp_send_json_error(['message' => 'Mailbox key required'], 400);
        }

        if (class_exists('SFFC_CRM_Database_Schema')) {
            SFFC_CRM_Database_Schema::get_instance()->create_mailbox_pins_table();
        }

        global $wpdb;
        $table = $this->get_mailbox_pins_table_name();
        $existing_id = (int) $wpdb->get_var(
            $wpdb->prepare(
                "SELECT id FROM {$table} WHERE user_id = %d AND mailbox_key = %s LIMIT 1",
                $user_id,
                $mailbox_key
            )
        );

        if ($existing_id > 0) {
            $wpdb->delete(
                $table,
                [
                    'id' => $existing_id,
                    'user_id' => $user_id,
                ],
                ['%d', '%d']
            );

            wp_send_json_success([
                'pinned' => false,
                'pinnedKeys' => $this->get_user_mailbox_pinned_keys($user_id),
            ]);
        }

        $metadata = wp_json_encode([
            'source' => 'cv_match_studio',
        ]);

        $result = $wpdb->replace(
            $table,
            [
                'user_id' => $user_id,
                'mailbox_key' => $mailbox_key,
                'crm_post_id' => $crm_post_id > 0 ? $crm_post_id : null,
                'jobs_post_id' => $jobs_post_id > 0 ? $jobs_post_id : null,
                'wp_post_id' => $wp_post_id > 0 ? $wp_post_id : null,
                'role_title' => $role_title,
                'company' => $company,
                'location' => $location,
                'metadata' => $metadata,
            ],
            ['%d', '%s', '%d', '%d', '%d', '%s', '%s', '%s', '%s']
        );

        if (false === $result) {
            wp_send_json_error(['message' => 'Unable to save pinned role'], 500);
        }

        wp_send_json_success([
            'pinned' => true,
            'pinnedKeys' => $this->get_user_mailbox_pinned_keys($user_id),
        ]);
    }

    private function get_mailbox_pins_table_name()
    {
        global $wpdb;

        return $wpdb->prefix . 'sffc_crm_mailbox_pins';
    }

    private function get_user_mailbox_pinned_keys($user_id)
    {
        global $wpdb;

        $user_id = (int) $user_id;
        if ($user_id <= 0) {
            return [];
        }

        $table = $this->get_mailbox_pins_table_name();
        $table_exists = (string) $wpdb->get_var(
            $wpdb->prepare('SHOW TABLES LIKE %s', $table)
        );
        if ($table_exists !== $table) {
            return [];
        }

        $keys = $wpdb->get_col(
            $wpdb->prepare(
                "SELECT mailbox_key FROM {$table} WHERE user_id = %d ORDER BY created_at DESC, id DESC",
                $user_id
            )
        );

        if (empty($keys) || !is_array($keys)) {
            return [];
        }

        return array_values(
            array_filter(
                array_map(
                    static function ($key) {
                        return sanitize_key((string) $key);
                    },
                    $keys
                )
            )
        );
    }

