    /**
     * Get live openings for a specific recruiter
     */
    public function get_recruiter_openings()
    {
        $user_id = $this->verify_request();
        $recruiter_id = intval($_POST['recruiter_id'] ?? 0);

        if (!$recruiter_id) {
            wp_send_json_error(['message' => 'Recruiter ID required'], 400);
        }

        $page = max(1, intval($_POST['page'] ?? 1));
        $per_page = intval($_POST['per_page'] ?? 10);
        if ($per_page < 5) {
            $per_page = 5;
        } elseif ($per_page > 25) {
            $per_page = 25;
        }

        $post_model = new SFFC_CRM_Post();
        $posts = $post_model->get_feed([
            'page' => $page,
            'per_page' => $per_page,
            'recruiter_id' => $recruiter_id,
            'approved_only' => true,
            'user_id' => $user_id,
        ]);

        $total = $post_model->get_feed_count([
            'recruiter_id' => $recruiter_id,
            'approved_only' => true,
        ]);

        $formatted_posts = [];
        if (!empty($posts)) {
            foreach ($posts as $post) {
                $snippet = $post['content_snippet'] ?? '';
                if (empty($snippet) && !empty($post['content'])) {
                    $snippet = wp_trim_words(wp_strip_all_tags($post['content']), 40, '...');
                }

                $permalink = $this->resolve_recommended_post_public_permalink($post);

                $formatted_posts[] = [
                    'id' => (int) $post['id'],
                    'role_title' => $post['role_title'] ?? '',
                    'company' => $post['company'] ?? '',
                    'location' => $post['location'] ?? '',
                    'sector' => $post['sector'] ?? '',
                    'seniority' => $post['seniority'] ?? '',
                    'salary_text' => $post['salary_text'] ?? '',
                    'posted_at' => $post['posted_at'] ?? '',
                    'snippet' => $snippet,
                    'application_url' => !empty($post['application_url']) ? esc_url_raw($post['application_url']) : '',
                    'source_url' => !empty($post['source_url']) ? esc_url_raw($post['source_url']) : '',
                    'permalink' => $permalink,
                    'match_score' => isset($post['match_score']) ? (int) $post['match_score'] : 0,
                    'is_saved' => !empty($post['is_saved']),
                    'is_early_bird' => isset($post['is_early_bird']) ? (int) $post['is_early_bird'] === 1 : false,
                    'recruiter_id' => (int) $post['recruiter_id'],
                    'recruiter_email' => $post['recruiter_email'] ?? '',
                    'recruiter_linkedin' => !empty($post['recruiter_linkedin']) ? esc_url_raw($post['recruiter_linkedin']) : '',
                    'recruiter_photo' => !empty($post['recruiter_photo']) ? esc_url_raw($post['recruiter_photo']) : '',
                    'recruiter_title' => $post['recruiter_title'] ?? '',
                    'recruiter_firm' => $post['recruiter_firm'] ?? '',
                ];
            }
        }

        $recruiter_model = new SFFC_CRM_Recruiter();
        $recruiter = $recruiter_model->get($recruiter_id);
        $recruiter_data = null;
        if ($recruiter) {
            $recruiter_data = [
                'id' => (int) $recruiter['id'],
                'name' => $recruiter['name'] ?? '',
                'firm' => $recruiter['firm'] ?? '',
                'title' => $recruiter['title'] ?? '',
                'email' => $recruiter['email'] ?? '',
                'linkedin_url' => $recruiter['linkedin_url'] ?? '',
                'photo_url' => $recruiter['photo_url'] ?? '',
            ];
        }

        wp_send_json_success([
            'page' => $page,
            'per_page' => $per_page,
            'total' => (int) $total,
            'has_more' => ($page * $per_page) < $total,
            'posts' => $formatted_posts,
            'recruiter' => $recruiter_data,
        ]);
    }

    /**
     * Save recruiter
     */
    public function save_recruiter()
    {
        $user_id = $this->verify_request();
        $recruiter_id = intval($_POST['recruiter_id'] ?? 0);

        if (!$recruiter_id) {
            wp_send_json_error(['message' => 'Recruiter ID required'], 400);
        }

        // Rate limiting
        $rate_limiter = SFFC_CRM_Rate_Limiter::get_instance();
        $check = $rate_limiter->throttle('save_recruiter', $user_id);
        if (is_wp_error($check)) {
            wp_send_json_error([
                'message' => $check->get_error_message(),
                'retry_after' => $check->get_error_data()['retry_after'] ?? 60,
            ], 429);
        }

        // Check limits
        $mepr = SFFC_CRM_MemberPress_Integration::get_instance();
        if (!$mepr->can_perform_action($user_id, 'save_recruiter')) {
            $prompt = $mepr->get_upgrade_prompt($user_id, 'recruiter_limit');
            wp_send_json_error([
                'message' => $prompt['message'],
                'upgrade_prompt' => $prompt,
            ], 403);
        }

        $recruiter_model = new SFFC_CRM_Recruiter();
        $result = $recruiter_model->save_recruiter($user_id, $recruiter_id);

        if (is_wp_error($result)) {
            wp_send_json_error(['message' => $result->get_error_message()], 400);
        }

        wp_send_json_success(['message' => 'Recruiter saved']);
    }

    /**
     * Unsave recruiter
     */
    public function unsave_recruiter()
    {
        $user_id = $this->verify_request();
        $recruiter_id = intval($_POST['recruiter_id'] ?? 0);

        if (!$recruiter_id) {
            wp_send_json_error(['message' => 'Recruiter ID required'], 400);
        }

        $recruiter_model = new SFFC_CRM_Recruiter();
        $recruiter_model->unsave_recruiter($user_id, $recruiter_id);

        wp_send_json_success(['message' => 'Recruiter removed']);
    }

    /**
     * Add recruiter to outreach list from post article page
     * This handles recruiters that may not exist in CRM yet
     */
    public function add_to_outreach_list()
    {
        $user_id = $this->verify_request();

        // Get recruiter data from request
        $recruiter_name = sanitize_text_field($_POST['recruiter_name'] ?? '');
        $recruiter_company = sanitize_text_field($_POST['recruiter_company'] ?? '');
        $recruiter_email = sanitize_email($_POST['recruiter_email'] ?? '');
        $post_id = intval($_POST['post_id'] ?? 0);
        $job_title = sanitize_text_field($_POST['job_title'] ?? '');

        if (!$recruiter_email && !$recruiter_name) {
            wp_send_json_error(['message' => 'Recruiter information required'], 400);
        }

        $recruiter_model = new SFFC_CRM_Recruiter();

        // Check if recruiter exists by email
        $recruiter_id = 0;
        if ($recruiter_email) {
            $existing = $recruiter_model->find_by_email($recruiter_email);
            if ($existing) {
                $recruiter_id = $existing['id'];
            }
        }

        // If recruiter doesn't exist, create them
        if (!$recruiter_id) {
            $recruiter_id = $recruiter_model->create([
                'name' => $recruiter_name,
                'email' => $recruiter_email,
                'firm' => $recruiter_company,
                'source' => 'post_article',
                'source_post_id' => $post_id,
            ]);
        }

        if (!$recruiter_id) {
            wp_send_json_error(['message' => 'Failed to create recruiter'], 500);
        }

        // Save recruiter to user's list
        $result = $recruiter_model->save_recruiter($user_id, $recruiter_id);

        // Optionally add to pipeline as "interested"
        if ($result && $post_id) {
            $pipeline_model = new SFFC_CRM_Pipeline();
            $pipeline_model->add_to_pipeline($user_id, [
                'recruiter_id' => $recruiter_id,
                'post_id' => $post_id,
                'stage' => 'not_applied',
                'notes' => 'Added from: ' . $job_title,
            ]);
        }

        wp_send_json_success([
            'message' => 'Added to outreach list',
            'recruiter_id' => $recruiter_id,
        ]);
    }

    /**
     * Remove recruiter from outreach list
     */
    public function remove_from_outreach_list()
    {
        $user_id = $this->verify_request();

        $recruiter_email = sanitize_email($_POST['recruiter_email'] ?? '');
        $post_id = intval($_POST['post_id'] ?? 0);

        if (!$recruiter_email && !$post_id) {
            wp_send_json_error(['message' => 'Recruiter information required'], 400);
        }

        $recruiter_model = new SFFC_CRM_Recruiter();

        // Find recruiter by email
        $recruiter_id = 0;
        if ($recruiter_email) {
            $existing = $recruiter_model->find_by_email($recruiter_email);
            if ($existing) {
                $recruiter_id = $existing['id'];
            }
        }

        if ($recruiter_id) {
            // Unsave the recruiter
            $recruiter_model->unsave_recruiter($user_id, $recruiter_id);

            // Remove from pipeline if exists
            if ($post_id) {
                $pipeline_model = new SFFC_CRM_Pipeline();
                $pipeline_model->remove_from_pipeline($user_id, $recruiter_id, $post_id);
            }
        }

        wp_send_json_success(['message' => 'Removed from outreach list']);
    }

