    /**
     * Add to pipeline
     */
    public function add_to_pipeline()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $data = [
            'recruiter_id' => intval($_POST['recruiter_id'] ?? 0),
            'post_id' => intval($_POST['post_id'] ?? 0) ?: null,
            'wp_post_id' => intval($_POST['wp_post_id'] ?? 0) ?: null,
            'stage' => sanitize_text_field($_POST['stage'] ?? 'interested'),
            'role_title' => sanitize_text_field($_POST['role_title'] ?? ''),
            'company' => sanitize_text_field($_POST['company'] ?? ''),
            'location' => sanitize_text_field($_POST['location'] ?? ''),
            'external_url' => esc_url_raw($_POST['external_url'] ?? ''),
        ];

        if (empty($data['post_id']) && !empty($data['wp_post_id'])) {
            $linked_crm_post_id = (int) get_post_meta($data['wp_post_id'], '_crm_post_id', true);
            if ($linked_crm_post_id > 0) {
                $data['post_id'] = $linked_crm_post_id;
            }
        }

        if (!$data['recruiter_id'] && !$data['post_id'] && (empty($data['role_title']) || empty($data['company']))) {
            wp_send_json_error(['message' => 'Recruiter, role, or post data required'], 400);
        }

        if (!$data['recruiter_id'] && !empty($data['post_id'])) {
            $data['source'] = 'platform';
        }

        $pipeline_model = new SFFC_CRM_Pipeline();
        $result = $pipeline_model->add_to_pipeline($user_id, $data);

        if (is_wp_error($result)) {
            $mepr = SFFC_CRM_MemberPress_Integration::get_instance();
            if ($result->get_error_code() === 'stage_not_allowed') {
                $prompt = $mepr->get_upgrade_prompt($user_id, 'pipeline_stages');
                wp_send_json_error([
                    'message' => $result->get_error_message(),
                    'upgrade_prompt' => $prompt,
                ], 403);
            }
            wp_send_json_error(['message' => $result->get_error_message()], 400);
        }

        if (!$result) {
            $message = !empty($wpdb->last_error)
                ? sprintf('Unable to add this role to tracking: %s', $wpdb->last_error)
                : 'Unable to add this role to tracking right now.';
            wp_send_json_error(['message' => $message], 500);
        }

        $stages = class_exists('SFFC_CRM_Pipeline') ? SFFC_CRM_Pipeline::get_stages() : [];
        $stage_meta = isset($stages[$data['stage']]) && is_array($stages[$data['stage']]) ? $stages[$data['stage']] : [];

        wp_send_json_success([
            'message' => 'Added to pipeline',
            'pipeline_id' => $result,
            'stage' => $data['stage'],
            'stage_label' => (string) ($stage_meta['label'] ?? $data['stage']),
            'stage_color' => (string) ($stage_meta['color'] ?? '#0d353e'),
        ]);
    }

    public function save_dashboard_tracking_status()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $pipeline_model = new SFFC_CRM_Pipeline();
        $pipeline_table = $wpdb->prefix . 'sffc_crm_pipeline';
        $stages = SFFC_CRM_Pipeline::get_stages();

        $stage = sanitize_text_field($_POST['stage'] ?? '');
        if ($stage === '' || !isset($stages[$stage])) {
            wp_send_json_error(['message' => 'Valid tracking stage required'], 400);
        }

        $pipeline_id = intval($_POST['pipeline_id'] ?? 0);
        $recruiter_id = intval($_POST['recruiter_id'] ?? 0);
        $crm_post_id = intval($_POST['post_id'] ?? 0) ?: null;
        $wp_post_id = intval($_POST['wp_post_id'] ?? 0) ?: null;
        $role_title = sanitize_text_field($_POST['role_title'] ?? '');
        $company = sanitize_text_field($_POST['company'] ?? '');
        $location = sanitize_text_field($_POST['location'] ?? '');
        $external_url = esc_url_raw($_POST['external_url'] ?? '');

        if (!$crm_post_id && $wp_post_id) {
            $linked_crm_post_id = (int) get_post_meta($wp_post_id, '_crm_post_id', true);
            if ($linked_crm_post_id > 0) {
                $crm_post_id = $linked_crm_post_id;
            }
        }

        if ($pipeline_id <= 0) {
            $existing = null;

            if ($crm_post_id) {
                $existing = $wpdb->get_row(
                    $wpdb->prepare(
                        "SELECT * FROM {$pipeline_table} WHERE user_id = %d AND post_id = %d ORDER BY id DESC LIMIT 1",
                        $user_id,
                        $crm_post_id
                    ),
                    ARRAY_A
                );
            }

            if (!$existing && $external_url !== '') {
                $existing = $wpdb->get_row(
                    $wpdb->prepare(
                        "SELECT * FROM {$pipeline_table} WHERE user_id = %d AND external_url = %s ORDER BY id DESC LIMIT 1",
                        $user_id,
                        $external_url
                    ),
                    ARRAY_A
                );
            }

            if (!$existing && $role_title !== '' && $company !== '') {
                $existing = $wpdb->get_row(
                    $wpdb->prepare(
                        "SELECT * FROM {$pipeline_table} WHERE user_id = %d AND role_title = %s AND company = %s AND location = %s ORDER BY id DESC LIMIT 1",
                        $user_id,
                        $role_title,
                        $company,
                        $location
                    ),
                    ARRAY_A
                );
            }

            if ($existing) {
                $pipeline_id = (int) ($existing['id'] ?? 0);
            }
        }

        if ($pipeline_id > 0) {
            $result = $pipeline_model->update_stage($pipeline_id, $user_id, $stage);

            if (is_wp_error($result)) {
                wp_send_json_error(['message' => $result->get_error_message()], 400);
            }

            if ($result === false) {
                $message = !empty($wpdb->last_error)
                    ? sprintf('Unable to update tracking status: %s', $wpdb->last_error)
                    : 'Unable to update tracking status right now.';
                wp_send_json_error(['message' => $message], 500);
            }
        } else {
            if (!$crm_post_id && $role_title === '') {
                wp_send_json_error(['message' => 'Role data required to track this opportunity'], 400);
            }

            $result = $pipeline_model->add_to_pipeline($user_id, [
                'recruiter_id' => $recruiter_id ?: null,
                'post_id' => $crm_post_id,
                'stage' => $stage,
                'role_title' => $role_title,
                'company' => $company,
                'location' => $location,
                'external_url' => $external_url,
                'source' => $crm_post_id ? 'platform' : 'other',
            ]);

            if (is_wp_error($result)) {
                wp_send_json_error(['message' => $result->get_error_message()], 400);
            }

            if (!$result) {
                $message = !empty($wpdb->last_error)
                    ? sprintf('Unable to add this role to tracking: %s', $wpdb->last_error)
                    : 'Unable to add this role to tracking right now.';
                wp_send_json_error(['message' => $message], 500);
            }

            $pipeline_id = (int) $result;
        }

        $sync_where_sql = '';
        $sync_params = [$stage, $user_id];

        if ($crm_post_id) {
            $sync_where_sql = 'post_id = %d';
            $sync_params[] = $crm_post_id;
        } elseif ($external_url !== '') {
            $sync_where_sql = 'external_url = %s';
            $sync_params[] = $external_url;
        } elseif ($role_title !== '' && $company !== '') {
            $sync_where_sql = 'role_title = %s AND company = %s AND location = %s';
            $sync_params[] = $role_title;
            $sync_params[] = $company;
            $sync_params[] = $location;
        }

        if ($sync_where_sql !== '') {
            $sync_sql = "UPDATE {$pipeline_table}
                SET stage = %s,
                    stage_entered_at = NOW()
                WHERE user_id = %d
                  AND {$sync_where_sql}";
            $wpdb->query($wpdb->prepare($sync_sql, $sync_params));
        }

        $stage_meta = (array) ($stages[$stage] ?? []);

        wp_send_json_success([
            'message' => 'Tracking status saved',
            'pipeline_id' => $pipeline_id,
            'stage' => $stage,
            'stage_label' => (string) ($stage_meta['label'] ?? $stage),
            'stage_color' => (string) ($stage_meta['color'] ?? '#0d353e'),
        ]);
    }

