    public function capture_lead()
    {
        $nonce = sanitize_text_field($_POST['nonce'] ?? '');
        if (!$nonce || !wp_verify_nonce($nonce, 'sffc_crm_nonce')) {
            wp_send_json_error(['message' => __('Invalid request. Please refresh and try again.', 'senna-finance')], 400);
        }

        $first_name = sanitize_text_field($_POST['first_name'] ?? '');
        $last_name = sanitize_text_field($_POST['last_name'] ?? '');
        $email = sanitize_email($_POST['email'] ?? '');

        if (!$first_name || !$last_name || !$email || !is_email($email)) {
            wp_send_json_error(['message' => __('Please enter a valid name and email.', 'senna-finance')], 400);
        }

        // Check if user already exists
        $existing_user = get_user_by('email', $email);

        if ($existing_user) {
            if (class_exists('SFFC_CRM_Shortcodes') && method_exists(SFFC_CRM_Shortcodes::get_instance(), 'stop_membership_signup_reminders')) {
                SFFC_CRM_Shortcodes::get_instance()->stop_membership_signup_reminders($email);
            }

            wp_send_json_success([
                'message' => __('This email already has a MENA Careers account. Continue to memberships to choose your plan.', 'senna-finance'),
                'user_exists' => true,
                'redirect' => home_url('/memberships/')
            ]);
            return;
        }

        if (class_exists('SFFC_CRM_Shortcodes') && method_exists(SFFC_CRM_Shortcodes::get_instance(), 'capture_membership_signup_lead')) {
            SFFC_CRM_Shortcodes::get_instance()->capture_membership_signup_lead([
                'email' => $email,
                'first_name' => $first_name,
                'last_name' => $last_name,
                'source' => 'crm_express_interest',
            ]);
        } else {
            update_option('sffc_membership_signup_lead_' . md5(strtolower($email)), [
                'email' => $email,
                'first_name' => $first_name,
                'last_name' => $last_name,
                'source' => 'crm_express_interest',
                'created_at' => time(),
            ], false);
        }

        // Store lead for tracking
        $leads = get_option('sffc_crm_interest_leads', []);
        if (!is_array($leads)) {
            $leads = [];
        }

        $entry = [
            'first_name' => $first_name,
            'last_name' => $last_name,
            'email' => $email,
            'user_id' => 0,
            'ts' => current_time('mysql'),
        ];

        array_unshift($leads, $entry);
        if (count($leads) > 500) {
            $leads = array_slice($leads, 0, 500);
        }
        update_option('sffc_crm_interest_leads', $leads, false);

        error_log('SFFC CRM: Express interest lead captured - Email: ' . $email);

        wp_send_json_success([
            'message' => __('Thanks. Continue to memberships to choose the plan that fits your search.', 'senna-finance'),
            'status' => 'lead_captured',
            'redirect' => home_url('/memberships/')
        ]);
    }

    /**
     * Get all badge counts for tabs (matches, saved, outreach lists)
     */
    public function get_badge_counts()
    {
        global $wpdb;
        $user_id = $this->verify_request();

        $counts = [];

        // Get matches count - just count posts for now, matching is done client-side
        $post_model = new SFFC_CRM_Post();
        $posts = $post_model->get_feed([
            'page' => 1,
            'per_page' => 100,
            'approved_only' => true,
            'user_id' => $user_id
        ]);
        $counts['matches'] = is_array($posts) ? count($posts) : 0;

        // Get saved items count (posts + recruiters)
        $post_model = new SFFC_CRM_Post();
        $saved_posts = $post_model->get_saved_posts($user_id);

        $recruiter_model = new SFFC_CRM_Recruiter();
        $saved_recruiters = $recruiter_model->get_saved_recruiters($user_id);

        $counts['saved'] = (is_array($saved_posts) ? count($saved_posts) : 0) +
            (is_array($saved_recruiters) ? count($saved_recruiters) : 0);

        // Get outreach lists count - direct query like get_recruiter_outreach_lists
        $table = $wpdb->prefix . 'sffc_crm_outreach_lists';
        $lists = $wpdb->get_results($wpdb->prepare(
            "SELECT id FROM $table
             WHERE user_id = %d",
            $user_id
        ), ARRAY_A);
        $counts['outreach_lists'] = is_array($lists) ? count($lists) : 0;

        // Smart message requests count
        $smart_apply_table = $wpdb->prefix . 'sffc_smart_apply_requests';
        if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $smart_apply_table)) === $smart_apply_table) {
            $smart_apply_count = $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$smart_apply_table} WHERE user_id = %d AND status != %s",
                $user_id,
                'cancelled'
            ));
            $counts['smart_apply'] = intval($smart_apply_count);
        } else {
            $counts['smart_apply'] = 0;
        }

        // Get recruiter intro count
        $intro_table = $wpdb->prefix . 'sffc_introduction_requests';
        if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $intro_table)) === $intro_table) {
            $intro_count = $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$intro_table} WHERE user_id = %d",
                $user_id
            ));
            $counts['recruiter_intros'] = intval($intro_count);
        } else {
            $counts['recruiter_intros'] = 0;
        }

        // Replies count (intro requests where recruiter responded)
        if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $intro_table)) === $intro_table) {
            $replies_count = $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$intro_table} WHERE user_id = %d AND recruiter_status = %s",
                $user_id,
                'replied'
            ));
            if ($replies_count === null) {
                $replies_count = 0;
            }
            $counts['replies'] = intval($replies_count);
        } else {
            $counts['replies'] = 0;
        }

        wp_send_json_success($counts);
    }

