    /**
     * Update pipeline notes and next action
     */
    public function update_pipeline_notes()
    {
        $user_id = $this->verify_request();
        $pipeline_id = intval($_POST['pipeline_id'] ?? 0);
        $notes = sanitize_textarea_field($_POST['notes'] ?? '');
        $next_action = sanitize_text_field($_POST['next_action'] ?? '');

        if (!$pipeline_id) {
            wp_send_json_error(['message' => 'Pipeline ID required'], 400);
        }

        $pipeline_model = new SFFC_CRM_Pipeline();

        // Verify ownership
        $item = $pipeline_model->get($pipeline_id);
        if (!$item || $item['user_id'] != $user_id) {
            wp_send_json_error(['message' => 'Pipeline item not found'], 404);
        }

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_pipeline';

        $result = $wpdb->update(
            $table,
            [
                'notes' => $notes,
                'next_action' => $next_action,
            ],
            ['id' => $pipeline_id, 'user_id' => $user_id]
        );

        if ($result === false) {
            wp_send_json_error(['message' => 'Failed to update notes'], 500);
        }

        wp_send_json_success(['message' => 'Notes updated']);
    }

    /**
     * Get data for reach out modal
     */
    public function get_reach_out_data()
    {
        $user_id = $this->verify_request();
        $recruiter_id = intval($_POST['recruiter_id'] ?? 0);
        $post_id = intval($_POST['post_id'] ?? 0);

        if (!$recruiter_id) {
            wp_send_json_error(['message' => 'Recruiter ID required'], 400);
        }

        $recruiter_model = new SFFC_CRM_Recruiter();
        $recruiter = $recruiter_model->get($recruiter_id);

        if (!$recruiter) {
            wp_send_json_error(['message' => 'Recruiter not found'], 404);
        }

        // Get post if provided
        $post = null;
        if ($post_id) {
            $post_model = new SFFC_CRM_Post();
            $post = $post_model->get($post_id);
        }

        // Get templates
        global $wpdb;
        $templates_table = $wpdb->prefix . 'sffc_crm_templates';
        $templates = $wpdb->get_results(
            "SELECT id, name, template_type, subject, content
             FROM {$templates_table}
             WHERE (user_id = {$user_id} OR is_system = 1) AND is_active = 1
             ORDER BY is_system ASC, usage_count DESC",
            ARRAY_A
        );

        wp_send_json_success([
            'recruiter' => $recruiter,
            'post' => $post,
            'templates' => $templates,
        ]);
    }

