        $total = $recruiter_model->get_recruiters_with_posts_count($args);
        $stats = $user_id ? $recruiter_model->get_user_stats($user_id) : [];
        $tags = $user_id ? $recruiter_model->get_user_tags($user_id) : [];

        wp_send_json_success([
            'recruiters' => $recruiters,
            'total' => $total,
            'page' => $args['page'],
            'total_pages' => ceil($total / $args['per_page']),
            'stats' => $stats,
            'tags' => $tags,
        ]);
    }

