    // ============================================
    // PHASE 2: ANALYTICS
    // ============================================

    /**
     * Get dashboard statistics - consolidated view
     */
    public function get_dashboard_stats()
    {
        $user_id = $this->verify_request();

        global $wpdb;

        // Initialize models
        $recruiter_model = new SFFC_CRM_Recruiter();
        $pipeline_model = new SFFC_CRM_Pipeline();

        // === SUMMARY COUNTS ===
        // Saved recruiters count
        $saved_recruiters_table = $wpdb->prefix . 'sffc_crm_saved_recruiters';
        $recruiters_count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$saved_recruiters_table} WHERE user_id = %d",
            $user_id
        ));

        // Saved posts count
        $saved_posts_table = $wpdb->prefix . 'sffc_crm_saved_posts';
        $posts_count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$saved_posts_table} WHERE user_id = %d",
            $user_id
        ));

        // Contacts count
        $contacts_table = $wpdb->prefix . 'sffc_crm_contacts';
        $contacts_count = 0;
        if ($wpdb->get_var("SHOW TABLES LIKE '{$contacts_table}'") === $contacts_table) {
            $contacts_count = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$contacts_table} WHERE user_id = %d",
                $user_id
            ));
        }

        // Pipeline count (active only)
        $pipeline_table = $wpdb->prefix . 'sffc_crm_pipeline';
        $pipeline_count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$pipeline_table} WHERE user_id = %d AND (outcome IS NULL OR outcome = '')",
            $user_id
        ));

        // Offers (won outcomes)
        $offers_count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$pipeline_table} WHERE user_id = %d AND outcome = 'won'",
            $user_id
        ));

        // === OUTREACH STATS ===
        $outreach_table = $wpdb->prefix . 'sffc_crm_outreach';
        $outreach_stats = $wpdb->get_row($wpdb->prepare(
            "SELECT
                COUNT(CASE WHEN status IN ('sent', 'opened', 'clicked', 'replied') THEN 1 END) as reached_out,
                COUNT(CASE WHEN status IN ('sent', 'opened', 'clicked') AND status != 'replied' THEN 1 END) as awaiting_reply,
                COUNT(CASE WHEN status = 'replied' THEN 1 END) as replied
             FROM {$outreach_table}
             WHERE user_id = %d",
            $user_id
        ), ARRAY_A);

        // Ensure outreach stats have defaults
        $outreach_stats = $outreach_stats ?: ['reached_out' => 0, 'awaiting_reply' => 0, 'replied' => 0];

        // === PIPELINE FUNNEL ===
        $stages = SFFC_CRM_Pipeline::get_stages();
        $funnel = [];
        $stage_counts = $wpdb->get_results($wpdb->prepare(
            "SELECT stage, COUNT(*) as count
             FROM {$pipeline_table}
             WHERE user_id = %d AND (outcome IS NULL OR outcome = '')
             GROUP BY stage",
            $user_id
        ), ARRAY_A);

        $stage_count_map = [];
        foreach ($stage_counts as $row) {
            $stage_count_map[$row['stage']] = (int) $row['count'];
        }

        foreach ($stages as $stage_key => $stage_data) {
            $funnel[] = [
                'stage' => $stage_key,
                'label' => $stage_data['label'],
                'color' => $stage_data['color'],
                'count' => isset($stage_count_map[$stage_key]) ? $stage_count_map[$stage_key] : 0
            ];
        }

        // === UPCOMING ITEMS ===
        // Upcoming follow-ups (recruiters with follow-up dates)
        $upcoming_followups = $wpdb->get_results($wpdb->prepare(
            "SELECT r.id, r.name, sr.followup_date
             FROM {$saved_recruiters_table} sr
             JOIN {$wpdb->prefix}sffc_crm_recruiters r ON r.id = sr.recruiter_id
             WHERE sr.user_id = %d
               AND sr.followup_date IS NOT NULL
               AND sr.followup_date >= CURDATE()
               AND sr.followup_date <= DATE_ADD(CURDATE(), INTERVAL 7 DAY)
             ORDER BY sr.followup_date ASC
             LIMIT 5",
            $user_id
        ), ARRAY_A) ?: [];

        // Upcoming pipeline actions
        $upcoming_pipeline = $wpdb->get_results($wpdb->prepare(
            "SELECT id, role_title, next_action, next_action_date
             FROM {$pipeline_table}
             WHERE user_id = %d
               AND next_action_date IS NOT NULL
               AND next_action_date >= CURDATE()
               AND next_action_date <= DATE_ADD(CURDATE(), INTERVAL 7 DAY)
               AND (outcome IS NULL OR outcome = '')
             ORDER BY next_action_date ASC
             LIMIT 5",
            $user_id
        ), ARRAY_A) ?: [];

        // Pending tasks
        $tasks_table = $wpdb->prefix . 'sffc_crm_tasks';
        $pending_tasks = [];
        if ($wpdb->get_var("SHOW TABLES LIKE '{$tasks_table}'") === $tasks_table) {
            $pending_tasks = $wpdb->get_results($wpdb->prepare(
                "SELECT t.id, t.title, t.due_date, t.priority, r.name as recruiter_name
                 FROM {$tasks_table} t
                 LEFT JOIN {$wpdb->prefix}sffc_crm_recruiters r ON r.id = t.recruiter_id
                 WHERE t.user_id = %d
                   AND t.status = 'pending'
                   AND (t.due_date IS NULL OR t.due_date <= DATE_ADD(CURDATE(), INTERVAL 7 DAY))
                 ORDER BY t.due_date ASC, t.priority DESC
                 LIMIT 5",
                $user_id
            ), ARRAY_A) ?: [];
        }

        // === RECENT ACTIVITY ===
        $activity_table = $wpdb->prefix . 'sffc_crm_activity';
        $recent_activity = [];
        if ($wpdb->get_var("SHOW TABLES LIKE '{$activity_table}'") === $activity_table) {
            $recent_activity = $wpdb->get_results($wpdb->prepare(
                "SELECT a.activity_type, a.activity_data, a.created_at, r.name as recruiter_name
                 FROM {$activity_table} a
                 LEFT JOIN {$wpdb->prefix}sffc_crm_recruiters r ON r.id = a.recruiter_id
                 WHERE a.user_id = %d
                 ORDER BY a.created_at DESC
                 LIMIT 10",
                $user_id
            ), ARRAY_A) ?: [];
        }

        wp_send_json_success([
            'summary' => [
                'recruiters' => $recruiters_count,
                'posts' => $posts_count,
                'contacts' => $contacts_count,
                'pipeline' => $pipeline_count,
                'offers' => $offers_count
            ],
            'outreach' => [
                'reached_out' => (int) $outreach_stats['reached_out'],
                'awaiting_reply' => (int) $outreach_stats['awaiting_reply'],
                'replied' => (int) $outreach_stats['replied']
            ],
            'funnel' => $funnel,
            'upcoming' => [
                'followups' => $upcoming_followups,
                'pipeline' => $upcoming_pipeline,
                'tasks' => $pending_tasks
            ],
            'recent_activity' => $recent_activity
        ]);
    }

