    /**
     * Get user templates
     */
    public function get_templates()
    {
        $user_id = $this->verify_request();

        $template_model = new SFFC_CRM_Template();

        $channel = isset($_POST['channel']) ? sanitize_text_field($_POST['channel']) : null;
