    /**
     * Get single template
     */
    public function get_template()
    {
        $user_id = $this->verify_request();

        $template_id = isset($_POST['template_id']) ? intval($_POST['template_id']) : 0;

        if (!$template_id) {
            wp_send_json_error(['message' => 'Template ID required'], 400);
        }

        $template_model = new SFFC_CRM_Template();
        $template = $template_model->get($template_id);

        if (!$template) {
            wp_send_json_error(['message' => 'Template not found'], 404);
        }

        // Get stats if it's a user template
        $stats = null;
        if ($template['user_id'] == $user_id || $template['is_system']) {
            $stats = $template_model->get_template_stats($template_id);
        }

        wp_send_json_success([
            'template' => $template,
            'stats' => $stats,
        ]);
    }

    /**
     * Create template
     */
    public function create_template()
    {
        $user_id = $this->verify_request();

        $data = [
            'name' => isset($_POST['name']) ? sanitize_text_field($_POST['name']) : '',
            'description' => isset($_POST['description']) ? sanitize_textarea_field($_POST['description']) : '',
            'channel' => isset($_POST['channel']) ? sanitize_text_field($_POST['channel']) : 'email',
            'template_type' => isset($_POST['template_type']) ? sanitize_text_field($_POST['template_type']) : 'custom',
            'subject' => isset($_POST['subject']) ? sanitize_text_field($_POST['subject']) : '',
            'content' => isset($_POST['content']) ? wp_kses_post($_POST['content']) : '',
        ];

        if (empty($data['name']) || empty($data['content'])) {
            wp_send_json_error(['message' => 'Name and content are required'], 400);
        }

        $template_model = new SFFC_CRM_Template();
        $template_id = $template_model->create($user_id, $data);

        if ($template_id) {
            $template = $template_model->get($template_id);
            wp_send_json_success(['template' => $template]);
        }

        wp_send_json_error(['message' => 'Failed to create template'], 500);
    }

    /**
     * Update template
     */
    public function update_template()
    {
        $user_id = $this->verify_request();

        $template_id = isset($_POST['template_id']) ? intval($_POST['template_id']) : 0;

        if (!$template_id) {
            wp_send_json_error(['message' => 'Template ID required'], 400);
        }

        $data = [];
        if (isset($_POST['name'])) $data['name'] = sanitize_text_field($_POST['name']);
        if (isset($_POST['description'])) $data['description'] = sanitize_textarea_field($_POST['description']);
        if (isset($_POST['channel'])) $data['channel'] = sanitize_text_field($_POST['channel']);
        if (isset($_POST['template_type'])) $data['template_type'] = sanitize_text_field($_POST['template_type']);
        if (isset($_POST['subject'])) $data['subject'] = sanitize_text_field($_POST['subject']);
        if (isset($_POST['content'])) $data['content'] = wp_kses_post($_POST['content']);
        if (isset($_POST['is_active'])) $data['is_active'] = intval($_POST['is_active']);

        $template_model = new SFFC_CRM_Template();
        $result = $template_model->update($template_id, $user_id, $data);

        if ($result) {
            $template = $template_model->get($template_id);
            wp_send_json_success(['template' => $template]);
        }

        wp_send_json_error(['message' => 'Failed to update template'], 500);
    }

    /**
     * Delete template
     */
    public function delete_template()
    {
        $user_id = $this->verify_request();

        $template_id = isset($_POST['template_id']) ? intval($_POST['template_id']) : 0;

        if (!$template_id) {
            wp_send_json_error(['message' => 'Template ID required'], 400);
        }

        $template_model = new SFFC_CRM_Template();
        $result = $template_model->delete($template_id, $user_id);

        if ($result) {
            wp_send_json_success(['message' => 'Template deleted']);
        }

        wp_send_json_error(['message' => 'Cannot delete this template'], 400);
    }

    /**
     * Duplicate template
     */
    public function duplicate_template()
    {
        $user_id = $this->verify_request();

        $template_id = isset($_POST['template_id']) ? intval($_POST['template_id']) : 0;

        if (!$template_id) {
            wp_send_json_error(['message' => 'Template ID required'], 400);
        }

        $template_model = new SFFC_CRM_Template();
        $new_id = $template_model->duplicate($template_id, $user_id);

        if ($new_id) {
            $template = $template_model->get($new_id);
            wp_send_json_success(['template' => $template]);
        }

        wp_send_json_error(['message' => 'Failed to duplicate template'], 500);
    }

    /**
     * Render template with variables
     */
    public function render_template()
    {
        $user_id = $this->verify_request();

        $template_id = isset($_POST['template_id']) ? intval($_POST['template_id']) : 0;
        $variables = isset($_POST['variables']) ? (array) json_decode(stripslashes($_POST['variables']), true) : [];

        // Sanitize variables
        $clean_variables = [];
        foreach ($variables as $key => $value) {
            $clean_variables[sanitize_key($key)] = sanitize_text_field($value);
        }

        $template_model = new SFFC_CRM_Template();

        if ($template_id) {
            $rendered = $template_model->render($template_id, $clean_variables);
        } else {
            // Render content directly
            $content = isset($_POST['content']) ? wp_kses_post($_POST['content']) : '';
            $subject = isset($_POST['subject']) ? sanitize_text_field($_POST['subject']) : '';
            $rendered = $template_model->render_content($content, $clean_variables, $subject);
        }

        if ($rendered) {
            wp_send_json_success($rendered);
        }

        wp_send_json_error(['message' => 'Failed to render template'], 500);
    }

    public function get_email_accounts()
    {
        $user_id = $this->verify_request();
        $accounts = SFFC_CRM_Email_Account::get_instance()->get_accounts($user_id);
        wp_send_json_success(['accounts' => $accounts]);
    }

    public function start_email_oauth()
    {
        $user_id = $this->verify_request();
        $provider = isset($_POST['provider']) ? sanitize_key($_POST['provider']) : '';
        if (!in_array($provider, ['gmail', 'outlook'], true)) {
            wp_send_json_error(['message' => 'Invalid provider'], 400);
        }

        $service = SFFC_CRM_Email_Service::get_instance();
        $url = $service->build_oauth_url($user_id, $provider);
        if (is_wp_error($url)) {
            wp_send_json_error(['message' => $url->get_error_message()], 400);
        }

        wp_send_json_success(['auth_url' => $url]);
    }

    public function connect_app_password()
    {
        $user_id = $this->verify_request();
        $email = isset($_POST['email']) ? sanitize_email($_POST['email']) : '';
        $name = isset($_POST['name']) ? sanitize_text_field($_POST['name']) : '';
        $host = isset($_POST['host']) ? sanitize_text_field($_POST['host']) : '';
        $port = isset($_POST['port']) ? intval($_POST['port']) : 587;
        $username = isset($_POST['username']) ? sanitize_text_field($_POST['username']) : '';
        $password = isset($_POST['password']) ? sanitize_text_field($_POST['password']) : '';
        $encryption = isset($_POST['encryption']) ? sanitize_key($_POST['encryption']) : 'tls';

        if (!$email || !$host || !$username || !$password) {
            wp_send_json_error(['message' => 'All SMTP fields are required'], 400);
        }

        $accounts = SFFC_CRM_Email_Account::get_instance();
        $account_id = $accounts->save_app_password_account($user_id, $email, $name ?: $email, [
            'host' => $host,
            'port' => $port,
            'username' => $username,
            'password' => $password,
            'encryption' => $encryption,
        ]);

        wp_send_json_success(['account_id' => $account_id]);
    }

    public function disconnect_email_account()
    {
        $user_id = $this->verify_request();
        $account_id = isset($_POST['account_id']) ? intval($_POST['account_id']) : 0;
        if (!$account_id) {
            wp_send_json_error(['message' => 'Account ID required'], 400);
        }

        $accounts = SFFC_CRM_Email_Account::get_instance();
        $accounts->delete_account($account_id, $user_id);
        wp_send_json_success(['success' => true]);
    }

    public function send_outreach_email()
    {
        $user_id = $this->verify_request();
        $recruiter_id = isset($_POST['recruiter_id']) ? intval($_POST['recruiter_id']) : 0;
        $subject = isset($_POST['subject']) ? sanitize_text_field(wp_unslash($_POST['subject'])) : '';
        $content = isset($_POST['content']) ? wp_kses_post(wp_unslash($_POST['content'])) : '';
        $account_id = isset($_POST['account_id']) ? intval($_POST['account_id']) : null;
        $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;

        if (!$recruiter_id) {
            wp_send_json_error(['message' => 'Recruiter required'], 400);
        }

        $email_mode = get_option('sffc_crm_email_mode', 'oauth');
        if ($email_mode !== 'oauth') {
            wp_send_json_error([
                'message' => __('Direct sending is disabled while manual email mode is active.', 'senna-finance'),
                'code' => 'email_mode_disabled',
            ], 400);
        }

        $service = SFFC_CRM_Email_Service::get_instance();
        $result = $service->send_connected_email($user_id, [
            'recruiter_id' => $recruiter_id,
            'post_id' => $post_id,
            'subject' => $subject,
            'content' => $content,
            'account_id' => $account_id,
        ]);

        if (is_wp_error($result)) {
            wp_send_json_error([
                'message' => $result->get_error_message(),
                'code' => $result->get_error_code(),
            ], 400);
        }

        wp_send_json_success($result);
    }

