    /**
     * Get compose data (recruiter + post + user profile + templates)
     */
    public function get_compose_data()
    {
        $user_id = $this->verify_request();

        $recruiter_id = isset($_POST['recruiter_id']) ? intval($_POST['recruiter_id']) : 0;
        $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;

        if (!$recruiter_id) {
            wp_send_json_error(['message' => 'Recruiter ID required'], 400);
        }

        // Get recruiter data
        $recruiter_model = new SFFC_CRM_Recruiter();
        $recruiter = $recruiter_model->get($recruiter_id);

        if (!$recruiter) {
            wp_send_json_error(['message' => 'Recruiter not found'], 404);
        }

        // Get post data if provided
        $post = null;
        if ($post_id) {
            $post_model = new SFFC_CRM_Post();
            $post = $post_model->get($post_id);
        }

        // Get user profile
        $user = wp_get_current_user();
        $user_meta = get_user_meta($user_id);

        $candidate = [
            'name' => $user->display_name,
            'first_name' => $user->first_name ?: explode(' ', $user->display_name)[0],
            'email' => $user->user_email,
            'current_role' => isset($user_meta['current_role'][0]) ? $user_meta['current_role'][0] : '',
            'company' => isset($user_meta['current_company'][0]) ? $user_meta['current_company'][0] : '',
            'experience' => isset($user_meta['experience_summary'][0]) ? $user_meta['experience_summary'][0] : '',
            'years' => isset($user_meta['years_experience'][0]) ? $user_meta['years_experience'][0] : '',
            'linkedin' => isset($user_meta['linkedin_url'][0]) ? $user_meta['linkedin_url'][0] : '',
            'phone' => isset($user_meta['phone'][0]) ? $user_meta['phone'][0] : '',
        ];

        // Build variables for template rendering
        $variables = [
            'recruiter_name' => $recruiter['name'],
            'recruiter_first_name' => $recruiter['first_name'] ?: explode(' ', $recruiter['name'])[0],
            'recruiter_firm' => $recruiter['firm'] ?: '',
            'recruiter_title' => $recruiter['title'] ?: '',
            'candidate_name' => $candidate['name'],
            'candidate_first_name' => $candidate['first_name'],
            'candidate_email' => $candidate['email'],
            'candidate_current_role' => $candidate['current_role'],
            'candidate_company' => $candidate['company'],
            'candidate_experience' => $candidate['experience'],
            'candidate_years' => $candidate['years'],
            'candidate_linkedin' => $candidate['linkedin'],
            'candidate_phone' => $candidate['phone'],
        ];

        if ($post) {
            $variables['role_title'] = $post['role_title'] ?: '';
            $variables['company'] = $post['company'] ?: '';
            $variables['location'] = $post['location'] ?: '';
            $variables['salary_range'] = $post['salary_text'] ?: '';
            $variables['post_snippet'] = $post['content_snippet'] ?: '';
        }

        // Get templates
        $template_model = new SFFC_CRM_Template();
        $templates = $template_model->get_user_templates($user_id);

        // Get outreach limits
        $outreach_model = new SFFC_CRM_Outreach();
        $remaining = $outreach_model->get_remaining($user_id);
        $limit = apply_filters('sffc_crm_outreach_limit', 5, $user_id);
        $used = $limit - $remaining;

        // Check features
        $features = apply_filters('sffc_crm_features', [], $user_id);

        wp_send_json_success([
            'recruiter' => $recruiter,
            'post' => $post,
            'candidate' => $candidate,
            'variables' => $variables,
            'templates' => $templates,
            'usage' => [
                'used' => $used,
                'limit' => $limit,
                'remaining' => $remaining,
            ],
            'features' => $features,
        ]);
    }

    /**
     * Create outreach record
     */
    public function create_outreach()
    {
        $user_id = $this->verify_request();

        $data = [
            'recruiter_id' => isset($_POST['recruiter_id']) ? intval($_POST['recruiter_id']) : 0,
            'post_id' => isset($_POST['post_id']) ? intval($_POST['post_id']) : null,
            'pipeline_id' => isset($_POST['pipeline_id']) ? intval($_POST['pipeline_id']) : null,
            'channel' => isset($_POST['channel']) ? sanitize_text_field($_POST['channel']) : 'email',
            'message_type' => isset($_POST['message_type']) ? sanitize_text_field($_POST['message_type']) : 'initial',
            'subject' => isset($_POST['subject']) ? sanitize_text_field($_POST['subject']) : '',
            'content' => isset($_POST['content']) ? wp_kses_post($_POST['content']) : '',
            'template_id' => isset($_POST['template_id']) ? intval($_POST['template_id']) : null,
        ];

        if (!$data['recruiter_id'] || empty($data['content'])) {
            wp_send_json_error(['message' => 'Recruiter ID and content are required'], 400);
        }

        $outreach_model = new SFFC_CRM_Outreach();
        $result = $outreach_model->create($user_id, $data);

        if (is_wp_error($result)) {
            wp_send_json_error(['message' => $result->get_error_message()], 400);
        }

        if ($result) {
            $outreach = $outreach_model->get_with_details($result, $user_id);
            wp_send_json_success([
                'outreach' => $outreach,
                'remaining' => $outreach_model->get_remaining($user_id),
            ]);
        }

        wp_send_json_error(['message' => 'Failed to create outreach'], 500);
    }

    /**
     * Send outreach
     */
    public function send_outreach()
    {
        $user_id = $this->verify_request();

        // Rate limiting
        $rate_limiter = SFFC_CRM_Rate_Limiter::get_instance();
        $check = $rate_limiter->throttle('outreach_send', $user_id);
        if (is_wp_error($check)) {
            $rate_limiter->add_headers('outreach_send', $user_id);
            wp_send_json_error([
                'message' => $check->get_error_message(),
                'retry_after' => $check->get_error_data()['retry_after'] ?? 60,
            ], 429);
        }

        $outreach_id = isset($_POST['outreach_id']) ? intval($_POST['outreach_id']) : 0;

        if (!$outreach_id) {
            wp_send_json_error(['message' => 'Outreach ID required'], 400);
        }

        $outreach_model = new SFFC_CRM_Outreach();
        $result = $outreach_model->send($outreach_id, $user_id);

        if (is_wp_error($result)) {
            wp_send_json_error(['message' => $result->get_error_message()], 400);
        }

        if ($result) {
            $outreach = $outreach_model->get_with_details($outreach_id, $user_id);
            wp_send_json_success([
                'outreach' => $outreach,
                'remaining' => $outreach_model->get_remaining($user_id),
            ]);
        }

        wp_send_json_error(['message' => 'Failed to send outreach'], 500);
    }

