    /**
     * Generate AI message
     */
    public function generate_message()
    {
        $user_id = $this->verify_request();

        // Check if user has AI feature
        $features = apply_filters('sffc_crm_features', [], $user_id);
        if (empty($features['ai_personalization'])) {
            wp_send_json_error([
                'message' => 'AI personalization requires a Pro subscription',
                'upgrade_required' => true,
            ], 403);
        }

        // Rate limiting for AI generation
        $rate_limiter = SFFC_CRM_Rate_Limiter::get_instance();
        $check = $rate_limiter->throttle('outreach_generate', $user_id);
        if (is_wp_error($check)) {
            $rate_limiter->add_headers('outreach_generate', $user_id);
            wp_send_json_error([
                'message' => $check->get_error_message(),
                'retry_after' => $check->get_error_data()['retry_after'] ?? 60,
            ], 429);
        }

        $recruiter_id = isset($_POST['recruiter_id']) ? intval($_POST['recruiter_id']) : 0;
        $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;
        $channel = isset($_POST['channel']) ? sanitize_text_field($_POST['channel']) : 'email';
        $tone = isset($_POST['tone']) ? sanitize_text_field($_POST['tone']) : 'professional';
        $length = isset($_POST['length']) ? sanitize_text_field($_POST['length']) : 'medium';

        if (!$recruiter_id) {
            wp_send_json_error(['message' => 'Recruiter ID required'], 400);
        }

        // Get recruiter
        $recruiter_model = new SFFC_CRM_Recruiter();
        $recruiter = $recruiter_model->get($recruiter_id);

        if (!$recruiter) {
            wp_send_json_error(['message' => 'Recruiter not found'], 404);
        }

        // Get post if available
        $post = null;
        if ($post_id) {
            $post_model = new SFFC_CRM_Post();
            $post = $post_model->get($post_id);
        }

        // Get user profile
        $user = wp_get_current_user();
        $user_meta = get_user_meta($user_id);

        // Build context for AI
        $cv_excerpt = '';
        if (class_exists('SFFC_CRM_CV_Manager')) {
            $cv_manager = new SFFC_CRM_CV_Manager();
            $default_cv = $cv_manager->get_default($user_id);
            if (!empty($default_cv['content'])) {
                $cv_excerpt = mb_substr(wp_strip_all_tags($default_cv['content']), 0, 1200);
            }
        }

        $context = [
            'recruiter' => [
                'name' => $recruiter['name'],
                'first_name' => $recruiter['first_name'] ?: explode(' ', $recruiter['name'])[0],
                'firm' => $recruiter['firm'],
                'title' => $recruiter['title'],
            ],
            'candidate' => [
                'name' => $user->display_name,
                'current_role' => isset($user_meta['current_role'][0]) ? $user_meta['current_role'][0] : '',
                'company' => isset($user_meta['current_company'][0]) ? $user_meta['current_company'][0] : '',
                'experience' => isset($user_meta['experience_summary'][0]) ? $user_meta['experience_summary'][0] : '',
            ],
            'channel' => $channel,
            'tone' => $tone,
            'length' => $length,
            'cv_excerpt' => $cv_excerpt,
        ];

        if ($post) {
            $context['post'] = [
                'role_title' => $post['role_title'],
                'company' => $post['company'],
                'location' => $post['location'],
                'content' => substr($post['content'], 0, 1000),
            ];
        }

        // Generate message using AI
        $generated = $this->call_ai_for_message($context);

        if (is_wp_error($generated)) {
            wp_send_json_error(['message' => $generated->get_error_message()], 500);
        }

        // Increment AI usage
        global $wpdb;
        $usage_table = $wpdb->prefix . 'sffc_crm_usage';
        $period = date('Y-m');

        $wpdb->query($wpdb->prepare(
            "INSERT INTO {$usage_table} (user_id, period_month, ai_generation_count)
             VALUES (%d, %s, 1)
             ON DUPLICATE KEY UPDATE ai_generation_count = ai_generation_count + 1",
            $user_id,
            $period
        ));

        wp_send_json_success($generated);
    }

    /**
     * Call AI service to generate message
     */
    private function call_ai_for_message($context)
    {
        // Check for Claude API key
        $api_key = defined('ANTHROPIC_API_KEY') ? ANTHROPIC_API_KEY : get_option('sffc_api_key');

        // Fallback to other possible option names
        if (empty($api_key)) {
            $api_key = get_option('sffc_anthropic_api_key');
        }
        if (empty($api_key)) {
            $api_key = get_option('sffc_anthropic_key');
        }

        if (empty($api_key)) {
            return new WP_Error('no_api_key', 'AI service not configured. Please add your Claude API key in Settings.');
        }

        $channel = $context['channel'];
        $tone = $context['tone'];
        $length_map = ['short' => 50, 'medium' => 100, 'long' => 200];
        $max_words = isset($length_map[$context['length']]) ? $length_map[$context['length']] : 100;

        $prompt = "Generate a professional outreach message from a job candidate to a recruiter.\n\n";
        $prompt .= "Candidate: {$context['candidate']['name']}, currently {$context['candidate']['current_role']} at {$context['candidate']['company']}\n";
        $prompt .= "Experience: {$context['candidate']['experience']}\n\n";
        $prompt .= "Recruiter: {$context['recruiter']['first_name']} {$context['recruiter']['name']}, {$context['recruiter']['title']} at {$context['recruiter']['firm']}\n\n";

        if (!empty($context['post'])) {
            $prompt .= "Job Post: {$context['post']['role_title']} at {$context['post']['company']}, {$context['post']['location']}\n";
            $prompt .= "Post content: {$context['post']['content']}\n\n";
        }

        if (!empty($context['cv_excerpt'])) {
            $prompt .= "Candidate CV excerpt:\n{$context['cv_excerpt']}\n\n";
        }

        $prompt .= "Channel: {$channel}\n";
        $prompt .= "Tone: {$tone}\n";
        $prompt .= "Maximum length: approximately {$max_words} words\n\n";

        if ($channel === 'linkedin') {
            $prompt .= "This is for a LinkedIn message, so keep it concise and personal. Do not include subject line.\n";
        } else {
            $prompt .= "This is for an email. Include a subject line at the beginning formatted as 'Subject: [subject text]' on its own line.\n";
        }

        $prompt .= "\nWrite a compelling, personalized message that references specific details and shows genuine interest. Do not use generic phrases like 'I hope this email finds you well' and do NOT mention finding the recruiter on LinkedIn or social media.";

        $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
            'timeout' => 30,
            'headers' => [
                'Content-Type' => 'application/json',
                'x-api-key' => $api_key,
                'anthropic-version' => '2023-06-01',
            ],
            'body' => json_encode([
                'model' => 'claude-3-haiku-20240307',
                'max_tokens' => 500,
                'messages' => [
                    ['role' => 'user', 'content' => $prompt]
                ],
            ]),
        ]);

        if (is_wp_error($response)) {
            return new WP_Error('api_error', 'Failed to connect to AI service');
        }

        $body = json_decode(wp_remote_retrieve_body($response), true);

        if (empty($body['content'][0]['text'])) {
            return new WP_Error('api_error', 'No response from AI service');
        }

        $generated_text = $body['content'][0]['text'];

        // Parse subject line if email
        $subject = '';
        $content = $generated_text;

        if ($channel === 'email' && preg_match('/^Subject:\s*(.+?)[\r\n]/i', $generated_text, $matches)) {
            $subject = trim($matches[1]);
            $content = trim(preg_replace('/^Subject:\s*.+?[\r\n]+/i', '', $generated_text));
        }

        return [
            'subject' => $subject,
            'content' => $content,
            'channel' => $channel,
        ];
    }

    /**
     * Bulk create outreach
     */
    public function bulk_create_outreach()
    {
        $user_id = $this->verify_request();

        // Accept either recruiter_ids array or recipients array
        $recruiter_ids = isset($_POST['recruiter_ids']) ? (array) $_POST['recruiter_ids'] : [];
        $recipients = isset($_POST['recipients']) ? json_decode(stripslashes($_POST['recipients']), true) : [];
        $template_id = isset($_POST['template_id']) ? intval($_POST['template_id']) : 0;
        $subject = isset($_POST['subject']) ? sanitize_text_field($_POST['subject']) : '';
        $channel = isset($_POST['channel']) ? sanitize_text_field($_POST['channel']) : 'email';

        // Convert recruiter_ids to recipients format if provided
        if (!empty($recruiter_ids) && empty($recipients)) {
            $recipients = array_map(function ($id) {
                return ['recruiter_id' => intval($id)];
            }, $recruiter_ids);
        }

        if (empty($recipients) || !is_array($recipients)) {
            wp_send_json_error(['message' => 'Recipients required'], 400);
        }

        // Check bulk outreach limit
        $mepr = SFFC_CRM_MemberPress_Integration::get_instance();
        $bulk_limit = apply_filters('sffc_crm_bulk_outreach_limit', 0, $user_id);
        $recipient_count = count($recipients);

        if ($bulk_limit === 0) {
            // No bulk access
            $prompt = $mepr->get_upgrade_prompt($user_id, 'bulk_outreach_required');
            wp_send_json_error([
                'message' => 'Bulk outreach requires a paid subscription.',
                'upgrade_prompt' => $prompt
            ], 403);
        }

        if ($bulk_limit > 0 && $recipient_count > $bulk_limit) {
            // Exceeds limit
            $tier = $mepr->get_crm_tier($user_id);
            $prompt = $mepr->get_upgrade_prompt($user_id, 'bulk_outreach_required');
            wp_send_json_error([
                'message' => sprintf(
                    'You can message up to %d recruiters at once on your %s plan. You selected %d recruiters.',
                    $bulk_limit,
                    ucfirst($tier),
                    $recipient_count
                ),
                'upgrade_prompt' => $prompt,
                'limit' => $bulk_limit,
                'attempted' => $recipient_count
            ], 403);
        }

        $outreach_model = new SFFC_CRM_Outreach();
        $template_model = new SFFC_CRM_Template();

        // Check limits
        $remaining = $outreach_model->get_remaining($user_id);
        if ($remaining !== -1 && count($recipients) > $remaining) {
            wp_send_json_error([
                'message' => "You can only send {$remaining} more messages this month",
                'remaining' => $remaining,
            ], 400);
        }

        $results = [
            'created' => [],
            'failed' => [],
        ];

        // Get candidate profile once
        $user = wp_get_current_user();
        $user_meta = get_user_meta($user_id);

        $candidate_vars = [
            'candidate_name' => $user->display_name,
            'candidate_first_name' => $user->first_name ?: explode(' ', $user->display_name)[0],
            'candidate_email' => $user->user_email,
            'candidate_current_role' => isset($user_meta['current_role'][0]) ? $user_meta['current_role'][0] : '',
            'candidate_company' => isset($user_meta['current_company'][0]) ? $user_meta['current_company'][0] : '',
            'candidate_experience' => isset($user_meta['experience_summary'][0]) ? $user_meta['experience_summary'][0] : '',
        ];

        $recruiter_model = new SFFC_CRM_Recruiter();
        $post_model = new SFFC_CRM_Post();

        foreach ($recipients as $recipient) {
            $recruiter_id = intval($recipient['recruiter_id']);
            $post_id = isset($recipient['post_id']) ? intval($recipient['post_id']) : null;

            // Get recruiter
            $recruiter = $recruiter_model->get($recruiter_id);
            if (!$recruiter) {
                $results['failed'][] = ['recruiter_id' => $recruiter_id, 'error' => 'Recruiter not found'];
                continue;
            }

            // Build variables
            $variables = array_merge($candidate_vars, [
                'recruiter_name' => $recruiter['name'],
                'recruiter_first_name' => $recruiter['first_name'] ?: explode(' ', $recruiter['name'])[0],
                'recruiter_firm' => $recruiter['firm'] ?: '',
                'recruiter_title' => $recruiter['title'] ?: '',
            ]);

            // Add post variables if available
            if ($post_id) {
                $post = $post_model->get($post_id);
                if ($post) {
                    $variables['role_title'] = $post['role_title'] ?: '';
                    $variables['company'] = $post['company'] ?: '';
                    $variables['location'] = $post['location'] ?: '';
                    $variables['salary_range'] = $post['salary_text'] ?: '';
                    $variables['post_snippet'] = $post['content_snippet'] ?: '';
                }
            }

            // Render template
            if ($template_id) {
                $rendered = $template_model->render($template_id, $variables);
            } else {
                // Use recipient's custom content if provided
                $content = isset($recipient['content']) ? wp_kses_post($recipient['content']) : '';
                $subject = isset($recipient['subject']) ? sanitize_text_field($recipient['subject']) : '';
                $rendered = $template_model->render_content($content, $variables, $subject);
            }

            if (!$rendered || empty($rendered['content'])) {
                $results['failed'][] = ['recruiter_id' => $recruiter_id, 'error' => 'Failed to render message'];
                continue;
            }

            // Create outreach
            $outreach_data = [
                'recruiter_id' => $recruiter_id,
                'post_id' => $post_id,
                'channel' => $channel,
                'message_type' => 'initial',
                'subject' => $rendered['subject'],
                'content' => $rendered['content'],
                'template_id' => $template_id ?: null,
            ];

            $outreach_id = $outreach_model->create($user_id, $outreach_data);

            if (is_wp_error($outreach_id)) {
                $results['failed'][] = ['recruiter_id' => $recruiter_id, 'error' => $outreach_id->get_error_message()];
                continue;
            }

            if ($outreach_id) {
                $results['created'][] = [
                    'outreach_id' => $outreach_id,
                    'recruiter_id' => $recruiter_id,
                    'recruiter_name' => $recruiter['name'],
                    'content' => $rendered['content'],
                    'subject' => $rendered['subject'],
                ];
            }
        }

        wp_send_json_success([
            'results' => $results,
            'created' => count($results['created']),
            'failed' => count($results['failed']),
            'messages' => $results['created'], // For LinkedIn copy flow
            'sent' => 0, // Email sending handled separately
            'remaining' => $outreach_model->get_remaining($user_id),
        ]);
    }

