    /**
     * Create sequence
     */
    public function create_sequence()
    {
        $user_id = $this->verify_request();

        $data = [
            'name' => isset($_POST['name']) ? sanitize_text_field($_POST['name']) : '',
            'description' => isset($_POST['description']) ? sanitize_textarea_field($_POST['description']) : '',
            'trigger_type' => isset($_POST['trigger_type']) ? sanitize_text_field($_POST['trigger_type']) : 'manual',
            'settings' => isset($_POST['settings']) ? json_decode(stripslashes($_POST['settings']), true) : [],
        ];

        if (empty($data['name'])) {
            wp_send_json_error(['message' => 'Sequence name is required'], 400);
        }

        $sequence_model = new SFFC_CRM_Sequence();
        $sequence_id = $sequence_model->create($user_id, $data);

        if (is_wp_error($sequence_id)) {
            wp_send_json_error(['message' => $sequence_id->get_error_message()], 400);
        }

        $sequence = $sequence_model->get($sequence_id);

        wp_send_json_success([
            'sequence' => $sequence,
            'message' => 'Sequence created',
        ]);
    }

    /**
     * Update sequence
     */
    public function update_sequence()
    {
        $user_id = $this->verify_request();

        $sequence_id = isset($_POST['sequence_id']) ? intval($_POST['sequence_id']) : 0;

        if (!$sequence_id) {
            wp_send_json_error(['message' => 'Sequence ID required'], 400);
        }

        $data = [];
        if (isset($_POST['name'])) $data['name'] = sanitize_text_field($_POST['name']);
        if (isset($_POST['description'])) $data['description'] = sanitize_textarea_field($_POST['description']);
        if (isset($_POST['is_active'])) $data['is_active'] = (bool) $_POST['is_active'];
        if (isset($_POST['trigger_type'])) $data['trigger_type'] = sanitize_text_field($_POST['trigger_type']);
        if (isset($_POST['settings'])) $data['settings'] = json_decode(stripslashes($_POST['settings']), true);

        $sequence_model = new SFFC_CRM_Sequence();
        $result = $sequence_model->update($sequence_id, $user_id, $data);

        if (is_wp_error($result)) {
            wp_send_json_error(['message' => $result->get_error_message()], 400);
        }

        $sequence = $sequence_model->get($sequence_id);

        wp_send_json_success([
            'sequence' => $sequence,
            'message' => 'Sequence updated',
        ]);
    }

