    /**
     * Add step to sequence
     */
    public function add_sequence_step()
    {
        $user_id = $this->verify_request();

        $sequence_id = isset($_POST['sequence_id']) ? intval($_POST['sequence_id']) : 0;

        if (!$sequence_id) {
            wp_send_json_error(['message' => 'Sequence ID required'], 400);
        }

        // Verify sequence ownership
        $sequence_model = new SFFC_CRM_Sequence();
        $sequence = $sequence_model->get($sequence_id);

        if (!$sequence || $sequence['user_id'] != $user_id) {
            wp_send_json_error(['message' => 'Sequence not found'], 404);
        }

        $data = [
            'step_type' => isset($_POST['step_type']) ? sanitize_text_field($_POST['step_type']) : 'manual_email',
            'delay_days' => isset($_POST['delay_days']) ? intval($_POST['delay_days']) : 0,
            'delay_hours' => isset($_POST['delay_hours']) ? intval($_POST['delay_hours']) : 0,
            'channel' => isset($_POST['channel']) ? sanitize_text_field($_POST['channel']) : 'email',
            'template_id' => isset($_POST['template_id']) ? intval($_POST['template_id']) : null,
            'subject' => isset($_POST['subject']) ? sanitize_text_field($_POST['subject']) : '',
            'content' => isset($_POST['content']) ? wp_kses_post($_POST['content']) : '',
            'task_title' => isset($_POST['task_title']) ? sanitize_text_field($_POST['task_title']) : '',
            'task_description' => isset($_POST['task_description']) ? sanitize_textarea_field($_POST['task_description']) : '',
            'send_time_preference' => isset($_POST['send_time_preference']) ? sanitize_text_field($_POST['send_time_preference']) : 'morning',
            'skip_weekends' => isset($_POST['skip_weekends']) ? (bool) $_POST['skip_weekends'] : true,
        ];

        $order = isset($_POST['order']) ? intval($_POST['order']) : null;

        $step_id = $sequence_model->add_step($sequence_id, $data, $order);

        if (is_wp_error($step_id)) {
            wp_send_json_error(['message' => $step_id->get_error_message()], 400);
        }

        $steps = $sequence_model->get_steps($sequence_id);

        wp_send_json_success([
            'step_id' => $step_id,
            'steps' => $steps,
            'message' => 'Step added',
        ]);
    }

    /**
     * Update sequence step
     */
    public function update_sequence_step()
    {
        $user_id = $this->verify_request();

        $step_id = isset($_POST['step_id']) ? intval($_POST['step_id']) : 0;

        if (!$step_id) {
            wp_send_json_error(['message' => 'Step ID required'], 400);
        }

        // Get step to find sequence
        global $wpdb;
        $steps_table = $wpdb->prefix . 'sffc_crm_sequence_steps';
        $step = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$steps_table} WHERE id = %d", $step_id), ARRAY_A);

        if (!$step) {
            wp_send_json_error(['message' => 'Step not found'], 404);
        }

        // Verify sequence ownership
        $sequence_model = new SFFC_CRM_Sequence();
        $sequence = $sequence_model->get($step['sequence_id']);

        if (!$sequence || $sequence['user_id'] != $user_id) {
            wp_send_json_error(['message' => 'Permission denied'], 403);
        }

        $data = [];
        if (isset($_POST['step_type'])) $data['step_type'] = sanitize_text_field($_POST['step_type']);
        if (isset($_POST['delay_days'])) $data['delay_days'] = intval($_POST['delay_days']);
        if (isset($_POST['delay_hours'])) $data['delay_hours'] = intval($_POST['delay_hours']);
        if (isset($_POST['channel'])) $data['channel'] = sanitize_text_field($_POST['channel']);
        if (isset($_POST['template_id'])) $data['template_id'] = intval($_POST['template_id']) ?: null;
        if (isset($_POST['subject'])) $data['subject'] = sanitize_text_field($_POST['subject']);
        if (isset($_POST['content'])) $data['content'] = wp_kses_post($_POST['content']);
        if (isset($_POST['task_title'])) $data['task_title'] = sanitize_text_field($_POST['task_title']);
        if (isset($_POST['task_description'])) $data['task_description'] = sanitize_textarea_field($_POST['task_description']);
        if (isset($_POST['send_time_preference'])) $data['send_time_preference'] = sanitize_text_field($_POST['send_time_preference']);
        if (isset($_POST['skip_weekends'])) $data['skip_weekends'] = (bool) $_POST['skip_weekends'];

        $result = $sequence_model->update_step($step_id, $data);

        if (is_wp_error($result)) {
            wp_send_json_error(['message' => $result->get_error_message()], 400);
        }

        $steps = $sequence_model->get_steps($step['sequence_id']);

        wp_send_json_success([
            'steps' => $steps,
            'message' => 'Step updated',
        ]);
    }

