    /**
     * Reorder sequence steps
     */
    public function reorder_sequence_steps()
    {
        $user_id = $this->verify_request();

        $sequence_id = isset($_POST['sequence_id']) ? intval($_POST['sequence_id']) : 0;
        $step_ids = isset($_POST['step_ids']) ? json_decode(stripslashes($_POST['step_ids']), true) : [];

        if (!$sequence_id || empty($step_ids)) {
            wp_send_json_error(['message' => 'Sequence ID and step IDs required'], 400);
        }

        // Verify sequence ownership
        $sequence_model = new SFFC_CRM_Sequence();
        $sequence = $sequence_model->get($sequence_id);

        if (!$sequence || $sequence['user_id'] != $user_id) {
            wp_send_json_error(['message' => 'Sequence not found'], 404);
        }

        $result = $sequence_model->reorder_steps($sequence_id, $step_ids);

        if (is_wp_error($result)) {
            wp_send_json_error(['message' => $result->get_error_message()], 400);
        }

        $steps = $sequence_model->get_steps($sequence_id);

        wp_send_json_success([
            'steps' => $steps,
            'message' => 'Steps reordered',
        ]);
    }

