    /**
     * Get user enrollments
     */
    public function get_enrollments()
    {
        $user_id = $this->verify_request();

        $args = [
            'sequence_id' => isset($_POST['sequence_id']) ? intval($_POST['sequence_id']) : null,
            'recruiter_id' => isset($_POST['recruiter_id']) ? intval($_POST['recruiter_id']) : null,
            'status' => isset($_POST['status']) ? sanitize_text_field($_POST['status']) : null,
            'page' => isset($_POST['page']) ? intval($_POST['page']) : 1,
            'per_page' => isset($_POST['per_page']) ? intval($_POST['per_page']) : 20,
        ];

        $enrollment_model = new SFFC_CRM_Sequence_Enrollment();
        $enrollments = $enrollment_model->get_user_enrollments($user_id, $args);
        $total = $enrollment_model->get_user_enrollments($user_id, array_merge($args, ['count_only' => true]));

        wp_send_json_success([
            'enrollments' => $enrollments,
            'total' => $total,
            'page' => $args['page'],
            'per_page' => $args['per_page'],
            'total_pages' => ceil($total / $args['per_page']),
        ]);
    }

    /**
     * Enroll recruiter in sequence
     */
    public function enroll_recruiter()
    {
        $user_id = $this->verify_request();

        $sequence_id = isset($_POST['sequence_id']) ? intval($_POST['sequence_id']) : 0;
        $recruiter_id = isset($_POST['recruiter_id']) ? intval($_POST['recruiter_id']) : 0;
        $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : null;
        $personalization = isset($_POST['personalization']) ? json_decode(stripslashes($_POST['personalization']), true) : [];

        if (!$sequence_id || !$recruiter_id) {
            wp_send_json_error(['message' => 'Sequence ID and recruiter ID required'], 400);
        }

        $enrollment_model = new SFFC_CRM_Sequence_Enrollment();
        $enrollment_id = $enrollment_model->enroll($sequence_id, $user_id, $recruiter_id, $post_id, $personalization);

        if (is_wp_error($enrollment_id)) {
            wp_send_json_error(['message' => $enrollment_id->get_error_message()], 400);
        }

        $enrollment = $enrollment_model->get_with_details($enrollment_id, $user_id);

        wp_send_json_success([
            'enrollment' => $enrollment,
            'message' => 'Recruiter enrolled in sequence',
        ]);
    }

    /**
