     */
    public function bulk_enroll()
    {
        $user_id = $this->verify_request();

        $sequence_id = isset($_POST['sequence_id']) ? intval($_POST['sequence_id']) : 0;
        $recruiter_ids = isset($_POST['recruiter_ids']) ? json_decode(stripslashes($_POST['recruiter_ids']), true) : [];
