        if (!$sequence_id || empty($recruiter_ids)) {
            wp_send_json_error(['message' => 'Sequence ID and recruiter IDs required'], 400);
        }

        $enrollment_model = new SFFC_CRM_Sequence_Enrollment();
        $results = $enrollment_model->bulk_enroll($sequence_id, $user_id, $recruiter_ids, $post_id);

        wp_send_json_success([
            'enrolled' => $results['enrolled'],
            'failed' => $results['failed'],
            'skipped' => $results['skipped'],
            'message' => sprintf('%d recruiters enrolled', count($results['enrolled'])),
        ]);
    }

