    // ============================================
    // PHASE 5: Inbox/Conversations Handlers
    // ============================================

    /**
     * Get user's conversations
     */
    public function get_conversations()
    {
        $user_id = $this->verify_request();

        $conversation_model = new SFFC_CRM_Conversation();

        $args = [
            'status'   => sanitize_text_field($_POST['status'] ?? 'active'),
            'is_read'  => isset($_POST['is_read']) ? (int) $_POST['is_read'] : null,
            'starred'  => isset($_POST['starred']) && $_POST['starred'] === '1',
            'search'   => sanitize_text_field($_POST['search'] ?? ''),
            'limit'    => intval($_POST['limit'] ?? 20),
            'offset'   => intval($_POST['offset'] ?? 0),
            'orderby'  => 'last_message_at',
            'order'    => 'DESC',
        ];

        // Remove null values
        $args = array_filter($args, function ($v) {
            return $v !== null && $v !== '';
        });

        $conversations = $conversation_model->get_user_conversations($user_id, $args);
        $counts = $conversation_model->get_counts($user_id);

        // Enrich conversations with recruiter info
        $recruiter_model = new SFFC_CRM_Recruiter();
        $message_model = new SFFC_CRM_Message();

        foreach ($conversations as &$conv) {
            if ($conv['recruiter_id']) {
                $recruiter = $recruiter_model->get($conv['recruiter_id']);
                $conv['recruiter'] = $recruiter ? [
                    'id'    => $recruiter['id'],
                    'name'  => $recruiter['name'],
                    'firm'  => $recruiter['firm'],
                    'email' => $recruiter['email'],
                ] : null;
            }

            // Get latest message snippet
            $latest = $message_model->get_latest($conv['id']);
            if ($latest) {
                $conv['latest_message'] = [
                    'snippet'   => $latest['snippet'],
                    'direction' => $latest['direction'],
                    'sent_at'   => $latest['sent_at'],
                ];
            }
        }

        wp_send_json_success([
            'conversations' => $conversations,
            'counts'        => $counts,
        ]);
    }

    /**
     * Get single conversation with messages
     */
    public function get_conversation()
    {
        $user_id = $this->verify_request();

        $conversation_id = intval($_POST['conversation_id'] ?? 0);

        if (!$conversation_id) {
            wp_send_json_error(['message' => 'Conversation ID required'], 400);
        }

        $conversation_model = new SFFC_CRM_Conversation();
        $conversation = $conversation_model->get($conversation_id);

        if (!$conversation) {
            wp_send_json_error(['message' => 'Conversation not found'], 404);
        }

        if ($conversation['user_id'] != $user_id) {
            wp_send_json_error(['message' => 'Permission denied'], 403);
        }

        // Get messages
        $message_model = new SFFC_CRM_Message();
        $messages = $message_model->get_conversation_messages($conversation_id, [
            'limit' => 100,
            'order' => 'ASC',
        ]);

        // Get recruiter info
        $recruiter = null;
        if ($conversation['recruiter_id']) {
            $recruiter_model = new SFFC_CRM_Recruiter();
            $recruiter = $recruiter_model->get($conversation['recruiter_id']);
        }

        // Mark as read
        $conversation_model->mark_read($conversation_id, $user_id);

        wp_send_json_success([
            'conversation' => $conversation,
            'messages'     => $messages,
            'recruiter'    => $recruiter,
        ]);
    }

    /**
     * Get messages for a conversation (paginated)
     */
    public function get_conversation_messages()
    {
        $user_id = $this->verify_request();

        $conversation_id = intval($_POST['conversation_id'] ?? 0);

        if (!$conversation_id) {
            wp_send_json_error(['message' => 'Conversation ID required'], 400);
        }

        // Verify ownership
        $conversation_model = new SFFC_CRM_Conversation();
        $conversation = $conversation_model->get($conversation_id);

        if (!$conversation || $conversation['user_id'] != $user_id) {
            wp_send_json_error(['message' => 'Permission denied'], 403);
        }

        $message_model = new SFFC_CRM_Message();
        $messages = $message_model->get_conversation_messages($conversation_id, [
            'limit'  => intval($_POST['limit'] ?? 50),
            'offset' => intval($_POST['offset'] ?? 0),
            'order'  => sanitize_text_field($_POST['order'] ?? 'ASC'),
        ]);

        $total = $message_model->get_conversation_message_count($conversation_id);

        wp_send_json_success([
            'messages' => $messages,
            'total'    => $total,
        ]);
    }

    /**
     * Create a new conversation
     */
    public function create_conversation()
    {
        $user_id = $this->verify_request();

        $recruiter_id = intval($_POST['recruiter_id'] ?? 0);
        $subject = sanitize_text_field($_POST['subject'] ?? '');
        $channel = sanitize_text_field($_POST['channel'] ?? 'email');

        if (!$recruiter_id) {
            wp_send_json_error(['message' => 'Recruiter ID required'], 400);
        }

        // Verify recruiter exists
        $recruiter_model = new SFFC_CRM_Recruiter();
        $recruiter = $recruiter_model->get($recruiter_id);

        if (!$recruiter) {
            wp_send_json_error(['message' => 'Recruiter not found'], 404);
        }

        $conversation_model = new SFFC_CRM_Conversation();
        $conversation_id = $conversation_model->create($user_id, [
            'recruiter_id' => $recruiter_id,
            'subject'      => $subject,
            'channel'      => $channel,
        ]);

        if (is_wp_error($conversation_id)) {
            wp_send_json_error(['message' => $conversation_id->get_error_message()], 400);
        }

        $conversation = $conversation_model->get($conversation_id);

        wp_send_json_success([
            'conversation' => $conversation,
            'message'      => 'Conversation created',
        ]);
    }

    /**
     * Send a message in a conversation
     */
    public function send_message()
    {
        $user_id = $this->verify_request();

        $conversation_id = intval($_POST['conversation_id'] ?? 0);
        $body = isset($_POST['body']) ? wp_kses_post($_POST['body']) : '';

        if (!$conversation_id) {
            wp_send_json_error(['message' => 'Conversation ID required'], 400);
        }

        if (empty(trim(strip_tags($body)))) {
            wp_send_json_error(['message' => 'Message content required'], 400);
        }

        // Verify ownership
        $conversation_model = new SFFC_CRM_Conversation();
        $conversation = $conversation_model->get($conversation_id);

        if (!$conversation || $conversation['user_id'] != $user_id) {
            wp_send_json_error(['message' => 'Permission denied'], 403);
        }

        // Get user info for from fields
        $user = wp_get_current_user();

        $message_model = new SFFC_CRM_Message();
        $message_id = $message_model->create_outbound($conversation_id, [
            'subject'    => sanitize_text_field($_POST['subject'] ?? ''),
            'body_html'  => $body,
            'body_text'  => strip_tags($body),
            'from_email' => $user->user_email,
            'from_name'  => $user->display_name,
        ]);

        if (is_wp_error($message_id)) {
            wp_send_json_error(['message' => $message_id->get_error_message()], 400);
        }

        $message = $message_model->get($message_id);

        wp_send_json_success([
            'message' => $message,
            'notice'  => 'Message sent',
        ]);
    }

