    /**
     * Toggle conversation star status
     */
    public function toggle_conversation_star()
    {
        $user_id = $this->verify_request();

        $conversation_id = intval($_POST['conversation_id'] ?? 0);

        if (!$conversation_id) {
            wp_send_json_error(['message' => 'Conversation ID required'], 400);
        }

        $conversation_model = new SFFC_CRM_Conversation();
        $conversation = $conversation_model->get($conversation_id);

        if (!$conversation || $conversation['user_id'] != $user_id) {
            wp_send_json_error(['message' => 'Permission denied'], 403);
        }

        $result = $conversation_model->toggle_starred($conversation_id, $user_id);

        if (is_wp_error($result)) {
            wp_send_json_error(['message' => $result->get_error_message()], 400);
        }

        // Get updated conversation to return starred status
        $updated = $conversation_model->get($conversation_id);
        $is_starred = $updated ? (bool) $updated['is_starred'] : false;

        wp_send_json_success([
            'is_starred' => $is_starred,
            'message'    => $is_starred ? 'Starred' : 'Unstarred',
        ]);
    }

