    /**
     * Search conversations and messages
     */
    public function search_conversations()
    {
        $user_id = $this->verify_request();

        $query = sanitize_text_field($_POST['query'] ?? '');

        if (strlen($query) < 2) {
            wp_send_json_error(['message' => 'Search query too short'], 400);
        }

        $conversation_model = new SFFC_CRM_Conversation();
        $conversations = $conversation_model->search($user_id, $query, [
            'limit' => 20,
        ]);

        // Also search messages
        $message_model = new SFFC_CRM_Message();
        $messages = $message_model->search($user_id, $query, [
            'limit' => 20,
        ]);

        wp_send_json_success([
            'conversations' => $conversations,
            'messages'      => $messages,
