    /**
     * Save message draft (stored in user_meta)
     */
    public function save_message_draft()
    {
        $user_id = $this->verify_request();

        $conversation_id = intval($_POST['conversation_id'] ?? 0);
        $body = isset($_POST['body']) ? wp_kses_post($_POST['body']) : '';
        $subject = sanitize_text_field($_POST['subject'] ?? '');

        if (!$conversation_id) {
            wp_send_json_error(['message' => 'Conversation ID required'], 400);
        }

        // Verify ownership
        $conversation_model = new SFFC_CRM_Conversation();
        $conversation = $conversation_model->get($conversation_id);

        if (!$conversation || $conversation['user_id'] != $user_id) {
            wp_send_json_error(['message' => 'Permission denied'], 403);
        }

        // Store draft in user_meta
        $meta_key = 'sffc_crm_draft_' . $conversation_id;
        $draft_data = [
            'subject'    => $subject,
            'body'       => $body,
            'updated_at' => current_time('mysql'),
        ];

        update_user_meta($user_id, $meta_key, $draft_data);

        wp_send_json_success([
            'draft'   => $draft_data,
            'message' => 'Draft saved',
        ]);
    }

