    /**
     * Create a new alert
     */
    public function create_alert()
    {
        $user_id = $this->verify_request();

        $data = [
            'type'          => sanitize_text_field($_POST['type'] ?? ''),
            'name'          => sanitize_text_field($_POST['name'] ?? ''),
            'config'        => isset($_POST['config']) ? $_POST['config'] : [],
            'email_enabled' => isset($_POST['email_enabled']) ? (int) $_POST['email_enabled'] : 1,
        ];

        $alert_model = new SFFC_CRM_Alert();
        $alert_id = $alert_model->create($user_id, $data);

        if (is_wp_error($alert_id)) {
            wp_send_json_error(['message' => $alert_id->get_error_message()], 400);
        }

        $alert = $alert_model->get($alert_id);

        wp_send_json_success([
            'alert'   => $alert,
            'message' => 'Alert created',
        ]);
    }

    /**
     * Update an alert
     */
    public function update_alert()
    {
        $user_id = $this->verify_request();

        $alert_id = intval($_POST['alert_id'] ?? 0);

        if (!$alert_id) {
            wp_send_json_error(['message' => 'Alert ID required'], 400);
        }

        $data = [];

        if (isset($_POST['name'])) {
            $data['name'] = sanitize_text_field($_POST['name']);
        }

        if (isset($_POST['config'])) {
            $data['config'] = $_POST['config'];
        }

        if (isset($_POST['is_active'])) {
            $data['is_active'] = (int) $_POST['is_active'];
        }

        if (isset($_POST['email_enabled'])) {
            $data['email_enabled'] = (int) $_POST['email_enabled'];
        }

        $alert_model = new SFFC_CRM_Alert();
        $result = $alert_model->update($alert_id, $user_id, $data);

        if (is_wp_error($result)) {
            wp_send_json_error(['message' => $result->get_error_message()], 400);
        }

        $alert = $alert_model->get($alert_id);

        wp_send_json_success([
            'alert'   => $alert,
            'message' => 'Alert updated',
        ]);
    }

