    // ============================================
    // PHASE 6: Export Handlers
    // ============================================

    /**
     * Export data (CSV/JSON)
     */
    public function export_data()
    {
        $user_id = $this->verify_request();

        // Rate limiting for exports
        $rate_limiter = SFFC_CRM_Rate_Limiter::get_instance();
        $check = $rate_limiter->throttle('export', $user_id);
        if (is_wp_error($check)) {
            $rate_limiter->add_headers('export', $user_id);
            wp_send_json_error([
                'message' => $check->get_error_message(),
                'retry_after' => $check->get_error_data()['retry_after'] ?? 300,
            ], 429);
        }

        $type = sanitize_text_field($_POST['type'] ?? 'recruiters');
        $format = sanitize_text_field($_POST['format'] ?? 'csv');

        // Check if user has export permission (Insider tier)
        $mepr_integration = class_exists('SFFC_CRM_MemberPress_Integration')
            ? new SFFC_CRM_MemberPress_Integration()
            : null;

        if ($mepr_integration) {
            $features = apply_filters('sffc_crm_features', [], $user_id);
            if (empty($features['export'])) {
                wp_send_json_error([
                    'message'      => 'Export is available for Insider members',
                    'upgrade_url'  => $mepr_integration->get_upgrade_url('insider'),
                ], 403);
            }
        }

        $data = [];
        $filename = '';

        switch ($type) {
            case 'recruiters':
                $data = $this->export_recruiters($user_id);
                $filename = 'recruiters-export';
                break;

            case 'pipeline':
                $data = $this->export_pipeline($user_id);
                $filename = 'pipeline-export';
                break;

            case 'outreach':
                $data = $this->export_outreach($user_id);
                $filename = 'outreach-export';
                break;

            case 'analytics':
                $data = $this->export_analytics($user_id);
                $filename = 'analytics-export';
                break;

            default:
                wp_send_json_error(['message' => 'Invalid export type'], 400);
        }

        if ($format === 'csv') {
            $csv = $this->array_to_csv($data);
            wp_send_json_success([
                'content'  => $csv,
                'filename' => $filename . '-' . date('Y-m-d') . '.csv',
                'type'     => 'text/csv',
            ]);
        } else {
            wp_send_json_success([
                'content'  => wp_json_encode($data, JSON_PRETTY_PRINT),
                'filename' => $filename . '-' . date('Y-m-d') . '.json',
                'type'     => 'application/json',
            ]);
        }
    }

    /**
     * Export recruiters data
     */
    private function export_recruiters($user_id)
    {
        global $wpdb;

        $saved_table = $wpdb->prefix . 'sffc_crm_saved_recruiters';
        $recruiters_table = $wpdb->prefix . 'sffc_crm_recruiters';

        $recruiters = $wpdb->get_results($wpdb->prepare(
            "SELECT r.name, r.email, r.firm, r.title, r.linkedin_url,
                    r.sector, r.location, r.status, sr.saved_at
            FROM {$saved_table} sr
            INNER JOIN {$recruiters_table} r ON sr.recruiter_id = r.id
            WHERE sr.user_id = %d
            ORDER BY sr.saved_at DESC",
            $user_id
        ), ARRAY_A);

        return $recruiters;
    }

    /**
     * Export pipeline data
     */
    private function export_pipeline($user_id)
    {
        global $wpdb;

        $pipeline_table = $wpdb->prefix . 'sffc_crm_pipeline';
        $recruiters_table = $wpdb->prefix . 'sffc_crm_recruiters';
        $posts_table = $wpdb->prefix . 'sffc_crm_posts';

        $pipeline = $wpdb->get_results($wpdb->prepare(
            "SELECT r.name as recruiter_name, r.firm, p.role_title, pi.stage,
                    pi.outcome, pi.notes, pi.created_at, pi.updated_at
            FROM {$pipeline_table} pi
            LEFT JOIN {$recruiters_table} r ON pi.recruiter_id = r.id
            LEFT JOIN {$posts_table} p ON pi.post_id = p.id
            WHERE pi.user_id = %d
            ORDER BY pi.updated_at DESC",
            $user_id
        ), ARRAY_A);

        return $pipeline;
    }

    /**
     * Export outreach data
     */
    private function export_outreach($user_id)
    {
        global $wpdb;

        $outreach_table = $wpdb->prefix . 'sffc_crm_outreach';
        $recruiters_table = $wpdb->prefix . 'sffc_crm_recruiters';

        $outreach = $wpdb->get_results($wpdb->prepare(
            "SELECT r.name as recruiter_name, r.email as recruiter_email,
                    o.channel, o.subject, o.status, o.sent_at, o.opened_at, o.replied_at
            FROM {$outreach_table} o
            INNER JOIN {$recruiters_table} r ON o.recruiter_id = r.id
            WHERE o.user_id = %d
            ORDER BY o.sent_at DESC",
            $user_id
        ), ARRAY_A);

        return $outreach;
    }

    /**
     * Export analytics summary
     */
    private function export_analytics($user_id)
    {
        $analytics = new SFFC_CRM_Analytics();

        return [
            'overview'          => $analytics->get_overview_metrics($user_id, 'all'),
            'pipeline_funnel'   => $analytics->get_pipeline_funnel($user_id),
            'sequence_stats'    => $analytics->get_sequence_performance($user_id),
            'template_stats'    => $analytics->get_template_performance($user_id),
            'timing_analysis'   => $analytics->get_best_send_times($user_id),
            'sector_breakdown'  => $analytics->get_sector_performance($user_id),
            'exported_at'       => current_time('mysql'),
        ];
    }

    /**
     * Convert array to CSV string
     */
    private function array_to_csv($data)
    {
        if (empty($data)) {
            return '';
        }

        $output = fopen('php://temp', 'r+');

        // Headers
        fputcsv($output, array_keys($data[0]));

        // Data rows
        foreach ($data as $row) {
            fputcsv($output, $row);
        }

        rewind($output);
        $csv = stream_get_contents($output);
        fclose($output);

        return $csv;
    }

    // =========================================================================
    // Phase 7: Onboarding & Polish Handlers
    // =========================================================================

    /**
     * Complete onboarding
     */
    public function complete_onboarding()
    {
        $user_id = $this->verify_request();

        update_user_meta($user_id, 'sffc_crm_onboarding_complete', '1');
        update_user_meta($user_id, 'sffc_crm_onboarding_completed_at', current_time('mysql'));

        wp_send_json_success([
            'message' => __('Onboarding completed', 'senna-finance'),
            'completed_at' => current_time('mysql'),
        ]);
    }

    /**
     * Get onboarding status
     */
    public function get_onboarding_status()
    {
        $user_id = $this->verify_request();

        $complete = get_user_meta($user_id, 'sffc_crm_onboarding_complete', true) === '1';
        $completed_at = get_user_meta($user_id, 'sffc_crm_onboarding_completed_at', true);

        // Get progress indicators
        $has_saved_posts = $this->user_has_saved_posts($user_id);
        $has_saved_recruiters = $this->user_has_saved_recruiters($user_id);
        $has_pipeline_items = $this->user_has_pipeline_items($user_id);
        $has_sent_outreach = $this->user_has_sent_outreach($user_id);

        wp_send_json_success([
            'complete' => $complete,
            'completed_at' => $completed_at,
            'progress' => [
                'saved_posts' => $has_saved_posts,
                'saved_recruiters' => $has_saved_recruiters,
                'pipeline_items' => $has_pipeline_items,
                'sent_outreach' => $has_sent_outreach,
            ],
        ]);
    }

    /**
     * Reset onboarding (for testing)
     */
    public function reset_onboarding()
    {
        $user_id = $this->verify_request();

        // Only allow admins to reset onboarding
        if (!current_user_can('manage_options')) {
            wp_send_json_error(['message' => __('Unauthorized', 'senna-finance')], 403);
        }

        delete_user_meta($user_id, 'sffc_crm_onboarding_complete');
        delete_user_meta($user_id, 'sffc_crm_onboarding_completed_at');

        wp_send_json_success([
            'message' => __('Onboarding reset', 'senna-finance'),
        ]);
    }

