    /**
     * Check if user has sent outreach
     */
    private function user_has_sent_outreach($user_id)
    {
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_outreach';
        return (bool) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$table} WHERE user_id = %d AND status = 'sent'",
            $user_id
        ));
    }

    /**
     * Get rate limit status
     */
    public function get_rate_limit_status()
    {
        $user_id = $this->verify_request();

        $rate_limiter = SFFC_CRM_Rate_Limiter::get_instance();
        $actions = ['outreach_send', 'outreach_generate', 'search', 'export', 'compose_message'];

        $status = [];
        foreach ($actions as $action) {
            $status[$action] = $rate_limiter->get_remaining($action, $user_id);
