    // ============================================
    // CONTACTS (from newsroom terminal)
    // ============================================

    /**
     * Get contacts with filters and pagination
     */
    public function get_contacts()
    {
        check_ajax_referer('sffc_crm_nonce', 'nonce', false);

        $user_id = is_user_logged_in() ? get_current_user_id() : 0;

        // Check if user has premium membership
        $is_premium = false;
        if ($user_id && class_exists('SFFC_MemberPress_Integration')) {
            $mepr = SFFC_MemberPress_Integration::get_instance();
            $is_premium = $mepr->has_premium_access($user_id);
        }

        $args = [
            'page' => intval($_POST['page'] ?? 1),
            'per_page' => intval($_POST['per_page'] ?? 20),
            'search' => sanitize_text_field($_POST['search'] ?? ''),
            'country' => sanitize_text_field($_POST['country'] ?? ''),
            'seniority' => sanitize_text_field($_POST['seniority'] ?? ''),
            'industry' => sanitize_text_field($_POST['industry'] ?? ''),
            'company' => sanitize_text_field($_POST['company'] ?? ''),
            // Random order for all users
            'orderby' => 'rand',
            'order' => '',
        ];

        // Get contacts from the contacts database
        $result = SFFC_Contacts_Database::get_contacts($args);

        // Get saved contact IDs for current user
        $saved_ids = [];
        if ($user_id) {
            $saved_ids = get_user_meta($user_id, 'sffc_saved_contacts', true) ?: [];
            $saved_ids = array_map('intval', $saved_ids); // Ensure integer comparison
        }

        // Format contacts for frontend
        $contacts = [];
        $contact_index = 0;
        foreach ($result['contacts'] as $contact) {
            $contact_id = intval($contact->id);
            // For non-premium users: only first 3 contacts are visible, rest are blurred
            $is_blurred = !$is_premium && $contact_index >= 3;
            $contact_index++;

            $contacts[] = [
                'id' => $contact_id,
                'first_name' => $contact->first_name,
                'last_name' => $contact->last_name,
                'full_name' => trim($contact->first_name . ' ' . $contact->last_name),
                'email' => $contact->email,
                'phone' => $contact->phone_1,
                'job_title' => $contact->job_title,
                'seniority' => $contact->seniority,
                'departments' => $contact->departments,
                'linkedin_url' => $contact->linkedin_url,
                'city' => $contact->city,
                'country' => $contact->country,
                'company_name' => $contact->company_name ?? '',
                'company_industry' => $contact->main_industry ?? '',
                'company_size' => $contact->num_employees ?? '',
                'is_saved' => in_array($contact_id, $saved_ids, true) ? 1 : 0,
                'is_blurred' => $is_blurred ? 1 : 0,
            ];
        }

        wp_send_json_success([
            'contacts' => $contacts,
            'total' => $result['total'],
            'pages' => $result['pages'],
            'page' => $result['page'],
            'per_page' => $result['per_page'],
            'is_premium' => $is_premium,
        ]);
    }

    /**
     * Get single contact details
     */
    public function get_contact()
    {
        $user_id = $this->verify_request();

        $contact_id = intval($_POST['contact_id'] ?? 0);
        if (!$contact_id) {
            wp_send_json_error(['message' => 'Contact ID required'], 400);
        }

        $contact = SFFC_Contacts_Database::get_contact($contact_id);
        if (!$contact) {
            wp_send_json_error(['message' => 'Contact not found'], 404);
        }

        // Check if saved
        $is_saved = SFFC_Contacts_Database::is_contact_saved($user_id, $contact_id);

        // Get outreach data
        $outreach = SFFC_Contacts_Database::get_contact_outreach($user_id, $contact_id);

        wp_send_json_success([
            'contact' => [
                'id' => $contact->id,
                'first_name' => $contact->first_name,
                'last_name' => $contact->last_name,
                'full_name' => trim($contact->first_name . ' ' . $contact->last_name),
                'email' => $contact->email,
                'phone_1' => $contact->phone_1,
                'phone_1_type' => $contact->phone_1_type,
                'phone_2' => $contact->phone_2,
                'phone_2_type' => $contact->phone_2_type,
                'job_title' => $contact->job_title,
                'seniority' => $contact->seniority,
                'departments' => $contact->departments,
                'linkedin_url' => $contact->linkedin_url,
                'city' => $contact->city,
                'state' => $contact->state,
                'country' => $contact->country,
                'company_name' => $contact->company_name ?? '',
                'company_domain' => $contact->company_domain ?? '',
                'company_description' => $contact->company_description ?? '',
                'company_website' => $contact->company_website ?? '',
                'company_linkedin' => $contact->company_linkedin ?? '',
                'company_industry' => $contact->main_industry ?? '',
                'company_sub_industry' => $contact->sub_industry ?? '',
                'company_size' => $contact->num_employees ?? '',
                'company_revenue' => $contact->revenue ?? '',
                'is_saved' => $is_saved ? 1 : 0,
                'outreach' => $outreach ?: null,
            ],
        ]);
