    // =========================================================================
    // EXPERT REACH OUT HANDLERS
    // =========================================================================

    /**
     * Request expert outreach for a recruiter
     */
    public function request_expert_outreach()
    {
        $user_id = $this->verify_request();

        // Check expert outreach limits
        $mepr_integration = SFFC_CRM_MemberPress_Integration::get_instance();
        $limit_check = $mepr_integration->can_submit_expert_outreach($user_id);

        if (!$limit_check['allowed']) {
            $upgrade_url = $mepr_integration->get_upgrade_url('pro');
            wp_send_json_error([
                'message' => $limit_check['message'],
                'reason' => $limit_check['reason'],
                'upgrade_url' => $upgrade_url,
                'limit' => $limit_check['limit'],
                'used' => $limit_check['used']
            ], 403);
        }

        $recruiter_id = isset($_POST['recruiter_id']) ? absint($_POST['recruiter_id']) : 0;
        $contact_id = isset($_POST['contact_id']) ? absint($_POST['contact_id']) : 0;

        if (!$recruiter_id && !$contact_id) {
            wp_send_json_error(['message' => 'Recruiter or contact ID required'], 400);
        }

        $outreach = SFFC_CRM_Expert_Outreach::get_instance();

        // Check for existing pending request
        if ($recruiter_id && $outreach->has_pending_request($user_id, $recruiter_id)) {
            wp_send_json_error(['message' => 'You already have a pending request for this recruiter'], 400);
        }

        $data = [
            'recruiter_id' => $recruiter_id ?: null,
            'contact_id' => $contact_id ?: null,
            'request_type' => 'manual',
            'message_tone' => isset($_POST['message_tone']) ? sanitize_text_field($_POST['message_tone']) : 'professional',
            'custom_notes' => isset($_POST['custom_notes']) ? sanitize_textarea_field($_POST['custom_notes']) : '',
            'include_cv' => isset($_POST['include_cv']) ? (int) $_POST['include_cv'] : 1
        ];

        $request_id = $outreach->create_request($user_id, $data);

        if (!$request_id) {
            wp_send_json_error(['message' => 'Failed to create outreach request'], 500);
        }

        wp_send_json_success([
            'message' => 'Expert outreach request submitted successfully',
            'request_id' => $request_id
        ]);
    }

