    /**
     * Log contact activity
     */
    private function log_contact_activity($user_id, $contact_id, $type, $data = [])
    {
        global $wpdb;

        $activity_table = $wpdb->prefix . 'sffc_crm_activity';

        $wpdb->insert($activity_table, [
            'user_id' => $user_id,
            'recruiter_id' => null,
            'post_id' => null,
            'activity_type' => $type,
            'activity_data' => wp_json_encode(array_merge($data, ['contact_id' => $contact_id])),
        ]);
    }

    /**
     * Submit expert outreach from post article page
     * Creates/finds recruiter, adds to pipeline, creates outreach request, sends admin email
     */
    public function submit_expert_outreach_from_post()
    {
        // Use gap analyzer nonce
        if (!check_ajax_referer('sffc_gap_analyzer_nonce', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid security token'], 403);
        }

        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Please log in to use Expert Outreach'], 401);
        }

        $user_id = get_current_user_id();
        $user = get_userdata($user_id);

        // Check expert outreach limits
        $mepr_integration = SFFC_CRM_MemberPress_Integration::get_instance();
        $limit_check = $mepr_integration->can_submit_expert_outreach($user_id);

        if (!$limit_check['allowed']) {
            $upgrade_url = $mepr_integration->get_upgrade_url('pro');
            wp_send_json_error([
                'message' => $limit_check['message'],
                'reason' => $limit_check['reason'],
                'upgrade_url' => $upgrade_url,
                'limit' => $limit_check['limit'],
                'used' => $limit_check['used']
            ], 403);
        }

        // Get request data
        $post_id = isset($_POST['post_id']) ? absint($_POST['post_id']) : 0;
        $job_title = isset($_POST['job_title']) ? sanitize_text_field($_POST['job_title']) : '';
        $company_name = isset($_POST['company_name']) ? sanitize_text_field($_POST['company_name']) : '';
        $recruiter_name = isset($_POST['recruiter_name']) ? sanitize_text_field($_POST['recruiter_name']) : '';
        $recruiter_email = isset($_POST['recruiter_email']) ? sanitize_email($_POST['recruiter_email']) : '';
        $quantity = isset($_POST['quantity']) ? absint($_POST['quantity']) : 1;
        $include_similar = !empty($_POST['include_similar']);
        $recruiter_types = isset($_POST['recruiter_types']) ? array_map('sanitize_text_field', (array)$_POST['recruiter_types']) : [];
        $message_tone = isset($_POST['message_tone']) ? sanitize_text_field($_POST['message_tone']) : 'professional';
        $custom_notes = isset($_POST['custom_notes']) ? sanitize_textarea_field($_POST['custom_notes']) : '';
        $include_cv = isset($_POST['include_cv']) ? (int) $_POST['include_cv'] : 1;
        $cv_text = isset($_POST['cv_text']) ? sanitize_textarea_field($_POST['cv_text']) : '';

        // Validate quantity against remaining credits
        $remaining = $limit_check['remaining'];
        if ($remaining !== -1 && $quantity > $remaining) {
            wp_send_json_error([
                'message' => sprintf('You only have %d credits remaining this month. Please reduce the quantity.', $remaining),
                'reason' => 'insufficient_credits',
                'limit' => $limit_check['limit'],
                'used' => $limit_check['used'],
                'remaining' => $remaining
            ], 400);
        }

        if (!$post_id || !$job_title) {
            wp_send_json_error(['message' => 'Job information is required'], 400);
        }

        global $wpdb;
        $recruiter_id = null;

        // Try to find or create recruiter in CRM
        if ($recruiter_name || $recruiter_email) {
            $recruiters_table = $wpdb->prefix . 'sffc_crm_recruiters';

            // Check if recruiter exists by email
            if ($recruiter_email) {
                $existing = $wpdb->get_var($wpdb->prepare(
                    "SELECT id FROM $recruiters_table WHERE email = %s LIMIT 1",
                    $recruiter_email
                ));

                if ($existing) {
                    $recruiter_id = (int) $existing;
                }
            }

            // If not found by email, try by name and company
            if (!$recruiter_id && $recruiter_name) {
                $existing = $wpdb->get_var($wpdb->prepare(
                    "SELECT id FROM $recruiters_table WHERE name = %s AND (firm = %s OR firm IS NULL) LIMIT 1",
                    $recruiter_name,
                    $company_name
                ));

                if ($existing) {
                    $recruiter_id = (int) $existing;
                }
            }

            // Create recruiter if not found
            if (!$recruiter_id && ($recruiter_name || $recruiter_email)) {
                $recruiter_company = get_post_meta($post_id, '_recruiter_company', true);
                $recruiter_title = get_post_meta($post_id, '_recruiter_title', true);
                $recruiter_linkedin = get_post_meta($post_id, '_recruiter_linkedin', true);

                $wpdb->insert($recruiters_table, [
                    'name' => $recruiter_name ?: 'Unknown Recruiter',
                    'email' => $recruiter_email ?: null,
                    'firm' => $recruiter_company ?: $company_name,
                    'title' => $recruiter_title ?: null,
                    'linkedin_url' => $recruiter_linkedin ?: null,
                    'data_source' => 'post_article',
                    'is_active' => 1,
                    'created_at' => current_time('mysql'),
                    'updated_at' => current_time('mysql')
                ]);

                $recruiter_id = $wpdb->insert_id;
            }
        }

        // Add to user's pipeline if we have a recruiter
        if ($recruiter_id) {
            $pipeline_table = $wpdb->prefix . 'sffc_crm_pipeline';

            // Check if already in pipeline
            $existing_pipeline = $wpdb->get_var($wpdb->prepare(
                "SELECT id FROM $pipeline_table WHERE user_id = %d AND recruiter_id = %d LIMIT 1",
                $user_id,
                $recruiter_id
            ));

            if (!$existing_pipeline) {
                $wpdb->insert($pipeline_table, [
                    'user_id' => $user_id,
                    'recruiter_id' => $recruiter_id,
                    'post_id' => $post_id,
                    'stage' => 'messaged',
                    'role_title' => $job_title,
                    'company' => $company_name,
                    'notes' => "Added via Expert Outreach request",
                    'created_at' => current_time('mysql'),
                    'updated_at' => current_time('mysql')
                ]);
            }
        }

        // Create expert outreach request
        $outreach = SFFC_CRM_Expert_Outreach::get_instance();

        $outreach_data = [
            'recruiter_id' => $recruiter_id,
            'request_type' => $include_similar ? 'similar_recruiters' : 'manual',
            'message_tone' => $message_tone,
            'custom_notes' => $custom_notes,
            'include_cv' => $include_cv
        ];

        $request_id = $outreach->create_request($user_id, $outreach_data);

        if (!$request_id) {
            wp_send_json_error(['message' => 'Failed to create outreach request'], 500);
        }

        // Store additional request details in meta
        $outreach_table = $wpdb->prefix . 'sffc_crm_expert_outreach';
        $wpdb->update(
            $outreach_table,
            [
                'admin_notes' => wp_json_encode([
                    'post_id' => $post_id,
                    'job_title' => $job_title,
                    'company_name' => $company_name,
                    'recruiter_name' => $recruiter_name,
                    'recruiter_email' => $recruiter_email,
                    'quantity' => $quantity,
                    'include_similar' => $include_similar,
                    'recruiter_types' => $recruiter_types,
                    'cv_included' => $include_cv && !empty($cv_text),
                    'cv_length' => strlen($cv_text)
                ])
            ],
            ['id' => $request_id]
        );

        // Send admin email notification
        $this->send_expert_outreach_admin_email([
            'request_id' => $request_id,
            'user_id' => $user_id,
            'user_name' => $user->display_name,
            'user_email' => $user->user_email,
            'post_id' => $post_id,
            'job_title' => $job_title,
            'company_name' => $company_name,
            'recruiter_name' => $recruiter_name,
            'recruiter_email' => $recruiter_email,
            'quantity' => $quantity,
            'include_similar' => $include_similar,
            'recruiter_types' => $recruiter_types,
            'message_tone' => $message_tone,
            'custom_notes' => $custom_notes,
            'include_cv' => $include_cv,
            'cv_text' => $cv_text
        ]);

        // Log activity
        $activity_table = $wpdb->prefix . 'sffc_crm_activity';
        $wpdb->insert($activity_table, [
            'user_id' => $user_id,
            'recruiter_id' => $recruiter_id,
            'post_id' => $post_id,
            'activity_type' => 'expert_outreach_from_post',
            'activity_data' => wp_json_encode([
                'request_id' => $request_id,
                'job_title' => $job_title,
                'message_tone' => $message_tone
            ]),
            'created_at' => current_time('mysql')
        ]);

        wp_send_json_success([
            'message' => 'Expert outreach request submitted successfully',
            'request_id' => $request_id,
            'recruiter_id' => $recruiter_id
        ]);
    }

    /**
     * Send admin email notification for expert outreach request
     */
    private function send_expert_outreach_admin_email($data)
    {
        $admin_email = get_option('admin_email');

        $quantity = isset($data['quantity']) ? (int) $data['quantity'] : 1;
        $include_similar = !empty($data['include_similar']);

        $subject = sprintf(
            '[Expert Outreach Request] %s - %s (%d recruiter%s)',
            $data['job_title'],
            $data['user_name'],
            $quantity,
            $quantity > 1 ? 's' : ''
        );

        $message = "New Expert Outreach Request\n";
        $message .= "================================\n\n";

        $message .= "Request Details\n";
        $message .= "---------------\n";
        $message .= "Request ID: #{$data['request_id']}\n";
        $message .= "Submitted: " . current_time('mysql') . "\n";
        $message .= "Number of Recruiters: {$quantity}\n";
        $message .= "Include Similar Recruiters: " . ($include_similar ? 'Yes' : 'No') . "\n";
        if ($include_similar && !empty($data['recruiter_types'])) {
            $type_labels = [
                'same_firm' => 'Same Firm',
                'same_sector' => 'Same Sector',
                'similar_roles' => 'Similar Roles',
                'same_location' => 'Same Location'
            ];
            $types = array_map(function ($t) use ($type_labels) {
                return $type_labels[$t] ?? $t;
            }, $data['recruiter_types']);
            $message .= "Target Types: " . implode(', ', $types) . "\n";
        }
        $message .= "\n";

        $message .= "User Information\n";
        $message .= "----------------\n";
        $message .= "Name: {$data['user_name']}\n";
        $message .= "Email: {$data['user_email']}\n";
        $message .= "User ID: {$data['user_id']}\n\n";

        $message .= "Job Details\n";
        $message .= "-----------\n";
        $message .= "Position: {$data['job_title']}\n";
        if ($data['company_name']) {
            $message .= "Company: {$data['company_name']}\n";
        }
        $message .= "Post ID: {$data['post_id']}\n";
        $message .= "Post URL: " . get_permalink($data['post_id']) . "\n\n";

        $message .= "Recruiter Information\n";
        $message .= "---------------------\n";
        $message .= "Name: " . ($data['recruiter_name'] ?: 'Not provided') . "\n";
        $message .= "Email: " . ($data['recruiter_email'] ?: 'Not provided') . "\n\n";

        $message .= "Outreach Preferences\n";
        $message .= "--------------------\n";
        $message .= "Message Tone: " . ucfirst($data['message_tone']) . "\n";
        $message .= "Include CV: " . ($data['include_cv'] ? 'Yes' : 'No') . "\n\n";

        if ($data['custom_notes']) {
            $message .= "Special Instructions\n";
            $message .= "--------------------\n";
            $message .= $data['custom_notes'] . "\n\n";
        }

        if ($data['include_cv'] && !empty($data['cv_text'])) {
            $message .= "CV Content (" . strlen($data['cv_text']) . " characters)\n";
            $message .= "----------\n";
            // Include first 2000 chars of CV
            $message .= substr($data['cv_text'], 0, 2000);
            if (strlen($data['cv_text']) > 2000) {
                $message .= "\n... [truncated, see full CV in user profile]\n";
            }
            $message .= "\n\n";
        }

        $message .= "--------------------------------\n";
        $message .= "Action Required: Please review and send outreach within 24 hours.\n";
        $message .= "Admin Panel: " . admin_url('admin.php?page=sffc-crm-admin&tab=expert-outreach') . "\n";

        $headers = function_exists('sffc_crm_build_email_headers')
            ? sffc_crm_build_email_headers('admin_notifications', 'text/plain', ['Reply-To: ' . $data['user_email']])
            : [
                'Content-Type: text/plain; charset=UTF-8',
                'From: MENA Careers <noreply@' . parse_url(home_url(), PHP_URL_HOST) . '>',
                'Reply-To: ' . $data['user_email'],
            ];

        wp_mail($admin_email, $subject, $message, $headers);

        // Also send confirmation to user
        $this->send_expert_outreach_user_confirmation($data);
    }

