    /**
     * Submit custom expert request (for bulk recruiter outreach based on criteria)
     */
    public function submit_custom_expert_request()
    {
        $this->verify_request();
        $user_id = get_current_user_id();

        // Check expert outreach limits
        $mepr_integration = SFFC_CRM_MemberPress_Integration::get_instance();
        $limit_check = $mepr_integration->can_submit_expert_outreach($user_id);

        if (!$limit_check['allowed']) {
            $upgrade_url = $mepr_integration->get_upgrade_url('pro');
            wp_send_json_error([
                'message' => $limit_check['message'],
                'reason' => $limit_check['reason'],
                'upgrade_url' => $upgrade_url,
                'limit' => $limit_check['limit'],
                'used' => $limit_check['used']
            ], 403);
        }

        // Get form data
        $sectors = isset($_POST['sectors']) ? array_map('sanitize_text_field', (array)$_POST['sectors']) : [];
        $seniority = isset($_POST['seniority']) ? array_map('sanitize_text_field', (array)$_POST['seniority']) : [];
        $locations = sanitize_text_field($_POST['locations'] ?? '');
        $firms = sanitize_textarea_field($_POST['firms'] ?? '');
        $quantity = intval($_POST['quantity'] ?? 10);
        $message_tone = sanitize_text_field($_POST['message_tone'] ?? 'professional');
        $notes = sanitize_textarea_field($_POST['notes'] ?? '');
        $include_cv = !empty($_POST['include_cv']);

        // Validation
        if (empty($sectors)) {
            wp_send_json_error(['message' => 'Please select at least one target sector'], 400);
        }

        if (empty($notes)) {
            wp_send_json_error(['message' => 'Please provide additional notes about your request'], 400);
        }

        // Handle CV file upload
        $cv_attachment_id = 0;
        $cv_file_url = '';
        if (!empty($_FILES['cv_file']) && $_FILES['cv_file']['error'] === UPLOAD_ERR_OK) {
            // Validate file type
            $allowed_types = ['application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
            $file_type = wp_check_filetype($_FILES['cv_file']['name']);
            $mime_type = $_FILES['cv_file']['type'];

            if (!in_array($mime_type, $allowed_types)) {
                wp_send_json_error(['message' => 'Invalid file type. Please upload a PDF or Word document.'], 400);
            }

            // Validate file size (5MB max)
            if ($_FILES['cv_file']['size'] > 5 * 1024 * 1024) {
                wp_send_json_error(['message' => 'File too large. Maximum size is 5MB.'], 400);
            }

            // Upload the file
            require_once(ABSPATH . 'wp-admin/includes/file.php');
            require_once(ABSPATH . 'wp-admin/includes/media.php');
            require_once(ABSPATH . 'wp-admin/includes/image.php');

            $upload = wp_handle_upload($_FILES['cv_file'], ['test_form' => false]);

            if (!empty($upload['error'])) {
                wp_send_json_error(['message' => 'File upload failed: ' . $upload['error']], 500);
            }

            // Create attachment post
            $attachment = [
                'guid' => $upload['url'],
                'post_mime_type' => $upload['type'],
                'post_title' => sanitize_file_name($_FILES['cv_file']['name']),
                'post_content' => '',
                'post_status' => 'private'
            ];

            $cv_attachment_id = wp_insert_attachment($attachment, $upload['file']);
            $cv_file_url = $upload['url'];
        }

        // Get user info
        $user = get_user_by('id', $user_id);
        $user_email = $user->user_email;
        $user_name = $user->display_name;

        // Get user's CV if available
        $cv_text = '';
        if ($include_cv) {
            $cv_text = get_user_meta($user_id, 'sffc_cv_text', true);
        }

        // Store the custom request in the database
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_expert_outreach';

        $request_data = [
            'sectors' => $sectors,
            'seniority' => $seniority,
            'locations' => $locations,
            'firms' => $firms,
            'quantity' => $quantity,
            'message_tone' => $message_tone,
            'notes' => $notes,
            'include_cv' => $include_cv,
            'request_type' => 'custom_bulk',
            'cv_attachment_id' => $cv_attachment_id,
            'cv_file_url' => $cv_file_url
        ];

        $wpdb->insert($table, [
            'user_id' => $user_id,
            'recruiter_id' => 0, // No specific recruiter for custom requests
            'message_tone' => $message_tone,
            'custom_notes' => wp_json_encode($request_data),
            'include_cv' => $include_cv ? 1 : 0,
            'status' => 'pending',
            'created_at' => current_time('mysql'),
            'updated_at' => current_time('mysql')
        ]);

        $request_id = $wpdb->insert_id;

        if (!$request_id) {
            wp_send_json_error(['message' => 'Failed to create request'], 500);
        }

        // Send admin email
        $this->send_custom_request_admin_email([
            'request_id' => $request_id,
            'user_id' => $user_id,
            'user_name' => $user_name,
            'user_email' => $user_email,
            'sectors' => $sectors,
            'seniority' => $seniority,
            'locations' => $locations,
            'firms' => $firms,
            'quantity' => $quantity,
            'message_tone' => $message_tone,
            'notes' => $notes,
            'include_cv' => $include_cv,
            'cv_text' => $cv_text,
            'cv_file_url' => $cv_file_url
        ]);

        // Send user confirmation
        $this->send_custom_request_user_confirmation([
            'user_email' => $user_email,
            'user_name' => $user_name,
            'sectors' => $sectors,
            'quantity' => $quantity
        ]);

        // Log activity
        $activity_table = $wpdb->prefix . 'sffc_crm_activity_log';
        $wpdb->insert($activity_table, [
            'user_id' => $user_id,
            'recruiter_id' => 0,
            'activity_type' => 'custom_expert_request',
            'activity_data' => wp_json_encode($request_data),
            'created_at' => current_time('mysql')
        ]);

        wp_send_json_success([
            'message' => 'Custom expert request submitted successfully',
            'request_id' => $request_id
        ]);
    }

