    /**
     * Get user's expert outreach status (limits, usage, remaining)
     * Accepts both CRM nonce and gap analyzer nonce for cross-context compatibility
     */
    public function get_expert_outreach_status()
    {
        // Accept either CRM nonce or gap analyzer nonce
        $crm_nonce_valid = check_ajax_referer('sffc_crm_nonce', 'nonce', false);
        $gap_nonce_valid = check_ajax_referer('sffc_gap_analyzer_nonce', 'nonce', false);

        if (!$crm_nonce_valid && !$gap_nonce_valid) {
            wp_send_json_error(['message' => 'Invalid security token'], 403);
        }

        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Please log in'], 401);
        }
        $user_id = get_current_user_id();

        $mepr_integration = SFFC_CRM_MemberPress_Integration::get_instance();
        $limit_check = $mepr_integration->can_submit_expert_outreach($user_id);
        $tier = $mepr_integration->get_crm_tier($user_id);

        $response = [
            'tier' => $tier,
            'tier_label' => ucfirst($tier),
            'allowed' => $limit_check['allowed'],
            'limit' => $limit_check['limit'],
            'used' => $limit_check['used'],
            'remaining' => $limit_check['remaining'] ?? ($limit_check['limit'] === -1 ? -1 : max(0, $limit_check['limit'] - $limit_check['used'])),
            'is_unlimited' => $limit_check['limit'] === -1,
            'has_access' => $limit_check['limit'] !== 0,
            'resets_on' => date('F 1, Y', strtotime('first day of next month')),
        ];

        if (!$limit_check['allowed'] && isset($limit_check['reason'])) {
            $response['reason'] = $limit_check['reason'];
            $response['message'] = $limit_check['message'];
            $response['upgrade_url'] = $mepr_integration->get_upgrade_url('pro');
        }

        wp_send_json_success($response);
    }

    /**
     * Track application from Express Interest form
     * Uses express_interest_nonce from recruiter post article
     */
    public function save_applicant()
    {
        if (!check_ajax_referer('sffc_express_interest_nonce', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid security token'], 403);
        }

        $payload = wp_unslash($_POST);
        $post_id = isset($payload['post_id']) ? intval($payload['post_id']) : 0;
        $crm_post_id = isset($payload['crm_post_id']) ? intval($payload['crm_post_id']) : 0;
        $recruiter_id = isset($payload['recruiter_id']) ? intval($payload['recruiter_id']) : 0;
        $job_title = sanitize_text_field($payload['job_title'] ?? '');
        $company = sanitize_text_field($payload['company_name'] ?? '');
        $first_name = sanitize_text_field($payload['first_name'] ?? '');
        $last_name = sanitize_text_field($payload['last_name'] ?? '');
        $email = sanitize_email($payload['email'] ?? '');
        $materials = isset($payload['materials']) ? array_map('sanitize_text_field', (array) $payload['materials']) : [];
        $source = sanitize_text_field($payload['source'] ?? 'wp');

        if (!$first_name || !$last_name || !$email) {
            wp_send_json_error(['message' => 'Missing applicant details'], 400);
        }

        $form_data = $payload;
        unset($form_data['nonce'], $form_data['action']);

        $applicant_model = new SFFC_CRM_Applicant();
        $result = $applicant_model->log_applicant([
            'user_id' => is_user_logged_in() ? get_current_user_id() : 0,
            'recruiter_post_id' => $post_id,
            'crm_post_id' => $crm_post_id,
            'recruiter_id' => $recruiter_id,
            'job_title' => $job_title,
            'company' => $company,
            'first_name' => $first_name,
            'last_name' => $last_name,
            'email' => $email,
            'materials' => $materials,
            'source' => $source,
            'form_data' => $form_data,
        ]);

        if (is_wp_error($result)) {
            wp_send_json_error(['message' => $result->get_error_message()], 500);
        }

        $this->send_applicant_followup_email([
            'first_name' => $first_name,
            'email'      => $email,
            'job_title'  => $job_title,
            'company'    => $company,
        ]);

        $this->notify_admin_of_application([
            'first_name' => $first_name,
            'last_name'  => $last_name,
            'email'      => $email,
            'job_title'  => $job_title,
            'company'    => $company,
            'match_score' => sanitize_text_field($payload['match_score'] ?? ''),
            'match_bucket' => sanitize_text_field($payload['match_bucket'] ?? ''),
            'action_taken' => sanitize_text_field($payload['action_taken'] ?? ''),
            'knockout_answers' => $payload['knockout_answers'] ?? [],
            'crm_post_id' => $crm_post_id,
        ]);

        wp_send_json_success(['message' => 'Applicant saved']);
    }

    /**
     * Email applicant after they submit the express-interest form
     */
    private function send_applicant_followup_email($args = [])
    {
        $email = sanitize_email($args['email'] ?? '');
        if (!$email) {
            return;
        }

        $locale = sanitize_text_field($args['locale'] ?? get_locale());
        $is_arabic = strpos(strtolower(str_replace('-', '_', (string) $locale)), 'ar') === 0;
        $first_name = sanitize_text_field($args['first_name'] ?? '');
        $job_title = sanitize_text_field($args['job_title'] ?? '');
        $company = sanitize_text_field($args['company'] ?? '');

        $job_label = $job_title ? $job_title : ($is_arabic ? 'هذه الفرصة' : __('this role', 'senna-finance'));
        if ($company) {
            $job_label .= $is_arabic ? sprintf(' لدى %s', $company) : sprintf(__(' at %s', 'senna-finance'), $company);
        }

        $subject = $is_arabic
            ? sprintf('هل أكملت التقديم على %s؟', $job_label)
            : sprintf(__('Did you finish your %s application?', 'senna-finance'), $job_label);

        $greeting = $first_name
            ? ($is_arabic ? sprintf('مرحباً %s،', $first_name) : sprintf(__('Hi %s,', 'senna-finance'), $first_name))
            : ($is_arabic ? 'مرحباً،' : __('Hi there,', 'senna-finance'));

        $benefits = $is_arabic
            ? [
                'مدرب مهني مخصص مع مكالمات متابعة أسبوعية حتى يبقى كل تقديم على المسار الصحيح.',
                'وصول مباشر إلى جهات التوظيف مع تقديمات دافئة إلى مسؤولين موثوقين وفرص غير معلنة.',
                'مواد يعدها سنّا لك مثل السيرة وخطابات التقديم ورسائل التواصل المبنية على ملفك.',
            ]
            : [
                __('Dedicated Career Coach - weekly accountability calls so every application stays on track.', 'senna-finance'),
                __('Direct Recruiter Access - warm introductions to vetted recruiters and hidden mandates.', 'senna-finance'),
                __('MENA Careers-Generated Materials - CVs, cover letters, and outreach scripts built from your profile.', 'senna-finance'),
            ];

        $message = $greeting . "\n\n";
        $message .= $is_arabic
            ? sprintf("شكراً لاستخدامك سنّا بخصوص %s. هل تمكنت من إرسال التقديم الكامل؟", $job_label) . "\n\n"
            : sprintf(__('Thanks for using MENA Careers to reach out about %s. Did you manage to submit the full application?', 'senna-finance'), $job_label) . "\n\n";
        $message .= $is_arabic
            ? "إذا كنت ما زلت تحتاج مساعدة، فقط رد على هذا البريد وسيساعدك الفريق في الخطوات التالية أو يوصلك بجهة توظيف مناسبة.\n\n"
            : __('If you still need help, reply to this email and the team can walk you through next steps or pair you with a recruiter.', 'senna-finance') . "\n\n";
        $message .= $is_arabic ? "هذا ما تفتحه العضوية المدفوعة:\n" : __('Here is what Premium members unlock:', 'senna-finance') . "\n";
        foreach ($benefits as $benefit) {
            $message .= '• ' . $benefit . "\n";
        }
        $message .= "\n";
        $message .= $is_arabic
            ? "إذا أردت متابعة سريعة، يمكننا ترتيب مكالمة قصيرة لمراجعة طريقتك وموادك قبل التقديم.\n\n"
            : __('Need a quick check-in? We can hop on a call to review your workflow and materials before you apply.', 'senna-finance') . "\n\n";
        $message .= $is_arabic
            ? "مع التحية،\nفريق سنّا"
            : __('Best,', 'senna-finance') . "\n" . __('The MENA Careers Team', 'senna-finance');

        $headers = [
            'Content-Type: text/plain; charset=UTF-8',
            'From: MENA Careers <support.team@joinsenna.com>'
        ];

        wp_mail($email, $subject, $message, $headers);
    }

    private function notify_admin_of_application($args = [])
    {
        $admin_email = get_option('admin_email');
        if (!$admin_email) {
            return;
        }

        $to = apply_filters('sffc_job_apply_notification_email', $admin_email, $args);
        $job_title = sanitize_text_field($args['job_title'] ?? '');
        $company = sanitize_text_field($args['company'] ?? '');
        $candidate_name = trim(sanitize_text_field($args['first_name'] ?? '') . ' ' . sanitize_text_field($args['last_name'] ?? ''));
        $email = sanitize_email($args['email'] ?? '');
        $match_score = sanitize_text_field($args['match_score'] ?? '');
        $match_bucket = sanitize_text_field($args['match_bucket'] ?? '');
        $action_taken = sanitize_text_field($args['action_taken'] ?? '');

        $subject_parts = array_filter([$job_title ?: __('New applicant', 'senna-finance'), $company]);
        $subject = sprintf(__('New job apply submission: %s', 'senna-finance'), implode(' @ ', $subject_parts));

        $lines = [];
        $lines[] = sprintf(__('Candidate: %s (%s)', 'senna-finance'), $candidate_name ?: __('Unknown', 'senna-finance'), $email ?: __('no email', 'senna-finance'));
        if ($job_title) {
            $lines[] = sprintf(__('Role: %s %s', 'senna-finance'), $job_title, $company ? sprintf(__('at %s', 'senna-finance'), $company) : '');
        }
        if ($match_score !== '') {
            $bucket_label = $match_bucket ? sprintf(__('bucket: %s', 'senna-finance'), $match_bucket) : '';
            $lines[] = trim(sprintf(__('Match score: %s%% %s', 'senna-finance'), $match_score, $bucket_label));
        }
        if ($action_taken) {
            $lines[] = sprintf(__('Action: %s', 'senna-finance'), $action_taken);
        }
        if (!empty($args['crm_post_id'])) {
            $lines[] = sprintf(__('CRM Post ID: %d', 'senna-finance'), intval($args['crm_post_id']));
        }

        $answers = $args['knockout_answers'] ?? [];
        if (!empty($answers) && is_array($answers)) {
            $lines[] = '';
            $lines[] = __('Knock-out responses:', 'senna-finance');
            foreach ($answers as $answer) {
                if (!is_array($answer)) {
                    continue;
                }
                $prompt = sanitize_text_field($answer['prompt'] ?? '');
                $value = sanitize_text_field($answer['answer'] ?? '');
                $expected = sanitize_text_field($answer['expected'] ?? '');
                if (!$prompt) {
                    continue;
                }
                $lines[] = sprintf('- %s: %s %s', $prompt, $value ?: __('Not provided', 'senna-finance'), $expected ? sprintf('(%s %s)', __('ideal', 'senna-finance'), $expected) : '');
            }
        }

        $headers = ['Content-Type: text/plain; charset=UTF-8'];
        wp_mail($to, $subject, implode("\n", $lines), $headers);
    }

    public function track_application()
    {
        // Verify nonce - allow either the job-apply express nonce or the CRM nonce
        $nonce_valid = check_ajax_referer('sffc_express_interest_nonce', 'nonce', false);
        if (!$nonce_valid) {
            $nonce_valid = check_ajax_referer('sffc_crm_nonce', 'nonce', false);
        }

        if (!$nonce_valid) {
            wp_send_json_error(['message' => 'Invalid security token'], 403);
        }

        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => 'Please log in to track applications'], 401);
        }

        $user_id = get_current_user_id();
        $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;
        $first_name = isset($_POST['first_name']) ? sanitize_text_field($_POST['first_name']) : '';
        $last_name = isset($_POST['last_name']) ? sanitize_text_field($_POST['last_name']) : '';
        $email = isset($_POST['email']) ? sanitize_email($_POST['email']) : '';
        $materials = isset($_POST['materials']) ? array_map('sanitize_text_field', (array) $_POST['materials']) : [];

        if (!$post_id) {
            wp_send_json_error(['message' => 'Invalid post ID'], 400);
        }

        // Try to add to pipeline
        try {
            $pipeline = new SFFC_CRM_Pipeline();

            // Check if already in pipeline
            $existing = $pipeline->get_by_post($user_id, $post_id);

            if ($existing) {
                // Update existing entry
                $pipeline->update_stage($existing['id'], 'applied', $user_id);
                $result_id = $existing['id'];
            } else {
                // Add new entry
                $result_id = $pipeline->add([
                    'user_id' => $user_id,
                    'post_id' => $post_id,
                    'stage' => 'applied',
                    'source' => 'express_interest',
                    'notes' => json_encode([
                        'first_name' => $first_name,
                        'last_name' => $last_name,
                        'email' => $email,
                        'materials' => $materials,
                        'applied_at' => current_time('mysql'),
                    ]),
                ]);
            }

            if ($result_id) {
                wp_send_json_success([
                    'message' => 'Application tracked successfully',
                    'pipeline_id' => $result_id,
                ]);
            } else {
                wp_send_json_error(['message' => 'Failed to track application'], 500);
            }
        } catch (Exception $e) {
            wp_send_json_error(['message' => $e->getMessage()], 500);
        }
    }

    /**
     * Add contact to outreach list
     */
    public function add_contact_to_list()
    {
        $user_id = $this->verify_request();

        $contact_id = intval($_POST['contact_id'] ?? 0);

        if (!$contact_id) {
            wp_send_json_error(['message' => 'Contact ID required'], 400);
        }

        // Use existing SFFC_Contacts_Database method
        SFFC_Contacts_Database::save_contact($user_id, $contact_id);

        // Log activity
        $this->log_contact_activity($user_id, $contact_id, 'contact_added_to_list');

        wp_send_json_success(['message' => 'Added to outreach list']);
    }

    /**
     * Remove contact from outreach list
     */
    public function remove_contact_from_list()
    {
        $user_id = $this->verify_request();

        $contact_id = intval($_POST['contact_id'] ?? 0);

        if (!$contact_id) {
            wp_send_json_error(['message' => 'Contact ID required'], 400);
        }

        // Use existing SFFC_Contacts_Database method
        SFFC_Contacts_Database::unsave_contact($user_id, $contact_id);

        // Log activity
        $this->log_contact_activity($user_id, $contact_id, 'contact_removed_from_list');

        wp_send_json_success(['message' => 'Removed from outreach list']);
    }

    /**
     * Bulk add contacts to list
     */
    public function bulk_add_to_list()
    {
        $user_id = $this->verify_request();

        $contact_ids = isset($_POST['contact_ids']) ? array_map('intval', (array) $_POST['contact_ids']) : [];

        if (empty($contact_ids)) {
            wp_send_json_error(['message' => 'No contacts selected'], 400);
        }

        // Get currently saved contacts
        $saved = get_user_meta($user_id, 'sffc_saved_contacts', true) ?: [];
        $added = 0;

        foreach ($contact_ids as $contact_id) {
            if (!$contact_id) continue;

            if (!in_array($contact_id, $saved)) {
                $saved[] = $contact_id;
                $added++;

                // Log activity
                $this->log_contact_activity($user_id, $contact_id, 'contact_added_to_list');
            }
        }

        // Update user meta with all saved contacts
        update_user_meta($user_id, 'sffc_saved_contacts', $saved);

        wp_send_json_success([
            'message' => $added . ' contacts added to list',
            'added' => $added,
        ]);
    }

    /**
     * Generate bulk message template using AI
     */
    public function generate_bulk_message()
    {
        $user_id = $this->verify_request();

        $contact_count = intval($_POST['contact_count'] ?? 0);

        // Get user info for personalization
        $user = wp_get_current_user();
        $user_meta = get_user_meta($user_id);
        $current_role = isset($user_meta['current_role'][0]) ? $user_meta['current_role'][0] : '';
        $current_company = isset($user_meta['current_company'][0]) ? $user_meta['current_company'][0] : '';

        // Default template
        $template = "Hi {name},\n\n";
        $template .= "I came across your profile and was impressed by your experience at {company}. ";
        $template .= "I'm currently exploring opportunities in finance and would love to connect and learn about your journey.\n\n";
        $template .= "Would you be open to a brief chat?\n\n";
        $template .= "Best regards";

        // Try to use Claude API for better message generation
        $api_key = defined('ANTHROPIC_API_KEY') ? ANTHROPIC_API_KEY : get_option('sffc_api_key');

        // Fallback to other possible option names
        if (empty($api_key)) {
            $api_key = get_option('sffc_anthropic_api_key');
        }
        if (empty($api_key)) {
            $api_key = get_option('sffc_anthropic_key');
        }
        if (empty($api_key)) {
            $api_key = get_option('sffc_anthropic_key', '');
        }

        if (!empty($api_key)) {
            $prompt = "Generate a professional networking outreach message template for reaching out to recruiters/contacts in finance.\n\n";
            $prompt .= "Sender: {$user->display_name}";
            if ($current_role) {
                $prompt .= ", currently {$current_role}";
            }
            if ($current_company) {
                $prompt .= " at {$current_company}";
            }
            $prompt .= "\n\n";
            $prompt .= "Use these placeholders for personalization:\n";
            $prompt .= "- {name} for the recipient's name\n";
            $prompt .= "- {company} for their company\n";
            $prompt .= "- {title} for their title\n\n";
            $prompt .= "Requirements:\n";
            $prompt .= "- Warm but professional tone\n";
            $prompt .= "- Concise (under 150 words)\n";
            $prompt .= "- Express genuine interest in connecting\n";
            $prompt .= "- Do NOT include a subject line, just the message body\n";
            $prompt .= "- Do NOT use generic phrases like 'I hope this email finds you well'\n";
            $prompt .= "\nWrite the message now:";

            $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
                'timeout' => 30,
                'headers' => [
                    'Content-Type' => 'application/json',
                    'x-api-key' => $api_key,
                    'anthropic-version' => '2023-06-01',
                ],
                'body' => json_encode([
                    'model' => 'claude-3-haiku-20240307',
                    'max_tokens' => 500,
                    'messages' => [
                        ['role' => 'user', 'content' => $prompt]
                    ],
                ]),
            ]);

            if (!is_wp_error($response)) {
                $body = json_decode(wp_remote_retrieve_body($response), true);
                if (!empty($body['content'][0]['text'])) {
                    $template = trim($body['content'][0]['text']);
                }
            }
        }

        wp_send_json_success([
            'content' => $template,
        ]);
    }

    /**
     * Send bulk outreach to multiple contacts
     * Note: This creates outreach records for tracking. Actual email sending
     * would be handled separately or via copy-to-clipboard flow.
     */
    public function send_bulk_outreach()
    {
        $user_id = $this->verify_request();

        $contacts = isset($_POST['contacts']) ? (array) $_POST['contacts'] : [];
        $message = sanitize_textarea_field($_POST['message'] ?? '');
        $personalize = isset($_POST['personalize']) && $_POST['personalize'] === 'true';

        if (empty($contacts)) {
            wp_send_json_error(['message' => 'No contacts selected'], 400);
        }

        if (empty($message)) {
            wp_send_json_error(['message' => 'Message is required'], 400);
        }

        $outreach_model = new SFFC_CRM_Outreach();
        $sent_count = 0;
        $errors = [];
        $messages = [];

        foreach ($contacts as $contact) {
            $contact_id = intval($contact['id'] ?? 0);
            $contact_name = sanitize_text_field($contact['name'] ?? '');
            $contact_email = sanitize_email($contact['email'] ?? '');

            if (!$contact_id) continue;

            // Personalize message by replacing placeholders
            $personalized_message = str_replace(
                ['{name}', '{company}', '{title}'],
                [$contact_name, '', ''],
                $message
            );

            // Store the personalized message for clipboard
            $messages[] = [
                'contact_id' => $contact_id,
                'name' => $contact_name,
                'email' => $contact_email,
                'message' => $personalized_message,
            ];

            // Create outreach record for tracking
            // Note: For contacts (not recruiters), we track via activity log instead
            $this->log_contact_activity($user_id, $contact_id, 'bulk_outreach_created', [
                'message_preview' => substr($personalized_message, 0, 100),
                'channel' => 'email',
            ]);

            $sent_count++;
        }

        if ($sent_count > 0) {
            wp_send_json_success([
                'message' => "Outreach prepared for $sent_count contacts. Messages have been personalized and are ready to send.",
                'sent' => $sent_count,
                'messages' => $messages,
                'errors' => $errors,
            ]);
        } else {
            wp_send_json_error([
                'message' => 'Failed to prepare outreach',
                'errors' => $errors,
            ], 500);
        }
    }

    /**
     * Get compose data for a contact (not a recruiter)
     */
    public function get_contact_compose_data()
    {
        $user_id = $this->verify_request();

        $contact_id = isset($_POST['contact_id']) ? intval($_POST['contact_id']) : 0;

        if (!$contact_id) {
            wp_send_json_error(['message' => 'Contact ID required'], 400);
        }

        // Get contact from contacts database
        $contact = SFFC_Contacts_Database::get_contact($contact_id);

        if (!$contact) {
            wp_send_json_error(['message' => 'Contact not found'], 404);
        }

        // Get user profile and CV context
        $user = wp_get_current_user();
        $user_meta = get_user_meta($user_id);
        $cv_context = get_user_meta($user_id, 'sffc_cv_context', true) ?: '';
        $has_cv = !empty($cv_context);

        // Get outreach list count
        $saved_contacts = get_user_meta($user_id, 'sffc_saved_contacts', true) ?: [];
        $list_count = count($saved_contacts);

        $candidate = [
            'name' => $user->display_name,
            'first_name' => $user->first_name ?: explode(' ', $user->display_name)[0],
            'email' => $user->user_email,
            'current_role' => isset($user_meta['current_role'][0]) ? $user_meta['current_role'][0] : '',
            'company' => isset($user_meta['current_company'][0]) ? $user_meta['current_company'][0] : '',
            'experience' => isset($user_meta['experience_summary'][0]) ? $user_meta['experience_summary'][0] : '',
        ];

        // Build variables for template
        $variables = [
            'contact_name' => $contact->first_name ?: explode(' ', trim($contact->first_name . ' ' . $contact->last_name))[0],
            'contact_full_name' => trim($contact->first_name . ' ' . $contact->last_name),
            'contact_company' => $contact->company_name ?: '',
            'contact_title' => $contact->job_title ?: '',
            'candidate_name' => $candidate['name'],
            'candidate_first_name' => $candidate['first_name'],
            'candidate_role' => $candidate['current_role'],
            'candidate_company' => $candidate['company'],
        ];

        wp_send_json_success([
            'contact' => [
                'id' => $contact->id,
                'name' => trim($contact->first_name . ' ' . $contact->last_name),
                'first_name' => $contact->first_name,
                'email' => $contact->email,
                'company' => $contact->company_name,
                'title' => $contact->job_title,
                'linkedin_url' => $contact->linkedin_url,
            ],
            'candidate' => $candidate,
            'variables' => $variables,
            'has_cv' => $has_cv,
            'list_count' => $list_count,
        ]);
    }

    /**
     * Generate personalized message for a contact using Claude
     */
    public function generate_contact_message()
    {
        $user_id = $this->verify_request();

        $contact_id = isset($_POST['contact_id']) ? intval($_POST['contact_id']) : 0;
        $tone = isset($_POST['tone']) ? sanitize_text_field($_POST['tone']) : 'professional';

        if (!$contact_id) {
            wp_send_json_error(['message' => 'Contact ID required'], 400);
        }

        // Get contact
        $contact = SFFC_Contacts_Database::get_contact($contact_id);
        if (!$contact) {
            wp_send_json_error(['message' => 'Contact not found'], 404);
        }

        // Get user info and CV context
        $user = wp_get_current_user();
        $user_meta = get_user_meta($user_id);
        $cv_context = get_user_meta($user_id, 'sffc_cv_context', true) ?: '';

        // Get API key
        $api_key = defined('ANTHROPIC_API_KEY') ? ANTHROPIC_API_KEY : get_option('sffc_anthropic_api_key');
        if (empty($api_key)) {
            $api_key = get_option('sffc_api_key', '');
        }
        if (empty($api_key)) {
            $api_key = get_option('sffc_anthropic_key', '');
        }

        if (empty($api_key)) {
            // Return a default template if no API key
            $template = "Hi " . ($contact->first_name ?: 'there') . ",\n\n";
            $template .= "I came across your profile and was impressed by your work at " . ($contact->company_name ?: 'your company') . ". ";
            $template .= "I'm currently exploring opportunities and would love to connect.\n\n";
            $template .= "Would you be open to a brief conversation?\n\n";
            $template .= "Best regards,\n" . $user->first_name;

            wp_send_json_success(['content' => $template, 'source' => 'template']);
        }

        // Build detailed prompt with CV context
        $contact_name = $contact->first_name ?: trim($contact->first_name . ' ' . $contact->last_name);
        $contact_company = $contact->company_name ?: '';
        $contact_title = $contact->job_title ?: '';
        $current_role = isset($user_meta['current_role'][0]) ? $user_meta['current_role'][0] : '';
        $current_company = isset($user_meta['current_company'][0]) ? $user_meta['current_company'][0] : '';

        $prompt = "Generate a unique, personalized networking outreach message.\n\n";
        $prompt .= "SENDER INFORMATION:\n";
        $prompt .= "Name: {$user->display_name}\n";
        if ($current_role) {
            $prompt .= "Current Role: {$current_role}\n";
        }
        if ($current_company) {
            $prompt .= "Current Company: {$current_company}\n";
        }
        if ($cv_context) {
            $prompt .= "\nCV/BACKGROUND:\n{$cv_context}\n";
        }

        $prompt .= "\nRECIPIENT INFORMATION:\n";
        $prompt .= "Name: {$contact_name}\n";
        if ($contact_title) {
            $prompt .= "Title: {$contact_title}\n";
        }
        if ($contact_company) {
            $prompt .= "Company: {$contact_company}\n";
        }

        $prompt .= "\nREQUIREMENTS:\n";
        $prompt .= "- Tone: {$tone}\n";
        $prompt .= "- Keep it concise (under 150 words)\n";
        $prompt .= "- Be specific and reference details from the CV/background if provided\n";
        $prompt .= "- Make it unique - avoid generic phrases\n";
        $prompt .= "- Do NOT include a subject line\n";
        $prompt .= "- Do NOT start with 'I hope this finds you well' or similar\n";
        $prompt .= "- Do NOT include any meta-commentary like 'Here is your message' or 'I'm analyzing'\n";
        $prompt .= "- Just output the message directly\n";
        $prompt .= "\nWrite the message now:";

        $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
            'timeout' => 30,
            'headers' => [
                'Content-Type' => 'application/json',
                'x-api-key' => $api_key,
                'anthropic-version' => '2023-06-01',
            ],
            'body' => json_encode([
                'model' => 'claude-3-haiku-20240307',
                'max_tokens' => 500,
                'messages' => [
                    ['role' => 'user', 'content' => $prompt]
                ],
            ]),
        ]);

        if (is_wp_error($response)) {
            wp_send_json_error(['message' => 'Failed to connect to AI service'], 500);
        }

        $body = json_decode(wp_remote_retrieve_body($response), true);

        if (empty($body['content'][0]['text'])) {
            wp_send_json_error(['message' => 'No response from AI service'], 500);
        }

        $generated = trim($body['content'][0]['text']);

        // Log the generation
        $this->log_contact_activity($user_id, $contact_id, 'message_generated', [
            'tone' => $tone,
        ]);

        wp_send_json_success([
            'content' => $generated,
            'source' => 'claude',
        ]);
    }

    /**
     * Save CV context for AI personalization
     */
    public function save_cv_context()
    {
        $user_id = $this->verify_request();

        $cv_text = isset($_POST['cv_text']) ? sanitize_textarea_field($_POST['cv_text']) : '';

        if (empty($cv_text)) {
            wp_send_json_error(['message' => 'CV text is required'], 400);
        }

        // Limit CV context to reasonable size (first 3000 chars)
        $cv_text = substr($cv_text, 0, 3000);

        update_user_meta($user_id, 'sffc_cv_context', $cv_text);

        wp_send_json_success(['message' => 'CV context saved']);
    }

