    /**
     * Create a new outreach list
     */
    public function create_outreach_list()
    {
        $user_id = $this->verify_request();

        $name = isset($_POST['name']) ? sanitize_text_field($_POST['name']) : '';
        $post_ids = isset($_POST['post_ids']) ? array_map('intval', (array) $_POST['post_ids']) : [];

        if (empty($name)) {
            wp_send_json_error(['message' => 'List name is required'], 400);
        }

        // Check list creation limit
        $mepr = SFFC_CRM_MemberPress_Integration::get_instance();
        $can_create = $mepr->can_create_outreach_list($user_id);

        if (!$can_create['allowed']) {
            $prompt = $mepr->get_upgrade_prompt($user_id, 'outreach_list_limit');
            wp_send_json_error([
                'message' => $can_create['message'],
                'upgrade_prompt' => $prompt,
                'limit_info' => $can_create
            ], 403);
        }

        $lists = get_user_meta($user_id, 'sffc_outreach_lists', true) ?: [];

        // Generate unique list ID
        $list_id = 'list_' . time() . '_' . wp_rand(1000, 9999);

        $lists[$list_id] = [
            'name' => $name,
            'post_ids' => $post_ids,
            'created_at' => current_time('mysql'),
        ];

        update_user_meta($user_id, 'sffc_outreach_lists', $lists);

        wp_send_json_success([
            'message' => count($post_ids) . ' recruiter(s) added to "' . $name . '"',
            'list_id' => $list_id,
        ]);
    }

    /**
     * Add posts to an existing outreach list
     */
    public function add_posts_to_outreach_list()
    {
        $user_id = $this->verify_request();

        $list_id = isset($_POST['list_id']) ? sanitize_text_field($_POST['list_id']) : '';
        $post_ids = isset($_POST['post_ids']) ? array_map('intval', (array) $_POST['post_ids']) : [];

        if (empty($list_id)) {
            wp_send_json_error(['message' => 'List ID is required'], 400);
        }

        $lists = get_user_meta($user_id, 'sffc_outreach_lists', true) ?: [];

        if (!isset($lists[$list_id])) {
            wp_send_json_error(['message' => 'List not found'], 404);
        }

        $existing_ids = $lists[$list_id]['post_ids'] ?? [];
        $new_ids = array_unique(array_merge($existing_ids, $post_ids));
        $added = count($new_ids) - count($existing_ids);

        // Check recruiter per list limit
        $mepr = SFFC_CRM_MemberPress_Integration::get_instance();
        $recruiter_limit = apply_filters('sffc_crm_list_recruiter_limit', 3, $user_id);

        if ($recruiter_limit !== -1 && count($new_ids) > $recruiter_limit) {
            $tier = $mepr->get_crm_tier($user_id);
            $prompt = $mepr->get_upgrade_prompt($user_id, 'outreach_list_limit');
            wp_send_json_error([
                'message' => sprintf(
                    'You can only add up to %d recruiters per list on your %s plan. This list would have %d recruiters.',
                    $recruiter_limit,
                    ucfirst($tier),
                    count($new_ids)
                ),
                'upgrade_prompt' => $prompt,
                'limit' => $recruiter_limit,
                'current' => count($existing_ids),
                'attempted' => count($new_ids)
            ], 403);
        }

        $lists[$list_id]['post_ids'] = $new_ids;

        update_user_meta($user_id, 'sffc_outreach_lists', $lists);

        wp_send_json_success([
            'message' => $added . ' recruiter(s) added to list',
            'added' => $added,
        ]);
    }

    /**
     * Get user's CV context
     */
    public function get_cv_context()
    {
        $user_id = $this->verify_request();

        $cv_context = get_user_meta($user_id, 'sffc_cv_context', true) ?: '';

        wp_send_json_success(['cv_context' => $cv_context]);
    }

    /**
     * Generate personalized outreach message for similar post recruiter
     */
    public function generate_similar_outreach()
    {
        $user_id = $this->verify_request();

        $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;
        $cv_context = isset($_POST['cv_context']) ? sanitize_textarea_field($_POST['cv_context']) : '';
        $current_job_title = isset($_POST['current_job_title']) ? sanitize_text_field($_POST['current_job_title']) : '';

        if (!$post_id) {
            wp_send_json_error(['message' => 'Post ID required'], 400);
        }

        // Get recruiter post data
        $recruiter_name = get_post_meta($post_id, '_recruiter_name', true);
        $recruiter_company = get_post_meta($post_id, '_recruiter_company', true);
        $job_title = get_post_meta($post_id, '_job_title', true) ?: get_the_title($post_id);
        $company_name = get_post_meta($post_id, '_company_name', true);

        // Get user info
        $user = wp_get_current_user();

        // Get API key
        $api_key = defined('ANTHROPIC_API_KEY') ? ANTHROPIC_API_KEY : get_option('sffc_anthropic_api_key');
        if (empty($api_key)) {
            $api_key = get_option('sffc_api_key', '');
        }
        if (empty($api_key)) {
            $api_key = get_option('sffc_anthropic_key', '');
        }

        if (empty($api_key)) {
            // Fallback template
            $message = $this->generate_template_message($recruiter_name, $job_title, $user->display_name);
            wp_send_json_success(['message' => $message, 'source' => 'template']);
        }

        // Build unique prompt for each message
        $prompt = "Generate a unique, personalized networking outreach message for a job seeker reaching out to a recruiter.\n\n";
        $prompt .= "SENDER INFORMATION:\n";
        $prompt .= "Name: {$user->display_name}\n";

        if ($cv_context) {
            $prompt .= "\nCV/BACKGROUND CONTEXT:\n{$cv_context}\n";
        }

        $prompt .= "\nRECRUITER/ROLE INFORMATION:\n";
        $prompt .= "Recruiter Name: " . ($recruiter_name ?: 'Hiring Manager') . "\n";
        if ($recruiter_company) {
            $prompt .= "Recruiter's Firm: {$recruiter_company}\n";
        }
        $prompt .= "Role They're Recruiting For: {$job_title}\n";
        if ($company_name) {
            $prompt .= "Hiring Company: {$company_name}\n";
        }
        if ($current_job_title) {
            $prompt .= "Sender is interested in roles similar to: {$current_job_title}\n";
        }

        $prompt .= "\nREQUIREMENTS:\n";
        $prompt .= "- Write a concise, professional networking message (100-150 words max)\n";
        $prompt .= "- Personalize based on the specific role and recruiter\n";
        $prompt .= "- Be genuine and not overly formal\n";
        $prompt .= "- Express interest in the role and ask to connect\n";
        $prompt .= "- Make each message unique - vary the opening, structure, and tone\n";
        $prompt .= "- Do NOT include any meta-commentary like 'Here is the message' or 'I'll write'\n";
        $prompt .= "- Output ONLY the message content, ready to send\n";
        $prompt .= "- Use a random seed based on: " . wp_rand(1, 100000) . "\n";
        $prompt .= "\nWrite the message now:";

        $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
            'timeout' => 30,
            'headers' => [
                'Content-Type' => 'application/json',
                'x-api-key' => $api_key,
                'anthropic-version' => '2023-06-01',
            ],
            'body' => json_encode([
                'model' => 'claude-3-haiku-20240307',
                'max_tokens' => 500,
                'messages' => [
                    ['role' => 'user', 'content' => $prompt]
                ],
                'temperature' => 0.9, // Higher temperature for more variety
            ]),
        ]);

        if (is_wp_error($response)) {
            $message = $this->generate_template_message($recruiter_name, $job_title, $user->display_name);
            wp_send_json_success(['message' => $message, 'source' => 'template']);
        }

        $body = json_decode(wp_remote_retrieve_body($response), true);

        if (!empty($body['content'][0]['text'])) {
            $message = trim($body['content'][0]['text']);
            wp_send_json_success(['message' => $message, 'source' => 'ai']);
        } else {
            $message = $this->generate_template_message($recruiter_name, $job_title, $user->display_name);
            wp_send_json_success(['message' => $message, 'source' => 'template']);
        }
    }

    /**
     * Generate a template message as fallback
     */
    private function generate_template_message($recruiter_name, $job_title, $sender_name)
    {
        $greetings = ['Hi', 'Hello', 'Dear'];
        $openings = [
            "I came across the {role} position and wanted to reach out.",
            "I noticed you're recruiting for the {role} role and I'm very interested.",
            "I saw the {role} opportunity and believe I'd be a strong fit.",
        ];
        $closings = [
            "Would you be open to a brief conversation?",
            "I'd love the opportunity to discuss how I could contribute.",
            "I'd welcome the chance to connect and learn more.",
        ];

        $greeting = $greetings[array_rand($greetings)];
        $opening = str_replace('{role}', $job_title, $openings[array_rand($openings)]);
        $closing = $closings[array_rand($closings)];

        $name = $recruiter_name ?: 'there';

        return "{$greeting} {$name},\n\n{$opening}\n\n{$closing}\n\nBest regards,\n{$sender_name}";
    }

    /**
     * Load additional HR outreach contacts for the Outreach tab
     */
    public function load_more_hr_contacts()
    {
        // Verify nonce
        if (!check_ajax_referer('sffc_crm_nonce', 'nonce', false)) {
            wp_send_json_error([
                'message' => __('Security check failed.', 'senna-finance'),
            ], 403);
            return;
        }

        $page = isset($_POST['page']) ? max(1, intval($_POST['page'])) : 1;
        $per_page = isset($_POST['per_page']) ? intval($_POST['per_page']) : 6;
        $per_page = max(1, min(24, $per_page));
        $offset = ($page - 1) * $per_page;

        if (!class_exists('SFFC_CRM_HR_Outreach')) {
            wp_send_json_error([
                'message' => __('HR outreach is temporarily unavailable.', 'senna-finance'),
            ], 500);
        }

        $model = new SFFC_CRM_HR_Outreach();
        $total = $model->count_all();

        if ($offset >= $total) {
            wp_send_json_success([
                'html' => '',
                'has_more' => false,
            ]);
        }

        $contacts = $model->get_all([
            'limit' => $per_page,
            'offset' => $offset,
        ]);

        if (!empty($contacts) && count($contacts) > 1) {
            $curated_contacts = array_values(array_filter($contacts, static function ($contact) {
                return ($contact['source_context'] ?? '') !== 'active_recruiter';
            }));
            $active_recruiter_contacts = array_values(array_filter($contacts, static function ($contact) {
                return ($contact['source_context'] ?? '') === 'active_recruiter';
            }));
            shuffle($curated_contacts);
            shuffle($active_recruiter_contacts);
            $contacts = array_merge($curated_contacts, $active_recruiter_contacts);
        }

        if (empty($contacts)) {
            wp_send_json_error([
                'message' => __('Unable to load more contacts right now. Please try again.', 'senna-finance'),
            ]);
        }

        $shortcodes = class_exists('SFFC_CRM_Shortcodes') ? SFFC_CRM_Shortcodes::get_instance() : null;
        $html = '';
        foreach ($contacts as $contact) {
            if ($shortcodes && method_exists($shortcodes, 'get_hr_contact_card_markup')) {
                $html .= $shortcodes->get_hr_contact_card_markup($contact);
            }
        }

        if (!$html) {
            wp_send_json_error([
                'message' => __('Unable to render contacts right now. Please try again.', 'senna-finance'),
            ]);
        }

        $has_more = ($offset + $per_page) < $total;

        wp_send_json_success([
            'html' => $html,
            'has_more' => $has_more,
        ]);
    }

    /**
     * Load more similar posts via AJAX
     */
    public function load_more_similar_posts()
    {
        check_ajax_referer('sffc_express_interest_nonce', 'nonce');

        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => __('Please create a MENA Careers account to view more roles.', 'senna-finance')], 401);
        }

        $page = isset($_POST['page']) ? intval($_POST['page']) : 2;
        $current_post_id = isset($_POST['current_post_id']) ? intval($_POST['current_post_id']) : 0;
        $job_title = isset($_POST['job_title']) ? sanitize_text_field($_POST['job_title']) : '';

        $offset = ($page - 1) * 9;

        // Extract keywords from job title
        $title_keywords = array_filter(
            preg_split('/[\s,\-\/]+/', strtolower($job_title)),
            function ($word) {
                return strlen($word) > 3 && !in_array($word, ['senior', 'junior', 'lead', 'head', 'manager', 'director', 'with', 'from', 'the', 'and', 'for']);
            }
        );

        $args = [
            'post_type' => 'sffc_recruiter_post',
            'posts_per_page' => 9,
            'offset' => $offset,
            'post_status' => 'publish',
            'post__not_in' => [$current_post_id],
            'orderby' => 'date',
            'order' => 'DESC',
        ];

        if (!empty($title_keywords)) {
            $meta_query = ['relation' => 'OR'];
            foreach (array_slice($title_keywords, 0, 3) as $keyword) {
                $meta_query[] = [
                    'key' => '_job_title',
                    'value' => $keyword,
                    'compare' => 'LIKE'
                ];
            }
            $args['meta_query'] = $meta_query;
        }

        $query = new WP_Query($args);

        $html = '';

        if ($query->have_posts()) {
            while ($query->have_posts()) {
                $query->the_post();
                $sim_post_id = get_the_ID();
                $sim_job_title = get_post_meta($sim_post_id, '_job_title', true) ?: get_the_title();
                $sim_company = get_post_meta($sim_post_id, '_company_name', true);
                $sim_location = get_post_meta($sim_post_id, '_job_location', true);
                $sim_salary_min = get_post_meta($sim_post_id, '_salary_min', true);
                $sim_salary_max = get_post_meta($sim_post_id, '_salary_max', true);
                $sim_salary_currency = get_post_meta($sim_post_id, '_salary_currency', true) ?: 'AED';
                $sim_recruiter_name = get_post_meta($sim_post_id, '_recruiter_name', true);
                $sim_recruiter_company = get_post_meta($sim_post_id, '_recruiter_company', true);
                $sim_recruiter_email = get_post_meta($sim_post_id, '_recruiter_email', true);
                $sim_locations = wp_get_post_terms($sim_post_id, 'recruiter_post_location', ['fields' => 'names']);
                $sim_location_label = !empty($sim_locations) ? $sim_locations[0] : $sim_location;

                $sim_salary_display = '';
                if ($sim_salary_min && $sim_salary_max) {
                    $sim_salary_display = $sim_salary_currency . ' ' . number_format($sim_salary_min) . ' - ' . number_format($sim_salary_max);
                } elseif ($sim_salary_min) {
                    $sim_salary_display = $sim_salary_currency . ' ' . number_format($sim_salary_min) . '+';
                }

                $html .= '<div class="inst-similar-post-card"';
                $html .= ' data-post-id="' . esc_attr($sim_post_id) . '"';
                $html .= ' data-recruiter-name="' . esc_attr($sim_recruiter_name) . '"';
                $html .= ' data-recruiter-company="' . esc_attr($sim_recruiter_company) . '"';
                $html .= ' data-recruiter-email="' . esc_attr($sim_recruiter_email) . '"';
                $html .= ' data-job-title="' . esc_attr($sim_job_title) . '">';

                $html .= '<label class="inst-similar-post-checkbox">';
                $html .= '<input type="checkbox" class="inst-similar-post-select" value="' . esc_attr($sim_post_id) . '">';
                $html .= '<span class="inst-similar-checkbox-mark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg></span>';
                $html .= '</label>';

                $html .= '<a href="' . esc_url(get_permalink()) . '" class="inst-similar-post-link">';
                $html .= '<div class="inst-similar-post-header">';
                $html .= '<h3 class="inst-similar-post-title">' . esc_html($sim_job_title) . '</h3>';
                if ($sim_company) {
                    $html .= '<span class="inst-similar-post-company">' . esc_html($sim_company) . '</span>';
                }
                $html .= '</div>';

                $html .= '<div class="inst-similar-post-meta">';
                if ($sim_location_label) {
                    $html .= '<span class="inst-similar-post-location"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>' . esc_html($sim_location_label) . '</span>';
                }
                if ($sim_salary_display) {
                    $html .= '<span class="inst-similar-post-salary"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>' . esc_html($sim_salary_display) . '</span>';
                }
                $html .= '</div>';
                $html .= '</a>';

                if ($sim_recruiter_name) {
                    $html .= '<div class="inst-similar-post-recruiter">';
                    $html .= '<div class="inst-similar-recruiter-avatar">' . esc_html(substr($sim_recruiter_name, 0, 1)) . '</div>';
                    $html .= '<div class="inst-similar-recruiter-info">';
                    $html .= '<span class="inst-similar-recruiter-name">' . esc_html($sim_recruiter_name) . '</span>';
                    if ($sim_recruiter_company) {
                        $html .= '<span class="inst-similar-recruiter-company">' . esc_html($sim_recruiter_company) . '</span>';
                    }
                    $html .= '</div>';
                    $html .= '<button type="button" class="inst-similar-add-to-list" title="Add to outreach list" data-post-id="' . esc_attr($sim_post_id) . '"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg></button>';
                    $html .= '</div>';
                }

                $html .= '</div>';
            }
            wp_reset_postdata();
        }

        wp_send_json_success([
            'html' => $html,
            'has_more' => $query->found_posts > ($offset + 9),
            'total' => $query->found_posts,
        ]);
    }

    /**
     * Handle recruiter scan request
     * Sends email to admin with user's scan request details
     */
    public function request_recruiter_scan()
    {
        $user_id = $this->verify_request();

        $role = isset($_POST['role']) ? sanitize_text_field($_POST['role']) : '';
        $location = isset($_POST['location']) ? sanitize_text_field($_POST['location']) : '';
        $industry = isset($_POST['industry']) ? sanitize_text_field($_POST['industry']) : '';
        $salary = isset($_POST['salary']) ? sanitize_text_field($_POST['salary']) : '';
        $experience = isset($_POST['experience']) ? sanitize_text_field($_POST['experience']) : '';
        $notes = isset($_POST['notes']) ? sanitize_textarea_field($_POST['notes']) : '';
        $current_post_id = isset($_POST['current_post_id']) ? intval($_POST['current_post_id']) : 0;

        if (empty($role)) {
            wp_send_json_error(['message' => 'Please specify what role you are looking for'], 400);
        }

        if (empty($location)) {
            wp_send_json_error(['message' => 'Please specify your preferred location(s)'], 400);
        }

        $user = get_user_by('id', $user_id);
        $user_name = $user->display_name ?: $user->user_email;
        $user_email = $user->user_email;

        // Get current post info if available
        $current_post_title = '';
        $current_post_url = '';
        if ($current_post_id) {
            $current_post_title = get_the_title($current_post_id);
            $current_post_url = get_permalink($current_post_id);
        }

        // Build email content
        $admin_email = get_option('admin_email');
        $site_name = get_bloginfo('name');

        $subject = '[MENA Careers] New Recruiter Scan Request from ' . $user_name;

        $message = "A user has requested a recruiter scan.\n\n";
        $message .= "=== User Details ===\n";
        $message .= "Name: {$user_name}\n";
        $message .= "Email: {$user_email}\n";
        $message .= "User ID: {$user_id}\n\n";

        $message .= "=== Scan Request Details ===\n";
        $message .= "Target Role: {$role}\n";
        $message .= "Preferred Location(s): {$location}\n";
        $message .= "Industry/Sector: " . ($industry ?: 'Not specified') . "\n";
        $message .= "Expected Salary: " . ($salary ?: 'Not specified') . "\n";
        $message .= "Experience Level: " . ($experience ?: 'Not specified') . "\n";
        if ($notes) {
            $message .= "\nAdditional Requirements:\n{$notes}\n";
        }
        $message .= "\n";

        if ($current_post_title) {
            $message .= "=== Current Post Context ===\n";
            $message .= "Post: {$current_post_title}\n";
            $message .= "URL: {$current_post_url}\n\n";
        }

        $message .= "=== Action Required ===\n";
        $message .= "Please search for recruiters matching the user's criteria and add them to the database.\n";
        $message .= "Once found, the user will be able to see similar recruiter posts on the platform.\n\n";

        $message .= "--\n";
        $message .= "This is an automated message from {$site_name}.";

        // Send email
        $headers = [
            'Content-Type: text/plain; charset=UTF-8',
            'From: ' . $site_name . ' <' . $admin_email . '>',
            'Reply-To: ' . $user_email,
        ];

        $sent = wp_mail($admin_email, $subject, $message, $headers);

        // Also save the request to user meta for tracking
        $scan_requests = get_user_meta($user_id, 'sffc_scan_requests', true) ?: [];
        $scan_requests[] = [
            'role' => $role,
            'location' => $location,
            'industry' => $industry,
            'salary' => $salary,
            'experience' => $experience,
            'notes' => $notes,
            'current_post_id' => $current_post_id,
            'requested_at' => current_time('mysql'),
            'status' => 'pending',
        ];
        update_user_meta($user_id, 'sffc_scan_requests', $scan_requests);

        if ($sent) {
            wp_send_json_success([
                'message' => 'Your scan request has been submitted! Our team will search for recruiters matching your criteria and notify you when we find matches.',
            ]);
        } else {
            wp_send_json_error([
                'message' => 'There was an issue submitting your request. Please try again or contact support.',
            ], 500);
        }
    }

    /**
     * Generate smart message using Claude AI
     * For premium users: generates real tailored message
     * For non-premium users: generates preview message (cached)
     */
    public function generate_smart_message()
    {
        // Verify nonce - uses different nonce than CRM
        if (!check_ajax_referer('sffc_express_interest_nonce', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid security token'], 403);
        }

        $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;
        $recruiter_name = isset($_POST['recruiter_name']) ? sanitize_text_field($_POST['recruiter_name']) : '';
        $job_title = isset($_POST['job_title']) ? sanitize_text_field($_POST['job_title']) : '';
        $company_name = isset($_POST['company_name']) ? sanitize_text_field($_POST['company_name']) : '';
        $jd_text = isset($_POST['jd_text']) ? sanitize_textarea_field($_POST['jd_text']) : '';
        $first_name = isset($_POST['first_name']) ? sanitize_text_field($_POST['first_name']) : '';
        $last_name = isset($_POST['last_name']) ? sanitize_text_field($_POST['last_name']) : '';
        $is_preview = isset($_POST['is_preview']) ? filter_var($_POST['is_preview'], FILTER_VALIDATE_BOOLEAN) : true;

        if (!$post_id || !$job_title) {
            wp_send_json_error(['message' => 'Missing required fields'], 400);
        }

        // Check for cached preview message (shared across all users for this post)
        $cache_key = 'sffc_smart_message_preview_' . $post_id;
        $cached_message = get_transient($cache_key);

        // For preview requests, return cached version if available
        if ($is_preview && $cached_message) {
            wp_send_json_success([
                'message' => $cached_message,
                'cached' => true,
            ]);
            return;
        }

        // Check premium access for full messages
        $is_premium = false;
        $default_cv_excerpt = '';
        if (is_user_logged_in()) {
            $user_id = get_current_user_id();
            if (class_exists('SFFC_MemberPress_Integration')) {
                $mepr = SFFC_MemberPress_Integration::get_instance();
                $is_premium = $mepr->has_premium_access($user_id);
            }

            if (class_exists('SFFC_CRM_CV_Manager')) {
                $cv_manager = new SFFC_CRM_CV_Manager();
                $default_cv = $cv_manager->get_default($user_id);
                if (!empty($default_cv['content'])) {
                    $default_cv_excerpt = mb_substr(wp_strip_all_tags($default_cv['content']), 0, 1200);
                }
            }
        }

        // Generate message using Claude
        if (!class_exists('SFFC_Claude_API_Manager')) {
            wp_send_json_error(['message' => 'AI service unavailable'], 500);
            return;
        }

        $claude = SFFC_Claude_API_Manager::get_instance();

        // Extract recruiter's first name
        $recruiter_first_name = explode(' ', $recruiter_name)[0] ?: 'Hiring Manager';

        // Extract key requirements from JD (first 500 chars for context)
        $jd_excerpt = mb_substr(strip_tags($jd_text), 0, 500);

        // Build the prompt
        $prompt = "Write a high-converting, personalized job application message for the following role:

Role: {$job_title}
Company: " . ($company_name ?: 'a leading firm') . "
Recruiter: {$recruiter_first_name}

Job Description excerpt:
{$jd_excerpt}

Candidate CV snapshot:
" . ($default_cv_excerpt ? $default_cv_excerpt : '[CV not provided]') . "

Instructions:
1. Start with 'Dear {$recruiter_first_name},' and immediately ground the opening in the role and company.
2. Use a confident but warm tone that sounds like a modern operator, not a template.
3. Reference 2-3 specifics from the excerpt in short sentences (no bullet points) so it feels tailored.
4. When mentioning the candidate's track record, use placeholders like [RELEVANT RESULT OR KPI] or [Sector-specific accomplishment] so they can personalise it quickly.
5. End with a decisive call to action inviting a 15-minute conversation and reference that the candidate can send a 30/60/90 plan.
6. Keep it between 170-210 words.
7. Do NOT claim the candidate found the recruiter on LinkedIn or mention social media discovery.
8. Output only the message body (no subject line).

Signature info:
" . ($first_name ? "Name: {$first_name} {$last_name}" : "Name: [YOUR NAME]") . "

Write the message now:";

        $response = $claude->call_api($prompt, [
            'model' => 'claude-3-haiku-20240307',
            'max_tokens' => 400,
            'temperature' => 0.7,
            'mode' => 'career',
        ]);

        // Extract message text
        $message_text = '';
        if (!empty($response['content']) && is_array($response['content'])) {
            foreach ($response['content'] as $content_block) {
                if (isset($content_block['text'])) {
                    $message_text = trim($content_block['text']);
                    break;
                }
            }
        }

        if (empty($message_text)) {
            // Fallback to a template if Claude fails
            $message_text = $this->get_fallback_smart_message($recruiter_first_name, $job_title, $company_name, $first_name, $last_name);
        }

        // Cache the preview for 1 hour (shared across users for this post)
        if ($is_preview || !$is_premium) {
            set_transient($cache_key, $message_text, HOUR_IN_SECONDS);
        }

        wp_send_json_success([
            'message' => $message_text,
            'cached' => false,
            'is_premium' => $is_premium,
        ]);
    }

    /**
     * Fallback smart message when Claude is unavailable
     */
    private function get_fallback_smart_message($recruiter_name, $job_title, $company_name, $first_name = '', $last_name = '')
    {
        $applicant_name = $first_name ? "{$first_name} {$last_name}" : "[YOUR NAME]";
        $company_text = $company_name ? " at {$company_name}" : "";

        return "Dear {$recruiter_name},

The {$job_title}{$company_text} search immediately stood out because it mirrors the mandates I've closed recently—translating high-pressure targets into crisp execution and measurable gains.

Across [YOUR EXPERIENCE], I've led [SPECIFIC ROLE ASPECT] while coordinating with senior stakeholders to keep delivery tight. I can bring that same operator mindset here: a clear 30/60/90 plan, a pipeline of quick wins, and the headspace to extend your bench right away.

If helpful, I'm free for a 15-minute call this week to walk through how I'd plug in and send you that ramp plan.

Best regards,
{$applicant_name}";
    }

