    /**
     * Get user's recruiter outreach lists from database
     */
    public function get_recruiter_outreach_lists()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $table = $wpdb->prefix . 'sffc_crm_outreach_lists';

        $lists = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM $table
             WHERE user_id = %d
             ORDER BY created_at DESC",
            $user_id
        ), ARRAY_A);

        wp_send_json_success($lists);
    }

    public function get_console_lists()
    {
        $user_id = $this->verify_request();
        $this->ensure_console_list_tables();

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_crm_console_lists';

        $lists = $wpdb->get_results($wpdb->prepare(
            "SELECT id, list_name, description, item_count, created_at, updated_at
             FROM {$table}
             WHERE user_id = %d
             ORDER BY updated_at DESC, id DESC",
            $user_id
        ), ARRAY_A);

        wp_send_json_success(['lists' => $lists]);
    }

    public function add_console_list_item()
    {
        $user_id = $this->verify_request();
        $this->ensure_console_list_tables();

        global $wpdb;

        $list_id = isset($_POST['list_id']) ? absint($_POST['list_id']) : 0;
        $new_list_name = isset($_POST['new_list_name']) ? sanitize_text_field(wp_unslash($_POST['new_list_name'])) : '';
        $payload = isset($_POST['match']) && is_array($_POST['match']) ? wp_unslash($_POST['match']) : [];

        if (!$list_id && $new_list_name === '') {
            wp_send_json_error(['message' => __('Choose a list or create a new one.', 'senna-finance')], 400);
        }

        $lists_table = $wpdb->prefix . 'sffc_crm_console_lists';
        $items_table = $wpdb->prefix . 'sffc_crm_console_list_items';

        if (!$list_id) {
            $description = __('Use lists to save contacts and manage your data in one place for seamless follow-up and smarter outreach, all with one click!', 'senna-finance');
            $inserted = $wpdb->insert(
                $lists_table,
                [
                    'user_id' => $user_id,
                    'list_name' => $new_list_name,
                    'description' => $description,
                    'item_count' => 0,
                    'created_at' => current_time('mysql'),
                    'updated_at' => current_time('mysql'),
                ],
                ['%d', '%s', '%s', '%d', '%s', '%s']
            );

            if (!$inserted) {
                wp_send_json_error(['message' => __('Unable to create list.', 'senna-finance')], 500);
            }
            $list_id = (int) $wpdb->insert_id;
        } else {
            $list_owner = (int) $wpdb->get_var($wpdb->prepare(
                "SELECT user_id FROM {$lists_table} WHERE id = %d",
                $list_id
            ));
            if ($list_owner !== $user_id) {
                wp_send_json_error(['message' => __('List not found.', 'senna-finance')], 404);
            }
        }

        $post_id = absint($payload['id'] ?? $payload['post_id'] ?? 0);
        $recruiter_id = absint($payload['recruiter_id'] ?? 0);
        $reasons = $payload['reasons'] ?? [];
        if (!is_array($reasons)) {
            $reasons = [];
        }

        $item = [
            'list_id' => $list_id,
            'user_id' => $user_id,
            'post_id' => $post_id,
            'recruiter_id' => $recruiter_id,
            'recruiter_name' => sanitize_text_field($payload['recruiter_name'] ?? ''),
            'recruiter_title' => sanitize_text_field($payload['recruiter_title'] ?? ''),
            'recruiter_email' => sanitize_email($payload['recruiter_email'] ?? ''),
            'recruiter_linkedin' => esc_url_raw($payload['recruiter_linkedin'] ?? ''),
            'recruiter_firm' => sanitize_text_field($payload['recruiter_firm'] ?? ''),
            'recruiter_photo' => esc_url_raw($payload['recruiter_photo'] ?? ''),
            'role_title' => sanitize_text_field($payload['role_title'] ?? ''),
            'company' => sanitize_text_field($payload['company'] ?? ''),
            'location' => sanitize_text_field($payload['location'] ?? ''),
            'company_logo' => esc_url_raw($payload['company_logo'] ?? ''),
            'match_score' => absint($payload['match_score'] ?? 0),
            'reasons' => wp_json_encode(array_map('sanitize_text_field', $reasons)),
            'insight' => sanitize_text_field($payload['insight'] ?? ''),
            'url' => esc_url_raw($payload['url'] ?? ''),
            'status' => 'saved',
            'created_at' => current_time('mysql'),
            'updated_at' => current_time('mysql'),
        ];

        $inserted = $wpdb->replace(
            $items_table,
            $item,
            ['%d', '%d', '%d', '%d', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%d', '%s', '%s', '%s', '%s', '%s', '%s']
        );

        if ($inserted === false) {
            wp_send_json_error(['message' => __('Unable to add this entry to the list.', 'senna-finance')], 500);
        }

        $item_count = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$items_table} WHERE list_id = %d",
            $list_id
        ));
        $wpdb->update(
            $lists_table,
            ['item_count' => $item_count, 'updated_at' => current_time('mysql')],
            ['id' => $list_id],
            ['%d', '%s'],
            ['%d']
        );

        wp_send_json_success([
            'message' => __('Added to list.', 'senna-finance'),
            'list_id' => $list_id,
            'item_count' => $item_count,
        ]);
    }

    private function ensure_console_list_tables()
    {
        global $wpdb;

        require_once ABSPATH . 'wp-admin/includes/upgrade.php';

        $charset_collate = $wpdb->get_charset_collate();
        $lists_table = $wpdb->prefix . 'sffc_crm_console_lists';
        $items_table = $wpdb->prefix . 'sffc_crm_console_list_items';

        $sql_lists = "CREATE TABLE {$lists_table} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            user_id bigint(20) NOT NULL,
            list_name varchar(200) NOT NULL,
            description text,
            item_count int(11) DEFAULT 0,
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            KEY idx_user (user_id),
            KEY idx_updated (updated_at)
        ) {$charset_collate};";

        $sql_items = "CREATE TABLE {$items_table} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            list_id bigint(20) NOT NULL,
            user_id bigint(20) NOT NULL,
            post_id bigint(20) DEFAULT 0,
            recruiter_id bigint(20) DEFAULT 0,
            recruiter_name varchar(200),
            recruiter_title varchar(200),
            recruiter_email varchar(255),
            recruiter_linkedin varchar(500),
            recruiter_firm varchar(200),
            recruiter_photo varchar(500),
            role_title varchar(255),
            company varchar(255),
            location varchar(255),
            company_logo varchar(500),
            match_score int(11) DEFAULT 0,
            reasons longtext,
            insight text,
            url varchar(500),
            status varchar(50) DEFAULT 'saved',
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            UNIQUE KEY unique_list_match (list_id, post_id, recruiter_id),
            KEY idx_user (user_id),
            KEY idx_list (list_id),
            KEY idx_recruiter (recruiter_id),
            KEY idx_post (post_id)
        ) {$charset_collate};";

        dbDelta($sql_lists);
        dbDelta($sql_items);
    }

    /**
     * Create new recruiter outreach list with recruiters
     */
    public function create_recruiter_outreach_list()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $list_name = isset($_POST['list_name']) ? sanitize_text_field($_POST['list_name']) : '';
        $description = isset($_POST['description']) ? sanitize_textarea_field($_POST['description']) : '';
        $recruiter_ids = isset($_POST['recruiter_ids']) ? array_map('intval', (array)$_POST['recruiter_ids']) : [];

        if (empty($list_name)) {
            wp_send_json_error(['message' => 'List name is required']);
        }

        // Create list
        $table_lists = $wpdb->prefix . 'sffc_crm_outreach_lists';
        $inserted = $wpdb->insert(
            $table_lists,
            [
                'user_id' => $user_id,
                'list_name' => $list_name,
                'description' => $description,
                'recruiter_count' => count($recruiter_ids),
                'created_at' => current_time('mysql'),
                'updated_at' => current_time('mysql')
            ],
            ['%d', '%s', '%s', '%d', '%s', '%s']
        );

        if (!$inserted) {
            wp_send_json_error(['message' => 'Failed to create list']);
        }

        $list_id = $wpdb->insert_id;

        // Add recruiters to list
        if (!empty($recruiter_ids)) {
            $table_members = $wpdb->prefix . 'sffc_crm_outreach_list_members';
            $order = 0;

            foreach ($recruiter_ids as $recruiter_id) {
                $wpdb->insert(
                    $table_members,
                    [
                        'list_id' => $list_id,
                        'recruiter_id' => $recruiter_id,
                        'added_at' => current_time('mysql'),
                        'order_position' => $order++
                    ],
                    ['%d', '%d', '%s', '%d']
                );
            }
        }

        wp_send_json_success([
            'list_id' => $list_id,
            'message' => 'List created successfully'
        ]);
    }

    /**
     * CV Manager: fetch CVs
     */
    public function get_cv_versions()
    {
        $user_id = $this->verify_request();
        $cv_manager = new SFFC_CRM_CV_Manager();
        $items = $cv_manager->get_cvs($user_id);
        $formatted = $this->format_cv_entries($items, $user_id);

        wp_send_json_success([
            'items' => $formatted,
            'default_id' => $this->get_default_cv_id($items),
        ]);
    }

    public function save_cv_version()
    {
        $user_id = $this->verify_request();
        $content = isset($_POST['content']) ? wp_kses_post(wp_unslash($_POST['content'])) : '';
        $label = isset($_POST['title']) ? sanitize_text_field($_POST['title']) : '';

        if (empty($content)) {
            wp_send_json_error(['message' => 'CV content required'], 400);
        }

        $cv_manager = new SFFC_CRM_CV_Manager();
        $entries = $cv_manager->save_cv($user_id, $content, $label);
        $formatted = $this->format_cv_entries($entries, $user_id);

        wp_send_json_success([
            'items' => $formatted,
            'default_id' => $this->get_default_cv_id($entries),
        ]);
    }

    public function set_cv_default()
    {
        $user_id = $this->verify_request();
        $cv_id = isset($_POST['cv_id']) ? sanitize_text_field($_POST['cv_id']) : '';

        if (!$cv_id) {
            wp_send_json_error(['message' => 'CV ID required'], 400);
        }

        $cv_manager = new SFFC_CRM_CV_Manager();
        $result = $cv_manager->set_default($user_id, $cv_id);

        if (is_wp_error($result)) {
            wp_send_json_error(['message' => $result->get_error_message()], 400);
        }

        $formatted = $this->format_cv_entries($result, $user_id);

        wp_send_json_success([
            'items' => $formatted,
            'default_id' => $this->get_default_cv_id($result),
        ]);
    }

    /**
     * Prepare JD + CV payload for the Gap Analyzer modal
     */
    public function get_gap_payload()
    {
        $user_id = $this->verify_request();
        $post_id = isset($_POST['post_id']) ? absint($_POST['post_id']) : 0;
        $cv_id = isset($_POST['cv_id']) ? sanitize_text_field(wp_unslash($_POST['cv_id'])) : '';

        $cv_text = $this->get_gap_cv_text($user_id, $cv_id);

        // If no post_id, return just CV data for general analysis
        if (!$post_id) {
            wp_send_json_success([
                'job_title' => 'General CV Analysis',
                'company' => '',
                'location' => '',
                'jd_text' => '',
                'cv_text' => $cv_text,
                'has_cv' => !empty($cv_text),
                'match_context' => [],
            ]);
            return;
        }

        $post_model = new SFFC_CRM_Post();
        $post = $post_model->get_full_detail($post_id, $user_id);

        if (!$post) {
            wp_send_json_error(['message' => 'Unable to find that post'], 404);
        }

        if (!function_exists('sffc_build_crm_jd_text_for_analysis')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/functions-gap-analyzer.php';
        }

        $jd_text = sffc_build_crm_jd_text_for_analysis($post);

        wp_send_json_success([
            'job_title' => $post['role_title'] ?? '',
            'company' => $post['company'] ?? '',
            'location' => $post['location'] ?? '',
            'jd_text' => $jd_text,
            'cv_text' => $cv_text,
            'has_cv' => !empty($cv_text),
            'match_context' => $this->build_gap_match_context($post),
        ]);
    }

    private function build_gap_match_context($post)
    {
        if (empty($post) || !is_array($post)) {
            return [];
        }

        return [
            'post_id' => isset($post['id']) ? (int) $post['id'] : 0,
            'role_title' => $post['role_title'] ?? '',
            'company' => $post['company'] ?? '',
            'location' => $post['location'] ?? '',
            'salary_text' => $post['salary_text'] ?? '',
            'salary_min' => isset($post['salary_min']) ? (int) $post['salary_min'] : null,
            'salary_max' => isset($post['salary_max']) ? (int) $post['salary_max'] : null,
            'salary_currency' => $post['salary_currency'] ?? '',
            'seniority' => $post['seniority'] ?? '',
            'sector' => $post['sector'] ?? '',
            'posted_at' => $post['posted_at'] ?? '',
            'application_url' => $post['application_url'] ?? '',
            'summary' => $post['content_snippet'] ?? '',
            'recruiter_id' => isset($post['recruiter_id']) ? (int) $post['recruiter_id'] : 0,
            'recruiter_name' => $post['recruiter_name'] ?? '',
            'recruiter_firm' => $post['recruiter_firm'] ?? '',
            'recruiter_title' => $post['recruiter_title'] ?? '',
            'recruiter_photo' => $post['recruiter_photo'] ?? '',
            'recruiter_linkedin' => $post['recruiter_linkedin'] ?? '',
            'recruiter_verified' => !empty($post['recruiter_verified']),
        ];
    }

    private function format_cv_entries($entries, $user_id = 0)
    {
        $profile_resume_document = $user_id ? $this->get_profile_resume_document($user_id) : null;
        $formatted = [];
        foreach ($entries as $entry) {
            $preview = wp_strip_all_tags($entry['content']);
            $preview = mb_substr($preview, 0, 200);
            if (mb_strlen($entry['content']) > 200) {
                $preview .= '…';
            }
            $display_label = $entry['label'];
            if ($profile_resume_document && !empty($entry['is_default'])) {
                $display_label = $profile_resume_document['name'];
            }
            $formatted[] = [
                'id' => $entry['id'],
                'label' => $entry['label'],
                'display_label' => $display_label,
                'created_at' => $entry['created_at'] ?? '',
                'is_default' => !empty($entry['is_default']),
                'preview' => $preview,
                'word_count' => str_word_count(wp_strip_all_tags($entry['content'])),
            ];
        }

        if (empty($formatted) && $profile_resume_document) {
            $formatted[] = [
                'id' => 'profile_resume',
                'label' => $profile_resume_document['name'],
                'display_label' => $profile_resume_document['name'],
                'created_at' => $profile_resume_document['uploaded'] ?? '',
                'is_default' => true,
                'preview' => __('Resume uploaded in Profile', 'senna-finance'),
                'word_count' => 0,
                'is_profile_document' => true,
            ];
        }

        return $formatted;
    }

    private function get_profile_resume_document($user_id)
    {
        $documents = get_user_meta($user_id, 'sffc_crm_documents', true);
        $documents = is_array($documents) ? $documents : [];

        foreach ($documents as $document) {
            $document_name = sanitize_text_field($document['name'] ?? '');
            $document_url = esc_url_raw($document['url'] ?? '');
            $document_type = sanitize_key($document['document_type'] ?? '');

            if ($document_type === 'resume_cv' && $document_name && $document_url) {
                return [
                    'name' => $document_name,
                    'url' => $document_url,
                    'uploaded' => sanitize_text_field($document['uploaded'] ?? ''),
                ];
            }
        }

        return null;
    }

    private function get_default_cv_id($entries)
    {
        foreach ($entries as $entry) {
            if (!empty($entry['is_default'])) {
                return $entry['id'];
            }
        }
        return !empty($entries) ? $entries[0]['id'] : null;
    }

    /**
     * Build user CV text for analyzer payload
     */
    private function get_gap_cv_text($user_id, $cv_id = '')
    {
        $cv_text = '';

        // PRIORITY 1: Use the selected CV from CV Manager when available.
        if (class_exists('SFFC_CRM_CV_Manager')) {
            $cv_manager = new SFFC_CRM_CV_Manager();
            if ($cv_id !== '') {
                $selected_cv = $cv_manager->get_cv_by_id($user_id, $cv_id);
                if (!empty($selected_cv['content'])) {
                    $cv_text = $selected_cv['content'];
                }
            }

            if (empty($cv_text)) {
                $default_cv = $cv_manager->get_default($user_id);
                if (!empty($default_cv['content'])) {
                    $cv_text = $default_cv['content'];
                }
            }
        }

        // PRIORITY 2: Fallback to sffc_cv_context (legacy, may be truncated)
        if (empty($cv_text)) {
            $cv_text = trim((string) get_user_meta($user_id, 'sffc_cv_context', true));
        }

        if (empty($cv_text)) {
            return '';
        }

        $cv_text = wp_strip_all_tags($cv_text);
        $cv_text = preg_replace("/\r\n?/", "\n", $cv_text);
        $cv_text = trim($cv_text);

        // Limit to 8000 chars for performance (much better than previous 3000)
        return mb_substr($cv_text, 0, 8000);
    }

    /**
     * Get job matches based on CV
     */
    public function get_matches()
    {
        try {
            $user_id = $this->verify_request(false);

            $cv_text_override = '';
            if (isset($_POST['cv_text'])) {
                $cv_text_override = $this->sanitize_cv_input(wp_unslash($_POST['cv_text']));
            }

            $search_filters = [
                'role' => isset($_POST['role']) ? sanitize_text_field(wp_unslash($_POST['role'])) : '',
                'location' => isset($_POST['location']) ? sanitize_text_field(wp_unslash($_POST['location'])) : '',
                'specialisation' => isset($_POST['specialisation']) ? sanitize_text_field(wp_unslash($_POST['specialisation'])) : '',
                'seniority' => isset($_POST['seniority']) ? sanitize_text_field(wp_unslash($_POST['seniority'])) : '',
            ];
            $has_search_filters = false;
            foreach ($search_filters as $search_filter_value) {
                if (trim((string) $search_filter_value) !== '') {
                    $has_search_filters = true;
                    break;
                }
            }

            $fast_mode = !empty($_POST['fast_mode']) && filter_var(wp_unslash($_POST['fast_mode']), FILTER_VALIDATE_BOOLEAN);

            // Get user's CV
            $cv_text = !empty($cv_text_override) ? $cv_text_override : $this->get_gap_cv_text($user_id);

            if (empty($cv_text)) {
                wp_send_json_success([
                    'items' => [],
                    'has_cv' => false,
                    'message' => 'Please upload your CV/Resume first to see matches.'
                ]);
                return;
            }

            // Get all posts
            $post_model = new SFFC_CRM_Post();
            $feed_args = [
                'page' => 1,
                'per_page' => $has_search_filters ? 250 : 60,
                'approved_only' => true,
                'user_id' => $user_id // Include user_id to check saved status
            ];

            if ($has_search_filters) {
                if ($search_filters['location'] !== '') {
                    $feed_args['location'] = $search_filters['location'];
                }

                if ($search_filters['role'] !== '') {
                    $feed_args['search'] = $search_filters['role'];
                }

                if ($search_filters['specialisation'] !== '') {
                    $feed_args['keywords'] = $search_filters['specialisation'];
                }
            }

            $posts = $post_model->get_feed($feed_args);

            if (empty($posts)) {
                wp_send_json_success([
                    'items' => [],
                    'has_cv' => true,
                    'message' => 'No posts available to match.'
                ]);
                return;
            }

            // ENRICHMENT: Load requirements data for nationality detection
            $posts = $this->enrich_posts_with_requirements($posts);

            $taxonomy = $this->load_keyword_taxonomy();
            $cv_parsed = $this->build_simple_cv_match_profile($cv_text);

            error_log('CRM Matches: Simple CV profile parsed - Title: ' . ($cv_parsed['current_title'] ?? '') . ', Seniority: ' . ($cv_parsed['effective_seniority'] ?? '') . ', Years: ' . ($cv_parsed['experience_years'] ?? 0));

            // Calculate deterministic scores from dates, seniority, title, and keyword overlap.
            $matches = [];
            $filtered_count = 0;

            foreach ($posts as $post) {
                try {
                    if (empty($post['seniority']) || $post['seniority'] === 'other') {
                        $post['seniority'] = $this->infer_seniority_from_post($post);
                    }

                    if (!$this->passes_cv_match_search_filters($post, $search_filters)) {
                        $filtered_count++;
                        continue;
                    }

                    if (!$fast_mode && !$has_search_filters && !$this->fast_match_prefilter($cv_parsed, $post)) {
                        $filtered_count++;
                        continue;
                    }

                    $legacy_score = (int) round($this->calculate_match_score($cv_parsed, $post, $taxonomy));
                    $minimum_match_score = $fast_mode ? 24 : ($has_search_filters ? 12 : 18);

                    if ($legacy_score < $minimum_match_score) {
                        $filtered_count++;
                        continue;
                    }

                    $post['match_score'] = $legacy_score;
                    $post['match_confidence'] = 0;
                    $post['match_model'] = 'deterministic_simple';
                    if (!isset($post['insights'])) {
                        $post['insights'] = $this->extract_requirement_insights($post);
                    }
                    $post['match_reasons'] = $this->build_match_reasons($cv_parsed, $post);
                    $post['match_warnings'] = $this->build_match_warnings($cv_parsed, $post);
                    $post['gaps'] = $this->build_match_gaps($cv_parsed, $post);
                    $matches[] = $post;
                } catch (Throwable $e) {
                    error_log('Error processing match for post ' . ($post['id'] ?? 'unknown') . ': ' . $e->getMessage() . ' in ' . $e->getFile() . ':' . $e->getLine());
                    // Continue to next post if this one fails
                    continue;
                }
            }

            usort($matches, function ($a, $b) {
                $score_diff = ($b['match_score'] ?? 0) <=> ($a['match_score'] ?? 0);
                if ($score_diff !== 0) {
                    return $score_diff;
                }

                return ($b['match_confidence'] ?? 0) <=> ($a['match_confidence'] ?? 0);
            });

            error_log('Match processing complete. Total: ' . count($posts) . ', Filtered: ' . $filtered_count . ', Matches: ' . count($matches));

            foreach ($matches as &$match) {
                $permalink = $this->resolve_recommended_post_public_permalink($match);
                $internal_permalink = $this->resolve_recommended_post_internal_permalink($match);

                $match['permalink'] = $permalink ?: '';
                $match['internal_permalink'] = $internal_permalink ?: '';
                $match['jobs_post_id'] = !empty($match['jobs_post_id']) ? (int) $match['jobs_post_id'] : 0;
            }
            unset($match);

            wp_send_json_success([
                'items' => array_slice($matches, 0, 50), // Return top 50 matches
                'report' => $this->build_cv_match_results_report($cv_parsed, $matches),
                'has_cv' => true,
                'total' => count($matches)
            ]);
        } catch (Throwable $e) {
            error_log('Fatal error in get_matches(): ' . $e->getMessage() . ' in ' . $e->getFile() . ':' . $e->getLine());
            error_log('Stack trace: ' . $e->getTraceAsString());
            wp_send_json_error([
                'message' => 'An error occurred while processing matches. Please try again.'
            ]);
        }
    }

    private function passes_cv_match_search_filters($post, $filters)
    {
        $filters = is_array($filters) ? $filters : [];
        $role_filter = $this->normalize_cv_match_search_value($filters['role'] ?? '');
        $location_filter = $this->normalize_cv_match_search_value($filters['location'] ?? '');
        $specialisation_filter = $this->normalize_cv_match_search_value($filters['specialisation'] ?? '');
        $seniority_filter = $this->normalize_cv_match_search_value($filters['seniority'] ?? '');

        if ($role_filter !== '') {
            $role_haystack = $this->normalize_cv_match_search_value(
                implode(' ', array_filter([
                    (string) ($post['role_title'] ?? ''),
                    (string) ($post['company'] ?? ''),
                ]))
            );
            if ($role_haystack === '' || strpos($role_haystack, $role_filter) === false) {
                return false;
            }
        }

        if ($location_filter !== '') {
            $location_haystack = $this->normalize_cv_match_search_value(
                implode(' ', array_filter([
                    (string) ($post['location'] ?? ''),
                    (string) ($post['location_city'] ?? ''),
                    (string) ($post['location_country'] ?? ''),
                ]))
            );
            if ($location_haystack === '' || strpos($location_haystack, $location_filter) === false) {
                return false;
            }
        }

        if ($specialisation_filter !== '') {
            $specialisation_haystack = $this->normalize_cv_match_search_value(
                implode(' ', array_filter([
                    (string) ($post['sector'] ?? ''),
                    (string) ($post['specialisation'] ?? ''),
                    (string) ($post['specialization'] ?? ''),
                    is_array($post['recruiter_specializations'] ?? null)
                        ? implode(' ', array_map('strval', (array) $post['recruiter_specializations']))
                        : (string) ($post['recruiter_specializations'] ?? ''),
                    (string) ($post['role_title'] ?? ''),
                ]))
            );
            if ($specialisation_haystack === '' || strpos($specialisation_haystack, $specialisation_filter) === false) {
                return false;
            }
        }

        if ($seniority_filter !== '') {
            $post_seniority = $this->normalize_cv_match_search_value(
                (string) (!empty($post['seniority']) ? $post['seniority'] : $this->infer_seniority_from_post((array) $post))
            );
            if (!$this->cv_match_search_seniority_matches($post_seniority, $seniority_filter)) {
                return false;
            }
        }

        return true;
    }

    private function normalize_cv_match_search_value($value)
    {
        $value = strtolower(trim((string) $value));
        if ($value === '') {
            return '';
        }

        $value = preg_replace('/[^a-z0-9]+/', ' ', $value);
        return trim((string) $value);
    }

    private function cv_match_search_seniority_matches($candidate, $requested)
    {
        $candidate = $this->normalize_cv_match_search_value($candidate);
        $requested = $this->normalize_cv_match_search_value($requested);

        if ($candidate === '' || $requested === '') {
            return false;
        }

        $groups = [
            'intern' => ['intern', 'internship', 'graduate', 'junior'],
            'analyst' => ['analyst', 'senior analyst'],
            'associate' => ['associate', 'senior associate'],
            'vp' => ['vp', 'vice president', 'avp', 'director', 'executive director'],
        ];

        foreach ($groups as $group => $aliases) {
            if ($requested === $group || in_array($requested, $aliases, true)) {
                return in_array($candidate, $aliases, true) || $candidate === $group;
            }
        }

        return $candidate === $requested;
    }

    private function build_cv_match_results_report($cv_parsed, $matches)
    {
        $all_matches = array_values(is_array($matches) ? $matches : []);
        $all_match_count = count($all_matches);
        $top_matches = array_values(array_slice(is_array($matches) ? $matches : [], 0, 8));
        if (empty($top_matches)) {
            return null;
        }

        $top_focus = array_values(array_slice($top_matches, 0, 5));
        $best_match = $top_matches[0];
        $score_values = array_map(static function ($item) {
            return (int) ($item['match_score'] ?? 0);
        }, $top_focus);
        $average_score = !empty($score_values) ? (int) round(array_sum($score_values) / count($score_values)) : 0;

        $role_summary = $this->build_cv_match_report_roles($top_matches);
        $lane_data = $this->build_cv_match_report_lanes($top_matches);
        $primary_lane = !empty($lane_data[0]['label']) ? (string) $lane_data[0]['label'] : __('Finance opportunities', 'senna-finance');
        $keyword_summary = $this->build_cv_match_report_keywords($cv_parsed, $top_focus);
        $recruiter_summary = $this->build_cv_match_report_recruiters($top_matches);
        $market_summary = $this->build_cv_match_report_markets($top_matches);
        $salary_summary = $this->build_cv_match_report_salary($top_matches, $market_summary);
        $fit_distribution = $this->build_cv_match_report_fit_distribution($top_matches);
        $blocker_summary = $this->build_cv_match_report_blockers($top_matches);
        $actions = $this->build_cv_match_report_actions($cv_parsed, $top_matches, $lane_data, $keyword_summary, $market_summary, $salary_summary);
        $recruiter_match_count = count(array_filter($top_matches, static function ($match) {
            return !empty($match['recruiter_name'])
                || !empty($match['recruiter_firm'])
                || !empty($match['recruiter_email'])
                || !empty($match['recruiter_linkedin'])
                || !empty($match['recruiter_photo'])
                || !empty($match['recruiter_id']);
        }));
        $keyword_coverage = (int) ($keyword_summary['coverage_score'] ?? 0);
        $salary_estimate = (array) ($salary_summary['estimate'] ?? []);

        $top_role = trim((string) ($best_match['role_title'] ?? ''));
        $top_company = trim((string) ($best_match['company'] ?? ''));
        $top_market = !empty($market_summary['items'][0]['label']) ? (string) $market_summary['items'][0]['label'] : trim((string) ($best_match['location'] ?? ''));
        $headline = sprintf(__('You are currently strongest for %s roles', 'senna-finance'), $primary_lane);
        $summary_parts = [];

        if ($top_role !== '') {
            $summary_parts[] = $top_company !== ''
                ? sprintf(__('Top current fit: %1$s at %2$s.', 'senna-finance'), $top_role, $top_company)
                : sprintf(__('Top current fit: %s.', 'senna-finance'), $top_role);
        }

        if ($top_market !== '') {
            $summary_parts[] = sprintf(__('Most live momentum is currently clustering around %s.', 'senna-finance'), $top_market);
        }

        if (!empty($salary_estimate['display'])) {
            $summary_parts[] = sprintf(
                __('Estimated target salary in %1$s: %2$s.', 'senna-finance'),
                $top_market !== '' ? $top_market : __('your strongest live market', 'senna-finance'),
                (string) $salary_estimate['display']
            );
        }

        if (!empty($keyword_summary['missing'])) {
            $summary_parts[] = sprintf(
                __('Biggest ATS gap right now: %s.', 'senna-finance'),
                implode(', ', array_slice((array) $keyword_summary['missing'], 0, 2))
            );
        } elseif (!empty($keyword_summary['matched'])) {
            $summary_parts[] = sprintf(
                __('Your CV is already surfacing %s.', 'senna-finance'),
                implode(', ', array_slice((array) $keyword_summary['matched'], 0, 2))
            );
        }

        $tools = [
            __('Open a top match and generate Interview Questions before first-round calls.', 'senna-finance'),
            __('Use ATS gaps to tighten your CV language before you submit applications.', 'senna-finance'),
            __('Queue the strongest roles into Recruiter Outreach once your CV is aligned.', 'senna-finance'),
        ];

        $summary_metrics = [
            [
                'label' => __('All Matches', 'senna-finance'),
                'value' => (string) $all_match_count,
                'meta'  => sprintf(_n('%d live role scored from your current CV', '%d live roles scored from your current CV', $all_match_count, 'senna-finance'), $all_match_count),
            ],
            [
                'label' => __('ATS coverage', 'senna-finance'),
                'value' => $keyword_coverage . '%',
                'meta'  => !empty($keyword_summary['matched_count']) || !empty($keyword_summary['total_terms'])
                    ? sprintf(__('Matched %1$d of %2$d recurring signals', 'senna-finance'), (int) ($keyword_summary['matched_count'] ?? 0), (int) ($keyword_summary['total_terms'] ?? 0))
                    : __('Recurring role language will appear once more signals are detected.', 'senna-finance'),
            ],
            [
                'label' => __('Recruiter Matches', 'senna-finance'),
                'value' => (string) $recruiter_match_count,
                'meta'  => $recruiter_match_count > 0
                    ? sprintf(_n('%d top role already includes recruiter context', '%d top roles already include recruiter context', $recruiter_match_count, 'senna-finance'), $recruiter_match_count)
                    : __('Recruiter context will appear once stronger live hiring signals show up', 'senna-finance'),
            ],
            [
                'label' => __('Estimated Target Salary', 'senna-finance'),
                'value' => !empty($salary_estimate['display']) ? (string) $salary_estimate['display'] : __('Calibrating', 'senna-finance'),
                'meta'  => !empty($salary_estimate['note'])
                    ? (string) $salary_estimate['note']
                    : __('MENA Careers is estimating compensation from your strongest live role set.', 'senna-finance'),
            ],
        ];

        return [
            'summary' => [
                'eyebrow' => __('Your Match Report', 'senna-finance'),
                'headline' => $headline,
                'copy' => implode(' ', array_filter($summary_parts)),
                'score' => max(0, min(99, $average_score)),
                'score_label' => __('Top-fit average', 'senna-finance'),
                'primary_lane' => $primary_lane,
                'metrics' => $summary_metrics,
                'top_market' => $top_market,
                'salary_estimate' => $salary_estimate,
            ],
            'cards' => [
                [
                    'type' => 'roles',
                    'title' => __('Strongest Live Roles', 'senna-finance'),
                    'copy' => __('These are the live opportunities currently sitting closest to your CV profile.', 'senna-finance'),
                    'items' => $role_summary,
                ],
                [
                    'type' => 'lanes',
                    'title' => __('Best-Fit Role Lanes', 'senna-finance'),
                    'copy' => __('These are the role lanes where your current CV is clustering most strongly.', 'senna-finance'),
                    'items' => $lane_data,
                ],
                [
                    'type' => 'keywords',
                    'title' => __('ATS Keyword Gaps', 'senna-finance'),
                    'copy' => $keyword_summary['copy'],
                    'matched' => $keyword_summary['matched'],
                    'missing' => $keyword_summary['missing'],
                    'score' => (int) ($keyword_summary['coverage_score'] ?? 0),
                    'summary' => sprintf(
                        __('%1$d matched · %2$d still missing', 'senna-finance'),
                        (int) ($keyword_summary['matched_count'] ?? 0),
                        (int) ($keyword_summary['missing_count'] ?? 0)
                    ),
                ],
                [
                    'type' => 'recruiters',
                    'title' => __('Recruiter Matches', 'senna-finance'),
                    'copy' => __('These recruiters or hiring lanes are sitting closest to your strongest live matches.', 'senna-finance'),
                    'items' => $recruiter_summary,
                ],
                [
                    'type' => 'markets',
                    'title' => __('Live Market Concentration', 'senna-finance'),
                    'copy' => $market_summary['copy'],
                    'items' => (array) ($market_summary['items'] ?? []),
                ],
                [
                    'type' => 'distribution',
                    'title' => __('Fit Distribution', 'senna-finance'),
                    'copy' => __('This is how your strongest current role set is splitting across fit quality.', 'senna-finance'),
                    'items' => (array) ($fit_distribution['items'] ?? []),
                ],
                [
                    'type' => 'blockers',
                    'title' => __('Top Blockers', 'senna-finance'),
                    'copy' => $blocker_summary['copy'],
                    'items' => (array) ($blocker_summary['items'] ?? []),
                ],
                [
                    'type' => 'salary',
                    'title' => __('Salary & Market Context', 'senna-finance'),
                    'copy' => $salary_summary['copy'],
                    'items' => $salary_summary['items'],
                ],
                [
                    'type' => 'actions',
                    'title' => __('How To Get These Jobs', 'senna-finance'),
                    'copy' => __('Practical next steps based on the gaps and patterns across your strongest matches.', 'senna-finance'),
                    'items' => $actions,
                ],
                [
                    'type' => 'tools',
                    'title' => __('Use MENA Careers Next', 'senna-finance'),
                    'copy' => __('Keep moving through the workflow once you have your strongest matches in view.', 'senna-finance'),
                    'items' => $tools,
                ],
            ],
        ];
    }

    private function build_cv_match_report_roles($matches)
    {
        $items = [];

        foreach (array_slice((array) $matches, 0, 3) as $match) {
            $meta_parts = [];
            $company = trim((string) ($match['company'] ?? ''));
            $location = trim((string) ($match['location'] ?? ''));

            if ($company !== '') {
                $meta_parts[] = $company;
            }
            if ($location !== '') {
                $meta_parts[] = $location;
            }
            $meta_parts[] = sprintf(__('%d%% match', 'senna-finance'), (int) ($match['match_score'] ?? 0));

            $items[] = [
                'label' => trim((string) ($match['role_title'] ?? __('Matched role', 'senna-finance'))),
                'meta' => implode(' · ', array_filter($meta_parts)),
                'avatar' => trim((string) ($match['company_logo'] ?? '')),
                'avatar_fallback' => $this->build_cv_match_report_initials($company !== '' ? $company : (string) ($match['role_title'] ?? '')),
            ];
        }

        return $items;
    }

    private function build_cv_match_report_lanes($matches)
    {
        $lanes = [];
        $total = max(1, count((array) $matches));

        foreach ((array) $matches as $match) {
            $lane_key = $this->detect_cv_match_role_lane_key($match);
            if (!isset($lanes[$lane_key])) {
                $lanes[$lane_key] = [
                    'label' => $this->format_cv_match_role_lane_label($lane_key, $match),
                    'count' => 0,
                    'score_total' => 0,
                ];
            }

            $lanes[$lane_key]['count']++;
            $lanes[$lane_key]['score_total'] += (int) ($match['match_score'] ?? 0);
        }

        uasort($lanes, static function ($left, $right) {
            $left_average = !empty($left['count']) ? ($left['score_total'] / $left['count']) : 0;
            $right_average = !empty($right['count']) ? ($right['score_total'] / $right['count']) : 0;
            $score_compare = $right_average <=> $left_average;
            if ($score_compare !== 0) {
                return $score_compare;
            }

            return ($right['count'] ?? 0) <=> ($left['count'] ?? 0);
        });

        $items = [];
        foreach (array_slice($lanes, 0, 3) as $lane) {
            $avg = !empty($lane['count']) ? (int) round($lane['score_total'] / $lane['count']) : 0;
            $items[] = [
                'label' => (string) ($lane['label'] ?? ''),
                'meta' => sprintf(
                    _n('%1$d role · %2$d%% average', '%1$d roles · %2$d%% average', (int) ($lane['count'] ?? 0), 'senna-finance'),
                    (int) ($lane['count'] ?? 0),
                    $avg
                ),
                'score' => $avg,
                'share' => (int) round((((int) ($lane['count'] ?? 0)) / $total) * 100),
            ];
        }

        return $items;
    }

    private function build_cv_match_report_keywords($cv_parsed, $matches)
    {
        $counts = [];
        $cv_lower = strtolower((string) ($cv_parsed['lower'] ?? ''));

        foreach ((array) $matches as $match) {
            $terms = array_merge(
                $this->collect_list_terms($match['keywords'] ?? []),
                $this->collect_list_terms($match['skills_mentioned'] ?? []),
                [trim((string) ($match['sector'] ?? ''))]
            );

            foreach ($terms as $term) {
                $clean = trim((string) $term);
                if ($clean === '' || $this->should_skip_cv_match_report_term($clean)) {
                    continue;
                }
                $counts[$clean] = (int) ($counts[$clean] ?? 0) + 1;
            }
        }

        arsort($counts);

        $matched = [];
        $missing = [];
        foreach (array_keys($counts) as $term) {
            if ($this->cv_match_report_term_visible($cv_lower, $term)) {
                if (count($matched) < 5) {
                    $matched[] = $term;
                }
            } else {
                if (count($missing) < 5) {
                    $missing[] = $term;
                }
            }

            if (count($matched) >= 5 && count($missing) >= 5) {
                break;
            }
        }

        if (!empty($missing)) {
            $copy = sprintf(
                __('Most commonly missing across your top matches: %s.', 'senna-finance'),
                implode(', ', array_slice($missing, 0, 3))
            );
        } elseif (!empty($matched)) {
            $copy = sprintf(
                __('Your CV is already surfacing the strongest repeated signals: %s.', 'senna-finance'),
                implode(', ', array_slice($matched, 0, 3))
            );
        } else {
            $copy = __('MENA Careers will surface ATS language once stronger recurring role signals appear in the current match set.', 'senna-finance');
        }

        $matched_count = count($matched);
        $missing_count = count($missing);
        $total_terms = max(1, $matched_count + $missing_count);
        $coverage_score = (int) round(($matched_count / $total_terms) * 100);

        return [
            'matched' => $matched,
            'missing' => $missing,
            'copy' => $copy,
            'matched_count' => $matched_count,
            'missing_count' => $missing_count,
            'total_terms' => $matched_count + $missing_count,
            'coverage_score' => $coverage_score,
        ];
    }

    private function build_cv_match_report_recruiters($matches)
    {
        $groups = [];

        foreach ((array) $matches as $match) {
            $name = trim((string) ($match['recruiter_name'] ?? ''));
            $firm = trim((string) ($match['recruiter_firm'] ?? ''));
            $label = $name !== '' ? $name : ($firm !== '' ? $firm : __('Recruiter lane', 'senna-finance'));
            $key = !empty($match['recruiter_id']) ? 'id:' . (int) $match['recruiter_id'] : strtolower($label . '|' . $firm);

            if (!isset($groups[$key])) {
                $groups[$key] = [
                    'label' => $label,
                    'firm' => $firm,
                    'count' => 0,
                    'score_total' => 0,
                    'location' => trim((string) ($match['location'] ?? '')),
                    'avatar' => trim((string) ($match['recruiter_photo'] ?? '')),
                    'avatar_fallback' => $this->build_cv_match_report_initials($label),
                ];
            }

            $groups[$key]['count']++;
            $groups[$key]['score_total'] += (int) ($match['match_score'] ?? 0);
        }

        uasort($groups, static function ($left, $right) {
            $left_avg = !empty($left['count']) ? ($left['score_total'] / $left['count']) : 0;
            $right_avg = !empty($right['count']) ? ($right['score_total'] / $right['count']) : 0;
            $score_compare = $right_avg <=> $left_avg;
            if ($score_compare !== 0) {
                return $score_compare;
            }
            return ($right['count'] ?? 0) <=> ($left['count'] ?? 0);
        });

        $items = [];
        foreach (array_slice($groups, 0, 3) as $group) {
            $avg = !empty($group['count']) ? (int) round($group['score_total'] / $group['count']) : 0;
            $meta_parts = [];
            if (!empty($group['firm']) && $group['firm'] !== $group['label']) {
                $meta_parts[] = $group['firm'];
            }
            if (!empty($group['location'])) {
                $meta_parts[] = $group['location'];
            }
            $meta_parts[] = sprintf(
                _n('%1$d matching role · %2$d%% avg', '%1$d matching roles · %2$d%% avg', (int) ($group['count'] ?? 0), 'senna-finance'),
                (int) ($group['count'] ?? 0),
                $avg
            );

            $items[] = [
                'label' => (string) ($group['label'] ?? ''),
                'meta' => implode(' · ', array_filter($meta_parts)),
                'avatar' => (string) ($group['avatar'] ?? ''),
                'avatar_fallback' => (string) ($group['avatar_fallback'] ?? ''),
                'score' => $avg,
            ];
        }

        return $items;
    }

    private function build_cv_match_report_salary($matches, array $market_summary = [])
    {
        $items = [];
        $top_market = !empty($market_summary['items'][0]['label']) ? (string) $market_summary['items'][0]['label'] : '';

        foreach ((array) $matches as $match) {
            $display = trim((string) ($match['salary_text'] ?? ''));
            if ($display === '') {
                $min = isset($match['salary_min']) ? (int) $match['salary_min'] : 0;
                $max = isset($match['salary_max']) ? (int) $match['salary_max'] : 0;
                $currency = trim((string) ($match['salary_currency'] ?? ''));
                if ($min > 0 && $max > 0) {
                    $display = sprintf('%s %s - %s', $currency !== '' ? $currency : 'GBP', number_format_i18n($min), number_format_i18n($max));
                } elseif ($min > 0) {
                    $display = sprintf('%s %s+', $currency !== '' ? $currency : 'GBP', number_format_i18n($min));
                }
            }

            if ($display === '') {
                continue;
            }

            $items[] = [
                'label' => trim((string) ($match['role_title'] ?? __('Matched role', 'senna-finance'))),
                'meta' => $display,
                'score' => (int) ($match['match_score'] ?? 0),
            ];

            if (count($items) >= 3) {
                break;
            }
        }

        if (!empty($items)) {
            $copy = __('These are the salary disclosures currently visible across your strongest live matches.', 'senna-finance');
        } else {
            $copy = __('Most of the current top matches are not publishing salary, so use role lane and market fit first before filtering on compensation.', 'senna-finance');
        }

        $estimate = $this->build_cv_match_report_salary_estimate($matches, $top_market);

        return [
            'copy' => $copy,
            'items' => $items,
            'count' => count($items),
            'estimate' => $estimate,
        ];
    }

    private function build_cv_match_report_salary_estimate($matches, $preferred_market = '')
    {
        $preferred_market_label = trim((string) $preferred_market);
        $preferred_market = strtolower($preferred_market_label);
        $rows = [];

        foreach ((array) $matches as $match) {
            $min = isset($match['salary_min']) ? (int) $match['salary_min'] : 0;
            $max = isset($match['salary_max']) ? (int) $match['salary_max'] : 0;
            $currency = strtoupper(trim((string) ($match['salary_currency'] ?? '')));
            $location = strtolower(trim((string) ($match['location'] ?? '')));

            if ($currency === '' || ($min <= 0 && $max <= 0)) {
                continue;
            }

            if ($min <= 0 && $max > 0) {
                $min = $max;
            }
            if ($max <= 0 && $min > 0) {
                $max = $min;
            }
            if ($min <= 0 && $max <= 0) {
                continue;
            }

            $rows[] = [
                'currency' => $currency,
                'min' => $min,
                'max' => max($min, $max),
                'location' => $location,
            ];
        }

        if (empty($rows)) {
            return $this->infer_cv_match_report_salary_estimate_from_market($matches, $preferred_market_label);
        }

        $market_rows = [];
        if ($preferred_market !== '') {
            foreach ($rows as $row) {
                if ($row['location'] !== '' && strpos($row['location'], $preferred_market) !== false) {
                    $market_rows[] = $row;
                }
            }
        }

        $candidate_rows = !empty($market_rows) ? $market_rows : $rows;
        $currency_counts = [];
        foreach ($candidate_rows as $row) {
            $currency_counts[$row['currency']] = (int) ($currency_counts[$row['currency']] ?? 0) + 1;
        }

        arsort($currency_counts);
        $dominant_currency = (string) array_key_first($currency_counts);
        if ($dominant_currency === '') {
            $dominant_currency = 'GBP';
        }

        $final_rows = array_values(array_filter($candidate_rows, static function ($row) use ($dominant_currency) {
            return (string) ($row['currency'] ?? '') === $dominant_currency;
        }));
        if (empty($final_rows)) {
            $final_rows = $candidate_rows;
        }

        $mins = array_map(static function ($row) {
            return (int) ($row['min'] ?? 0);
        }, $final_rows);
        $maxs = array_map(static function ($row) {
            return (int) ($row['max'] ?? 0);
        }, $final_rows);

        $average_min = !empty($mins) ? (int) round(array_sum($mins) / count($mins)) : 0;
        $average_max = !empty($maxs) ? (int) round(array_sum($maxs) / count($maxs)) : 0;

        if ($average_min <= 0 && $average_max > 0) {
            $average_min = $average_max;
        }
        if ($average_max <= 0 && $average_min > 0) {
            $average_max = $average_min;
        }

        if ($average_min <= 0 && $average_max <= 0) {
            return $this->infer_cv_match_report_salary_estimate_from_market($matches, $preferred_market_label, $dominant_currency);
        }

        $display = $average_max > $average_min
            ? sprintf('%s %s - %s', $dominant_currency, number_format_i18n($average_min), number_format_i18n($average_max))
            : sprintf('%s %s+', $dominant_currency, number_format_i18n($average_min));

        $note = $preferred_market !== ''
            ? sprintf(
                _n('Estimated from %1$d disclosed match in %2$s', 'Estimated from %1$d disclosed matches in %2$s', count($final_rows), 'senna-finance'),
                count($final_rows),
                $preferred_market_label
            )
            : sprintf(
                _n('Estimated from %d disclosed live match', 'Estimated from %d disclosed live matches', count($final_rows), 'senna-finance'),
                count($final_rows)
            );

        return [
            'display' => $display,
            'currency' => $dominant_currency,
            'count' => count($final_rows),
            'min' => $average_min,
            'max' => $average_max,
            'note' => $note,
        ];
    }

    private function infer_cv_match_report_salary_estimate_from_market($matches, $preferred_market = '', $preferred_currency = '')
    {
        $top_match = !empty($matches[0]) && is_array($matches[0]) ? $matches[0] : [];
        $seniority = trim((string) ($top_match['seniority'] ?? ''));
        if ($seniority === '' || $seniority === 'other') {
            $seniority = $this->infer_seniority_from_post($top_match);
        }

        $profile = $this->get_cv_match_report_salary_market_profile($preferred_market, $preferred_currency);
        $base_ranges = [
            'intern' => [25000, 35000],
            'analyst' => [65000, 95000],
            'associate' => [90000, 140000],
            'vp' => [160000, 240000],
            'director' => [220000, 360000],
            'md' => [320000, 600000],
            'c_level' => [380000, 750000],
            'other' => [80000, 120000],
        ];

        $range = $base_ranges[$seniority] ?? $base_ranges['other'];
        $average_min = (int) round($range[0] * (float) ($profile['multiplier'] ?? 1));
        $average_max = (int) round($range[1] * (float) ($profile['multiplier'] ?? 1));
        $currency = (string) ($profile['currency'] ?? 'GBP');

        return [
            'display' => sprintf('%s %s - %s', $currency, number_format_i18n($average_min), number_format_i18n($average_max)),
            'currency' => $currency,
            'count' => 0,
            'min' => $average_min,
            'max' => $average_max,
            'note' => __('Estimated from role titles, seniority, and market when live salary disclosures are limited.', 'senna-finance'),
        ];
    }

    private function get_cv_match_report_salary_market_profile($preferred_market = '', $preferred_currency = '')
    {
        $market = strtolower(trim((string) $preferred_market));
        $currency = strtoupper(trim((string) $preferred_currency));

        $profiles = [
            'dubai' => ['currency' => 'AED', 'multiplier' => 4.9],
            'abu dhabi' => ['currency' => 'AED', 'multiplier' => 4.9],
            'uae' => ['currency' => 'AED', 'multiplier' => 4.9],
            'london' => ['currency' => 'GBP', 'multiplier' => 1.0],
            'united kingdom' => ['currency' => 'GBP', 'multiplier' => 1.0],
            'new york' => ['currency' => 'USD', 'multiplier' => 1.85],
            'san francisco' => ['currency' => 'USD', 'multiplier' => 2.0],
            'paris' => ['currency' => 'EUR', 'multiplier' => 1.05],
            'france' => ['currency' => 'EUR', 'multiplier' => 1.0],
            'milan' => ['currency' => 'EUR', 'multiplier' => 0.9],
            'italy' => ['currency' => 'EUR', 'multiplier' => 0.9],
            'munich' => ['currency' => 'EUR', 'multiplier' => 1.0],
            'frankfurt' => ['currency' => 'EUR', 'multiplier' => 1.05],
            'germany' => ['currency' => 'EUR', 'multiplier' => 1.0],
            'singapore' => ['currency' => 'SGD', 'multiplier' => 1.75],
            'hong kong' => ['currency' => 'HKD', 'multiplier' => 10.0],
            'zurich' => ['currency' => 'CHF', 'multiplier' => 1.15],
        ];

        foreach ($profiles as $needle => $profile) {
            if ($market !== '' && strpos($market, $needle) !== false) {
                return $profile;
            }
        }

        if ($currency !== '') {
            return [
                'currency' => $currency,
                'multiplier' => 1.0,
            ];
        }

        return [
            'currency' => 'GBP',
            'multiplier' => 1.0,
        ];
    }

    private function build_cv_match_report_markets($matches)
    {
        $counts = [];

        foreach ((array) $matches as $match) {
            $location = trim((string) ($match['location'] ?? ''));
            if ($location === '') {
                continue;
            }
            $counts[$location] = (int) ($counts[$location] ?? 0) + 1;
        }

        arsort($counts);
        $total = max(1, array_sum($counts));

        $items = [];
        foreach (array_slice($counts, 0, 3, true) as $location => $count) {
            $items[] = [
                'label' => (string) $location,
                'count' => (int) $count,
                'meta' => sprintf(
                    _n('%d matched role', '%d matched roles', (int) $count, 'senna-finance'),
                    (int) $count
                ),
                'share' => (int) round((((int) $count) / $total) * 100),
            ];
        }

        return [
            'copy' => !empty($items)
                ? __('This is where your strongest live matches are currently clustering by market.', 'senna-finance')
                : __('No reliable market pattern has surfaced yet in the current live match set.', 'senna-finance'),
            'items' => $items,
        ];
    }

    private function build_cv_match_report_fit_distribution($matches)
    {
        $total = max(1, count((array) $matches));
        $strong = 0;
        $good = 0;
        $stretch = 0;

        foreach ((array) $matches as $match) {
            $score = (int) ($match['match_score'] ?? 0);
            if ($score >= 70) {
                $strong++;
            } elseif ($score >= 50) {
                $good++;
            } else {
                $stretch++;
            }
        }

        return [
            'items' => [
                [
                    'label' => __('Strong Fit', 'senna-finance'),
                    'meta' => sprintf(_n('%d role', '%d roles', $strong, 'senna-finance'), $strong),
                    'share' => (int) round(($strong / $total) * 100),
                ],
                [
                    'label' => __('Good Fit', 'senna-finance'),
                    'meta' => sprintf(_n('%d role', '%d roles', $good, 'senna-finance'), $good),
                    'share' => (int) round(($good / $total) * 100),
                ],
                [
                    'label' => __('Stretch Fit', 'senna-finance'),
                    'meta' => sprintf(_n('%d role', '%d roles', $stretch, 'senna-finance'), $stretch),
                    'share' => (int) round(($stretch / $total) * 100),
                ],
            ],
        ];
    }

    private function build_cv_match_report_blockers($matches)
    {
        $groups = [];
        $label_map = [
            'language_gap' => __('Language requirement', 'senna-finance'),
            'qualification_gap' => __('Qualification requirement', 'senna-finance'),
            'required_skill_gap' => __('Core skill evidence', 'senna-finance'),
            'nationality_requirement' => __('Eligibility or work authorisation', 'senna-finance'),
            'experience_gap' => __('Experience depth', 'senna-finance'),
        ];

        foreach ((array) $matches as $match) {
            foreach ((array) ($match['gaps'] ?? []) as $gap) {
                $type = sanitize_key((string) ($gap['type'] ?? 'required_skill_gap'));
                if ($type === '') {
                    $type = 'required_skill_gap';
                }
                if (!isset($groups[$type])) {
                    $groups[$type] = [
                        'label' => (string) ($label_map[$type] ?? ucwords(str_replace('_', ' ', $type))),
                        'count' => 0,
                        'severity' => (string) ($gap['severity'] ?? 'medium'),
                    ];
                }
                $groups[$type]['count']++;
            }

            if (!empty($match['detected_years']) && !empty($match['match_warnings'])) {
                foreach ((array) $match['match_warnings'] as $warning) {
                    if (stripos((string) $warning, 'experience') !== false) {
                        if (!isset($groups['experience_gap'])) {
                            $groups['experience_gap'] = [
                                'label' => __('Experience depth', 'senna-finance'),
                                'count' => 0,
                                'severity' => 'high',
                            ];
                        }
                        $groups['experience_gap']['count']++;
                        break;
                    }
                }
            }
        }

        uasort($groups, static function ($left, $right) {
            return ((int) ($right['count'] ?? 0)) <=> ((int) ($left['count'] ?? 0));
        });

        $total = 0;
        foreach ($groups as $group) {
            $total += (int) ($group['count'] ?? 0);
        }
        $total = max(1, $total);

        $items = [];
        foreach (array_slice($groups, 0, 4) as $group) {
            $count = (int) ($group['count'] ?? 0);
            $items[] = [
                'label' => (string) ($group['label'] ?? ''),
                'meta' => sprintf(_n('Flagged in %d top role', 'Flagged in %d top roles', $count, 'senna-finance'), $count),
                'share' => (int) round(($count / $total) * 100),
            ];
        }

        return [
            'copy' => !empty($items)
                ? __('These are the recurring blockers appearing most often across your top current matches.', 'senna-finance')
                : __('No recurring blocker pattern is dominating the current top match set.', 'senna-finance'),
            'items' => $items,
        ];
    }

    private function build_cv_match_report_actions($cv_parsed, $matches, $lane_data, $keyword_summary, $market_summary, $salary_summary)
    {
        $actions = [];

        if (!empty($keyword_summary['missing'])) {
            $actions[] = sprintf(
                __('Rewrite your strongest experience bullets to include language around %s.', 'senna-finance'),
                implode(', ', array_slice((array) $keyword_summary['missing'], 0, 3))
            );
        }

        if (!empty($lane_data[0]['label'])) {
            $actions[] = sprintf(
                __('Bias your applications toward %s roles first, because that is where your current CV is clustering most strongly.', 'senna-finance'),
                $lane_data[0]['label']
            );
        }

        $required_years = [];
        foreach ((array) $matches as $match) {
            $years = (int) ($match['detected_years'] ?? 0);
            if ($years > 0) {
                $required_years[] = $years;
            }
        }
        if (!empty($required_years)) {
            $median_required = (int) round(array_sum($required_years) / count($required_years));
            $cv_years = (float) ($cv_parsed['experience_years'] ?? 0);
            if ($cv_years > 0 && $cv_years + 0.8 < $median_required) {
                $actions[] = sprintf(
                    __('Target internship, off-cycle, and analyst routes that sit closer to %d years of required experience before pushing further up-market.', 'senna-finance'),
                    $median_required
                );
            }
        }

        if (!empty($market_summary['items'][0]['label'])) {
            $actions[] = sprintf(
                __('Prioritise applications in %s first, because that is where the strongest current live concentration is showing up.', 'senna-finance'),
                $market_summary['items'][0]['label']
            );
        }

        if (empty($actions)) {
            $actions[] = __('Open the top match first, tighten the missing ATS language, and then use Interview Questions plus Recruiter Outreach from that role page.', 'senna-finance');
        }

        return array_slice(array_values(array_unique(array_filter($actions))), 0, 4);
    }

    private function build_cv_match_report_initials($value)
    {
        $text = trim(wp_strip_all_tags((string) $value));
        if ($text === '') {
            return 'S';
        }

        $parts = preg_split('/\s+/', $text) ?: [];
        $initials = '';
        foreach ($parts as $part) {
            $part = trim((string) $part);
            if ($part === '') {
                continue;
            }
            $initials .= strtoupper(substr($part, 0, 1));
            if (strlen($initials) >= 2) {
                break;
            }
        }

        if ($initials === '') {
            $initials = strtoupper(substr($text, 0, 1));
        }

        return $initials;
    }

    private function get_cv_match_report_ai_api_key()
    {
        $api_key = get_option('sffc_api_key', '');

        if ($api_key === '') {
            $api_key = get_option('sffc_anthropic_key', '');
        }

        if ($api_key === '') {
            $api_key = get_option('sffc_claude_api_key', '');
        }

        if ($api_key === '' && defined('ANTHROPIC_API_KEY')) {
            $api_key = ANTHROPIC_API_KEY;
        }

        if ($api_key === '' && class_exists('SFFC_API_Key_Manager')) {
            $key_manager = SFFC_API_Key_Manager::get_instance();
            $api_key = $key_manager->get_api_key();
        }

        if ($api_key === '' && class_exists('SFFC_Claude_API_Manager')) {
            $manager = SFFC_Claude_API_Manager::get_instance();
            if (method_exists($manager, 'get_api_key')) {
                $api_key = (string) $manager->get_api_key();
            }
        }

        return is_string($api_key) ? trim($api_key) : '';
    }

    private function get_cv_match_report_ai_model()
    {
        return 'claude-sonnet-4-6';
    }

    private function call_cv_match_report_ai_claude(array $context)
    {
        $api_key = $this->get_cv_match_report_ai_api_key();
        $cv_text = trim((string) ($context['cv_text'] ?? ''));
        $matches = (array) ($context['matches'] ?? []);
        if ($api_key === '' || $cv_text === '' || empty($matches)) {
            return null;
        }

        $request_body = [
            'model' => $this->get_cv_match_report_ai_model(),
            'max_tokens' => 1800,
            'temperature' => 0.1,
            'system' => 'You are MENA Careers’s finance career match strategist.

CRITICAL INSTRUCTIONS:
1. Respond with ONLY valid JSON. No markdown, no commentary, no code fences.
2. Use ONLY the supplied CV text, top matched roles, and deterministic report summary.
3. Be specific, commercially useful, and concise. Avoid generic career advice.
4. Prefer short bullets and compact insight strings over long paragraphs.
5. All numeric scores must be integers from 0 to 100.
6. Return exactly this shape:
{
  "headline": "string",
  "summary": "string",
  "panels": {
    "readiness": {"label": "string", "score": 0, "note": "string"},
    "competition": {"label": "string", "score": 0, "note": "string"},
    "market_timing": {"label": "string", "score": 0, "note": "string"}
  },
  "salary_estimate": {"display": "string", "note": "string"},
  "positioning_moves": ["string"],
  "recruiter_angle": ["string"],
  "interview_focus": ["string"],
  "application_pack": ["string"],
  "watchouts": ["string"]
}
Use the role titles, seniority, markets, and any disclosed pay to estimate a realistic target salary for the strongest live market. If disclosed pay is sparse, infer a realistic finance-market range. salary_estimate.display must never be empty.',
            'messages' => [
                [
                    'role' => 'user',
                    'content' => wp_json_encode([
                        'instruction' => 'Synthesize a strategic CV-to-role report for a finance candidate. Focus on fit quality, what is holding the candidate back, how they should position themselves, what recruiter angle to use, what to prepare for interviews and applications, and what a realistic target salary range looks like in the strongest live market.',
                        'cv_text' => $cv_text,
                        'top_matches' => $matches,
                        'deterministic_report' => (array) ($context['report'] ?? []),
                    ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE),
                ],
            ],
        ];

        $response = wp_remote_post('https://api.anthropic.com/v1/messages', [
            'timeout' => 120,
            'headers' => [
                'Content-Type' => 'application/json',
                'x-api-key' => $api_key,
                'anthropic-version' => '2023-06-01',
            ],
            'body' => wp_json_encode($request_body),
        ]);

        if (is_wp_error($response)) {
            error_log('CV Match Report AI Claude Error: ' . $response->get_error_message());
            return null;
        }

        $status = wp_remote_retrieve_response_code($response);
        $body = json_decode(wp_remote_retrieve_body($response), true);

        if ($status !== 200 || empty($body['content'][0]['text'])) {
            error_log('CV Match Report AI Claude Error: status ' . $status);
            return null;
        }

        $decoded = json_decode((string) $body['content'][0]['text'], true);
        if (!is_array($decoded)) {
            error_log('CV Match Report AI Claude Parse Error: ' . json_last_error_msg());
            return null;
        }

        return [
            'headline' => sanitize_text_field((string) ($decoded['headline'] ?? '')),
            'summary' => sanitize_text_field((string) ($decoded['summary'] ?? '')),
            'panels' => [
                'readiness' => $this->sanitize_cv_match_report_ai_panel((array) ($decoded['panels']['readiness'] ?? [])),
                'competition' => $this->sanitize_cv_match_report_ai_panel((array) ($decoded['panels']['competition'] ?? [])),
                'market_timing' => $this->sanitize_cv_match_report_ai_panel((array) ($decoded['panels']['market_timing'] ?? [])),
            ],
            'salary_estimate' => $this->sanitize_cv_match_report_ai_salary_estimate((array) ($decoded['salary_estimate'] ?? [])),
            'positioning_moves' => $this->sanitize_cv_match_report_ai_list($decoded['positioning_moves'] ?? []),
            'recruiter_angle' => $this->sanitize_cv_match_report_ai_list($decoded['recruiter_angle'] ?? []),
            'interview_focus' => $this->sanitize_cv_match_report_ai_list($decoded['interview_focus'] ?? []),
            'application_pack' => $this->sanitize_cv_match_report_ai_list($decoded['application_pack'] ?? []),
            'watchouts' => $this->sanitize_cv_match_report_ai_list($decoded['watchouts'] ?? []),
        ];
    }

    private function sanitize_cv_match_report_ai_panel(array $panel)
    {
        return [
            'label' => sanitize_text_field((string) ($panel['label'] ?? '')),
            'score' => max(0, min(100, (int) ($panel['score'] ?? 0))),
            'note' => sanitize_text_field((string) ($panel['note'] ?? '')),
        ];
    }

    private function sanitize_cv_match_report_ai_salary_estimate(array $estimate)
    {
        return [
            'display' => sanitize_text_field((string) ($estimate['display'] ?? '')),
            'note' => sanitize_text_field((string) ($estimate['note'] ?? '')),
        ];
    }

    private function sanitize_cv_match_report_ai_list($items)
    {
        $items = is_array($items) ? $items : [];
        $items = array_values(array_filter(array_map(static function ($item) {
            return sanitize_text_field((string) $item);
        }, $items)));

        return array_slice($items, 0, 4);
    }

    private function detect_cv_match_role_lane_key($post)
    {
        $haystack = strtolower(implode(' ', array_filter([
            (string) ($post['role_title'] ?? ''),
            (string) ($post['sector'] ?? ''),
            implode(' ', $this->collect_list_terms($post['keywords'] ?? [])),
            implode(' ', $this->collect_list_terms($post['skills_mentioned'] ?? [])),
        ])));

        $patterns = [
            'investor_relations' => '/investor relations|fundraising|ddq|lp\b|institutional investors|placement agent|rfp|roadshow/',
            'private_equity' => '/private equity|buyout|lbo|value creation|portfolio company/',
            'venture_capital' => '/venture capital|seed|series a|series b|startup|founder/',
            'investment_banking' => '/investment banking|m&a|mergers|acquisition financing|dcm|ecm|leveraged finance|syndication/',
            'asset_management' => '/asset management|investment management|buy-side|equity research|fundamental analysis|portfolio management/',
            'private_credit' => '/private credit|credit analysis|credit memo|covenant|investment grade debt|structured credit|debt pricing/',
            'real_estate' => '/real estate|underwriting|appraisal|offering memoranda|capital structures/',
            'esg' => '/esg|sustainability|decarbonisation|responsible investment/',
        ];

        foreach ($patterns as $key => $pattern) {
            if (preg_match($pattern, $haystack)) {
                return $key;
            }
        }

        return 'finance_general';
    }

    private function format_cv_match_role_lane_label($lane_key, $post = [])
    {
        $labels = [
            'investor_relations' => __('Investor Relations & Fundraising', 'senna-finance'),
            'private_equity' => __('Private Equity', 'senna-finance'),
            'venture_capital' => __('Venture Capital', 'senna-finance'),
            'investment_banking' => __('Investment Banking & Capital Markets', 'senna-finance'),
            'asset_management' => __('Asset Management & Buy-Side Research', 'senna-finance'),
            'private_credit' => __('Private Credit', 'senna-finance'),
            'real_estate' => __('Real Estate Finance', 'senna-finance'),
            'esg' => __('ESG & Sustainability', 'senna-finance'),
            'finance_general' => __('Finance Opportunities', 'senna-finance'),
        ];

        if (!empty($labels[$lane_key])) {
            return $labels[$lane_key];
        }

        $sector = trim((string) ($post['sector'] ?? ''));
        return $sector !== '' ? $sector : __('Finance Opportunities', 'senna-finance');
    }

    private function should_skip_cv_match_report_term($term)
    {
        $normalized = strtolower(trim((string) $term));
        if ($normalized === '') {
            return true;
        }

        $blocked = [
            'role', 'opportunity', 'team', 'london', 'dubai', 'resume', 'cv',
            'application', 'interview', 'finance', 'job', 'company', 'english'
        ];

        if (in_array($normalized, $blocked, true)) {
            return true;
        }

        return strlen($normalized) < 3 && !in_array($normalized, ['ai', 'm&a'], true);
    }

    private function cv_match_report_term_visible($cv_lower, $term)
    {
        $cv_lower = strtolower((string) $cv_lower);
        $term = strtolower(trim((string) $term));
        if ($cv_lower === '' || $term === '') {
            return false;
        }

        if (strpos($cv_lower, $term) !== false) {
            return true;
        }

        $tokens = preg_split('/[^a-z0-9\+\#&]+/i', $term) ?: [];
        $tokens = array_values(array_filter(array_map('trim', $tokens), static function ($token) {
            return strlen((string) $token) >= 2;
        }));

        if (count($tokens) <= 1) {
            return false;
        }

        $matched = 0;
        foreach ($tokens as $token) {
            if (strpos($cv_lower, strtolower((string) $token)) !== false) {
                $matched++;
            }
        }

        return $matched >= max(2, count($tokens) - 1);
    }

    private function filter_recommended_posts_by_search_query(array $posts, $search_query)
    {
        $search_query = trim((string) $search_query);
        if ($search_query === '') {
            return $posts;
        }

        $tokens = preg_split('/\s+/', strtolower(remove_accents($search_query)));
        $tokens = array_values(array_filter(array_map('trim', (array) $tokens), static function ($token) {
            return $token !== '' && strlen($token) >= 2;
        }));

        if (empty($tokens)) {
            return $posts;
        }

        return array_values(array_filter($posts, static function ($post) use ($tokens) {
            if (!is_array($post)) {
                return false;
            }

            $haystack = strtolower(remove_accents(implode(' ', array_filter([
                (string) ($post['role_title'] ?? ''),
                (string) ($post['title'] ?? ''),
                (string) ($post['company'] ?? ''),
                (string) ($post['location'] ?? ''),
                (string) ($post['location_city'] ?? ''),
                (string) ($post['location_country'] ?? ''),
                (string) ($post['sector'] ?? ''),
                (string) ($post['seniority'] ?? ''),
                (string) ($post['recruiter_name'] ?? ''),
                (string) ($post['recruiter_firm'] ?? ''),
                (string) ($post['specialisation'] ?? ''),
                (string) ($post['description'] ?? ''),
                (string) ($post['job_description'] ?? ''),
            ]))));

            foreach ($tokens as $token) {
                if (strpos($haystack, $token) === false) {
                    return false;
                }
            }

            return true;
        }));
    }

    public function get_recommended_roles()
    {
        try {
            $user_id = $this->verify_request(false);

            $recent_roles = $this->sanitize_recommended_recent_roles(wp_unslash($_POST['recent_roles'] ?? '[]'));
            $guest_context = $this->sanitize_recommended_guest_context(wp_unslash($_POST['guest_context'] ?? '[]'));
            $browser_timezone = sanitize_text_field(wp_unslash($_POST['browser_timezone'] ?? ($_COOKIE['currency_detector_timezone'] ?? '')));
            $browser_locale = sanitize_text_field(wp_unslash($_POST['browser_locale'] ?? ($_SERVER['HTTP_ACCEPT_LANGUAGE'] ?? '')));
            $search_query = sanitize_text_field(wp_unslash($_POST['search'] ?? ''));
            $page = max(1, (int) wp_unslash($_POST['page'] ?? 1));
            $per_page = max(6, min(24, (int) wp_unslash($_POST['per_page'] ?? 18)));
            $payload = $this->build_recommended_roles_payload(
                $user_id,
                $recent_roles,
                $guest_context,
                $browser_timezone,
                $browser_locale,
                $per_page,
                $page,
                $search_query
            );

            wp_send_json_success([
                'items' => (array) ($payload['items'] ?? []),
                'mode' => (string) ($payload['mode'] ?? 'recent'),
                'kicker' => (string) ($payload['kicker'] ?? ''),
                'title' => (string) ($payload['title'] ?? ''),
                'copy' => (string) ($payload['copy'] ?? ''),
                'page' => (int) ($payload['page'] ?? $page),
                'per_page' => (int) ($payload['per_page'] ?? $per_page),
                'has_more' => !empty($payload['has_more']),
                'total' => (int) ($payload['total'] ?? 0),
            ]);
        } catch (Throwable $e) {
            error_log('Fatal error in get_recommended_roles(): ' . $e->getMessage() . ' in ' . $e->getFile() . ':' . $e->getLine());
            wp_send_json_error([
                'message' => 'Unable to load recommended roles right now.'
            ]);
        }
    }

    private function build_recommended_roles_payload($user_id, array $recent_roles, array $guest_context, $browser_timezone, $browser_locale, $limit = 18, $page = 1, $search_query = '')
    {
        $limit = max(1, (int) $limit);
        $page = max(1, (int) $page);
        $search_query = trim((string) $search_query);
        $offset = ($page - 1) * $limit;
        $collect_limit = max(48, $offset + ($limit * 3));
        $cv_text = $user_id > 0 ? $this->get_gap_cv_text($user_id) : '';
        $profile_hints = $user_id > 0 ? $this->get_recommended_profile_hints($user_id) : [];

        $post_model = new SFFC_CRM_Post();
        $posts = $post_model->get_feed([
            'page' => 1,
            'per_page' => max(120, $collect_limit * 4),
            'approved_only' => true,
            'user_id' => $user_id,
        ]);

        if (empty($posts)) {
            return [
                'items' => [],
                'mode' => 'empty',
                'kicker' => __('Smart ranking', 'senna-finance'),
                'title' => __('No recommended roles yet', 'senna-finance'),
                'copy' => __('No approved roles are available in the feed right now.', 'senna-finance'),
                'page' => $page,
                'per_page' => $limit,
                'has_more' => false,
                'total' => 0,
            ];
        }

        if ($search_query !== '') {
            $posts = $this->filter_recommended_posts_by_search_query($posts, $search_query);
            if (empty($posts)) {
                return [
                    'items' => [],
                    'mode' => 'search',
                    'kicker' => __('Database search', 'senna-finance'),
                    'title' => __('No matching recommended jobs', 'senna-finance'),
                    'copy' => __('No approved roles matched that search. Try a role title, firm name, city, or finance keyword.', 'senna-finance'),
                    'page' => $page,
                    'per_page' => $limit,
                    'has_more' => false,
                    'total' => 0,
                ];
            }
        }

        $this->enrich_posts_with_requirements($posts);

        $primary_mode = '';
        $recommended = [];

        if ($user_id <= 0 && $this->guest_context_has_recommendation_signal($guest_context)) {
            $guest_items = $this->rank_recommended_posts_from_guest_context($posts, $guest_context, $recent_roles);
            if (!empty($guest_items)) {
                $primary_mode = 'guest';
                $recommended = $this->merge_recommended_posts($recommended, $guest_items, $collect_limit);
            }
        }

        if (!empty($recent_roles)) {
            $history_items = $this->rank_recommended_posts_from_history($posts, $recent_roles, $cv_text);
            if (!empty($history_items)) {
                if ($primary_mode === '') {
                    $primary_mode = 'history';
                }
                $recommended = $this->merge_recommended_posts($recommended, $history_items, $collect_limit);
            }
        }

        if (count($recommended) < $collect_limit && $this->profile_hints_have_recommendation_signal($profile_hints)) {
            $profile_items = $this->rank_recommended_posts_from_profile($posts, $profile_hints);
            if (!empty($profile_items)) {
                if ($primary_mode === '') {
                    $primary_mode = 'profile';
                }
                $recommended = $this->merge_recommended_posts($recommended, $profile_items, $collect_limit);
            }
        }

        if (count($recommended) < $collect_limit && trim((string) $cv_text) !== '') {
            $cv_items = $this->rank_recommended_posts_from_cv($posts, $cv_text);
            if (!empty($cv_items)) {
                if ($primary_mode === '') {
                    $primary_mode = 'cv';
                }
                $recommended = $this->merge_recommended_posts($recommended, $cv_items, $collect_limit);
            }
        }

        if (count($recommended) < $collect_limit) {
            $market_context = $this->detect_recommended_browser_market($browser_timezone, $browser_locale);
            $location_items = $this->rank_recommended_posts_from_location($posts, $market_context);
            if (!empty($location_items)) {
                if ($primary_mode === '') {
                    $primary_mode = 'location';
                }
                $recommended = $this->merge_recommended_posts($recommended, $location_items, $collect_limit);
            }
        }

        if ($primary_mode === '') {
            $primary_mode = $search_query !== '' ? 'search' : 'recent';
            $recommended = $this->rank_recommended_posts_by_recency($posts);
        }

        $recommended = array_slice($recommended, 0, $collect_limit);
        $total_available = count($recommended);
        $recommended = array_slice($recommended, $offset, $limit);

        foreach ($recommended as &$item) {
            $this->hydrate_recommended_post_links($item);
            $item['match_score'] = (int) ($item['recommendation_score'] ?? 0);
            $item['match_reasons'] = !empty($item['recommendation_reason']) ? [(string) $item['recommendation_reason']] : [];
        }
        unset($item);

        $display = $this->get_recommended_roles_display_copy($primary_mode, $recommended, $recent_roles, $profile_hints, $browser_timezone, $browser_locale, $guest_context);
        if ($search_query !== '') {
            $display = [
                'kicker' => __('Database search', 'senna-finance'),
                'title' => __('Recommended Jobs', 'senna-finance'),
                'copy' => sprintf(
                    /* translators: %s: search query */
                    __('Showing approved roles matching "%s" from the jobs database.', 'senna-finance'),
                    $search_query
                ),
            ];
        }

        return [
            'items' => $recommended,
            'mode' => $primary_mode,
            'kicker' => (string) ($display['kicker'] ?? __('Smart ranking', 'senna-finance')),
            'title' => (string) ($display['title'] ?? __('Recommended Jobs', 'senna-finance')),
            'copy' => (string) ($display['copy'] ?? __('MENA Careers is curating your best next roles.', 'senna-finance')),
            'page' => $page,
            'per_page' => $limit,
            'has_more' => ($offset + $limit) < $total_available,
            'total' => $total_available,
        ];
    }

    public function get_match_report_ai()
    {
        $this->verify_request(false);

        $cv_text = trim((string) wp_unslash($_POST['cv_text'] ?? ''));
        $top_matches = json_decode(wp_unslash($_POST['top_matches'] ?? '[]'), true);
        $report = json_decode(wp_unslash($_POST['report'] ?? 'null'), true);

        if ($cv_text === '' || empty($top_matches) || !is_array($top_matches)) {
            wp_send_json_error(['message' => __('Missing CV or role context.', 'senna-finance')], 400);
        }

        $sanitized_matches = [];
        foreach (array_slice($top_matches, 0, 5) as $match) {
            if (!is_array($match)) {
                continue;
            }

            $sanitized_matches[] = [
                'role_title' => sanitize_text_field((string) ($match['roleTitle'] ?? $match['role_title'] ?? '')),
                'company' => sanitize_text_field((string) ($match['company'] ?? '')),
                'location' => sanitize_text_field((string) ($match['location'] ?? '')),
                'sector' => sanitize_text_field((string) ($match['sector'] ?? '')),
                'seniority' => sanitize_text_field((string) ($match['seniority'] ?? '')),
                'score' => max(0, min(99, (int) ($match['score'] ?? $match['match_score'] ?? 0))),
                'salary_text' => sanitize_text_field((string) ($match['salaryText'] ?? $match['salary_text'] ?? '')),
                'salary_min' => isset($match['salaryMin']) ? (int) $match['salaryMin'] : (isset($match['salary_min']) ? (int) $match['salary_min'] : 0),
                'salary_max' => isset($match['salaryMax']) ? (int) $match['salaryMax'] : (isset($match['salary_max']) ? (int) $match['salary_max'] : 0),
                'salary_currency' => sanitize_text_field((string) ($match['salaryCurrency'] ?? $match['salary_currency'] ?? '')),
                'keywords' => array_values(array_slice(array_filter(array_map('sanitize_text_field', (array) ($match['keywords'] ?? []))), 0, 6)),
                'reasons' => array_values(array_slice(array_filter(array_map('sanitize_text_field', (array) ($match['reasons'] ?? $match['match_reasons'] ?? []))), 0, 3)),
                'warnings' => array_values(array_slice(array_filter(array_map('sanitize_text_field', (array) ($match['warnings'] ?? $match['match_warnings'] ?? []))), 0, 3)),
            ];
        }

        if (empty($sanitized_matches)) {
            wp_send_json_error(['message' => __('No role context was available for AI analysis.', 'senna-finance')], 400);
        }

        $cache_key = 'sffc_cv_match_report_ai_' . md5($cv_text . wp_json_encode($sanitized_matches) . wp_json_encode(is_array($report) ? $report : []));
        $cached = get_transient($cache_key);
        if (is_array($cached)) {
            wp_send_json_success(['analysis' => $cached, 'cached' => true]);
        }

        $analysis = $this->call_cv_match_report_ai_claude([
            'cv_text' => $cv_text,
            'matches' => $sanitized_matches,
            'report' => is_array($report) ? $report : [],
        ]);

        if (!is_array($analysis)) {
            wp_send_json_success(['analysis' => null, 'cached' => false]);
        }

        set_transient($cache_key, $analysis, 12 * HOUR_IN_SECONDS);

        wp_send_json_success(['analysis' => $analysis, 'cached' => false]);
    }

    private function sanitize_recommended_recent_roles($raw_roles)
    {
        if (is_string($raw_roles)) {
            $decoded = json_decode($raw_roles, true);
            $raw_roles = is_array($decoded) ? $decoded : [];
        }

        if (!is_array($raw_roles)) {
            return [];
        }

        $roles = [];
        foreach ($raw_roles as $role) {
            if (!is_array($role)) {
                continue;
            }

            $title = sanitize_text_field($role['title'] ?? '');
            $href = esc_url_raw($role['href'] ?? '');
            if ($title === '' && $href === '') {
                continue;
            }

            $keywords = $role['keywords'] ?? [];
            if (is_string($keywords)) {
                $keywords = preg_split('/[\r\n,|]+/', $keywords);
            }

            $roles[] = [
                'id' => absint($role['id'] ?? 0),
                'jobs_post_id' => absint($role['jobsPostId'] ?? ($role['jobs_post_id'] ?? 0)),
                'wp_post_id' => absint($role['wpPostId'] ?? ($role['wp_post_id'] ?? 0)),
                'title' => $title,
                'href' => $href,
                'location' => sanitize_text_field($role['location'] ?? ''),
                'sector' => sanitize_text_field($role['sector'] ?? ''),
                'seniority' => sanitize_text_field($role['seniority'] ?? ''),
                'keywords' => array_values(array_filter(array_map('sanitize_text_field', is_array($keywords) ? $keywords : []))),
                'touched_at' => (int) ($role['touchedAt'] ?? $role['touched_at'] ?? 0),
                'pinned' => !empty($role['pinned']),
            ];
        }

        usort($roles, static function ($left, $right) {
            if (!empty($left['pinned']) !== !empty($right['pinned'])) {
                return !empty($left['pinned']) ? -1 : 1;
            }

            return ((int) ($right['touched_at'] ?? 0)) <=> ((int) ($left['touched_at'] ?? 0));
        });

        return array_slice($roles, 0, 12);
    }

    private function sanitize_recommended_guest_context($raw_context)
    {
        if (is_string($raw_context)) {
            $decoded = json_decode($raw_context, true);
            $raw_context = is_array($decoded) ? $decoded : [];
        }

        if (!is_array($raw_context)) {
            return [
                'landing_role' => [],
                'interactions' => [],
                'referrer_domain' => '',
                'referrer_path' => '',
                'source_channel' => '',
            ];
        }

        $sanitize_role = function ($role, $fallback_event_type = 'view') {
            if (!is_array($role)) {
                return [];
            }

            $title = sanitize_text_field($role['title'] ?? '');
            $href = esc_url_raw($role['href'] ?? '');
            if ($title === '' && $href === '' && empty($role['id']) && empty($role['jobsPostId']) && empty($role['jobs_post_id'])) {
                return [];
            }

            $keywords = $role['keywords'] ?? [];
            if (is_string($keywords)) {
                $keywords = preg_split('/[\r\n,|]+/', $keywords);
            }

            return [
                'id' => absint($role['id'] ?? 0),
                'jobs_post_id' => absint($role['jobsPostId'] ?? ($role['jobs_post_id'] ?? 0)),
                'wp_post_id' => absint($role['wpPostId'] ?? ($role['wp_post_id'] ?? 0)),
                'title' => $title,
                'href' => $href,
                'location' => sanitize_text_field($role['location'] ?? ''),
                'sector' => sanitize_text_field($role['sector'] ?? ''),
                'seniority' => sanitize_text_field($role['seniority'] ?? ''),
                'keywords' => array_values(array_filter(array_map('sanitize_text_field', is_array($keywords) ? $keywords : []))),
                'touched_at' => (int) ($role['touchedAt'] ?? $role['touched_at'] ?? 0),
                'pinned' => !empty($role['pinned']),
                'event_type' => sanitize_key($role['eventType'] ?? ($role['event_type'] ?? $fallback_event_type)),
                'referrer_domain' => strtolower(sanitize_text_field($role['referrerDomain'] ?? ($role['referrer_domain'] ?? ''))),
                'referrer_path' => sanitize_text_field($role['referrerPath'] ?? ($role['referrer_path'] ?? '')),
                'source_channel' => strtolower(sanitize_key($role['sourceChannel'] ?? ($role['source_channel'] ?? ''))),
            ];
        };

        $interactions = [];
        foreach ((array) ($raw_context['interactions'] ?? []) as $index => $interaction) {
            $sanitized = $sanitize_role($interaction, 'view');
            if (!empty($sanitized)) {
                $interactions[] = $sanitized;
            }
        }

        usort($interactions, static function ($left, $right) {
            if (!empty($left['pinned']) !== !empty($right['pinned'])) {
                return !empty($left['pinned']) ? -1 : 1;
            }

            return ((int) ($right['touched_at'] ?? 0)) <=> ((int) ($left['touched_at'] ?? 0));
        });

        return [
            'landing_role' => $sanitize_role($raw_context['landingRole'] ?? ($raw_context['landing_role'] ?? []), 'landing'),
            'interactions' => array_slice($interactions, 0, 12),
            'referrer_domain' => strtolower(sanitize_text_field($raw_context['referrerDomain'] ?? ($raw_context['referrer_domain'] ?? ''))),
            'referrer_path' => sanitize_text_field($raw_context['referrerPath'] ?? ($raw_context['referrer_path'] ?? '')),
            'source_channel' => strtolower(sanitize_key($raw_context['sourceChannel'] ?? ($raw_context['source_channel'] ?? ''))),
        ];
    }

    private function guest_context_has_recommendation_signal(array $guest_context)
    {
        return !empty($guest_context['landing_role'])
            || !empty($guest_context['interactions'])
            || !empty($guest_context['source_channel'])
            || !empty($guest_context['referrer_domain']);
    }

    private function get_recommended_profile_hints($user_id)
    {
        $preferences = function_exists('sffc_crm_get_job_preferences')
            ? sffc_crm_get_job_preferences((int) $user_id)
            : [];

        return [
            'target_roles' => array_values(array_filter(array_map('sanitize_text_field', (array) ($preferences['target_roles'] ?? [])))),
            'target_locations' => array_values(array_filter(array_map('sanitize_text_field', (array) ($preferences['target_locations'] ?? [])))),
            'target_sectors' => array_values(array_filter(array_map('sanitize_text_field', (array) ($preferences['target_sectors'] ?? [])))),
            'technical_skills' => array_values(array_filter(array_map('sanitize_text_field', (array) (get_user_meta((int) $user_id, 'sffc_crm_technical_skills', true) ?: [])))),
        ];
    }

    private function profile_hints_have_recommendation_signal(array $profile_hints)
    {
        return !empty($profile_hints['target_roles'])
            || !empty($profile_hints['target_locations'])
            || !empty($profile_hints['target_sectors'])
            || !empty($profile_hints['technical_skills']);
    }

    private function merge_recommended_posts(array $existing, array $incoming, $limit = 18)
    {
        $merged = [];

        foreach (array_merge($existing, $incoming) as $item) {
            $key = (int) ($item['id'] ?? 0);
            if ($key <= 0) {
                continue;
            }

            if (!isset($merged[$key]) || ((int) ($item['recommendation_score'] ?? 0)) > ((int) ($merged[$key]['recommendation_score'] ?? 0))) {
                $merged[$key] = $item;
            }
        }

        $merged = array_values($merged);
        usort($merged, function ($left, $right) {
            $score_compare = ((int) ($right['recommendation_score'] ?? 0)) <=> ((int) ($left['recommendation_score'] ?? 0));
            if ($score_compare !== 0) {
                return $score_compare;
            }

            return strtotime((string) ($right['posted_at'] ?? '')) <=> strtotime((string) ($left['posted_at'] ?? ''));
        });

        return array_slice($merged, 0, $limit);
    }

    private function rank_recommended_posts_from_guest_context(array $posts, array $guest_context, array $recent_roles = [])
    {
        $seeds = [];
        $excluded_ids = [];
        $seen_seed_keys = [];

        $append_seed = function (array $seed, $weight_bonus = 0) use (&$seeds, &$excluded_ids, &$seen_seed_keys, $guest_context) {
            if (empty($seed)) {
                return;
            }

            $seed_key = (int) ($seed['id'] ?? 0);
            if ($seed_key <= 0) {
                $seed_key = crc32(
                    strtolower(trim((string) ($seed['href'] ?? ''))) . '|' .
                    strtolower(trim((string) ($seed['title'] ?? '')))
                );
            }

            if (isset($seen_seed_keys[$seed_key])) {
                return;
            }

            $event_type = strtolower(trim((string) ($seed['event_type'] ?? 'view')));
            $event_weights = [
                'landing' => 30,
                'open_role' => 24,
                'quick_view' => 18,
                'view' => 14,
            ];

            $source_channel = strtolower(trim((string) ($seed['source_channel'] ?? ($guest_context['source_channel'] ?? ''))));
            $seed['seed_weight'] = ($event_weights[$event_type] ?? 12) + (int) $weight_bonus + (!empty($seed['pinned']) ? 6 : 0);
            if ($source_channel === 'linkedin') {
                $seed['seed_weight'] += 6;
            }
            $seed['source_channel'] = $source_channel;
            $seed['title_tokens'] = $this->tokenize_recommended_text($seed['title'] ?? '');
            $seed['sector_normalized'] = strtolower(trim((string) ($seed['sector'] ?? '')));
            $seed['seniority_normalized'] = strtolower(trim((string) ($seed['seniority'] ?? '')));
            $seed['keywords_normalized'] = $this->normalize_recommended_keywords($seed['keywords'] ?? []);
            $seed['location_parsed'] = $this->parse_recommended_location_label($seed['location'] ?? '');

            $seeds[] = $seed;
            $seen_seed_keys[$seed_key] = true;

            if (!empty($seed['id'])) {
                $excluded_ids[(int) $seed['id']] = true;
            }
        };

        $append_seed((array) ($guest_context['landing_role'] ?? []), 8);

        foreach ((array) ($guest_context['interactions'] ?? []) as $index => $interaction) {
            $append_seed((array) $interaction, max(0, 5 - min(4, (int) $index)));
        }

        foreach ($recent_roles as $index => $recent_role) {
            $recent_role['event_type'] = $recent_role['event_type'] ?? 'open_role';
            $recent_role['source_channel'] = $recent_role['source_channel'] ?? ($guest_context['source_channel'] ?? '');
            $append_seed((array) $recent_role, max(0, 3 - min(2, (int) $index)));
        }

        if (empty($seeds)) {
            return [];
        }

        $ranked = [];
        foreach ($posts as $post) {
            $post_id = (int) ($post['id'] ?? 0);
            if ($post_id > 0 && isset($excluded_ids[$post_id])) {
                continue;
            }

            $post_title_tokens = $this->tokenize_recommended_text($post['role_title'] ?? '');
            $post_sector = strtolower(trim((string) ($post['sector'] ?? '')));
            $post_seniority = strtolower(trim((string) ($post['seniority'] ?? '')));
            $post_keywords = $this->normalize_recommended_keywords($post['keywords'] ?? []);
            $post_location = $this->extract_recommended_post_location($post);
            $post_region = strtolower((string) $this->infer_recommended_region_from_location($post_location));

            $best_score = 0;
            $best_reason = '';

            foreach ($seeds as $seed) {
                $score = (int) ($seed['seed_weight'] ?? 0);
                $reason = '';
                $seed_location = (array) ($seed['location_parsed'] ?? []);
                $seed_region = strtolower((string) $this->infer_recommended_region_from_location($seed_location));
                $seed_nearby_cities = array_map('strtolower', $this->get_recommended_nearby_cities($seed_location['city'] ?? '', $seed_region));

                $shared_title_tokens = count(array_intersect($post_title_tokens, (array) ($seed['title_tokens'] ?? [])));
                if ($shared_title_tokens > 0) {
                    $score += 16 + ($shared_title_tokens * 4);
                    $reason = !empty($guest_context['landing_role']) && (int) ($seed['id'] ?? 0) === (int) (($guest_context['landing_role']['id'] ?? 0))
                        ? __('Similar to the role you landed on', 'senna-finance')
                        : __('Similar to the roles you opened this session', 'senna-finance');
                }

                if ($post_sector !== '' && $post_sector === (string) ($seed['sector_normalized'] ?? '')) {
                    $score += 18;
                    if ($reason === '') {
                        $reason = __('Within the same finance lane as the roles you are opening', 'senna-finance');
                    }
                }

                if ($post_seniority !== '' && $post_seniority === (string) ($seed['seniority_normalized'] ?? '')) {
                    $score += 12;
                    if ($reason === '') {
                        $reason = __('At a similar level to the role you opened', 'senna-finance');
                    }
                }

                $keyword_overlap = count(array_intersect($post_keywords, (array) ($seed['keywords_normalized'] ?? [])));
                if ($keyword_overlap > 0) {
                    $score += min(22, $keyword_overlap * 6);
                    if ($reason === '') {
                        $reason = __('Shares the same focus areas as the role you clicked', 'senna-finance');
                    }
                }

                if (!empty($seed_location['city']) && !empty($post_location['city']) && $seed_location['city'] === $post_location['city']) {
                    $score += 14;
                    if ($reason === '') {
                        $reason = sprintf(__('In the same city as the role you viewed: %s', 'senna-finance'), $post_location['label']);
                    }
                } elseif (!empty($seed_nearby_cities) && !empty($post_location['city']) && in_array((string) $post_location['city'], $seed_nearby_cities, true)) {
                    $score += 9;
                    if ($reason === '') {
                        $reason = sprintf(__('Near the market you just explored: %s', 'senna-finance'), $seed_location['label'] ?: __('your recent city', 'senna-finance'));
                    }
                } elseif (!empty($seed_location['country']) && !empty($post_location['country']) && $seed_location['country'] === $post_location['country']) {
                    $score += 7;
                    if ($reason === '') {
                        $reason = sprintf(__('In the same market as the role you viewed: %s', 'senna-finance'), $post_location['country']);
                    }
                } elseif ($seed_region !== '' && $seed_region !== 'global' && $seed_region === $post_region) {
                    $score += 5;
                }

                if (($seed['source_channel'] ?? '') === 'linkedin') {
                    $score += 5;
                    if ($reason === '') {
                        $reason = __('Similar to the role you arrived on from LinkedIn', 'senna-finance');
                    }
                }

                $score += min(12, $this->recommendation_recency_bonus($post));

                if ($score > $best_score) {
                    $best_score = $score;
                    $best_reason = $reason;
                }
            }

            if ($best_score < 20) {
                continue;
            }

            $post['recommendation_score'] = min(99, (int) round($best_score));
            $post['recommendation_reason'] = $best_reason ?: __('Recommended from your recent guest session activity', 'senna-finance');
            $ranked[] = $post;
        }

        usort($ranked, function ($left, $right) {
            $score_compare = ((int) ($right['recommendation_score'] ?? 0)) <=> ((int) ($left['recommendation_score'] ?? 0));
            if ($score_compare !== 0) {
                return $score_compare;
            }

            return strtotime((string) ($right['posted_at'] ?? '')) <=> strtotime((string) ($left['posted_at'] ?? ''));
        });

        return array_slice($ranked, 0, 18);
    }

    private function rank_recommended_posts_from_history(array $posts, array $recent_roles, $cv_text = '')
    {
        $cv_text = trim((string) $cv_text);
        $cv_profile = $cv_text !== '' ? $this->build_simple_cv_match_profile($cv_text) : [];
        $clicked_ids = [];
        foreach ($recent_roles as $recent_role) {
            if (!empty($recent_role['id'])) {
                $clicked_ids[(int) $recent_role['id']] = true;
            }
        }

        $ranked = [];
        foreach ($posts as $post) {
            $post_id = (int) ($post['id'] ?? 0);
            if ($post_id > 0 && isset($clicked_ids[$post_id])) {
                continue;
            }

            $best_score = 0;
            $best_reason = '';
            $post_title_tokens = $this->tokenize_recommended_text($post['role_title'] ?? '');
            $post_sector = strtolower(trim((string) ($post['sector'] ?? '')));
            $post_seniority = strtolower(trim((string) ($post['seniority'] ?? '')));
            $post_keywords = $this->normalize_recommended_keywords($post['keywords'] ?? []);
            $post_location = $this->extract_recommended_post_location($post);

            foreach ($recent_roles as $index => $recent_role) {
                $score = 0;
                $reason = '';
                $weight = max(1, 5 - min(4, (int) $index));
                $recent_title_tokens = $this->tokenize_recommended_text($recent_role['title'] ?? '');
                $shared_title_tokens = count(array_intersect($post_title_tokens, $recent_title_tokens));

                if ($shared_title_tokens > 0) {
                    $score += 16 + ($shared_title_tokens * 4);
                    $reason = __('Similar to roles you opened recently', 'senna-finance');
                }

                $recent_sector = strtolower(trim((string) ($recent_role['sector'] ?? '')));
                if ($recent_sector !== '' && $post_sector !== '' && $recent_sector === $post_sector) {
                    $score += 16;
                    $reason = __('Aligned with the sectors you are opening most', 'senna-finance');
                }

                $recent_seniority = strtolower(trim((string) ($recent_role['seniority'] ?? '')));
                if ($recent_seniority !== '' && $post_seniority !== '' && $recent_seniority === $post_seniority) {
                    $score += 12;
                    $reason = __('A similar level to the roles you keep opening', 'senna-finance');
                }

                $recent_keywords = $this->normalize_recommended_keywords($recent_role['keywords'] ?? []);
                $keyword_overlap = count(array_intersect($post_keywords, $recent_keywords));
                if ($keyword_overlap > 0) {
                    $score += min(18, $keyword_overlap * 6);
                    $reason = __('Shares the same focus areas as your recent role clicks', 'senna-finance');
                }

                $recent_location = $this->parse_recommended_location_label($recent_role['location'] ?? '');
                if ($recent_location['city'] !== '' && $post_location['city'] !== '' && $recent_location['city'] === $post_location['city']) {
                    $score += 11;
                    $reason = sprintf(__('Recent role activity suggests %s', 'senna-finance'), $post_location['label']);
                } elseif ($recent_location['country'] !== '' && $post_location['country'] !== '' && $recent_location['country'] === $post_location['country']) {
                    $score += 7;
                    $reason = sprintf(__('Recent role activity suggests %s', 'senna-finance'), $post_location['country']);
                }

                if (!empty($recent_role['pinned'])) {
                    $score += 6;
                }

                $score *= (1 + ($weight * 0.06));

                if ($score > $best_score) {
                    $best_score = $score;
                    $best_reason = $reason;
                }
            }

            if ($cv_text !== '') {
                if (empty($post['seniority']) || $post['seniority'] === 'other') {
                    $post['seniority'] = $this->infer_seniority_from_post($post);
                }
                $best_score += max(0, (int) round($this->calculate_match_score($cv_profile, $post, $this->load_keyword_taxonomy()) / 7));
                if ($best_reason === '') {
                    $best_reason = __('Also reads as a fit against your saved CV', 'senna-finance');
                }
            }

            if ($best_score < 18) {
                continue;
            }

            $post['recommendation_score'] = min(99, (int) round($best_score));
            $post['recommendation_reason'] = $best_reason ?: __('Recommended from recent role activity', 'senna-finance');
            $ranked[] = $post;
        }

        usort($ranked, function ($left, $right) {
            $score_compare = ((int) ($right['recommendation_score'] ?? 0)) <=> ((int) ($left['recommendation_score'] ?? 0));
            if ($score_compare !== 0) {
                return $score_compare;
            }

            return strtotime((string) ($right['posted_at'] ?? '')) <=> strtotime((string) ($left['posted_at'] ?? ''));
        });

        return array_slice($ranked, 0, 18);
    }

    private function rank_recommended_posts_from_profile(array $posts, array $profile_hints)
    {
        $role_tokens = $this->tokenize_recommended_text(implode(' ', (array) ($profile_hints['target_roles'] ?? [])));
        $location_tokens = array_map([$this, 'parse_recommended_location_label'], (array) ($profile_hints['target_locations'] ?? []));
        $sector_tokens = array_map('strtolower', array_map('trim', (array) ($profile_hints['target_sectors'] ?? [])));
        $skill_tokens = array_map('strtolower', array_map('trim', (array) ($profile_hints['technical_skills'] ?? [])));

        $ranked = [];
        foreach ($posts as $post) {
            $score = 0;
            $reason = '';
            $post_title_tokens = $this->tokenize_recommended_text($post['role_title'] ?? '');
            $shared_title_tokens = count(array_intersect($post_title_tokens, $role_tokens));
            $post_sector = strtolower(trim((string) ($post['sector'] ?? '')));
            $post_location = $this->extract_recommended_post_location($post);
            $post_keywords = $this->normalize_recommended_keywords($post['keywords'] ?? []);

            if ($shared_title_tokens > 0) {
                $score += 22 + ($shared_title_tokens * 4);
                $reason = __('Matched to the role types in your profile', 'senna-finance');
            }

            if ($post_sector !== '' && in_array($post_sector, $sector_tokens, true)) {
                $score += 18;
                $reason = __('Matched to the sectors in your profile', 'senna-finance');
            }

            foreach ($location_tokens as $location_token) {
                if (($location_token['city'] ?? '') !== '' && $location_token['city'] === $post_location['city']) {
                    $score += 16;
                    $reason = sprintf(__('Within one of your preferred markets: %s', 'senna-finance'), $post_location['label']);
                    break;
                }
                if (($location_token['country'] ?? '') !== '' && $location_token['country'] === $post_location['country']) {
                    $score += 10;
                    $reason = sprintf(__('Within one of your preferred markets: %s', 'senna-finance'), $post_location['country']);
                    break;
                }
            }

            if (!empty($skill_tokens) && !empty($post_keywords)) {
                $skill_overlap = 0;
                foreach ($post_keywords as $keyword) {
                    foreach ($skill_tokens as $skill_token) {
                        if ($skill_token !== '' && (strpos($keyword, $skill_token) !== false || strpos($skill_token, $keyword) !== false)) {
                            $skill_overlap++;
                            break;
                        }
                    }
                }
                if ($skill_overlap > 0) {
                    $score += min(18, $skill_overlap * 5);
                    $reason = __('Contains technical signals from your profile', 'senna-finance');
                }
            }

            if ($score < 16) {
                continue;
            }

            $post['recommendation_score'] = min(99, (int) round($score));
            $post['recommendation_reason'] = $reason ?: __('Recommended from your saved profile preferences', 'senna-finance');
            $ranked[] = $post;
        }

        usort($ranked, function ($left, $right) {
            $score_compare = ((int) ($right['recommendation_score'] ?? 0)) <=> ((int) ($left['recommendation_score'] ?? 0));
            if ($score_compare !== 0) {
                return $score_compare;
            }

            return strtotime((string) ($right['posted_at'] ?? '')) <=> strtotime((string) ($left['posted_at'] ?? ''));
        });

        return array_slice($ranked, 0, 18);
    }

    private function rank_recommended_posts_from_cv(array $posts, $cv_text)
    {
        $cv_text = trim((string) $cv_text);
        if ($cv_text === '') {
            return [];
        }

        $taxonomy = $this->load_keyword_taxonomy();
        $cv_parsed = $this->build_simple_cv_match_profile($cv_text);
        $ranked = [];

        foreach ($posts as $post) {
            if (empty($post['seniority']) || $post['seniority'] === 'other') {
                $post['seniority'] = $this->infer_seniority_from_post($post);
            }

            $score = (int) round($this->calculate_match_score($cv_parsed, $post, $taxonomy));
            if ($score < 18) {
                continue;
            }

            $reasons = $this->build_match_reasons($cv_parsed, $post);
            $post['recommendation_score'] = min(99, $score);
            $post['recommendation_reason'] = !empty($reasons[0]) ? (string) $reasons[0] : __('Reads as one of the stronger matches from your saved CV', 'senna-finance');
            $ranked[] = $post;
        }

        usort($ranked, function ($left, $right) {
            $score_compare = ((int) ($right['recommendation_score'] ?? 0)) <=> ((int) ($left['recommendation_score'] ?? 0));
            if ($score_compare !== 0) {
                return $score_compare;
            }

            return strtotime((string) ($right['posted_at'] ?? '')) <=> strtotime((string) ($left['posted_at'] ?? ''));
        });

        return array_slice($ranked, 0, 18);
    }

    private function rank_recommended_posts_from_location(array $posts, array $market_context)
    {
        $ranked = [];
        $target_city = strtolower(trim((string) ($market_context['city'] ?? '')));
        $target_country = strtolower(trim((string) ($market_context['country'] ?? '')));
        $target_region = strtolower(trim((string) ($market_context['region'] ?? '')));
        $nearby_cities = array_map('strtolower', (array) ($market_context['nearby_cities'] ?? []));

        foreach ($posts as $post) {
            $score = 0;
            $reason = '';
            $post_location = $this->extract_recommended_post_location($post);
            $post_city = strtolower((string) ($post_location['city'] ?? ''));
            $post_country = strtolower((string) ($post_location['country'] ?? ''));
            $post_region = strtolower((string) $this->infer_recommended_region_from_location($post_location));

            if ($target_city !== '' && $post_city !== '' && $target_city === $post_city) {
                $score = 48;
                $reason = sprintf(__('Recently added in %s', 'senna-finance'), $post_location['label']);
            } elseif (!empty($nearby_cities) && $post_city !== '' && in_array($post_city, $nearby_cities, true)) {
                $score = 38;
                $reason = sprintf(__('Nearest active market to %s', 'senna-finance'), $market_context['city_label'] ?? __('your city', 'senna-finance'));
            } elseif ($target_country !== '' && $post_country !== '' && $target_country === $post_country) {
                $score = 32;
                $reason = sprintf(__('Recently added in %s', 'senna-finance'), $post_location['country']);
            } elseif ($target_region !== '' && $post_region !== '' && $target_region === $post_region) {
                $score = 24;
                $reason = sprintf(__('Recent roles across the %s market', 'senna-finance'), $market_context['region_label'] ?? __('broader market', 'senna-finance'));
            } else {
                $score = 12;
                $reason = __('Recently added finance opportunities', 'senna-finance');
            }

            $score += min(12, $this->recommendation_recency_bonus($post));
            $post['recommendation_score'] = min(99, (int) round($score));
            $post['recommendation_reason'] = $reason;
            $ranked[] = $post;
        }

        usort($ranked, function ($left, $right) {
            $score_compare = ((int) ($right['recommendation_score'] ?? 0)) <=> ((int) ($left['recommendation_score'] ?? 0));
            if ($score_compare !== 0) {
                return $score_compare;
            }

            return strtotime((string) ($right['posted_at'] ?? '')) <=> strtotime((string) ($left['posted_at'] ?? ''));
        });

        return array_slice($ranked, 0, 18);
    }

    private function rank_recommended_posts_by_recency(array $posts)
    {
        foreach ($posts as &$post) {
            $post['recommendation_score'] = 10 + min(12, $this->recommendation_recency_bonus($post));
            $post['recommendation_reason'] = __('Recently added finance opportunities', 'senna-finance');
            $this->hydrate_recommended_post_links($post);
        }
        unset($post);

        usort($posts, function ($left, $right) {
            return strtotime((string) ($right['posted_at'] ?? '')) <=> strtotime((string) ($left['posted_at'] ?? ''));
        });

        return array_slice($posts, 0, 18);
    }

    private function recommendation_recency_bonus(array $post)
    {
        $posted_at = !empty($post['posted_at']) ? strtotime((string) $post['posted_at']) : 0;
        if ($posted_at <= 0) {
            return 0;
        }

        $age_hours = max(1, (time() - $posted_at) / HOUR_IN_SECONDS);
        if ($age_hours <= 24) {
            return 12;
        }
        if ($age_hours <= 72) {
            return 9;
        }
        if ($age_hours <= 168) {
            return 6;
        }
        return 3;
    }

    private function hydrate_recommended_post_links(array &$post)
    {
        $permalink = $this->resolve_recommended_post_public_permalink($post);
        $internal_permalink = $this->resolve_recommended_post_internal_permalink($post);

        $post['permalink'] = $permalink ?: '';
        $post['internal_permalink'] = $internal_permalink ?: '';
        $post['jobs_post_id'] = !empty($post['jobs_post_id']) ? (int) $post['jobs_post_id'] : 0;
    }

    private function find_recruiter_post_id_by_crm_post_id($crm_post_id)
    {
        $crm_post_id = (int) $crm_post_id;
        if ($crm_post_id <= 0) {
            return 0;
        }

        static $cache = [];
        if (isset($cache[$crm_post_id])) {
            return (int) $cache[$crm_post_id];
        }

        $post_ids = get_posts([
            'post_type' => 'sffc_recruiter_post',
            'post_status' => 'publish',
            'posts_per_page' => 1,
            'fields' => 'ids',
            'no_found_rows' => true,
            'meta_query' => [
                [
                    'key' => '_crm_post_id',
                    'value' => (string) $crm_post_id,
                ],
            ],
        ]);

        $cache[$crm_post_id] = !empty($post_ids[0]) ? (int) $post_ids[0] : 0;

        return (int) $cache[$crm_post_id];
    }

    private function resolve_recommended_post_internal_permalink(array $post)
    {
        $jobs_post_id = (int) ($post['jobs_post_id'] ?? 0);
        if ($jobs_post_id > 0) {
            $jobs_post = get_post($jobs_post_id);
            if ($jobs_post && $jobs_post->post_type === 'jobs') {
                $permalink = get_permalink($jobs_post_id);
                if (is_string($permalink) && $permalink !== '') {
                    return $permalink;
                }
            }
        }

        $wp_post_id = (int) ($post['wp_post_id'] ?? 0);
        if ($wp_post_id > 0) {
            $wp_post = get_post($wp_post_id);
            if ($wp_post && $wp_post->post_type === 'jobs') {
                $permalink = get_permalink($wp_post_id);
                if (is_string($permalink) && $permalink !== '') {
                    return $permalink;
                }
            }
            if ($wp_post && $wp_post->post_type === 'sffc_recruiter_post') {
                $permalink = get_permalink($wp_post_id);
                if (is_string($permalink) && $permalink !== '') {
                    return $permalink;
                }
            }
        }

        $crm_post_id = (int) ($post['crm_post_id'] ?? ($post['id'] ?? 0));
        if ($crm_post_id > 0) {
            $recruiter_post_id = $this->find_recruiter_post_id_by_crm_post_id($crm_post_id);
            if ($recruiter_post_id > 0) {
                $permalink = get_permalink($recruiter_post_id);
                if (is_string($permalink) && $permalink !== '') {
                    return $permalink;
                }
            }
        }

        if ($wp_post_id > 0) {
            $wp_post = get_post($wp_post_id);
            if ($wp_post && $wp_post->post_type !== 'sffc_crm_post') {
                $permalink = get_permalink($wp_post_id);
                if (is_string($permalink) && $permalink !== '') {
                    return $permalink;
                }
            }
        }

        return '';
    }

    private function resolve_recommended_post_public_permalink(array $post)
    {
        $permalink = $this->resolve_recommended_post_internal_permalink($post);
        if ($permalink !== '') {
            return $permalink;
        }

        foreach (['source_url', 'application_url'] as $field) {
            $candidate = $this->normalize_recommended_post_fallback_url($post[$field] ?? '', $post);
            if ($candidate !== '') {
                return $candidate;
            }
        }

        return '';
    }

    private function normalize_recommended_post_fallback_url($url, array $post)
    {
        $url = esc_url_raw((string) $url);
        if ($url === '') {
            return '';
        }

        $canonical_jobs_url = $this->resolve_recommended_jobs_permalink($post);
        if ($canonical_jobs_url !== '' && $this->is_internal_jobs_url($url)) {
            return $canonical_jobs_url;
        }

        return $url;
    }

    private function resolve_recommended_jobs_permalink(array $post)
    {
        $jobs_post_id = (int) ($post['jobs_post_id'] ?? 0);
        if ($jobs_post_id > 0) {
            $jobs_post = get_post($jobs_post_id);
            if ($jobs_post && $jobs_post->post_type === 'jobs') {
                $permalink = get_permalink($jobs_post_id);
                if (is_string($permalink) && $permalink !== '') {
                    return $permalink;
                }
            }
        }

        $wp_post_id = (int) ($post['wp_post_id'] ?? 0);
        if ($wp_post_id > 0) {
            $wp_post = get_post($wp_post_id);
            if ($wp_post && $wp_post->post_type === 'jobs') {
                $permalink = get_permalink($wp_post_id);
                if (is_string($permalink) && $permalink !== '') {
                    return $permalink;
                }
            }
        }

        return '';
    }

    private function is_internal_jobs_url($url)
    {
        $url = trim((string) $url);
        if ($url === '') {
            return false;
        }

        $home_host = wp_parse_url(home_url('/'), PHP_URL_HOST);
        $url_host = wp_parse_url($url, PHP_URL_HOST);
        $path = wp_parse_url($url, PHP_URL_PATH);

        if (!is_string($path) || strpos($path, '/jobs/') !== 0) {
            return false;
        }

        if ($url_host === null || $url_host === false || $url_host === '') {
            return true;
        }

        return is_string($home_host) && strtolower($url_host) === strtolower($home_host);
    }

    private function normalize_recommended_text($text)
    {
        $text = strtolower(trim((string) $text));
        $text = preg_replace('/[^a-z0-9\+\#\.]+/i', ' ', $text);
        return trim((string) preg_replace('/\s+/', ' ', (string) $text));
    }

    private function tokenize_recommended_text($text)
    {
        $text = $this->normalize_recommended_text($text);
        if ($text === '') {
            return [];
        }

        $tokens = preg_split('/\s+/', $text);
        $stop_words = ['and', 'the', 'for', 'with', 'from', 'role', 'jobs', 'job', 'team', 'senna', 'your'];
        return array_values(array_filter(array_unique(array_map('trim', (array) $tokens)), function ($token) use ($stop_words) {
            return $token !== '' && strlen($token) > 2 && !in_array($token, $stop_words, true);
        }));
    }

    private function normalize_recommended_keywords($keywords)
    {
        if (is_string($keywords)) {
            $decoded = json_decode($keywords, true);
            if (is_array($decoded)) {
                $keywords = $decoded;
            } else {
                $keywords = preg_split('/[\r\n,|]+/', $keywords);
            }
        }

        $normalized = [];
        foreach ((array) $keywords as $keyword) {
            if (is_array($keyword)) {
                $keyword = $keyword['label'] ?? $keyword['term'] ?? $keyword['name'] ?? $keyword['value'] ?? '';
            }
            $value = $this->normalize_recommended_text($keyword);
            if ($value !== '') {
                $normalized[] = $value;
            }
        }

        return array_values(array_unique($normalized));
    }

    private function parse_recommended_location_label($location)
    {
        $location = trim((string) $location);
        if ($location === '') {
            return ['label' => '', 'city' => '', 'country' => ''];
        }

        $parts = array_values(array_filter(array_map('trim', explode(',', $location))));
        $city = strtolower((string) ($parts[0] ?? $location));
        $country = strtolower((string) ($parts[count($parts) - 1] ?? ''));

        return [
            'label' => $location,
            'city' => $city,
            'country' => $country === $city ? '' : $country,
        ];
    }

    private function extract_recommended_post_location(array $post)
    {
        $city = trim((string) ($post['location_city'] ?? ''));
        $country = trim((string) ($post['location_country'] ?? ''));
        $label = trim((string) ($post['location'] ?? ''));

        if ($city === '' && $label !== '') {
            $parsed = $this->parse_recommended_location_label($label);
            $city = $parsed['city'];
            $country = $parsed['country'];
        }

        return [
            'label' => $label !== '' ? $label : trim($city . ($country !== '' ? ', ' . $country : '')),
            'city' => strtolower($city),
            'country' => strtolower($country),
        ];
    }

    private function detect_recommended_browser_market($timezone, $locale)
    {
        $timezone = trim((string) $timezone);
        $locale = trim((string) $locale);
        $city = '';
        $country = '';
        $region = 'global';

        if ($timezone !== '') {
            $parts = explode('/', $timezone);
            if (!empty($parts[1])) {
                $city = str_replace('_', ' ', (string) end($parts));
            }
            $region = $this->infer_recommended_region_from_timezone($timezone);
        }

        $locale_region = '';
        if (preg_match('/[-_]([A-Z]{2})/i', $locale, $matches)) {
            $locale_region = strtoupper((string) $matches[1]);
        }

        $locale_map = [
            'GB' => ['city' => 'London', 'country' => 'United Kingdom', 'region' => 'europe'],
            'FR' => ['city' => 'Paris', 'country' => 'France', 'region' => 'europe'],
            'DE' => ['city' => 'Frankfurt', 'country' => 'Germany', 'region' => 'europe'],
            'SE' => ['city' => 'Stockholm', 'country' => 'Sweden', 'region' => 'europe'],
            'AE' => ['city' => 'Dubai', 'country' => 'United Arab Emirates', 'region' => 'private_equity'],
            'QA' => ['city' => 'Doha', 'country' => 'Qatar', 'region' => 'private_equity'],
            'JO' => ['city' => 'Amman', 'country' => 'Jordan', 'region' => 'private_equity'],
            'SA' => ['city' => 'Riyadh', 'country' => 'Saudi Arabia', 'region' => 'private_equity'],
            'SG' => ['city' => 'Singapore', 'country' => 'Singapore', 'region' => 'asia'],
            'HK' => ['city' => 'Hong Kong', 'country' => 'Hong Kong', 'region' => 'asia'],
        ];

        if (($city === '' || $country === '') && $locale_region !== '' && isset($locale_map[$locale_region])) {
            $city = $city !== '' ? $city : $locale_map[$locale_region]['city'];
            $country = $locale_map[$locale_region]['country'];
            if ($region === 'global') {
                $region = $locale_map[$locale_region]['region'];
            }
        }

        $timezone_city_country = [
            'Asia/Dubai' => ['city' => 'Dubai', 'country' => 'United Arab Emirates', 'region' => 'private_equity'],
            'Asia/Qatar' => ['city' => 'Doha', 'country' => 'Qatar', 'region' => 'private_equity'],
            'Asia/Amman' => ['city' => 'Amman', 'country' => 'Jordan', 'region' => 'private_equity'],
            'Asia/Riyadh' => ['city' => 'Riyadh', 'country' => 'Saudi Arabia', 'region' => 'private_equity'],
            'Europe/London' => ['city' => 'London', 'country' => 'United Kingdom', 'region' => 'europe'],
            'Europe/Paris' => ['city' => 'Paris', 'country' => 'France', 'region' => 'europe'],
            'Europe/Berlin' => ['city' => 'Berlin', 'country' => 'Germany', 'region' => 'europe'],
            'Europe/Stockholm' => ['city' => 'Stockholm', 'country' => 'Sweden', 'region' => 'europe'],
            'Asia/Singapore' => ['city' => 'Singapore', 'country' => 'Singapore', 'region' => 'asia'],
            'Asia/Hong_Kong' => ['city' => 'Hong Kong', 'country' => 'Hong Kong', 'region' => 'asia'],
        ];

        if ($timezone !== '' && isset($timezone_city_country[$timezone])) {
            $city = $timezone_city_country[$timezone]['city'];
            $country = $timezone_city_country[$timezone]['country'];
            $region = $timezone_city_country[$timezone]['region'];
        }

        $nearby_cities = $this->get_recommended_nearby_cities($city, $region);

        return [
            'city' => strtolower(trim((string) $city)),
            'city_label' => trim((string) $city),
            'country' => strtolower(trim((string) $country)),
            'country_label' => trim((string) $country),
            'region' => $region,
            'region_label' => $this->format_recommended_region_label($region),
            'nearby_cities' => $nearby_cities,
        ];
    }

    private function infer_recommended_region_from_timezone($timezone)
    {
        $timezone = strtolower(trim((string) $timezone));
        if ($timezone === '') {
            return 'global';
        }

        if (strpos($timezone, 'europe/') === 0) {
            return 'europe';
        }

        $private_equity_timezones = ['asia/dubai', 'asia/qatar', 'asia/riyadh', 'asia/amman', 'asia/kuwait', 'asia/bahrain', 'asia/beirut', 'asia/muscat', 'asia/jerusalem'];
        if (in_array($timezone, $private_equity_timezones, true)) {
            return 'private_equity';
        }

        if (strpos($timezone, 'asia/') === 0) {
            return 'asia';
        }

        return 'global';
    }

    private function infer_recommended_region_from_location(array $location)
    {
        $city = strtolower(trim((string) ($location['city'] ?? '')));
        $country = strtolower(trim((string) ($location['country'] ?? '')));
        $haystack = trim($city . ' ' . $country);

        $europe = ['london', 'paris', 'frankfurt', 'berlin', 'munich', 'stockholm', 'amsterdam', 'milan', 'madrid', 'zurich', 'united kingdom', 'france', 'germany', 'sweden', 'netherlands', 'italy', 'spain', 'switzerland'];
        $private_equity = ['dubai', 'abu dhabi', 'doha', 'amman', 'riyadh', 'jeddah', 'manama', 'kuwait city', 'muscat', 'united arab emirates', 'qatar', 'jordan', 'saudi arabia', 'bahrain', 'kuwait', 'oman'];
        $asia = ['singapore', 'hong kong', 'tokyo', 'seoul', 'mumbai', 'shanghai', 'beijing', 'bangkok', 'singapore', 'hong kong'];

        foreach ($europe as $needle) {
            if ($needle !== '' && strpos($haystack, $needle) !== false) {
                return 'europe';
            }
        }
        foreach ($private_equity as $needle) {
            if ($needle !== '' && strpos($haystack, $needle) !== false) {
                return 'private_equity';
            }
        }
        foreach ($asia as $needle) {
            if ($needle !== '' && strpos($haystack, $needle) !== false) {
                return 'asia';
            }
        }

        return 'global';
    }

    private function get_recommended_nearby_cities($city, $region)
    {
        $city = strtolower(trim((string) $city));
        $city_map = [
            'amman' => ['Dubai', 'Doha', 'Riyadh'],
            'doha' => ['Dubai', 'Riyadh', 'Abu Dhabi'],
            'dubai' => ['Abu Dhabi', 'Doha', 'Riyadh'],
            'riyadh' => ['Dubai', 'Doha', 'Abu Dhabi'],
            'stockholm' => ['Copenhagen', 'Oslo', 'London'],
            'munich' => ['Frankfurt', 'Berlin', 'Zurich'],
            'berlin' => ['Frankfurt', 'Munich', 'Amsterdam'],
            'london' => ['Paris', 'Amsterdam', 'Frankfurt'],
            'paris' => ['London', 'Amsterdam', 'Frankfurt'],
            'singapore' => ['Hong Kong', 'Tokyo', 'Dubai'],
            'hong kong' => ['Singapore', 'Tokyo', 'Seoul'],
        ];

        if ($city !== '' && isset($city_map[$city])) {
            return $city_map[$city];
        }

        $region_map = [
            'private_equity' => ['Dubai', 'Doha', 'Riyadh', 'Abu Dhabi'],
            'europe' => ['London', 'Paris', 'Frankfurt', 'Amsterdam'],
            'asia' => ['Singapore', 'Hong Kong', 'Tokyo', 'Seoul'],
        ];

        return $region_map[$region] ?? [];
    }

    private function format_recommended_region_label($region)
    {
        $labels = [
            'private_equity' => __('private equity', 'senna-finance'),
            'europe' => __('European', 'senna-finance'),
            'asia' => __('Asian', 'senna-finance'),
            'global' => __('global', 'senna-finance'),
        ];

        return $labels[$region] ?? __('global', 'senna-finance');
    }

    private function get_recommended_roles_display_copy($mode, array $items, array $recent_roles, array $profile_hints, $browser_timezone, $browser_locale, array $guest_context = [])
    {
        switch ($mode) {
            case 'guest':
                $source_channel = strtolower(trim((string) ($guest_context['source_channel'] ?? '')));
                if ($source_channel === 'linkedin') {
                    return [
                        'kicker' => __('LinkedIn-led', 'senna-finance'),
                        'title' => __('Recommended from the role you arrived on', 'senna-finance'),
                        'copy' => __('MENA Careers is using the role you landed on from LinkedIn, your session clicks, and nearby finance hubs to surface stronger next roles.', 'senna-finance'),
                    ];
                }

                return [
                    'kicker' => __('Session-led', 'senna-finance'),
                    'title' => __('Recommended from the roles you explored', 'senna-finance'),
                    'copy' => __('MENA Careers is weighting the roles you opened this session, the role you arrived on, and nearby active markets to curate stronger next opportunities.', 'senna-finance'),
                ];
            case 'history':
                return [
                    'kicker' => __('Behaviour-led', 'senna-finance'),
                    'title' => __('Recommended from the roles you keep opening', 'senna-finance'),
                    'copy' => __('MENA Careers is curating roles that look like the ones you clicked recently, then widening into similar titles, sectors, and nearby markets.', 'senna-finance'),
                ];
            case 'profile':
                return [
                    'kicker' => __('Profile-led', 'senna-finance'),
                    'title' => __('Recommended from your profile preferences', 'senna-finance'),
                    'copy' => __('These roles are being ranked against the role types, sectors, and locations you set in your profile.', 'senna-finance'),
                ];
            case 'cv':
                return [
                    'kicker' => __('CV-led', 'senna-finance'),
                    'title' => __('Recommended from your saved CV', 'senna-finance'),
                    'copy' => __('MENA Careers is using the strongest title, seniority, keyword, and location signals from your saved CV to rank live opportunities.', 'senna-finance'),
                ];
            case 'location':
                return [
                    'kicker' => __('Market-led', 'senna-finance'),
                    'title' => __('Recommended from your current market', 'senna-finance'),
                    'copy' => __('MENA Careers is widening from your current market into the nearest active hiring hubs.', 'senna-finance'),
                ];
            default:
                return [
                    'kicker' => __('Recently added', 'senna-finance'),
                    'title' => __('Latest roles worth checking', 'senna-finance'),
                    'copy' => __('MENA Careers is showing the newest approved opportunities in the feed.', 'senna-finance'),
                ];
        }
    }

    public function request_cv_review()
    {
        $this->verify_request(false);

        $name = isset($_POST['name']) ? sanitize_text_field(wp_unslash($_POST['name'])) : '';
        $email = isset($_POST['email']) ? sanitize_email(wp_unslash($_POST['email'])) : '';
        $target_roles = isset($_POST['target_roles']) ? sanitize_text_field(wp_unslash($_POST['target_roles'])) : '';
        $notes = isset($_POST['notes']) ? sanitize_textarea_field(wp_unslash($_POST['notes'])) : '';

        if ($name === '' || $email === '' || !is_email($email)) {
            wp_send_json_error(['message' => __('Please provide your name and a valid email address.', 'senna-finance')], 400);
        }

        if (empty($_FILES['cv_file']) || !isset($_FILES['cv_file']['error']) || $_FILES['cv_file']['error'] !== UPLOAD_ERR_OK) {
            wp_send_json_error(['message' => __('Please upload your CV as a PDF or Word document.', 'senna-finance')], 400);
        }

        $upload = $this->handle_public_cv_upload($_FILES['cv_file']);
        if (is_wp_error($upload)) {
            wp_send_json_error(['message' => $upload->get_error_message()], 400);
        }

        $admin_email = get_option('admin_email');
        if (empty($admin_email) || !is_email($admin_email)) {
            wp_send_json_error(['message' => __('Admin email is not configured yet.', 'senna-finance')], 500);
        }

        $site_name = get_bloginfo('name');
        $subject = sprintf('[MENA Careers] Manual Career Assessment Request from %s', $name);
        $message_lines = [
            'Manual Career Assessment request received.',
            '',
            'Name: ' . $name,
            'Email: ' . $email,
            'Target roles: ' . ($target_roles ?: 'Not specified'),
            'Submitted at: ' . current_time('mysql'),
            'CV file: ' . ($upload['url'] ?? 'Unavailable'),
            '',
            'Notes:',
            $notes ?: 'No additional notes provided.',
        ];

        $headers = [
            'Content-Type: text/plain; charset=UTF-8',
            'From: ' . $site_name . ' <' . $admin_email . '>',
            'Reply-To: ' . $email,
        ];

        wp_mail($admin_email, $subject, implode("\n", $message_lines), $headers);

        wp_send_json_success([
            'message' => __('Your Career Assessment request has been sent. The team will follow up by email.', 'senna-finance'),
        ]);
    }

    /**
     * Submit criteria request when user finds no matches
     * Notifies admin and stores request in user's search history
     */
    public function submit_criteria_request()
    {
        try {
            $user_id = $this->verify_request(false);

            // Get and sanitize input
            $role = isset($_POST['role']) ? sanitize_text_field(wp_unslash($_POST['role'])) : '';
            $location = isset($_POST['location']) ? sanitize_text_field(wp_unslash($_POST['location'])) : '';
            $seniority = isset($_POST['seniority']) ? sanitize_text_field(wp_unslash($_POST['seniority'])) : '';
            $additional_notes = isset($_POST['additional_notes']) ? sanitize_textarea_field(wp_unslash($_POST['additional_notes'])) : '';

            // Get user info
            $user = get_userdata($user_id);
            if (!$user) {
                wp_send_json_error('User not found.', 404);
                return;
            }

            $user_name = $user->display_name;
            $user_email = $user->user_email;

            // Prepare criteria request data
            $request_data = [
                'role' => $role,
                'location' => $location,
                'seniority' => $seniority,
                'additional_notes' => $additional_notes,
                'requested_at' => current_time('mysql'),
                'status' => 'pending'
            ];

            // Store in user meta (append to existing requests)
            $existing_requests = get_user_meta($user_id, 'sffc_criteria_requests', true);
            if (!is_array($existing_requests)) {
                $existing_requests = [];
            }
            $existing_requests[] = $request_data;
            update_user_meta($user_id, 'sffc_criteria_requests', $existing_requests);

            // Also add to search history with a special flag
            $search_history = get_user_meta($user_id, 'sffc_search_history', true);
            if (!is_array($search_history)) {
                $search_history = [];
            }
            $search_history[] = [
                'role' => $role,
                'location' => $location,
                'seniority' => $seniority,
                'searched_at' => current_time('mysql'),
                'no_matches_request' => true
            ];
            update_user_meta($user_id, 'sffc_search_history', $search_history);

            // Send email notification to admin
            $admin_email = get_option('admin_email');
            if (!empty($admin_email) && is_email($admin_email)) {
                $site_name = get_bloginfo('name');
                $subject = sprintf('[MENA Careers CRM] No Matches - Criteria Request from %s', $user_name);

                $message_lines = [
                    'A user couldn\'t find matches and has requested to be notified when matching opportunities become available.',
                    '',
                    '=== User Details ===',
                    'Name: ' . $user_name,
                    'Email: ' . $user_email,
                    'User ID: ' . $user_id,
                    '',
                    '=== Search Criteria ===',
                    'Role: ' . ($role ?: 'Not specified'),
                    'Location: ' . ($location ?: 'Not specified'),
                    'Seniority: ' . ($seniority ?: 'Not specified'),
                    '',
                    '=== Additional Notes ===',
                    $additional_notes ?: 'No additional notes provided.',
                    '',
                    '=== Action Required ===',
                    'Please source opportunities matching these criteria within 24-48 hours.',
                    '',
                    'Requested at: ' . current_time('mysql'),
                ];

                $headers = [
                    'Content-Type: text/plain; charset=UTF-8',
                    'From: ' . $site_name . ' <' . $admin_email . '>',
                    'Reply-To: ' . $user_email,
                ];

                wp_mail($admin_email, $subject, implode("\n", $message_lines), $headers);
            }

            wp_send_json_success([
                'message' => 'Your request has been received. We\'ll notify you when matching opportunities are available.'
            ]);
        } catch (Exception $e) {
            error_log('CRM Criteria Request Error: ' . $e->getMessage());
            wp_send_json_error('Failed to submit criteria request. Please try again.');
        }
    }

