    private function handle_public_cv_upload($file)
    {
        if (empty($file) || !is_array($file)) {
            return new WP_Error('missing_file', __('Please upload your CV first.', 'senna-finance'));
        }

        $allowed_mimes = [
            'pdf' => 'application/pdf',
            'doc' => 'application/msword',
            'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        ];

        $checked = wp_check_filetype_and_ext($file['tmp_name'], $file['name'], $allowed_mimes);
        if (empty($checked['ext']) || empty($checked['type'])) {
            return new WP_Error('invalid_file', __('Please upload a PDF, DOC, or DOCX file.', 'senna-finance'));
        }

        if (!empty($file['size']) && (int) $file['size'] > 5 * 1024 * 1024) {
            return new WP_Error('file_too_large', __('The CV file is too large. Maximum size is 5MB.', 'senna-finance'));
        }

        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/media.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';

        $upload = wp_handle_upload($file, ['test_form' => false, 'mimes' => $allowed_mimes]);

        if (!empty($upload['error'])) {
            return new WP_Error('upload_failed', sprintf(__('Upload failed: %s', 'senna-finance'), $upload['error']));
        }

        return $upload;
    }

    /**
     * Get all available roles without matching
     */
    public function get_all_roles()
    {
        try {
            $user_id = $this->verify_request();

            // Get all approved posts
            $post_model = new SFFC_CRM_Post();
            $posts = $post_model->get_feed([
                'page' => 1,
                'per_page' => 100,
                'approved_only' => true,
                'user_id' => $user_id // Include user_id to check saved status
            ]);

            if (empty($posts)) {
                wp_send_json_success([
                    'items' => [],
                    'message' => 'No posts available.'
                ]);
                return;
            }

            wp_send_json_success([
                'items' => $posts,
                'total' => count($posts)
            ]);
        } catch (Throwable $e) {
            error_log('Fatal error in get_all_roles(): ' . $e->getMessage() . ' in ' . $e->getFile() . ':' . $e->getLine());
            wp_send_json_error([
                'message' => 'An error occurred while loading roles. Please try again.'
            ]);
        }
    }

    /**
     * Public version of all roles endpoint for logged-out visitors
     */
    public function get_all_roles_public()
    {
        try {
            // Do not require login. Provide limited dataset.
            $post_model = new SFFC_CRM_Post();
            $posts = $post_model->get_feed([
                'page' => 1,
                'per_page' => 100,
                'approved_only' => true,
                'user_id' => 0,
            ]);

            if (empty($posts)) {
                wp_send_json_success([
                    'items' => [],
                    'message' => 'No posts available.',
                ]);
                return;
            }

            // Strip any sensitive fields (saved states etc.)
            foreach ($posts as &$post) {
                unset($post['is_saved'], $post['saved_id']);
            }

            wp_send_json_success([
                'items' => $posts,
                'total' => count($posts),
            ]);
        } catch (Throwable $e) {
            error_log('Fatal error in get_all_roles_public(): ' . $e->getMessage());
            wp_send_json_error([
                'message' => 'Unable to load roles right now. Please try again.',
            ]);
        }
    }

