    private function normalize_advanced_match_text($text)
    {
        $text = strtolower(wp_strip_all_tags((string) $text));
        $text = html_entity_decode($text, ENT_QUOTES, 'UTF-8');
        $text = preg_replace('/[^a-z0-9\+\#\.\&\/\-\s]/', ' ', $text);
        $text = preg_replace('/\s+/', ' ', $text);

        return trim((string) $text);
    }

    private function tokenize_advanced_match_text($text, $stopwords = [])
    {
        $normalized = $this->normalize_advanced_match_text($text);
        if ($normalized === '') {
            return [];
        }

        $tokens = preg_split('/\s+/', $normalized) ?: [];
        $stopwords = array_fill_keys($stopwords, true);
        $filtered = [];

        foreach ($tokens as $token) {
            if ($token === '' || strlen($token) < 2) {
                continue;
            }
            if (isset($stopwords[$token])) {
                continue;
            }
            $filtered[] = $token;
        }

        return array_values(array_unique($filtered));
    }

    private function collect_list_terms($value)
    {
        if (empty($value)) {
            return [];
        }

        if (is_array($value)) {
            $items = $value;
        } elseif (is_string($value)) {
            $decoded = json_decode($value, true);
            if (is_array($decoded)) {
                $items = $decoded;
            } else {
                $items = preg_split('/[\r\n,|;]+/', $value) ?: [];
            }
        } else {
            $items = [(string) $value];
        }

        $terms = [];
        foreach ($items as $item) {
            if (is_array($item)) {
                $preferred_keys = ['label', 'term', 'name', 'value'];
                $preferred_value = '';
                foreach ($preferred_keys as $key) {
                    if (!empty($item[$key]) && is_scalar($item[$key])) {
                        $preferred_value = trim((string) $item[$key]);
                        break;
                    }
                }

                if ($preferred_value !== '') {
                    $terms[] = $preferred_value;
                    continue;
                }

                foreach ($item as $nested_key => $nested) {
                    if (in_array((string) $nested_key, ['type', 'priority', 'category', 'weight'], true)) {
                        continue;
                    }

                    if (is_array($nested)) {
                        foreach ($nested as $nested_child) {
                            $terms[] = trim((string) $nested_child);
                        }
                    } else {
                        $terms[] = trim((string) $nested);
                    }
                }
            } else {
                $terms[] = trim((string) $item);
            }
        }

        return array_values(array_filter(array_unique($terms)));
    }

    private function extract_current_role_title_advanced($cv_text)
    {
        $lines = preg_split('/[\r\n]+/', (string) $cv_text) ?: [];
        $cleaned = [];
        foreach ($lines as $line) {
            $line = trim(preg_replace('/\s+/', ' ', (string) $line));
            if ($line !== '') {
                $cleaned[] = $line;
            }
        }

        foreach ($cleaned as $line) {
            if (!preg_match('/(?:19|20)\d{2}\s*[-–—]\s*(?:current|present|(?:19|20)\d{2})/i', $line)) {
                continue;
            }

            $title = preg_replace('/\s*(?:19|20)\d{2}\s*[-–—]\s*(?:current|present|(?:19|20)\d{2}).*$/i', '', $line);
            $title = trim((string) $title, " \t\n\r\0\x0B-–—");
            if ($title === '') {
                continue;
            }

            if (preg_match('/^(work experience|experience|education|additional information)$/i', $title)) {
                continue;
            }

            if (strlen($title) >= 4 && strlen($title) <= 120) {
                return $title;
            }
        }

        foreach ($cleaned as $index => $line) {
            if (!preg_match('/(?:19|20)\d{2}\s*[-–—]\s*(?:current|present|(?:19|20)\d{2})/i', $line)) {
                continue;
            }
            $previous = $cleaned[$index - 1] ?? '';
            if ($previous !== '' && !preg_match('/\b(university|institute|school|college)\b/i', $previous)) {
                return $previous;
            }
        }

        return $this->extract_current_role_title($cv_text);
    }

    private function detect_alias_hits_in_text($text, $map)
    {
        $hits = [];
        foreach ($map as $canonical => $aliases) {
            $count = 0;
            foreach ((array) $aliases as $alias) {
                $alias = $this->normalize_advanced_match_text($alias);
                if ($alias === '') {
                    continue;
                }
                if (strpos($text, $alias) !== false) {
                    $count++;
                }
            }
            if ($count > 0) {
                $hits[$canonical] = $count;
            }
        }

        return $hits;
    }

    private function detect_locations_in_text($text, $config)
    {
        $normalized = $this->normalize_advanced_match_text($text);
        $hits = [];

        foreach ($config['location_regions'] as $location => $regions) {
            $count = $this->count_normalized_phrase_hits($normalized, (string) $location);
            if ($count > 0) {
                $hits[$location] = [
                    'regions' => $regions,
                    'count' => $count,
                    'country' => in_array('europe', (array) $regions, true) || in_array('private_equity', (array) $regions, true) || in_array('gcc', (array) $regions, true)
                        ? (string) $location
                        : '',
                ];
            }
        }

        foreach ($this->get_curated_cv_location_library() as $canonical => $location_data) {
            $count = 0;
            foreach ((array) ($location_data['aliases'] ?? []) as $alias) {
                $count += $this->count_normalized_phrase_hits($normalized, (string) $alias);
            }

            if ($count <= 0) {
                continue;
            }

            $existing = (array) ($hits[$canonical] ?? []);
            $hits[$canonical] = [
                'regions' => array_values(array_unique(array_merge(
                    (array) ($existing['regions'] ?? []),
                    (array) ($location_data['regions'] ?? [])
                ))),
                'count' => (int) ($count + (int) ($existing['count'] ?? 0)),
                'country' => (string) (($existing['country'] ?? '') ?: ($location_data['country'] ?? '')),
                'type' => 'city',
            ];
        }

        uasort($hits, static function ($left, $right) {
            $left_count = (int) ($left['count'] ?? 0);
            $right_count = (int) ($right['count'] ?? 0);
            if ($left_count === $right_count) {
                return 0;
            }
            return $left_count > $right_count ? -1 : 1;
        });

        return $hits;
    }

    private function count_normalized_phrase_hits($text, $phrase)
    {
        $text = trim((string) $text);
        $phrase = $this->normalize_advanced_match_text($phrase);
        if ($text === '' || $phrase === '') {
            return 0;
        }

        $pattern = '/(?<![a-z0-9])' . preg_quote($phrase, '/') . '(?![a-z0-9])/';
        $matches = [];
        preg_match_all($pattern, $text, $matches);

        return count((array) ($matches[0] ?? []));
    }

