    private function extract_role_family_scores($text, $config)
    {
        $scores = [];
        foreach ($config['role_families'] as $family => $aliases) {
            $score = 0;
            foreach ((array) $aliases as $alias) {
                $alias = $this->normalize_advanced_match_text($alias);
                if ($alias === '') {
                    continue;
                }
                if (strpos($text, $alias) !== false) {
                    $score += max(1, substr_count($text, $alias));
                }
            }
            if ($score > 0) {
                $scores[$family] = $score;
            }
        }
        arsort($scores);

        return $scores;
    }

    private function get_top_role_family($scores)
    {
        if (empty($scores) || !is_array($scores)) {
            return 'other';
        }

        $keys = array_keys($scores);
        return $keys ? (string) $keys[0] : 'other';
    }

    private function score_document_domains_advanced($text, $taxonomy)
    {
        $scores = [];
        foreach ((array) $taxonomy as $domain => $domain_data) {
            $domain_score = 0;
            foreach ((array) ($domain_data['keywords'] ?? []) as $group_data) {
                $weight = (float) ($group_data['weight'] ?? 1);
                foreach ((array) ($group_data['phrases'] ?? []) as $phrase) {
                    $phrase = $this->normalize_advanced_match_text($phrase);
                    if ($phrase !== '' && strpos($text, $phrase) !== false) {
                        $domain_score += max(1, substr_count($text, $phrase)) * ($weight * 1.5);
                    }
                }
                foreach ((array) ($group_data['terms'] ?? []) as $term) {
                    $term = $this->normalize_advanced_match_text($term);
                    if ($term !== '' && strpos($text, $term) !== false) {
                        $domain_score += max(1, substr_count($text, $term)) * $weight;
                    }
                }
            }
            if ($domain_score > 0) {
                $scores[$domain] = $domain_score;
            }
        }

        $total = array_sum($scores);
        if ($total > 0) {
            foreach ($scores as $domain => $score) {
                $scores[$domain] = $score / $total;
            }
        }

        arsort($scores);
        return $scores;
    }

    private function get_top_domain_key($scores)
    {
        if (empty($scores) || !is_array($scores)) {
            return '';
        }

        $keys = array_keys($scores);
        return $keys ? (string) $keys[0] : '';
    }

    private function extract_job_skill_requirements($post, $jd_lower, $config)
    {
        $required = [];
        $preferred = [];

        foreach ($this->collect_list_terms($post['required_technical_skills'] ?? []) as $term) {
            $normalized = $this->normalize_advanced_match_text($term);
            if ($normalized !== '') {
                $required[$normalized] = true;
            }
        }

        foreach ($this->collect_list_terms($post['skills_mentioned'] ?? []) as $term) {
            $normalized = $this->normalize_advanced_match_text($term);
            if ($normalized !== '') {
                $preferred[$normalized] = true;
            }
        }

        foreach ($this->collect_list_terms($post['keywords'] ?? []) as $term) {
            $normalized = $this->normalize_advanced_match_text($term);
            if ($normalized !== '') {
                $preferred[$normalized] = true;
            }
        }

        foreach ((array) ($post['insights']['must_have_keywords'] ?? []) as $term) {
            $normalized = $this->normalize_advanced_match_text($term);
            if ($normalized !== '') {
                $required[$normalized] = true;
            }
        }

        foreach (array_keys($required) as $canonical) {
            unset($preferred[$canonical]);
        }

        return [
            'required' => array_keys($required),
            'preferred' => array_keys($preferred),
        ];
    }

    private function normalize_required_skill_term($term, $config)
    {
        $term = $this->normalize_advanced_match_text($term);
        if ($term === '') {
            return '';
        }

        foreach ($config['skills'] as $canonical => $aliases) {
            foreach ((array) $aliases as $alias) {
                if ($term === $this->normalize_advanced_match_text($alias)) {
                    return $canonical;
                }
            }
        }

        return $term;
    }

    private function normalize_advanced_match_token($token)
    {
        $token = $this->normalize_advanced_match_text($token);
        if ($token === '') {
            return '';
        }

        if (in_array($token, ['modelling'], true)) {
            return 'modeling';
        }
        if (in_array($token, ['analyses'], true)) {
            return 'analysis';
        }
        if (in_array($token, ['valuations'], true)) {
            return 'valuation';
        }

        if (strlen($token) > 5 && substr($token, -3) === 'ing') {
            $token = substr($token, 0, -3);
        } elseif (strlen($token) > 4 && substr($token, -2) === 'ed') {
            $token = substr($token, 0, -2);
        } elseif (strlen($token) > 4 && substr($token, -1) === 's') {
            $token = substr($token, 0, -1);
        }

        return $token;
    }

    private function get_advanced_match_stopwords()
    {
        static $stopwords = null;
        if ($stopwords !== null) {
            return $stopwords;
        }

        $base = [];
        if (function_exists('wp_search_stopwords')) {
            $base = (array) wp_search_stopwords();
        }

        // Keep this minimal and generic. The matcher should learn from the JD/CV pair,
        // not from a large plugin-owned vocabulary.
        $fallback = [
            'the', 'and', 'for', 'with', 'from', 'into', 'onto', 'over', 'under',
            'this', 'that', 'these', 'those', 'will', 'would', 'should', 'could',
            'have', 'has', 'had', 'your', 'their', 'our',
        ];

        $stopwords = array_values(array_unique(array_filter(array_map('strval', array_merge($base, $fallback)))));
        return $stopwords;
    }

    private function extract_acronym_tokens_from_text_advanced($text)
    {
        $preserve = [];

        if (preg_match_all('/\b[A-Z]{2,6}(?:[&\/][A-Z0-9]{1,6})?\b/', (string) $text, $matches)) {
            foreach ((array) ($matches[0] ?? []) as $match) {
                $preserve[$this->normalize_advanced_match_text($match)] = true;
            }
        }

        if (preg_match_all('/\b[A-Za-z]{1,4}[0-9]{1,4}\b/', (string) $text, $matches)) {
            foreach ((array) ($matches[0] ?? []) as $match) {
                $preserve[$this->normalize_advanced_match_text($match)] = true;
            }
        }

        return array_keys(array_filter($preserve));
    }

    private function tokenize_for_advanced_matching($text, $config)
    {
        $preserve_tokens = $this->extract_acronym_tokens_from_text_advanced($text);
        $preserve_lookup = array_fill_keys($preserve_tokens, true);
        $tokens = $this->tokenize_advanced_match_text($text, $this->get_advanced_match_stopwords());
        $normalized = [];

        foreach ($tokens as $token) {
            $token = $this->normalize_advanced_match_token($token);
            if ($token === '') {
                continue;
            }
            if (strlen($token) < 3 && !isset($preserve_lookup[$token])) {
                continue;
            }
            $normalized[] = $token;
        }

        foreach ($preserve_tokens as $token) {
            $token = $this->normalize_advanced_match_token($token);
            if ($token !== '') {
                $normalized[] = $token;
            }
        }

        return array_values(array_unique($normalized));
    }

    private function extract_labelled_list_items_advanced($line)
    {
        if (!preg_match('/^\s*([A-Za-z][A-Za-z\s&\/-]{2,40})\s*:\s*(.+)$/', (string) $line, $matches)) {
            return [];
        }

        $label = strtolower(trim((string) $matches[1]));
        $value = trim((string) $matches[2]);
        if ($value === '') {
            return [];
        }

        $items = preg_split('/[,;|]+/', $value) ?: [];
        $normalized_items = [];
        foreach ($items as $item) {
            $item = trim(preg_replace('/\([^)]*\)/', '', (string) $item));
            $item = $this->normalize_advanced_match_text($item);
            if ($item !== '' && strlen($item) >= 2) {
                $normalized_items[] = $item;
            }
        }

        return [
            'label' => $label,
            'items' => array_values(array_unique($normalized_items)),
        ];
    }

    private function split_line_into_requirement_units_advanced($line)
    {
        $line = trim((string) $line);
        if ($line === '') {
            return [];
        }

        $segments = preg_split('/(?:\s*[•\-]\s+)|(?:\.\s+)|(?:;\s+)|(?:\s{2,})/', $line) ?: [];
        $units = [];

        foreach ($segments as $segment) {
            $segment = trim(preg_replace('/\s+/', ' ', (string) $segment));
            if ($segment === '') {
                continue;
            }
            if (strlen($segment) < 12 && !preg_match('/\b(cfa|acca|aca|cpa|frm|mba|sql|vba|python|java|excel|sap)\b/i', $segment)) {
                continue;
            }
            $units[] = $segment;
        }

        if (empty($units)) {
            $units[] = $line;
        }

        return array_values(array_unique($units));
    }

    private function extract_phrase_candidates_from_line_advanced($line, $config, $max_phrases = 4)
    {
        $tokens = $this->tokenize_for_advanced_matching($line, $config);
        if (empty($tokens)) {
            return [];
        }

        $preserve_lookup = array_fill_keys($this->extract_acronym_tokens_from_text_advanced($line), true);
        $candidates = [];
        $token_count = count($tokens);

        for ($length = min(4, $token_count); $length >= 1; $length--) {
            for ($i = 0; $i <= $token_count - $length; $i++) {
                $phrase_tokens = array_slice($tokens, $i, $length);
                if (empty($phrase_tokens)) {
                    continue;
                }

                if ($length === 1) {
                    $token = $phrase_tokens[0];
                    if (strlen($token) < 5 && !isset($preserve_lookup[$token])) {
                        continue;
                    }
                }

                $phrase = implode(' ', $phrase_tokens);
                $char_length = strlen(str_replace(' ', '', $phrase));
                if ($char_length < 6 && !isset($preserve_lookup[$phrase])) {
                    continue;
                }

                $score = ($length * 1.1) + min(1.8, $char_length / 12);
                if (!isset($candidates[$phrase]) || $score > $candidates[$phrase]) {
                    $candidates[$phrase] = $score;
                }
            }
        }

        arsort($candidates);
        return array_slice(array_keys($candidates), 0, $max_phrases);
    }

    private function detect_cv_line_section_advanced($current_section, $line)
    {
        if (preg_match('/^(education|academic)/i', $line)) {
            return 'education';
        }
        if (preg_match('/^(additional information|skills|technical skills|certifications|languages)/i', $line)) {
            return 'skills';
        }
        if (preg_match('/^(projects|project)/i', $line)) {
            return 'project';
        }
        if (preg_match('/^(experience|work experience|professional experience|employment)/i', $line)) {
            return 'experience';
        }

        return $current_section;
    }

    private function detect_cv_years_ago_from_line_advanced($line)
    {
        $current_year = (int) gmdate('Y');
        if (preg_match('/(?:present|current)/i', $line)) {
            return 0;
        }
        if (preg_match_all('/(?:19|20)\d{2}/', $line, $matches) && !empty($matches[0])) {
            $years = array_map('intval', $matches[0]);
            $end_year = max($years);
            return max(0, $current_year - $end_year);
        }

        return null;
    }

    private function build_advanced_cv_evidence_map($cv_text, $config)
    {
        $lines = preg_split('/[\r\n]+/', (string) $cv_text) ?: [];
        $section = 'summary';
        $evidence_map = [];
        $blocks = [];
        $token_index = [];
        $document_frequency = [];

        foreach ($lines as $line) {
            $line = trim(preg_replace('/\s+/', ' ', (string) $line));
            if ($line === '') {
                continue;
            }

            $section = $this->detect_cv_line_section_advanced($section, $line);
            $section_key = $section;
            $years_ago = $this->detect_cv_years_ago_from_line_advanced($line);
            if ($section === 'experience') {
                if ($years_ago === 0) {
                    $section_key = 'current_role';
                } elseif ($years_ago !== null && $years_ago <= 3) {
                    $section_key = 'recent_role';
                } else {
                    $section_key = 'past_role';
                }
            } elseif ($section === 'skills' && preg_match('/\b(cfa|acca|aca|cpa|frm|imc|mba|chartered)\b/i', $line)) {
                $section_key = 'certification';
            }

            $line_tokens = $this->tokenize_for_advanced_matching($line, $config);
            if (!empty($line_tokens)) {
                $block_id = 'block_' . count($blocks);
                $blocks[$block_id] = [
                    'id' => $block_id,
                    'text' => $line,
                    'tokens' => $line_tokens,
                    'token_frequencies' => array_count_values($line_tokens),
                    'length' => count($line_tokens),
                    'section' => $section_key,
                    'years_ago' => $years_ago ?? 5,
                ];

                foreach (array_unique($line_tokens) as $token) {
                    $token_index[$token][] = $block_id;
                    $document_frequency[$token] = (int) ($document_frequency[$token] ?? 0) + 1;
                }
            }

            $labelled = $this->extract_labelled_list_items_advanced($line);
            if (!empty($labelled['items'])) {
                foreach ((array) $labelled['items'] as $item) {
                    if (!isset($evidence_map[$item])) {
                        $evidence_map[$item] = [
                            'phrase' => $item,
                            'tokens' => $this->tokenize_for_advanced_matching($item, $config),
                            'count' => 0,
                            'best_section' => $section_key,
                            'best_years_ago' => $years_ago ?? 5,
                            'source_lines' => [],
                        ];
                    }
                    $evidence_map[$item]['count']++;
                    $evidence_map[$item]['source_lines'][] = $line;
                }
            }

            foreach ($this->extract_phrase_candidates_from_line_advanced($line, $config) as $phrase) {
                if (!isset($evidence_map[$phrase])) {
                    $evidence_map[$phrase] = [
                        'phrase' => $phrase,
                        'tokens' => $this->tokenize_for_advanced_matching($phrase, $config),
                        'count' => 0,
                        'best_section' => $section_key,
                        'best_years_ago' => $years_ago ?? 5,
                        'source_lines' => [],
                    ];
                }

                $evidence_map[$phrase]['count']++;
                $evidence_map[$phrase]['source_lines'][] = $line;

                $current_multiplier = (float) (($config['section_multipliers'][$evidence_map[$phrase]['best_section']] ?? 0.5));
                $new_multiplier = (float) (($config['section_multipliers'][$section_key] ?? 0.5));
                if ($new_multiplier > $current_multiplier) {
                    $evidence_map[$phrase]['best_section'] = $section_key;
                }
                if ($years_ago !== null) {
                    $evidence_map[$phrase]['best_years_ago'] = min((float) $evidence_map[$phrase]['best_years_ago'], (float) $years_ago);
                }
            }
        }

        $phrase_token_index = [];
        foreach ($evidence_map as $phrase => $evidence) {
            foreach ((array) ($evidence['tokens'] ?? []) as $token) {
                $phrase_token_index[$token][] = $phrase;
            }
        }

        $avg_block_length = 0.0;
        if (!empty($blocks)) {
            $total_length = 0;
            foreach ($blocks as $block) {
                $total_length += (int) ($block['length'] ?? 0);
            }
            $avg_block_length = $total_length / max(1, count($blocks));
        }

        return [
            'items' => $evidence_map,
            'token_index' => $phrase_token_index,
            'blocks' => $blocks,
            'block_token_index' => $token_index,
            'document_frequency' => $document_frequency,
            'document_count' => count($blocks),
            'avg_block_length' => $avg_block_length,
        ];
    }

    private function detect_job_requirement_section_advanced($current_section, $line)
    {
        if (preg_match('/^(requirements|qualifications|skills required|what you need)/i', $line)) {
            return 'essential';
        }
        if (preg_match('/^(responsibilities|duties|what you will do|the role)/i', $line)) {
            return 'responsibilities';
        }
        if (preg_match('/^(preferred|nice to have|desirable|bonus)/i', $line)) {
            return 'preferred';
        }

        return $current_section;
    }

    private function determine_requirement_importance_advanced($line, $section)
    {
        if (preg_match('/must have|mandatory|required to|requires? |requirement:|essential|at least|min(?:imum)?/i', $line)) {
            return 'required';
        }
        if ($section === 'essential') {
            return 'must';
        }
        if ($section === 'preferred' || preg_match('/preferred|nice to have|desirable|bonus/i', $line)) {
            return 'preferred';
        }

        return $section === 'title' ? 'must' : 'core';
    }

    private function line_has_requirement_signal_advanced($line, $section)
    {
        if (in_array($section, ['title', 'essential', 'responsibilities', 'preferred'], true)) {
            return true;
        }

        return (bool) preg_match(
            '/must|required|essential|preferred|nice to have|desirable|responsible for|responsibilities|experience in|experience with|background in|knowledge of|understanding of|exposure to|ability to|proven|track record|hands on|hands-on|min(?:imum)?|at least|familiarity with/i',
            $line
        );
    }

    private function add_requirement_item_advanced(&$requirements, $type, $value, $importance, $section, $meta = [])
    {
        $config = $this->get_advanced_match_config();
        $key = $type . ':' . md5($type . '|' . maybe_serialize($value));
        $base_weight = (float) ($meta['base_weight'] ?? 1.0);

        if (!isset($requirements[$key])) {
            $requirements[$key] = array_merge([
                'type' => $type,
                'value' => $value,
                'importance' => $importance,
                'section' => $section,
                'frequency' => 0,
                'base_weight' => $base_weight,
                'tokens' => is_string($value) ? $this->tokenize_for_advanced_matching($value, $config) : [],
                'hard_gate' => false,
            ], $meta);
        }

        $requirements[$key]['frequency']++;
        if (($config['importance_multipliers'][$importance] ?? 1.0) > ($config['importance_multipliers'][$requirements[$key]['importance']] ?? 1.0)) {
            $requirements[$key]['importance'] = $importance;
        }
        if (($config['section_multipliers'][$section] ?? 1.0) > ($config['section_multipliers'][$requirements[$key]['section']] ?? 1.0)) {
            $requirements[$key]['section'] = $section;
        }
        if (!empty($meta['hard_gate'])) {
            $requirements[$key]['hard_gate'] = true;
        }
    }

    private function extract_job_requirement_items_advanced($post, $config)
    {
        $requirements = [];
        $title = trim((string) ($post['role_title'] ?? ''));
        $content = (string) ($post['content'] ?? '');
        $lines = [];
        if ($title !== '') {
            $lines[] = ['line' => $title, 'section' => 'title'];
        }
        foreach (preg_split('/[\r\n]+/', $content) ?: [] as $line) {
            $line = trim(preg_replace('/\s+/', ' ', (string) $line));
            if ($line !== '') {
                $lines[] = ['line' => $line, 'section' => null];
            }
        }

        $current_section = 'summary';
        foreach ($lines as $entry) {
            $line = $entry['line'];
            $section = $entry['section'] ?: $this->detect_job_requirement_section_advanced($current_section, $line);
            $current_section = $section;
            foreach ($this->split_line_into_requirement_units_advanced($line) as $unit) {
                $importance = $this->determine_requirement_importance_advanced($unit, $section);
                $has_requirement_signal = $this->line_has_requirement_signal_advanced($unit, $section);

                if (!$has_requirement_signal && $section !== 'title') {
                    continue;
                }

                $labelled = $this->extract_labelled_list_items_advanced($unit);
                if (!empty($labelled['items'])) {
                    foreach ((array) $labelled['items'] as $item) {
                        $this->add_requirement_item_advanced(
                            $requirements,
                            'phrase',
                            $item,
                            $importance,
                            $section,
                            [
                                'hard_gate' => in_array($importance, ['must', 'required'], true),
                                'base_weight' => $section === 'title' ? 1.2 : 1.0,
                            ]
                        );
                    }
                }

                $phrase_limit = 1;
                if ($section === 'title') {
                    $phrase_limit = 5;
                } elseif ($section === 'essential') {
                    $phrase_limit = 3;
                } elseif ($section === 'responsibilities') {
                    $phrase_limit = 2;
                } elseif ($section === 'preferred') {
                    $phrase_limit = 1;
                }

                foreach ($this->extract_phrase_candidates_from_line_advanced($unit, $config, $phrase_limit) as $phrase) {
                    $this->add_requirement_item_advanced(
                        $requirements,
                        'phrase',
                        $phrase,
                        $importance,
                        $section,
                        [
                            'hard_gate' => in_array($importance, ['must', 'required'], true),
                            'base_weight' => $section === 'title' ? 1.35 : 1.0,
                        ]
                    );
                }

                foreach ($this->detect_alias_hits_in_text($this->normalize_advanced_match_text($unit), $config['languages']) as $language => $count) {
                    $this->add_requirement_item_advanced($requirements, 'language', $language, $importance, $section, [
                        'hard_gate' => in_array($importance, ['must', 'required'], true),
                        'base_weight' => 1.2,
                    ]);
                }

                foreach ($this->detect_alias_hits_in_text($this->normalize_advanced_match_text($unit), $config['qualifications']) as $qualification => $count) {
                    $this->add_requirement_item_advanced($requirements, 'qualification', $qualification, $importance, $section, [
                        'hard_gate' => in_array($importance, ['must', 'required'], true),
                        'base_weight' => 1.2,
                    ]);
                }
            }
        }

        foreach ($this->collect_list_terms($post['required_technical_skills'] ?? []) as $term) {
            $normalized = $this->normalize_advanced_match_text($term);
            if ($normalized !== '') {
                $this->add_requirement_item_advanced($requirements, 'phrase', $normalized, 'required', 'essential', [
                    'hard_gate' => true,
                    'base_weight' => 1.25,
                ]);
            }
        }
        foreach ($this->collect_list_terms($post['skills_mentioned'] ?? []) as $term) {
            $normalized = $this->normalize_advanced_match_text($term);
            if ($normalized !== '') {
                $this->add_requirement_item_advanced($requirements, 'phrase', $normalized, 'core', 'responsibilities', [
                    'base_weight' => 1.0,
                ]);
            }
        }

        uasort($requirements, function ($a, $b) use ($config) {
            return $this->calculate_requirement_weight_advanced($b, $config) <=> $this->calculate_requirement_weight_advanced($a, $config);
        });

        $hard_gates = [];
        $scored = [];
        foreach ($requirements as $requirement) {
            if (!empty($requirement['hard_gate'])) {
                $hard_gates[] = $requirement;
            } else {
                $scored[] = $requirement;
            }
        }

        return array_values(array_merge($hard_gates, array_slice($scored, 0, 14)));
    }

    private function calculate_advanced_bm25_score($query_tokens, $block, $evidence_index)
    {
        $query_tokens = array_values(array_unique(array_filter((array) $query_tokens)));
        $block_frequencies = (array) ($block['token_frequencies'] ?? []);
        if (empty($query_tokens) || empty($block_frequencies)) {
            return 0.0;
        }

        $document_count = max(1, (int) ($evidence_index['document_count'] ?? 1));
        $avg_block_length = max(1.0, (float) ($evidence_index['avg_block_length'] ?? 1.0));
        $block_length = max(1.0, (float) ($block['length'] ?? count($block_frequencies)));
        $document_frequency = (array) ($evidence_index['document_frequency'] ?? []);

        $k1 = 1.2;
        $b = 0.75;
        $score = 0.0;

        foreach ($query_tokens as $token) {
            $tf = (float) ($block_frequencies[$token] ?? 0);
            if ($tf <= 0) {
                continue;
            }
            $df = max(0.0, (float) ($document_frequency[$token] ?? 0));
            $idf = log(1 + (($document_count - $df + 0.5) / ($df + 0.5)));
            $denominator = $tf + $k1 * (1 - $b + $b * ($block_length / $avg_block_length));
            if ($denominator <= 0) {
                continue;
            }
            $score += $idf * (($tf * ($k1 + 1)) / $denominator);
        }

        return max(0.0, $score);
    }

    private function calculate_requirement_document_alignment_advanced($cv_profile, $job_profile, $config)
    {
        $requirements = (array) ($job_profile['requirements'] ?? []);
        $evidence_items = (array) ($cv_profile['evidence_index']['items'] ?? []);
        if (empty($requirements) || empty($evidence_items)) {
            return 0.50;
        }

        $requirement_vectors = [];
        foreach ($requirements as $requirement) {
            if (($requirement['type'] ?? '') !== 'phrase') {
                continue;
            }
            $requirement_vectors[] = (array) ($requirement['tokens'] ?? []);
        }

        if (empty($requirement_vectors)) {
            return 0.50;
        }

        $evidence_vectors = [];
        foreach ($evidence_items as $evidence) {
            $evidence_vectors[] = (array) ($evidence['tokens'] ?? []);
        }

        $total = 0.0;
        foreach ($requirement_vectors as $requirement_tokens) {
            $best = 0.0;
            foreach ($evidence_vectors as $evidence_tokens) {
                $best = max($best, $this->calculate_phrase_similarity_advanced($requirement_tokens, $evidence_tokens));
                if ($best >= 0.95) {
                    break;
                }
            }
            $total += $best;
        }

        return min(1.0, max(0.0, $total / count($requirement_vectors)));
    }

    private function calculate_requirement_weight_advanced($requirement, $config)
    {
        $importance = (float) ($config['importance_multipliers'][$requirement['importance'] ?? 'core'] ?? 1.0);
        $section = (float) ($config['section_multipliers'][$requirement['section'] ?? 'summary'] ?? 1.0);
        $frequency = 1 + min(0.4, log(1 + (int) ($requirement['frequency'] ?? 1)) / 4);
        return ((float) ($requirement['base_weight'] ?? 1.0)) * $importance * $section * $frequency;
    }

    private function calculate_phrase_similarity_advanced($requirement_tokens, $evidence_tokens)
    {
        $requirement_tokens = array_values(array_unique(array_filter((array) $requirement_tokens)));
        $evidence_tokens = array_values(array_unique(array_filter((array) $evidence_tokens)));
        if (empty($requirement_tokens) || empty($evidence_tokens)) {
            return 0.0;
        }

        $overlap = array_values(array_intersect($requirement_tokens, $evidence_tokens));
        if (empty($overlap)) {
            return 0.0;
        }

        $coverage = count($overlap) / count($requirement_tokens);
        $precision = count($overlap) / count($evidence_tokens);
        $jaccard = count($overlap) / count(array_unique(array_merge($requirement_tokens, $evidence_tokens)));

        return min(1.0, max(0.0, (0.55 * $coverage) + (0.25 * $precision) + (0.20 * $jaccard)));
    }

    private function score_phrase_requirement_advanced($requirement, $cv_profile, $config)
    {
        $phrase = (string) ($requirement['value'] ?? '');
        $tokens = (array) ($requirement['tokens'] ?? []);
        $evidence_index = (array) ($cv_profile['evidence_index']['items'] ?? []);
        $blocks = (array) ($cv_profile['evidence_index']['blocks'] ?? []);
        $block_token_index = (array) ($cv_profile['evidence_index']['block_token_index'] ?? []);
        $best = [
            'score' => 0.0,
            'matched_phrase' => '',
            'matched_line' => '',
            'matched_section' => '',
        ];

        if ($phrase !== '' && !empty($evidence_index[$phrase])) {
            $evidence = $evidence_index[$phrase];
            $section_multiplier = (float) ($config['section_multipliers'][$evidence['best_section'] ?? 'summary'] ?? 0.5);
            $count_strength = 1 - exp(-0.45 * (float) ($evidence['count'] ?? 1));
            $recency = exp(-0.18 * (float) ($evidence['best_years_ago'] ?? 4));
            $score = min(1.0, 0.55 + (0.20 * $section_multiplier) + (0.15 * $count_strength) + (0.10 * $recency));
            return [
                'score' => min(1.0, $score),
                'matched_phrase' => $phrase,
                'matched_line' => $evidence['source_lines'][0] ?? '',
                'matched_section' => $evidence['best_section'] ?? '',
            ];
        }

        $candidate_blocks = [];
        foreach ($tokens as $token) {
            foreach ((array) ($block_token_index[$token] ?? []) as $block_id) {
                $candidate_blocks[$block_id] = true;
            }
        }

        foreach (array_keys($candidate_blocks) as $block_id) {
            $block = $blocks[$block_id] ?? null;
            if (!$block) {
                continue;
            }

            $block_tokens = (array) ($block['tokens'] ?? []);
            $overlap_similarity = $this->calculate_phrase_similarity_advanced($tokens, $block_tokens);
            if ($overlap_similarity <= 0.14) {
                continue;
            }

            $bm25 = $this->calculate_advanced_bm25_score($tokens, $block, $cv_profile['evidence_index'] ?? []);
            $bm25_strength = 1 - exp(-0.9 * $bm25);
            $section_multiplier = (float) ($config['section_multipliers'][$block['section'] ?? 'summary'] ?? 0.5);
            $section_quality = min(1.0, $section_multiplier / 1.45);
            $recency = exp(-0.16 * (float) ($block['years_ago'] ?? 4));
            $score = (
                (0.48 * $overlap_similarity)
                + (0.28 * $bm25_strength)
                + (0.14 * $section_quality)
                + (0.10 * $recency)
            );

            if ($score > $best['score']) {
                $best = [
                    'score' => min(1.0, $score),
                    'matched_phrase' => $block['text'] ?? '',
                    'matched_line' => $block['text'] ?? '',
                    'matched_section' => $block['section'] ?? '',
                ];
            }
        }

        return $best;
    }

    private function calculate_advanced_requirement_fit($cv_profile, $job_profile, $config)
    {
        $requirements = (array) ($job_profile['requirements'] ?? []);
        if (empty($requirements)) {
            return [
                'score' => 0.55,
                'coverage' => 0.50,
                'matched' => [],
                'missing_required' => [],
                'breakdown' => [],
            ];
        }

        $total_weight = 0.0;
        $weighted_score = 0.0;
        $coverage_hits = 0;
        $matched = [];
        $missing_required = [];
        $breakdown = [];

        foreach ($requirements as $requirement) {
            $weight = $this->calculate_requirement_weight_advanced($requirement, $config);
            $total_weight += $weight;

            if (($requirement['type'] ?? '') === 'phrase') {
                $match = $this->score_phrase_requirement_advanced($requirement, $cv_profile, $config);
                $score = (float) ($match['score'] ?? 0.0);
                if ($score >= 0.34) {
                    $coverage_hits++;
                    $matched[] = $match['matched_phrase'] ?: (string) $requirement['value'];
                } elseif (($requirement['importance'] ?? 'core') !== 'preferred') {
                    $missing_required[] = (string) $requirement['value'];
                }
                $weighted_score += $score * $weight;
                $breakdown[] = [
                    'requirement' => (string) $requirement['value'],
                    'importance' => (string) ($requirement['importance'] ?? 'core'),
                    'score' => round($score * 100),
                    'matched_phrase' => $match['matched_phrase'] ?? '',
                    'matched_section' => $match['matched_section'] ?? '',
                ];
            }
        }

        $score = $total_weight > 0 ? ($weighted_score / $total_weight) : 0.55;
        $coverage = count($requirements) > 0 ? ($coverage_hits / count($requirements)) : 0.50;

        return [
            'score' => min(1.0, max(0.0, $score)),
            'coverage' => min(1.0, max(0.0, $coverage)),
            'matched' => array_values(array_unique(array_filter($matched))),
            'missing_required' => array_values(array_unique(array_filter($missing_required))),
            'breakdown' => $breakdown,
        ];
    }

    private function build_advanced_cv_match_profile($cv_text, $taxonomy)
    {
        $config = $this->get_advanced_match_config();
        $cv_lower = $this->normalize_advanced_match_text($cv_text);
        $current_title = $this->extract_current_role_title_advanced($cv_text);
        $seniority = $this->classify_seniority_from_title($current_title);
        if ($seniority === 'unknown' || $seniority === '') {
            $seniority = $this->infer_seniority_from_cv_text($cv_text);
        }
        $experience_years = $this->extract_experience_years($cv_text);
        $experience_seniority = $this->map_years_to_seniority((int) round($experience_years));
        $seniority_rank = max(
            (int) ($config['seniority_scale'][$seniority] ?? 2),
            (int) ($config['seniority_scale'][$experience_seniority] ?? 2)
        );
        $effective_seniority = array_search($seniority_rank, $config['seniority_scale'], true);
        if (!is_string($effective_seniority) || $effective_seniority === '') {
            $effective_seniority = $seniority;
        }

        $family_scores = [];
        $location_hits = $this->detect_locations_in_text($cv_lower, $config);
        $language_hits = $this->detect_alias_hits_in_text($cv_lower, $config['languages']);
        $qualification_hits = $this->detect_alias_hits_in_text($cv_lower, $config['qualifications']);
        $title_tokens = $this->tokenize_advanced_match_text($current_title, $config['generic_title_tokens']);
        $evidence_index = $this->build_advanced_cv_evidence_map($cv_text, $config);
        $evidence_hits = [];
        foreach ((array) ($evidence_index['items'] ?? []) as $phrase => $evidence) {
            $evidence_hits[$phrase] = (int) ($evidence['count'] ?? 1);
        }

        $leadership_score = 0.30;
        foreach (['led ', 'managed ', 'supervised ', 'head of', 'built ', 'created ', 'launched ', 'owned '] as $leadership_signal) {
            if (strpos($cv_lower, $leadership_signal) !== false) {
                $leadership_score += 0.08;
            }
        }
        $leadership_score = min(1.0, $leadership_score);

        $trajectory_score = min(
            1.0,
            (
                0.34 * min(1.0, ($this->extract_experience_years($cv_text) / 10))
                + 0.10 * min(1.0, ($experience_years / 12))
                + 0.24 * min(1.0, count($qualification_hits) / 3)
                + 0.22 * $leadership_score
                + 0.20 * min(1.0, count($evidence_hits) / 20)
            )
        );

        $parse_quality = 0.35;
        if ($current_title !== '') {
            $parse_quality += 0.25;
        }
        if (!empty($title_tokens)) {
            $parse_quality += 0.15;
        }
        if (!empty($evidence_hits)) {
            $parse_quality += 0.15;
        }
        if (!empty($evidence_index['items'])) {
            $parse_quality += 0.10;
        }
        $parse_quality = min(1.0, $parse_quality);

        return [
            'raw_text' => $cv_text,
            'lower' => $cv_lower,
            'current_title' => $current_title,
            'title_tokens' => $title_tokens,
            'experience_years' => $experience_years,
            'seniority' => $seniority,
            'effective_seniority' => $effective_seniority,
            'role_family_scores' => $family_scores,
            'role_family' => 'other',
            'skill_hits' => $evidence_hits,
            'location_hits' => $location_hits,
            'language_hits' => $language_hits,
            'qualification_hits' => $qualification_hits,
            'domain_scores' => [],
            'dominant_domain' => '',
            'evidence_index' => $evidence_index,
            'trajectory_score' => $trajectory_score,
            'leadership_score' => $leadership_score,
            'parse_quality' => $parse_quality,
        ];
    }

    private function build_advanced_job_match_profile($post, $taxonomy)
    {
        $config = $this->get_advanced_match_config();
        $jd_text = $this->build_jd_text($post);
        $jd_lower = $this->normalize_advanced_match_text($jd_text);
        $title = (string) ($post['role_title'] ?? '');
        $title_tokens = $this->tokenize_advanced_match_text($title, $config['generic_title_tokens']);
        $seniority = (string) ($post['seniority'] ?? 'other');
        if ($seniority === '' || $seniority === 'other') {
            $seniority = $this->infer_seniority_from_post($post);
        }

        $family_scores = [];
        $requirements = $this->extract_job_requirement_items_advanced($post, $config);
        $skills = $this->extract_job_skill_requirements($post, $jd_lower, $config);
        $language_hits = $this->detect_alias_hits_in_text($jd_lower, $config['languages']);
        $qualification_hits = $this->detect_alias_hits_in_text($jd_lower, $config['qualifications']);
        $is_junior_role = false;
        foreach ((array) $config['junior_title_markers'] as $marker) {
            if (strpos($this->normalize_advanced_match_text($title), $marker) !== false) {
                $is_junior_role = true;
                break;
            }
        }

        foreach ($this->collect_list_terms($post['required_certifications'] ?? []) as $term) {
            $normalized = $this->normalize_required_skill_term($term, ['skills' => $config['qualifications']]);
            if ($normalized !== '') {
                $qualification_hits[$normalized] = ($qualification_hits[$normalized] ?? 0) + 1;
            }
        }

        $location_seed = implode(' ', array_filter([
            (string) ($post['location'] ?? ''),
            (string) ($post['country'] ?? ''),
            (string) ($post['city'] ?? ''),
            $jd_text,
        ]));
        $location_hits = $this->detect_locations_in_text($this->normalize_advanced_match_text($location_seed), $config);

        $required_phrases = [];
        $preferred_phrases = [];
        foreach ((array) $requirements as $requirement) {
            if (($requirement['type'] ?? '') !== 'phrase') {
                continue;
            }

            $value = (string) ($requirement['value'] ?? '');
            if ($value === '') {
                continue;
            }

            if (!empty($requirement['hard_gate']) || in_array(($requirement['importance'] ?? 'core'), ['must', 'required'], true)) {
                $required_phrases[$value] = true;
                continue;
            }

            if (($requirement['importance'] ?? 'core') !== 'nice') {
                $preferred_phrases[$value] = true;
            }
        }

        foreach ((array) $skills['required'] as $skill) {
            $required_phrases[(string) $skill] = true;
        }
        foreach ((array) $skills['preferred'] as $skill) {
            if (!isset($required_phrases[(string) $skill])) {
                $preferred_phrases[(string) $skill] = true;
            }
        }

        return [
            'title' => $title,
            'title_tokens' => $title_tokens,
            'lower' => $jd_lower,
            'seniority' => $seniority,
            'min_years' => (int) max(
                $this->detect_required_years_from_text($title . ' ' . ($post['content'] ?? '')),
                $this->map_seniority_to_years($seniority)
            ),
            'role_family_scores' => $family_scores,
            'role_family' => 'other',
            'domain_scores' => [],
            'dominant_domain' => '',
            'required_skills' => array_values(array_keys($required_phrases)),
            'preferred_skills' => array_values(array_keys($preferred_phrases)),
            'language_hits' => $language_hits,
            'qualification_hits' => $qualification_hits,
            'location_hits' => $location_hits,
            'location_label' => (string) ($post['location'] ?? ''),
            'remote' => (bool) preg_match('/remote|hybrid|work from home/i', $jd_text),
            'is_junior_role' => $is_junior_role,
            'requirements' => $requirements,
            'nationality_requirements' => (array) ($post['nationality_requirements'] ?? []),
        ];
    }

    private function get_role_family_similarity($cv_family, $job_family, $config)
    {
        if ($cv_family === '' || $job_family === '') {
            return 0.50;
        }
        if ($cv_family === $job_family) {
            return 1.0;
        }
        if (!empty($config['role_family_similarity'][$cv_family][$job_family])) {
            return (float) $config['role_family_similarity'][$cv_family][$job_family];
        }
        if (!empty($config['role_family_similarity'][$job_family][$cv_family])) {
            return (float) $config['role_family_similarity'][$job_family][$cv_family];
        }

        return 0.42;
    }

    private function calculate_advanced_title_fit($cv_profile, $job_profile, $config)
    {
        $cv_tokens = (array) ($cv_profile['title_tokens'] ?? []);
        $job_tokens = (array) ($job_profile['title_tokens'] ?? []);
        $overlap = array_values(array_intersect($cv_tokens, $job_tokens));
        $union = array_values(array_unique(array_merge($cv_tokens, $job_tokens)));
        $token_score = !empty($union) ? (count($overlap) / count($union)) : 0;

        $exact_title_boost = 0;
        $cv_title = $this->normalize_advanced_match_text($cv_profile['current_title'] ?? '');
        $job_title = $this->normalize_advanced_match_text($job_profile['title'] ?? '');
        if ($cv_title !== '' && $job_title !== '') {
            if ($cv_title === $job_title) {
                $exact_title_boost = 0.25;
            } elseif (strpos($cv_title, $job_title) !== false || strpos($job_title, $cv_title) !== false) {
                $exact_title_boost = 0.12;
            }
        }

        $title_phrase_score = $this->calculate_phrase_similarity_advanced(
            $this->tokenize_for_advanced_matching($job_title, $config),
            $this->tokenize_for_advanced_matching($cv_title, $config)
        );

        $score = (0.58 * $title_phrase_score) + (0.30 * $token_score) + $exact_title_boost;

        $candidate_rank = (int) ($config['seniority_scale'][$cv_profile['effective_seniority'] ?? ($cv_profile['seniority'] ?? 'unknown')] ?? 2);
        if (!empty($job_profile['is_junior_role']) && $candidate_rank >= 3 && (float) ($cv_profile['experience_years'] ?? 0) >= 5) {
            $score *= 0.18;
        }

        return min(1.0, max(0.0, $score));
    }

    private function calculate_advanced_seniority_fit($cv_profile, $job_profile, $config)
    {
        $scale = $config['seniority_scale'];
        $cv_level = (int) ($scale[$cv_profile['effective_seniority'] ?? ($cv_profile['seniority'] ?? 'unknown')] ?? 2);
        $job_level = (int) ($scale[$job_profile['seniority'] ?? 'unknown'] ?? 2);
        $distance = abs($job_level - $cv_level);
        $score = exp(-0.45 * ($distance ** 2));

        if ($cv_level < $job_level && ($job_level - $cv_level) >= 2) {
            $score *= 0.55;
        }
        if (!empty($job_profile['is_junior_role']) && $cv_level >= 3) {
            $score *= 0.10;
        }

        return min(1.0, max(0.0, $score));
    }

    private function calculate_advanced_experience_fit($cv_profile, $job_profile)
    {
        $cv_years = (float) ($cv_profile['experience_years'] ?? 0);
        $required_years = (float) ($job_profile['min_years'] ?? 0);

        if ($required_years <= 0) {
            return min(1.0, 0.58 + min(0.35, $cv_years / 18));
        }

        $gap = $cv_years - $required_years;
        if ($gap >= 0) {
            return min(1.0, 0.84 + min(0.14, log(1 + $gap) * 0.08));
        }

        return max(0.0, exp(-0.55 * (abs($gap) ** 1.15)));
    }

    private function calculate_advanced_skill_fit($cv_profile, $job_profile)
    {
        $cv_skills = (array) ($cv_profile['skill_hits'] ?? []);
        $required = array_values(array_unique(array_filter((array) ($job_profile['required_skills'] ?? []))));
        $preferred = array_values(array_unique(array_filter((array) ($job_profile['preferred_skills'] ?? []))));
        $matched = [];
        $missing_required = [];
        $missing_preferred = [];
        $weighted_total = 0.0;
        $weighted_score = 0.0;

        foreach ($required as $skill) {
            $weighted_total += 1.0;
            $skill_strength = 0.0;
            if (!empty($cv_skills[$skill])) {
                $skill_strength = min(1.0, 0.72 + (log(1 + (int) $cv_skills[$skill]) * 0.12));
                $matched[] = $skill;
            } else {
                $missing_required[] = $skill;
            }
            $weighted_score += $skill_strength * 1.0;
        }

        foreach ($preferred as $skill) {
            $weighted_total += 0.45;
            $skill_strength = 0.0;
            if (!empty($cv_skills[$skill])) {
                $skill_strength = min(1.0, 0.65 + (log(1 + (int) $cv_skills[$skill]) * 0.10));
                if (!in_array($skill, $matched, true)) {
                    $matched[] = $skill;
                }
            } else {
                $missing_preferred[] = $skill;
            }
            $weighted_score += $skill_strength * 0.45;
        }

        $score = $weighted_total > 0 ? ($weighted_score / $weighted_total) : 0.55;

        return [
            'score' => min(1.0, max(0.0, $score)),
            'matched' => array_values(array_unique($matched)),
            'missing_required' => array_values(array_unique($missing_required)),
            'missing_preferred' => array_values(array_unique($missing_preferred)),
        ];
    }

    private function calculate_advanced_domain_fit($cv_profile, $job_profile, $config)
    {
        return $this->calculate_requirement_document_alignment_advanced($cv_profile, $job_profile, $config);
    }

    private function calculate_advanced_location_fit($cv_profile, $job_profile, $config)
    {
        $job_locations = array_keys((array) ($job_profile['location_hits'] ?? []));
        $cv_locations = array_keys((array) ($cv_profile['location_hits'] ?? []));

        if ($job_profile['remote'] ?? false) {
            return 0.94;
        }

        if (empty($job_locations)) {
            return 0.72;
        }

        if (!empty(array_intersect($job_locations, $cv_locations))) {
            return 1.0;
        }

        foreach ($job_locations as $job_location) {
            $job_regions = (array) ($config['location_regions'][$job_location] ?? []);
            foreach ($cv_locations as $cv_location) {
                $cv_regions = (array) ($config['location_regions'][$cv_location] ?? []);
                if (!empty(array_intersect($job_regions, $cv_regions))) {
                    return 0.86;
                }
            }
        }

        return empty($cv_locations) ? 0.60 : 0.42;
    }

    private function calculate_advanced_qualification_fit($cv_profile, $job_profile)
    {
        $required = array_keys((array) ($job_profile['qualification_hits'] ?? []));
        if (empty($required)) {
            return ['score' => 0.82, 'missing' => []];
        }

        $cv_qualifications = array_keys((array) ($cv_profile['qualification_hits'] ?? []));
        $missing = array_values(array_diff($required, $cv_qualifications));
        $matched = count($required) - count($missing);
        $score = count($required) > 0 ? ($matched / count($required)) : 0.82;

        return ['score' => min(1.0, max(0.0, $score)), 'missing' => $missing];
    }

    private function calculate_advanced_language_fit($cv_profile, $job_profile)
    {
        $required = array_keys((array) ($job_profile['language_hits'] ?? []));
        if (empty($required)) {
            return ['score' => 0.82, 'missing' => []];
        }

        $cv_languages = array_keys((array) ($cv_profile['language_hits'] ?? []));
        $missing = array_values(array_diff($required, $cv_languages));
        $matched = count($required) - count($missing);
        $score = count($required) > 0 ? ($matched / count($required)) : 0.82;

        return ['score' => min(1.0, max(0.0, $score)), 'missing' => $missing];
    }

    private function calculate_advanced_transition_fit($cv_profile, $job_profile, $config)
    {
        $trajectory = (float) ($cv_profile['trajectory_score'] ?? 0.5);
        $title_fit = $this->calculate_advanced_title_fit($cv_profile, $job_profile, $config);

        return min(1.0, max(0.0, (0.62 * $title_fit) + (0.38 * $trajectory)));
    }

    private function calculate_advanced_hard_gate_multiplier($job_profile, $skill_result, $qualification_result, $language_result, $experience_fit, $location_fit)
    {
        $config = $this->get_advanced_match_config();
        $multiplier = 1.0;
        $failures = [];

        if (!empty($language_result['missing'])) {
            $multiplier *= (float) $config['hard_gate_penalties']['language'];
            $failures[] = [
                'type' => 'language',
                'items' => $language_result['missing'],
                'multiplier' => (float) $config['hard_gate_penalties']['language'],
            ];
        }

        if (!empty($qualification_result['missing'])) {
            $multiplier *= (float) $config['hard_gate_penalties']['qualification'];
            $failures[] = [
                'type' => 'qualification',
                'items' => $qualification_result['missing'],
                'multiplier' => (float) $config['hard_gate_penalties']['qualification'],
            ];
        }

        if (!empty($skill_result['missing_required']) && count((array) ($job_profile['required_skills'] ?? [])) >= 2) {
            $multiplier *= (float) $config['hard_gate_penalties']['technical_must_have'];
            $failures[] = [
                'type' => 'technical_must_have',
                'items' => array_slice($skill_result['missing_required'], 0, 4),
                'multiplier' => (float) $config['hard_gate_penalties']['technical_must_have'],
            ];
        }

        if ($experience_fit < 0.42 && !empty($job_profile['min_years'])) {
            $multiplier *= (float) $config['hard_gate_penalties']['minimum_experience'];
            $failures[] = [
                'type' => 'minimum_experience',
                'items' => [(string) $job_profile['min_years'] . '+ years'],
                'multiplier' => (float) $config['hard_gate_penalties']['minimum_experience'],
            ];
        }

        if (($job_profile['remote'] ?? false) === false && $location_fit < 0.45 && !empty($job_profile['location_hits'])) {
            $multiplier *= (float) $config['hard_gate_penalties']['location'];
            $failures[] = [
                'type' => 'location',
                'items' => array_keys((array) $job_profile['location_hits']),
                'multiplier' => (float) $config['hard_gate_penalties']['location'],
            ];
        }

        $candidate_seniority_rank = (int) ($config['seniority_scale'][$job_profile['candidate_effective_seniority'] ?? 'unknown'] ?? 2);
        if (!empty($job_profile['is_junior_role']) && $candidate_seniority_rank >= 3 && !empty($job_profile['candidate_years']) && $job_profile['candidate_years'] >= 5) {
            $multiplier *= 0.08;
            $failures[] = [
                'type' => 'overqualification',
                'items' => ['junior role mismatch'],
                'multiplier' => 0.08,
            ];
        }

        return [$multiplier, $failures];
    }

    private function calculate_advanced_match_result($cv_profile, $job_profile)
    {
        $config = $this->get_advanced_match_config();
        $weights = $config['weights'];

        $title_fit = $this->calculate_advanced_title_fit($cv_profile, $job_profile, $config);
        $seniority_fit = $this->calculate_advanced_seniority_fit($cv_profile, $job_profile, $config);
        $experience_fit = $this->calculate_advanced_experience_fit($cv_profile, $job_profile);
        $requirement_result = $this->calculate_advanced_requirement_fit($cv_profile, $job_profile, $config);
        $skill_result = [
            'score' => $requirement_result['score'],
            'matched' => $requirement_result['matched'],
            'missing_required' => $requirement_result['missing_required'],
            'missing_preferred' => [],
        ];
        $domain_fit = $this->calculate_advanced_domain_fit($cv_profile, $job_profile, $config);
        $location_fit = $this->calculate_advanced_location_fit($cv_profile, $job_profile, $config);
        $qualification_result = $this->calculate_advanced_qualification_fit($cv_profile, $job_profile);
        $language_result = $this->calculate_advanced_language_fit($cv_profile, $job_profile);
        $transition_fit = min(1.0, max(0.0, (0.5 * $title_fit) + (0.5 * $domain_fit)));
        $trajectory_fit = min(1.0, max(0.0, (float) ($cv_profile['trajectory_score'] ?? 0.5)));

        $subscores = [
            'title_fit' => round($title_fit * 100),
            'skill_fit' => round($skill_result['score'] * 100),
            'experience_fit' => round($experience_fit * 100),
            'seniority_fit' => round($seniority_fit * 100),
            'domain_fit' => round($domain_fit * 100),
            'location_fit' => round($location_fit * 100),
            'qualification_fit' => round($qualification_result['score'] * 100),
            'language_fit' => round($language_result['score'] * 100),
            'trajectory_fit' => round($trajectory_fit * 100),
            'transition_fit' => round($transition_fit * 100),
        ];

        $base_score = 0.0;
        foreach ($weights as $key => $weight) {
            $metric_key = $key;
            if ($metric_key === 'skill_fit') {
                $metric_value = $skill_result['score'];
            } elseif ($metric_key === 'qualification_fit') {
                $metric_value = $qualification_result['score'];
            } elseif ($metric_key === 'language_fit') {
                $metric_value = $language_result['score'];
            } else {
                $metric_name = str_replace('_fit', '_fit', $metric_key);
                $metric_value = ${$metric_name} ?? 0;
            }
            $base_score += ((float) $metric_value * (float) $weight);
        }

        [$hard_gate_multiplier, $hard_gate_failures] = $this->calculate_advanced_hard_gate_multiplier(
            array_merge($job_profile, [
                'candidate_effective_seniority' => $cv_profile['effective_seniority'] ?? ($cv_profile['seniority'] ?? 'unknown'),
                'candidate_years' => (float) ($cv_profile['experience_years'] ?? 0),
            ]),
            $skill_result,
            $qualification_result,
            $language_result,
            $experience_fit,
            $location_fit
        );

        $soft_penalty = 0.0;
        if ($title_fit < 0.35 && $requirement_result['coverage'] < 0.40) {
            $soft_penalty += 0.12;
        }

        if (!empty($requirement_result['missing_required']) && count($requirement_result['missing_required']) >= 4) {
            $soft_penalty += 0.08;
        }

        $cv_seniority = (int) ($config['seniority_scale'][$cv_profile['seniority'] ?? 'unknown'] ?? 2);
        $job_seniority = (int) ($config['seniority_scale'][$job_profile['seniority'] ?? 'unknown'] ?? 2);
        if (($cv_seniority - $job_seniority) >= 2) {
            $soft_penalty += 0.08;
        }

        if (!empty($job_profile['nationality_requirements'])) {
            $soft_penalty += 0.04;
        }

        $final_score = max(0.0, min(1.0, ($base_score * $hard_gate_multiplier) - $soft_penalty));

        $evidence_volume = min(1.0, count((array) ($cv_profile['evidence_index']['blocks'] ?? [])) / 22);
        $coverage = 0.0;
        $coverage_components = [
            $requirement_result['score'],
            $title_fit,
            $requirement_result['coverage'],
            $experience_fit,
            $qualification_result['score'],
            $language_result['score'],
        ];
        if (!empty($coverage_components)) {
            $coverage = array_sum($coverage_components) / count($coverage_components);
        }
        $confidence = min(
            1.0,
            max(
                0.0,
                (0.40 * (float) ($cv_profile['parse_quality'] ?? 0.5))
                + (0.35 * $coverage)
                + (0.25 * $evidence_volume)
            )
        );

        return [
            'final_score' => (int) round($final_score * 100),
            'base_score' => (int) round($base_score * 100),
            'confidence' => (int) round($confidence * 100),
            'subscores' => $subscores,
            'matched_skills' => $skill_result['matched'],
            'missing_required_skills' => $skill_result['missing_required'],
            'missing_preferred_skills' => $skill_result['missing_preferred'],
            'missing_qualifications' => $qualification_result['missing'],
            'missing_languages' => $language_result['missing'],
            'requirement_breakdown' => $requirement_result['breakdown'],
            'hard_gate_failures' => $hard_gate_failures,
            'hard_gate_multiplier' => round($hard_gate_multiplier, 2),
            'soft_penalty' => round($soft_penalty * 100),
        ];
    }

    private function format_advanced_label($key)
    {
        $map = [
            'fpna' => 'FP&A',
            'lbo' => 'LBO',
            'lp_reporting' => 'LP Reporting',
            'fund_accounting' => 'Fund Accounting',
            'financial_modeling' => 'Financial Modelling',
            'financial_control' => 'Financial Control',
            'risk_management' => 'Risk Management',
            'investment_memo' => 'Investment Memos',
            'deal_execution' => 'Deal Execution',
            'asset_management' => 'Asset Management',
            'private_equity' => 'Private Equity',
            'venture_capital' => 'Venture Capital',
            'investment_banking' => 'Investment Banking',
            'investor_relations' => 'Investor Relations',
            'powerbi' => 'Power BI',
            'qlik' => 'Qlik',
            'sql' => 'SQL',
            'vba' => 'VBA',
            'cfa' => 'CFA',
            'acca' => 'ACCA',
            'aca' => 'ACA',
            'cpa' => 'CPA',
            'frm' => 'FRM',
            'imc' => 'IMC',
            'md' => 'MD',
            'vp' => 'VP',
            'c_level' => 'C-Level',
        ];

        return $map[$key] ?? ucwords(str_replace('_', ' ', (string) $key));
    }

    private function build_advanced_match_reasons($cv_profile, $job_profile, $match_result)
    {
        $reasons = [];

        if (!empty($match_result['matched_skills'])) {
            $labels = array_map([$this, 'format_advanced_label'], array_slice((array) $match_result['matched_skills'], 0, 3));
            $reasons[] = sprintf(__('Strong overlap in %s', 'senna-finance'), implode(', ', $labels));
        }

        if (($match_result['subscores']['experience_fit'] ?? 0) >= 75 && !empty($job_profile['min_years'])) {
            $reasons[] = sprintf(
                __('Experience level aligns with the %d+ year requirement', 'senna-finance'),
                (int) $job_profile['min_years']
            );
        }

        if (($match_result['subscores']['title_fit'] ?? 0) >= 72) {
            $reasons[] = __('Current title and target role are closely aligned', 'senna-finance');
        }

        if (($match_result['subscores']['domain_fit'] ?? 0) >= 68) {
            $reasons[] = __('Your CV covers a large share of the role requirements', 'senna-finance');
        }

        if (($match_result['subscores']['location_fit'] ?? 0) >= 86 && !empty($job_profile['location_label'])) {
            $reasons[] = sprintf(__('Location fit is strong for %s', 'senna-finance'), $job_profile['location_label']);
        }

        return array_slice(array_values(array_unique(array_filter($reasons))), 0, 4);
    }

    private function build_advanced_match_warnings($cv_profile, $job_profile, $match_result)
    {
        $warnings = [];

        if (!empty($match_result['missing_required_skills'])) {
            $labels = array_map([$this, 'format_advanced_label'], array_slice((array) $match_result['missing_required_skills'], 0, 2));
            $warnings[] = sprintf(__('Missing core signals: %s', 'senna-finance'), implode(', ', $labels));
        }

        if (!empty($match_result['missing_qualifications'])) {
            $labels = array_map([$this, 'format_advanced_label'], array_slice((array) $match_result['missing_qualifications'], 0, 2));
            $warnings[] = sprintf(__('Qualification gap: %s', 'senna-finance'), implode(', ', $labels));
        }

        if (!empty($match_result['missing_languages'])) {
            $labels = array_map([$this, 'format_advanced_label'], array_slice((array) $match_result['missing_languages'], 0, 2));
            $warnings[] = sprintf(__('Language gap: %s', 'senna-finance'), implode(', ', $labels));
        }

        if (($match_result['subscores']['experience_fit'] ?? 0) < 45 && !empty($job_profile['min_years'])) {
            $warnings[] = sprintf(__('Experience looks light against the %d+ year expectation', 'senna-finance'), (int) $job_profile['min_years']);
        }

        return array_slice(array_values(array_unique(array_filter($warnings))), 0, 3);
    }

    private function build_advanced_match_gaps($cv_profile, $job_profile, $match_result, $post)
    {
        $gaps = [];

        foreach ((array) ($match_result['missing_required_skills'] ?? []) as $skill) {
            $gaps[] = [
                'type' => 'required_skill_gap',
                'item' => $this->format_advanced_label($skill),
                'severity' => 'high',
                'is_dealbreaker' => false,
                'score_impact' => 0,
                'recommendation' => sprintf(__('Show stronger evidence of %s in your CV before applying.', 'senna-finance'), $this->format_advanced_label($skill)),
            ];
        }

        foreach ((array) ($match_result['missing_qualifications'] ?? []) as $qualification) {
            $gaps[] = [
                'type' => 'qualification_gap',
                'item' => $this->format_advanced_label($qualification),
                'severity' => 'high',
                'is_dealbreaker' => true,
                'score_impact' => 0,
                'recommendation' => sprintf(__('This role appears to require %s. Verify whether an equivalent credential is acceptable.', 'senna-finance'), $this->format_advanced_label($qualification)),
            ];
        }

        foreach ((array) ($match_result['missing_languages'] ?? []) as $language) {
            $gaps[] = [
                'type' => 'language_gap',
                'item' => $this->format_advanced_label($language),
                'severity' => 'high',
                'is_dealbreaker' => true,
                'score_impact' => 0,
                'recommendation' => sprintf(__('This role signals %s as a requirement.', 'senna-finance'), $this->format_advanced_label($language)),
            ];
        }

        if (!empty($job_profile['nationality_requirements'])) {
            foreach ((array) $job_profile['nationality_requirements'] as $requirement) {
                $gaps[] = [
                    'type' => 'nationality_requirement',
                    'item' => $requirement['display_name'] ?? ucwords(str_replace('_', ' ', (string) ($requirement['nationality'] ?? ''))),
                    'severity' => 'critical',
                    'is_dealbreaker' => true,
                    'score_impact' => 0,
                    'recommendation' => __('Check work authorization and nationality eligibility before applying.', 'senna-finance'),
                ];
            }
        }

        return array_slice($gaps, 0, 5);
    }

    /**
     * Calculate match score between CV and job post - Enhanced version
     *
     * @param array $cv_parsed Pre-parsed CV data (raw_text, lower, experience_years, etc.)
     * @param array $post Job post data
     * @param array $taxonomy Pre-loaded keyword taxonomy
     * @return int Match score 0-100
     */
    private function calculate_match_score($cv_parsed, $post, $taxonomy)
    {
        $job_profile = $this->build_simple_job_match_profile($post);

        $title_score = $this->calculate_simple_title_fit($cv_parsed, $job_profile);
        $seniority_score = $this->calculate_simple_seniority_fit($cv_parsed, $job_profile);
        $experience_score = $this->calculate_simple_experience_fit($cv_parsed, $job_profile);
        $keyword_score = $this->calculate_simple_keyword_overlap_score($cv_parsed, $job_profile);
        $location_score = $this->calculate_simple_location_fit($cv_parsed, $job_profile);
        $qualification_score = $this->calculate_simple_qualification_fit($cv_parsed, $job_profile);
        $language_score = $this->calculate_simple_language_fit($cv_parsed, $job_profile);

        $weights = [
            'title' => 0.22,
            'seniority' => 0.20,
            'experience' => 0.22,
            'keyword' => 0.24,
            'location' => 0.05,
            'qualification' => 0.04,
            'language' => 0.03,
        ];

        $has_location_signal = !empty($cv_parsed['location_hits']) && !empty($job_profile['location_hits']);
        if (!$has_location_signal) {
            $weights['location'] = 0.0;
            $weights['title'] += 0.02;
            $weights['seniority'] += 0.01;
            $weights['experience'] += 0.02;
            $location_score = 70;
        }

        $score = 0.0;
        $score += $title_score * $weights['title'];
        $score += $seniority_score * $weights['seniority'];
        $score += $experience_score * $weights['experience'];
        $score += $keyword_score * $weights['keyword'];
        $score += $location_score * $weights['location'];
        $score += $qualification_score * $weights['qualification'];
        $score += $language_score * $weights['language'];

        if ($has_location_signal) {
            if ($location_score >= 100) {
                $score += 6.0;
            } elseif ($location_score >= 92) {
                $score += 3.0;
            } elseif ($location_score >= 84) {
                $score += 1.5;
            }
        }

        if ($title_score < 20 && $keyword_score < 25) {
            $score *= 0.55;
        }

        if ($seniority_score <= 10 || $experience_score <= 10) {
            $score *= 0.40;
        }

        if (!empty($job_profile['is_internship']) && ((float) ($cv_parsed['experience_years'] ?? 0) >= 4 || $this->get_simple_seniority_rank((string) ($cv_parsed['effective_seniority'] ?? 'associate')) >= 3)) {
            $score *= 0.10;
        }

        return min(100, max(0, (int) round($score)));
    }

    /**
     * Load keyword taxonomy from JSON
     */
    private function load_keyword_taxonomy()
    {
        $taxonomy_file = dirname(dirname(__FILE__)) . '/data/financial-services-keywords.json';
        if (file_exists($taxonomy_file)) {
            $json = file_get_contents($taxonomy_file);
            return json_decode($json, true);
        }
        return [];
    }

    /**
     * Build JD text from post data
     */
    private function build_jd_text($post)
    {
        $jd_text = '';
        $jd_text .= ($post['role_title'] ?? '') . ' ';
        $jd_text .= ($post['content'] ?? '') . ' ';
        $jd_text .= ($post['sector'] ?? '') . ' ';
        $jd_text .= ($post['industry'] ?? '') . ' ';
        $jd_text .= ($post['seniority'] ?? '') . ' ';

        if (!empty($post['requirements'])) {
            $requirements = is_string($post['requirements']) ? json_decode($post['requirements'], true) : $post['requirements'];
            if (is_array($requirements)) {
                $jd_text .= implode(' ', $requirements) . ' ';
            }
        }

        if (!empty($post['skills_mentioned'])) {
            $skills = is_string($post['skills_mentioned']) ? json_decode($post['skills_mentioned'], true) : $post['skills_mentioned'];
            if (is_array($skills)) {
                $jd_text .= implode(' ', $skills) . ' ';
            }
        }

        if (!empty($post['keywords'])) {
            $keyword_terms = $this->collect_list_terms($post['keywords']);
            if (!empty($keyword_terms)) {
                $jd_text .= implode(' ', $keyword_terms) . ' ';
            } elseif (is_string($post['keywords'])) {
                $jd_text .= $post['keywords'] . ' ';
            }
        }

        return $jd_text;
    }

    private function fast_match_prefilter($cv_parsed, $post)
    {
        $cv_lower = $cv_parsed['lower'];
        $cv_keywords = (array) ($cv_parsed['keyword_counts'] ?? []);
        $signal_hits = 0;

        $primary_signals = [
            $post['role_title'] ?? '',
            $post['sector'] ?? '',
            $post['industry'] ?? '',
        ];

        foreach ($primary_signals as $signal) {
            $signal = strtolower(trim((string) $signal));
            if ($signal !== '' && strpos($cv_lower, $signal) !== false) {
                $signal_hits += 2;
            }
        }

        foreach ($this->tokenize_simple_match_text(implode(' ', $primary_signals)) as $token) {
            if (!empty($cv_keywords[$token])) {
                $signal_hits++;
            }
        }

        $lists = [];

        if (!empty($post['skills_mentioned'])) {
            $lists[] = is_string($post['skills_mentioned']) ? (json_decode($post['skills_mentioned'], true) ?: []) : $post['skills_mentioned'];
        }

        if (!empty($post['keywords'])) {
            $decoded_keywords = $this->collect_list_terms($post['keywords']);
            if (!empty($decoded_keywords)) {
                $lists[] = $decoded_keywords;
            } elseif (is_string($post['keywords'])) {
                $lists[] = preg_split('/[\s,]+/', strtolower($post['keywords']));
            }
        }

        foreach ($lists as $signals) {
            foreach ((array) $signals as $signal) {
                $signal = strtolower(trim((string) $signal));
                if ($signal === '' || strlen($signal) < 3) {
                    continue;
                }

                if (strpos($cv_lower, $signal) !== false) {
                    $signal_hits++;
                }

                if ($signal_hits >= 2) {
                    return true;
                }
            }
        }

        return $signal_hits >= 2;
    }

    private function get_simple_match_stopwords()
    {
        static $stopwords = null;
        if ($stopwords !== null) {
            return $stopwords;
        }

        $base = function_exists('wp_search_stopwords') ? (array) wp_search_stopwords() : [];
        $fallback = [
            'role', 'roles', 'team', 'teams', 'work', 'worked', 'working', 'experience',
            'experienced', 'skills', 'skill', 'knowledge', 'business', 'professional',
            'professionals', 'using', 'used', 'within', 'across', 'strong', 'proven',
            'responsible', 'responsibilities', 'candidate', 'candidates', 'year', 'years',
            'including', 'required', 'preferred', 'minimum', 'must', 'need', 'needs',
            'opportunity', 'company', 'position', 'ability', 'support', 'relevant'
        ];

        $stopwords = array_values(array_unique(array_merge($base, $fallback)));
        return $stopwords;
    }

    private function tokenize_simple_match_text($text)
    {
        $text = strtolower(wp_strip_all_tags((string) $text));
        $text = html_entity_decode($text, ENT_QUOTES, 'UTF-8');
        $text = str_replace(['&', '/', '\\'], ' ', $text);
        $text = preg_replace('/[^a-z0-9\+\#\.\-\s]/', ' ', $text);
        $text = preg_replace('/\s+/', ' ', $text);
        $tokens = preg_split('/\s+/', trim((string) $text)) ?: [];
        $stopwords = array_fill_keys($this->get_simple_match_stopwords(), true);
        $normalized = [];

        foreach ($tokens as $token) {
            $token = trim((string) $token);
            if ($token === '') {
                continue;
            }
            if (isset($stopwords[$token])) {
                continue;
            }
            if (strlen($token) < 2) {
                continue;
            }
            if (strlen($token) > 4) {
                if (substr($token, -3) === 'ing') {
                    $token = substr($token, 0, -3);
                } elseif (substr($token, -2) === 'ed') {
                    $token = substr($token, 0, -2);
                } elseif (substr($token, -1) === 's') {
                    $token = substr($token, 0, -1);
                }
            }
            $normalized[] = $token;
        }

        return array_values(array_filter($normalized));
    }

    private function build_simple_keyword_counts($text, $weighted_text = '')
    {
        $counts = [];
        $source = trim($weighted_text . ' ' . $text);
        foreach ($this->tokenize_simple_match_text($source) as $token) {
            $counts[$token] = (int) ($counts[$token] ?? 0) + 1;
        }
        arsort($counts);
        return $counts;
    }

    private function extract_cv_role_entries_simple($cv_text)
    {
        $lines = preg_split('/[\r\n]+/', (string) $cv_text) ?: [];
        $cleaned = [];
        foreach ($lines as $line) {
            $line = trim(preg_replace('/\s+/', ' ', (string) $line));
            if ($line !== '') {
                $cleaned[] = $line;
            }
        }

        $entries = [];
        foreach ($cleaned as $index => $line) {
            $months = $this->detect_month_span_from_line_simple($line);
            if ($months === null) {
                continue;
            }

            $title = trim((string) preg_replace('/(?:\d{2}\/\d{2}\/\d{2,4}|(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+\d{4}|\d{4})\s*[-–—to]+\s*(?:\d{2}\/\d{2}\/\d{2,4}|(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+\d{4}|\d{4}|present|current)/i', '', $line));
            $title = trim($title, " \t\n\r\0\x0B-–—(),");

            if ($title === '' || preg_match('/\d{4}/', $title)) {
                $title = $cleaned[$index - 1] ?? '';
            }

            if ($title === '' || preg_match('/^(education|experience|work experience|employment|professional experience|additional information)$/i', $title)) {
                continue;
            }

            $entries[] = [
                'title' => $title,
                'months' => $months,
                'is_internship' => (bool) preg_match('/intern|internship|summer|trainee|graduate/i', $title),
            ];
        }

        return $entries;
    }

    private function detect_month_span_from_line_simple($line)
    {
        $line = trim((string) $line);
        if ($line === '') {
            return null;
        }

        $current_year = (int) gmdate('Y');
        $current_month = (int) gmdate('n');
        $month_map = [
            'jan' => 1, 'feb' => 2, 'mar' => 3, 'apr' => 4, 'may' => 5, 'jun' => 6,
            'jul' => 7, 'aug' => 8, 'sep' => 9, 'oct' => 10, 'nov' => 11, 'dec' => 12,
        ];

        if (preg_match('/(\d{2})\/(\d{2})\/(\d{2,4})\s*[-–—to]+\s*(?:(\d{2})\/(\d{2})\/(\d{2,4})|present|current)/i', $line, $match)) {
            $start_month = (int) $match[2];
            $start_year = $this->normalize_simple_year_token($match[3]);
            if (preg_match('/present|current/i', $line)) {
                return max(1, (($current_year - $start_year) * 12) + ($current_month - $start_month));
            }
            $end_month = (int) $match[5];
            $end_year = $this->normalize_simple_year_token($match[6]);
            return max(1, (($end_year - $start_year) * 12) + ($end_month - $start_month));
        }

        if (preg_match('/(\d{1,2})[\/\-](\d{2,4})\s*[-–—to]+\s*(?:(\d{1,2})[\/\-](\d{2,4})|present|current)/i', $line, $match)) {
            $start_month = (int) $match[1];
            $start_year = $this->normalize_simple_year_token($match[2]);
            if (preg_match('/present|current/i', $line)) {
                return max(1, (($current_year - $start_year) * 12) + ($current_month - $start_month));
            }
            $end_month = (int) $match[3];
            $end_year = $this->normalize_simple_year_token($match[4]);
            return max(1, (($end_year - $start_year) * 12) + ($end_month - $start_month));
        }

        if (preg_match('/(jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\s*[\'’]?\s*(\d{2,4})\s*[-–—to]+\s*(?:(jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\s*[\'’]?\s*(\d{2,4})|present|current)/i', $line, $match)) {
            $start_month = $this->normalize_simple_month_token($match[1], $month_map);
            $start_year = $this->normalize_simple_year_token($match[2]);
            if (preg_match('/present|current/i', $line)) {
                return max(1, (($current_year - $start_year) * 12) + ($current_month - $start_month));
            }
            $end_month = $this->normalize_simple_month_token($match[3], $month_map);
            $end_year = $this->normalize_simple_year_token($match[4]);
            return max(1, (($end_year - $start_year) * 12) + ($end_month - $start_month));
        }

        if (preg_match('/(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+(\d{4})\s*[-–—to]+\s*(?:(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+(\d{4})|present|current)/i', $line, $match)) {
            $start_month = (int) ($month_map[strtolower(substr($match[1], 0, 3))] ?? 1);
            $start_year = (int) $match[2];
            if (preg_match('/present|current/i', $line)) {
                return max(1, (($current_year - $start_year) * 12) + ($current_month - $start_month));
            }
            $end_month = (int) ($month_map[strtolower(substr($match[3], 0, 3))] ?? 12);
            $end_year = (int) $match[4];
            return max(1, (($end_year - $start_year) * 12) + ($end_month - $start_month));
        }

        if (preg_match('/(\d{4})\s*[-–—to]+\s*(\d{4}|present|current)/i', $line, $match)) {
            $start_year = (int) $match[1];
            if (preg_match('/present|current/i', $match[2])) {
                return max(1, (($current_year - $start_year) * 12) + ($current_month - 1));
            }
            $end_year = (int) $match[2];
            return max(1, ($end_year - $start_year) * 12);
        }

        return null;
    }

    private function normalize_simple_year_token($year_token)
    {
        $year = (int) $year_token;
        if ($year < 100) {
            return $year >= 70 ? 1900 + $year : 2000 + $year;
        }
        return $year;
    }

    private function normalize_simple_month_token($month_token, $month_map = [])
    {
        $month_token = strtolower(substr((string) $month_token, 0, 3));
        return (int) ($month_map[$month_token] ?? 1);
    }

    private function get_simple_seniority_rank($seniority)
    {
        $map = [
            'intern' => 0,
            'analyst' => 1,
            'associate' => 2,
            'vp' => 3,
            'director' => 4,
            'md' => 5,
            'partner' => 5,
            'c_level' => 6,
        ];

        return (float) ($map[$seniority] ?? 2);
    }

    private function get_simple_seniority_label_from_rank($rank)
    {
        $rank = max(0, min(6, (float) $rank));
        if ($rank <= 0.75) {
            return 'intern';
        }
        if ($rank <= 1.6) {
            return 'analyst';
        }
        if ($rank <= 2.6) {
            return 'associate';
        }
        if ($rank <= 3.6) {
            return 'vp';
        }
        if ($rank <= 4.6) {
            return 'director';
        }
        if ($rank <= 5.6) {
            return 'md';
        }

        return 'c_level';
    }

    private function infer_simple_cv_seniority_from_entries($entries, $experience_years)
    {
        if (empty($entries)) {
            return $this->map_years_to_seniority((int) floor((float) $experience_years));
        }

        $recent_titles = array_slice(array_values((array) $entries), 0, 3);
        $recent_intern_titles = 0;
        $recent_analyst_titles = 0;

        foreach ($recent_titles as $entry) {
            $title = strtolower((string) ($entry['title'] ?? ''));
            if ($title === '') {
                continue;
            }
            if (!empty($entry['is_internship']) || preg_match('/intern|internship|off-?cycle|summer|spring|placement|trainee|graduate/i', $title)) {
                $recent_intern_titles++;
                continue;
            }
            if (preg_match('/analyst|research assistant|investment assistant|coordinator|junior/i', $title)) {
                $recent_analyst_titles++;
            }
        }

        if ($recent_intern_titles >= 2 && (float) $experience_years <= 1.5) {
            return 'intern';
        }

        if (($recent_intern_titles + $recent_analyst_titles) >= 2 && (float) $experience_years <= 3.0) {
            return $recent_analyst_titles > 0 ? 'analyst' : 'intern';
        }

        $weighted_rank_total = 0.0;
        $weight_total = 0.0;
        $recent_rank = 0;
        $recent_count = 0;

        foreach (array_values((array) $entries) as $index => $entry) {
            $title = (string) ($entry['title'] ?? '');
            $label = $this->classify_seniority_from_title($title);
            if ($label === 'unknown' || $label === '') {
                continue;
            }

            $rank = $this->get_simple_seniority_rank($label);
            $months = max(1, (int) ($entry['months'] ?? 1));
            $duration_weight = min(2.4, 0.45 + ($months / 18));
            $recency_weight = $index === 0 ? 2.0 : ($index === 1 ? 1.5 : ($index === 2 ? 1.15 : 0.9));

            if (!empty($entry['is_internship']) || preg_match('/intern|internship|off-?cycle|summer|spring|placement|trainee|graduate/i', $title)) {
                $duration_weight *= 0.60;
                $recency_weight *= 0.75;
            }

            $weight = $duration_weight * $recency_weight;
            $weighted_rank_total += $rank * $weight;
            $weight_total += $weight;

            if ($index <= 1) {
                $recent_rank = max($recent_rank, $rank);
                $recent_count++;
            }
        }

        if ($weight_total <= 0) {
            return $this->map_years_to_seniority((int) floor((float) $experience_years));
        }

        $weighted_rank = $weighted_rank_total / $weight_total;
        if ($recent_count > 0 && $recent_rank > 0) {
            $weighted_rank = max($weighted_rank, $recent_rank - 0.15);
        }

        $years_rank = $this->get_simple_seniority_rank($this->map_years_to_seniority((int) floor((float) $experience_years)));

        // Years confirm or lightly nudge, but they do not overpower the actual titled roles.
        if ($years_rank <= 1 && $weighted_rank <= 1.2) {
            $final_rank = min($weighted_rank, $years_rank + 0.20);
        } elseif ($years_rank <= 2 && $weighted_rank <= 2.2) {
            $final_rank = min($weighted_rank, $years_rank + 0.35);
        } elseif ($years_rank >= 5 && $weighted_rank <= 2.2) {
            $final_rank = min(3.0, $weighted_rank + 0.65);
        } elseif (abs($years_rank - $weighted_rank) <= 1) {
            $final_rank = max($weighted_rank, $years_rank - 0.1);
        } else {
            $final_rank = $weighted_rank;
        }

        return $this->get_simple_seniority_label_from_rank($final_rank);
    }

    private function build_simple_cv_match_profile($cv_text)
    {
        $lower = strtolower((string) $cv_text);
        $entries = $this->extract_cv_role_entries_simple($cv_text);
        $entry_current_title = (string) (($entries[0]['title'] ?? '') ?: '');
        $current_title = $entry_current_title !== '' ? $entry_current_title : $this->extract_current_role_title($cv_text);
        $title_seniority = $this->classify_seniority_from_title($current_title);
        $experience_years = (float) $this->extract_experience_years($cv_text);
        $year_seniority = $this->map_years_to_seniority((int) floor($experience_years));
        $entry_seniority = $this->infer_simple_cv_seniority_from_entries($entries, $experience_years);
        $effective_seniority = $entry_seniority !== 'unknown' ? $entry_seniority : ($title_seniority !== 'unknown' ? $title_seniority : $year_seniority);
        if ($effective_seniority === 'unknown' || $effective_seniority === '') {
            $effective_seniority = $this->infer_seniority_from_cv_text($cv_text);
        }

        $internship_count = 0;
        foreach ($entries as $entry) {
            if (!empty($entry['is_internship']) || (!empty($entry['title']) && preg_match('/intern|internship|off-?cycle|summer|spring|placement|trainee|graduate/i', (string) $entry['title']) && (int) ($entry['months'] ?? 0) <= 12)) {
                $internship_count++;
            }
        }

        $config = $this->get_advanced_match_config();

        return [
            'raw_text' => $cv_text,
            'lower' => $lower,
            'current_title' => $current_title,
            'title_tokens' => array_values(array_unique($this->tokenize_simple_match_text($current_title))),
            'experience_years' => $experience_years,
            'seniority' => $entry_seniority !== 'unknown' ? $entry_seniority : ($title_seniority !== 'unknown' ? $title_seniority : $year_seniority),
            'effective_seniority' => $effective_seniority,
            'role_entries' => $entries,
            'internship_count' => $internship_count,
            'keyword_counts' => $this->build_simple_keyword_counts($cv_text, $current_title . ' ' . $current_title),
            'language_hits' => $this->detect_alias_hits_in_text($lower, $config['languages']),
            'qualification_hits' => $this->detect_alias_hits_in_text($lower, $config['qualifications']),
            'location_hits' => $this->detect_locations_in_text($lower, $config),
        ];
    }

    private function build_simple_job_match_profile($post)
    {
        $config = $this->get_advanced_match_config();
        $jd_text = $this->build_jd_text($post);
        $title = (string) ($post['role_title'] ?? '');
        $title_seniority = $this->classify_seniority_from_title($title);
        $detected_years = (int) max(
            $this->detect_required_years_from_text($title . ' ' . ($post['content'] ?? '')),
            (int) ($post['detected_years'] ?? 0),
            $this->map_seniority_to_years((string) ($post['seniority'] ?? 'other'))
        );
        $effective_seniority = $title_seniority !== 'unknown' ? $title_seniority : $this->infer_seniority_from_post($post);
        $normalized_title = strtolower($title);
        $is_internship = (bool) preg_match('/intern|internship|summer|trainee|graduate/i', $normalized_title) || $detected_years <= 1;

        return [
            'title' => $title,
            'lower' => strtolower($jd_text),
            'title_tokens' => array_values(array_unique($this->tokenize_simple_match_text($title))),
            'seniority' => $effective_seniority,
            'required_years' => $detected_years,
            'is_internship' => $is_internship,
            'keyword_counts' => $this->build_simple_keyword_counts($jd_text, $title . ' ' . $title . ' ' . $title),
            'language_hits' => $this->detect_alias_hits_in_text(strtolower($jd_text), $config['languages']),
            'qualification_hits' => $this->detect_alias_hits_in_text(strtolower($jd_text), $config['qualifications']),
            'location_hits' => $this->detect_locations_in_text(strtolower(implode(' ', array_filter([
                (string) ($post['location'] ?? ''),
                (string) ($post['country'] ?? ''),
                (string) ($post['city'] ?? ''),
                $jd_text,
            ]))), $config),
        ];
    }

    private function calculate_simple_title_fit($cv_profile, $job_profile)
    {
        $cv_tokens = (array) ($cv_profile['title_tokens'] ?? []);
        $job_tokens = (array) ($job_profile['title_tokens'] ?? []);
        if (empty($cv_tokens) || empty($job_tokens)) {
            return 45;
        }

        $overlap = array_values(array_intersect($cv_tokens, $job_tokens));
        $union = array_values(array_unique(array_merge($cv_tokens, $job_tokens)));
        $score = !empty($union) ? (count($overlap) / count($union)) * 100 : 45;

        $cv_title = strtolower((string) ($cv_profile['current_title'] ?? ''));
        $job_title = strtolower((string) ($job_profile['title'] ?? ''));
        if ($cv_title !== '' && $job_title !== '') {
            if ($cv_title === $job_title) {
                $score += 25;
            } elseif (strpos($cv_title, $job_title) !== false || strpos($job_title, $cv_title) !== false) {
                $score += 12;
            }
        }

        return max(0, min(100, (int) round($score)));
    }

    private function calculate_simple_keyword_overlap_score($cv_profile, $job_profile)
    {
        $cv_keywords = (array) ($cv_profile['keyword_counts'] ?? []);
        $job_keywords = array_slice((array) ($job_profile['keyword_counts'] ?? []), 0, 35, true);
        if (empty($job_keywords)) {
            return 40;
        }

        $matched_weight = 0.0;
        $total_weight = 0.0;
        foreach ($job_keywords as $token => $count) {
            $weight = min(4.0, 1.0 + ((float) $count * 0.7));
            $total_weight += $weight;
            if (!empty($cv_keywords[$token])) {
                $matched_weight += $weight * min(1.4, 1.0 + (log(1 + (int) $cv_keywords[$token]) * 0.25));
            }
        }

        if ($total_weight <= 0) {
            return 40;
        }

        return max(0, min(100, (int) round(($matched_weight / $total_weight) * 100)));
    }

    private function calculate_simple_language_fit($cv_profile, $job_profile)
    {
        $required = array_keys((array) ($job_profile['language_hits'] ?? []));
        if (empty($required)) {
            return 100;
        }
        $cv_languages = array_keys((array) ($cv_profile['language_hits'] ?? []));
        $matched = count(array_intersect($required, $cv_languages));
        return (int) round(($matched / max(1, count($required))) * 100);
    }

    private function calculate_simple_qualification_fit($cv_profile, $job_profile)
    {
        $required = array_keys((array) ($job_profile['qualification_hits'] ?? []));
        if (empty($required)) {
            return 100;
        }
        $cv_quals = array_keys((array) ($cv_profile['qualification_hits'] ?? []));
        $matched = count(array_intersect($required, $cv_quals));
        return (int) round(($matched / max(1, count($required))) * 100);
    }

    private function calculate_simple_location_fit($cv_profile, $job_profile)
    {
        $job_location_map = (array) ($job_profile['location_hits'] ?? []);
        $cv_location_map = (array) ($cv_profile['location_hits'] ?? []);
        $job_locations = array_keys($job_location_map);
        $cv_locations = array_keys($cv_location_map);
        if (empty($job_locations)) {
            return 70;
        }
        if (!empty(array_intersect($job_locations, $cv_locations))) {
            return 100;
        }
        foreach ($job_locations as $job_location) {
            $job_regions = (array) (($job_location_map[$job_location]['regions'] ?? []));
            $job_country = (string) ($job_location_map[$job_location]['country'] ?? '');
            foreach ($cv_locations as $cv_location) {
                $cv_regions = (array) (($cv_location_map[$cv_location]['regions'] ?? []));
                $cv_country = (string) ($cv_location_map[$cv_location]['country'] ?? '');
                if ($job_country !== '' && $cv_country !== '' && $job_country === $cv_country) {
                    return 92;
                }
                if (!empty(array_intersect($job_regions, $cv_regions))) {
                    return 84;
                }
            }
        }
        return empty($cv_locations) ? 55 : 35;
    }

    private function calculate_simple_seniority_fit($cv_profile, $job_profile)
    {
        $cv_rank = $this->get_simple_seniority_rank((string) ($cv_profile['effective_seniority'] ?? $cv_profile['seniority'] ?? 'associate'));
        $job_rank = $this->get_simple_seniority_rank((string) ($job_profile['seniority'] ?? 'associate'));
        $distance = abs($cv_rank - $job_rank);
        $score = (int) round(100 * exp(-0.45 * ($distance ** 2)));

        if (!empty($job_profile['is_internship']) && ((float) ($cv_profile['experience_years'] ?? 0) >= 4 || $cv_rank >= 3)) {
            return 5;
        }

        if (!empty($job_profile['is_internship']) && $cv_rank <= 1) {
            return min(100, $score + 10);
        }

        return max(0, min(100, $score));
    }

    private function calculate_simple_experience_fit($cv_profile, $job_profile)
    {
        $cv_years = (float) ($cv_profile['experience_years'] ?? 0);
        $required_years = (float) ($job_profile['required_years'] ?? 0);

        if (!empty($job_profile['is_internship'])) {
            if ($cv_years <= 1.5) {
                return 100;
            }
            if ($cv_years <= 3.0) {
                return 65;
            }
            return 8;
        }

        if ($required_years <= 0) {
            return min(100, (int) round(55 + min(35, $cv_years * 4)));
        }

        if ($cv_years >= $required_years) {
            $gap = $cv_years - $required_years;
            if ($gap <= 2) {
                return min(100, (int) round(88 + ($gap * 4)));
            }
            if ($gap >= 6 && $required_years <= 2) {
                return 18;
            }
            return min(100, (int) round(94 - min(16, ($gap - 2) * 2)));
        }

        $deficit = $required_years - $cv_years;
        if ($deficit <= 1) {
            return 72;
        }
        if ($deficit <= 2) {
            return 48;
        }
        return 18;
    }

    /**
     * Extract years of experience from CV using date patterns
     */
    private function extract_experience_years($cv_text)
    {
        $total_months = 0;
        $current_year = date('Y');
        $current_month = date('n');

        // Helper function to convert month name to number
        $month_map = [
            'jan' => 1,
            'january' => 1,
            'feb' => 2,
            'february' => 2,
            'mar' => 3,
            'march' => 3,
            'apr' => 4,
            'april' => 4,
            'may' => 5,
            'jun' => 6,
            'june' => 6,
            'jul' => 7,
            'july' => 7,
            'aug' => 8,
            'august' => 8,
            'sep' => 9,
            'september' => 9,
            'oct' => 10,
            'october' => 10,
            'nov' => 11,
            'november' => 11,
            'dec' => 12,
            'december' => 12
        ];

        // Pattern 1: "20/03/23 – Present" or "01/07/19-14/08/20"
        preg_match_all('/(\d{2})\/(\d{2})\/(\d{2,4})\s*[-–—to]+\s*(?:(\d{2})\/(\d{2})\/(\d{2,4})|present|current)/i', $cv_text, $matches, PREG_SET_ORDER);
        foreach ($matches as $match) {
            $start_month = intval($match[2]);
            $start_year = $this->normalize_simple_year_token($match[3]);

            if (preg_match('/present|current/i', $match[0])) {
                // Current role
                $months = (($current_year - $start_year) * 12) + ($current_month - $start_month);
            } else {
                $end_month = intval($match[5]);
                $end_year = $this->normalize_simple_year_token($match[6]);
                $months = (($end_year - $start_year) * 12) + ($end_month - $start_month);
            }
            $total_months += max(0, $months);
        }

        // Pattern 2: "08/2020 - 04/2022" or "8-20 - 4-22"
        preg_match_all('/(\d{1,2})[\/\-](\d{2,4})\s*[-–—to]+\s*(?:(\d{1,2})[\/\-](\d{2,4})|present|current)/i', $cv_text, $matches, PREG_SET_ORDER);
        foreach ($matches as $match) {
            $start_month = intval($match[1]);
            $start_year = $this->normalize_simple_year_token($match[2]);

            if (preg_match('/present|current/i', $match[0])) {
                $months = (($current_year - $start_year) * 12) + ($current_month - $start_month);
            } else {
                $end_month = intval($match[3]);
                $end_year = $this->normalize_simple_year_token($match[4]);
                $months = (($end_year - $start_year) * 12) + ($end_month - $start_month);
            }
            $total_months += max(0, $months);
        }

        // Pattern 3: "Jan 22 - Mar 24" or "August 2020 - April 2022"
        preg_match_all('/(jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\s*[\'’]?\s*(\d{2,4})\s*[-–—to]+\s*(?:(jan|january|feb|february|mar|march|apr|april|may|jun|june|jul|july|aug|august|sep|sept|september|oct|october|nov|november|dec|december)\s*[\'’]?\s*(\d{2,4})|present|current)/i', $cv_text, $matches, PREG_SET_ORDER);
        foreach ($matches as $match) {
            $start_month_name = strtolower(substr($match[1], 0, 3));
            $start_month = $month_map[$start_month_name] ?? 1;
            $start_year = $this->normalize_simple_year_token($match[2]);

            if (preg_match('/present|current/i', $match[0])) {
                $months = (($current_year - $start_year) * 12) + ($current_month - $start_month);
            } else {
                $end_month_name = strtolower(substr($match[3], 0, 3));
                $end_month = $month_map[$end_month_name] ?? 12;
                $end_year = $this->normalize_simple_year_token($match[4]);
                $months = (($end_year - $start_year) * 12) + ($end_month - $start_month);
            }
            $total_months += max(0, $months);
        }

        // Pattern 4: "Mar 2023 – Present" or "August 2020 - April 2022"
        preg_match_all('/(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+(\d{4})\s*[-–—to]+\s*(?:(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+(\d{4})|present|current)/i', $cv_text, $matches, PREG_SET_ORDER);
        foreach ($matches as $match) {
            $start_month_name = strtolower(substr($match[1], 0, 3));
            $start_month = $month_map[$start_month_name] ?? 1;
            $start_year = intval($match[2]);

            if (preg_match('/present|current/i', $match[0])) {
                // Current role
                $months = (($current_year - $start_year) * 12) + ($current_month - $start_month);
            } else {
                $end_month_name = strtolower(substr($match[3], 0, 3));
                $end_month = $month_map[$end_month_name] ?? 12;
                $end_year = intval($match[4]);
                $months = (($end_year - $start_year) * 12) + ($end_month - $start_month);
            }
            $total_months += max(0, $months);
        }

        // Pattern 5: "2019 – Present" or "2015-2019" (fallback to year-only)
        if ($total_months == 0) {
            preg_match_all('/(\d{4})\s*[-–—to]+\s*(?:(\d{4})|present|current)/i', $cv_text, $matches, PREG_SET_ORDER);
            foreach ($matches as $match) {
                $start_year = intval($match[1]);
                if (preg_match('/present|current/i', $match[0])) {
                    $months = ($current_year - $start_year) * 12;
                } else {
                    $end_year = intval($match[2]);
                    $months = ($end_year - $start_year) * 12;
                }
                $total_months += max(0, $months);
            }
        }

        // Convert months to years with decimal precision
        $total_years = $total_months / 12;

        // Fallback: look for explicit years mentions
        if ($total_years == 0) {
            if (preg_match('/(\d+)\+?\s*years?\s+(?:of\s+)?experience/i', $cv_text, $match)) {
                $total_years = intval($match[1]);
            }
        }

        // Round to 1 decimal place for accuracy (e.g., 4.7 years)
        return max(0, min(40, round($total_years, 1))); // Cap at 40 years
    }

    /**
     * Check qualification match and return status
     */
    private function check_qualification_match($cv_years, $jd_seniority, $detected_years = 0)
    {
        $seniority_ranges = [
            'analyst' => ['min' => 0, 'max' => 3],
            'associate' => ['min' => 3, 'max' => 5],
            'vp' => ['min' => 5, 'max' => 8],
            'director' => ['min' => 8, 'max' => 12],
            'md' => ['min' => 12, 'max' => 20],
            'partner' => ['min' => 15, 'max' => 40],
            'c_level' => ['min' => 15, 'max' => 40]
        ];

        if (!isset($seniority_ranges[$jd_seniority])) {
            if ($detected_years > 0) {
                $jd_seniority = $this->map_years_to_seniority($detected_years);
            }
        }

        if (!isset($seniority_ranges[$jd_seniority])) {
            return 'neutral';
        }

        $range = $seniority_ranges[$jd_seniority];

        // Heavily over-qualified: filter out completely
        if ($cv_years > $range['max'] + 5) {
            return 'filter_out';
        }

        // Significantly over-qualified
        if ($cv_years > $range['max'] + 2) {
            return 'over_qualified';
        }

        // Perfect match or close
        if ($cv_years >= $range['min'] && $cv_years <= $range['max']) {
            return 'exact_match';
        }

        // Slightly under-qualified (within tolerance)
        if ($cv_years >= $range['min'] - 1 && $cv_years < $range['min']) {
            return 'close_match';
        }

        // Under-qualified
        if ($cv_years < $range['min'] - 1) {
            return 'under_qualified';
        }

        return 'neutral';
    }

    private function map_years_to_seniority($years)
    {
        if ($years <= 1) {
            return 'intern';
        }
        if ($years <= 2) {
            return 'analyst';
        }
        if ($years <= 4) {
            return 'associate';
        }
        if ($years <= 7) {
            return 'vp';
        }
        if ($years <= 10) {
            return 'director';
        }
        if ($years <= 15) {
            return 'md';
        }
        return 'partner';
    }

    /**
     * Calculate frequency-weighted keyword scoring
     */
    private function calculate_frequency_weighted_keywords($cv_text, $jd_text, $taxonomy)
    {
        $score = 0;
        $max_score = 0;

        foreach ($taxonomy as $category => $cat_data) {
            if (!isset($cat_data['keywords'])) continue;

            foreach ($cat_data['keywords'] as $group => $group_data) {
                $group_weight = $group_data['weight'] ?? 1;

                // Check phrases (higher specificity)
                if (isset($group_data['phrases'])) {
                    foreach ($group_data['phrases'] as $phrase) {
                        $jd_phrase_count = substr_count($jd_text, strtolower($phrase));
                        if ($jd_phrase_count > 0) {
                            $cv_phrase_count = substr_count($cv_text, strtolower($phrase));
                            if ($cv_phrase_count > 0) {
                                // Apply frequency multiplier
                                $frequency_multiplier = $this->get_frequency_multiplier($cv_phrase_count);
                                $score += ($group_weight * 3 * $frequency_multiplier);
                            }
                            $max_score += ($group_weight * 3);
                        }
                    }
                }

                // Check individual terms (lower specificity)
                if (isset($group_data['terms'])) {
                    foreach ($group_data['terms'] as $term) {
                        $jd_term_count = substr_count($jd_text, strtolower($term));
                        if ($jd_term_count > 0) {
                            $cv_term_count = substr_count($cv_text, strtolower($term));
                            if ($cv_term_count > 0) {
                                $frequency_multiplier = $this->get_frequency_multiplier($cv_term_count);
                                $score += ($group_weight * $frequency_multiplier);
                            }
                            $max_score += $group_weight;
                        }
                    }
                }
            }
        }

        return $max_score > 0 ? ($score / $max_score) * 100 : 0;
    }

    /**
     * Get frequency multiplier for keyword scoring
     */
    private function get_frequency_multiplier($count)
    {
        if ($count >= 7) return 2.5; // Cap at 2.5x
        if ($count >= 4) return 2.0;
        if ($count >= 2) return 1.5;
        return 1.0;
    }

    private function detect_required_years_from_text($text)
    {
        if (empty($text)) {
            return 0;
        }

        $text = strtolower($text);

        // ENHANCED PATTERNS: Detect more variations of experience requirements

        // Pattern 1: "5+ years experience" or "5+ years of experience"
        if (preg_match('/(\d+)\+\s+years?\s+(?:of\s+)?experience/i', $text, $match)) {
            return intval($match[1]);
        }

        // Pattern 2: "5-7 years experience" or "4-7 years" (use minimum)
        if (preg_match('/(\d+)\s*[-–—to]+\s*(\d+)\s+years?\s+(?:of\s+)?experience/i', $text, $match)) {
            return intval($match[1]); // Return minimum of range
        }

        // Pattern 3: "minimum 5 years" or "at least 5 years"
        if (preg_match('/(?:at least|min(?:imum)?|require[sd]?)\s+(\d+)\s+years?/i', $text, $match)) {
            return intval($match[1]);
        }

        // Pattern 4: "5 years of experience in" or "5 years experience in"
        if (preg_match('/(\d+)\s+years?\s+(?:of\s+)?experience\s+in/i', $text, $match)) {
            return intval($match[1]);
        }

        // Pattern 5: Generic "X years" near "experience" keyword (fallback)
        if (preg_match('/(\d+)\s*[-–]\s*(\d+)\s+years/', $text, $match)) {
            return intval($match[1]);
        }

        if (preg_match('/(\d+)\+\s+years/', $text, $match)) {
            return intval($match[1]);
        }

        return 0;
    }

    private function infer_seniority_from_post($post)
    {
        $title = $post['role_title'] ?? '';
        $content = $post['content'] ?? '';

        $classified = $this->classify_seniority_from_title($title);
        if ($classified && $classified !== 'unknown') {
            return $classified;
        }

        $years = $this->detect_required_years_from_text($content);
        if ($years > 0) {
            return $this->map_years_to_seniority($years);
        }

        return 'other';
    }

    private function infer_seniority_from_cv_text($cv_text)
    {
        $text = strtolower($cv_text);
        $levels = [
            'c_level' => ['chief executive', 'chief financial', 'chief operating', 'ceo', 'cfo', 'coo', 'cto', 'cio'],
            'md' => ['managing director', 'senior partner', 'equity partner', 'principal'],
            'director' => ['director', 'head of', 'senior manager'],
            'vp' => ['vice president', 'vp ', ' vp', 'manager', 'lead analyst', 'lead associate'],
            'associate' => ['associate', 'senior analyst', 'sr analyst', 'assistant manager', 'consultant'],
            'analyst' => ['analyst', 'junior', 'assistant', 'coordinator'],
            'intern' => ['intern', 'internship', 'off-cycle', 'off cycle', 'placement', 'spring week', 'summer analyst', 'summer intern', 'trainee', 'graduate programme', 'graduate program', 'graduate trainee']
        ];

        foreach ($levels as $level => $keywords) {
            foreach ($keywords as $keyword) {
                if (strpos($text, $keyword) !== false) {
                    return $level;
                }
            }
        }

        // Default to associate-level if nothing matches
        return 'associate';
    }

    private function extract_requirement_insights($post)
    {
        $jd_text = strtolower($this->build_jd_text($post));
        $lines = preg_split('/[\r\n]+/', $jd_text);
        $must_have = [];
        $tags = [];
        $tag_map = $this->get_functional_tag_map();

        foreach ($lines as $line) {
            $line = trim($line);
            if ($line === '') {
                continue;
            }

            $is_must = preg_match('/must|require|mandatory|need|essential|at least|minimum|required/i', $line);

            foreach ($tag_map as $tag => $keywords) {
                foreach ($keywords as $keyword) {
                    if (strpos($line, $keyword) !== false) {
                        $tags[] = $tag;
                        if ($is_must) {
                            $must_have[] = $keyword;
                        }
                        break 2;
                    }
                }
            }
        }

        return [
            'must_have_keywords' => array_values(array_unique($must_have)),
            'functional_tags' => array_values(array_unique($tags))
        ];
    }

    private function extract_cv_functional_tags($cv_text)
    {
        $text = strtolower($cv_text);
        $tag_map = $this->get_functional_tag_map();
        $tags = [];

        foreach ($tag_map as $tag => $keywords) {
            foreach ($keywords as $keyword) {
                if (strpos($text, $keyword) !== false) {
                    $tags[] = $tag;
                    break;
                }
            }
        }

        return array_values(array_unique($tags));
    }

    private function get_functional_tag_map()
    {
        return [
            'tax' => ['tax', 'vat', 'withholding', 'transfer pricing'],
            'consolidation' => ['consolidation', 'group reporting', 'entity consolidation'],
            'audit' => ['audit', 'auditor', 'internal control', 'sox'],
            'finance_ops' => ['finance', 'financial control', 'controller', 'general ledger', 'closing'],
            'pmo' => ['pmo', 'project management', 'project coordination', 'project plan'],
            'accounting' => ['accounting', 'accountant', 'acca', 'cpa', 'aca', 'chartered accountant']
        ];
    }

    private function merge_reason_lists($existing, $additional, $limit = 4)
    {
        $combined = array_merge(
            array_filter(is_array($existing) ? $existing : []),
            array_filter(is_array($additional) ? $additional : [])
        );
        $unique = array_values(array_unique($combined));
        return array_slice($unique, 0, $limit);
    }

    private function build_match_reasons($cv_parsed, $post)
    {
        $reasons = [];
        $cv_lower = $cv_parsed['lower'];
        $insights = $post['insights'] ?? [];

        // PRIORITY 1: Experience requirement (if met)
        if (!empty($post['detected_years']) && $cv_parsed['experience_years'] >= $post['detected_years']) {
            $cv_years = $cv_parsed['experience_years'];
            $required_years = (int) $post['detected_years'];
            $extra_years = $cv_years - $required_years;

            if ($extra_years >= 2) {
                $reasons[] = sprintf(__('%s years experience (exceeds %d+ year requirement)', 'senna-finance'), $cv_years, $required_years);
            } else {
                $reasons[] = sprintf(__('%s years experience (meets %d+ year requirement)', 'senna-finance'), $cv_years, $required_years);
            }
        }

        // PRIORITY 2: Critical keywords with emphasis
        if (!empty($insights['must_have_keywords'])) {
            $critical_hits = [];
            $general_hits = [];

            // Define high-value keywords
            $high_value_keywords = [
                'private equity',
                'venture capital',
                'investment banking',
                'm&a',
                'dcf',
                'lbo',
                'financial modeling',
                'valuation',
                'portfolio management',
                'risk management',
                'equity research',
                'derivatives',
                'structured finance',
                'asset management'
            ];

            foreach ($insights['must_have_keywords'] as $keyword) {
                if (strpos($cv_lower, $keyword) !== false) {
                    $formatted = ucwords($keyword);
                    if (in_array(strtolower($keyword), $high_value_keywords)) {
                        $critical_hits[] = $formatted;
                    } else {
                        $general_hits[] = $formatted;
                    }
                }
            }

            // Show critical matches first
            if (!empty($critical_hits)) {
                $display = implode(', ', array_slice($critical_hits, 0, 3));
                if (count($critical_hits) > 3) {
                    $display .= sprintf(__(' +%d more', 'senna-finance'), count($critical_hits) - 3);
                }
                $reasons[] = sprintf(__('Key expertise: %s', 'senna-finance'), $display);
            }

            // Then general matches
            if (!empty($general_hits) && count($reasons) < 2) {
                $display = implode(', ', array_slice($general_hits, 0, 4));
                if (count($general_hits) > 4) {
                    $display .= sprintf(__(' +%d more', 'senna-finance'), count($general_hits) - 4);
                }
                $reasons[] = sprintf(__('Skills match: %s', 'senna-finance'), $display);
            }
        }

        // PRIORITY 3: Functional specialization
        if (!empty($insights['functional_tags'])) {
            $cv_tags = $this->extract_cv_functional_tags($cv_parsed['raw_text']);
            $overlap = array_intersect($insights['functional_tags'], $cv_tags);
            if (!empty($overlap)) {
                $labels = array_map([$this, 'format_tag_label'], array_slice($overlap, 0, 2));
                $reasons[] = sprintf(__('Functional fit: %s', 'senna-finance'), implode(' & ', $labels));
            }
        }

        // PRIORITY 4: Seniority alignment
        if (!empty($post['seniority']) && count($reasons) < 3) {
            $seniority_label = $this->format_tag_label($post['seniority']);
            $reasons[] = sprintf(__('%s level experience', 'senna-finance'), $seniority_label);
        }

        // PRIORITY 5: Industry match
        if (!empty($post['industry']) && count($reasons) < 4) {
            $industry_label = ucwords(str_replace('_', ' ', $post['industry']));
            $reasons[] = sprintf(__('%s background', 'senna-finance'), $industry_label);
        }

        return array_slice(array_values(array_unique(array_filter($reasons))), 0, 4);
    }

    private function build_match_warnings($cv_parsed, $post)
    {
        $warnings = [];
        $insights = $post['insights'] ?? [];
        $cv_lower = $cv_parsed['lower'];

        if (!empty($insights['must_have_keywords'])) {
            $missing = [];
            foreach ($insights['must_have_keywords'] as $keyword) {
                if (strpos($cv_lower, $keyword) === false) {
                    $missing[] = $keyword;
                }
            }
            if (!empty($missing)) {
                $warnings[] = sprintf(__('Missing: %s', 'senna-finance'), implode(', ', array_slice($missing, 0, 2)));
            }
        }

        $required_years = $post['detected_years'] ?? 0;
        if (!$required_years && !empty($post['seniority'])) {
            $required_years = $this->map_seniority_to_years($post['seniority']);
        }

        if ($required_years && $cv_parsed['experience_years'] < $required_years) {
            $warnings[] = sprintf(__('Only %d yrs vs %d required', 'senna-finance'), (int) $cv_parsed['experience_years'], (int) $required_years);
        }

        return array_slice(array_values(array_unique($warnings)), 0, 2);
    }

    /**
     * Build match gaps array including nationality requirements
     */
    private function build_match_gaps($cv_parsed, $post)
    {
        $gaps = [];

        // PRIORITY 1: Check enriched nationality requirements (from enrich_posts_with_requirements)
        if (!empty($post['nationality_requirements']) && is_array($post['nationality_requirements'])) {
            foreach ($post['nationality_requirements'] as $nat_req) {
                $gaps[] = [
                    'type' => 'nationality_requirement',
                    'item' => $nat_req['display_name'] ?? ucwords(str_replace('_', ' ', $nat_req['nationality'])),
                    'severity' => 'critical',
                    'is_dealbreaker' => true,
                    'score_impact' => 0, // No score penalty per user requirement
                    'recommendation' => sprintf(
                        __('This role requires %s status. Please verify your eligibility before applying.', 'senna-finance'),
                        $nat_req['display_name'] ?? $nat_req['nationality']
                    )
                ];
            }
        }

        // PRIORITY 2: Fallback to pattern matching in job title and content
        if (empty($gaps)) {
            $job_text = strtolower(($post['role_title'] ?? '') . ' ' . ($post['content'] ?? ''));

            // Detect common nationality requirements
            $nationality_patterns = [
                'uae_national' => ['uae national', 'emirati', 'emirates national'],
                'saudi_national' => ['saudi national', 'saudi arabia national', 'ksa national'],
                'gcc_national' => ['gcc national', 'gulf national'],
            ];

            foreach ($nationality_patterns as $nationality_code => $patterns) {
                foreach ($patterns as $pattern) {
                    if (strpos($job_text, $pattern) !== false) {
                        $display_name = ucwords(str_replace('_', ' ', $nationality_code));
                        $gaps[] = [
                            'type' => 'nationality_requirement',
                            'item' => $display_name,
                            'severity' => 'critical',
                            'is_dealbreaker' => true,
                            'score_impact' => 0,
                            'recommendation' => sprintf(
                                __('This role requires %s status. Please verify your eligibility before applying.', 'senna-finance'),
                                $display_name
                            )
                        ];
                        break 2; // Found a match, exit both loops
                    }
                }
            }
        }

        return $gaps;
    }

    /**
     * Enrich posts with requirements data from WordPress post meta
     * This loads nationality requirements and other structured requirements for accurate matching
     */
    private function enrich_posts_with_requirements($posts)
    {
        if (empty($posts)) {
            return $posts;
        }

        foreach ($posts as &$post) {
            // Only enrich if post has a linked WordPress post
            if (!empty($post['wp_post_id'])) {
                $wp_post_id = $post['wp_post_id'];

                // Load nationality requirements
                $nationality_reqs = get_post_meta($wp_post_id, 'job_nationality_requirements', true);
                if (!empty($nationality_reqs) && is_array($nationality_reqs)) {
                    $post['nationality_requirements'] = $nationality_reqs;
                }

                // Load structured requirements for comprehensive matching
                $structured_reqs = get_post_meta($wp_post_id, 'job_requirements_structured', true);
                if (!empty($structured_reqs) && is_array($structured_reqs)) {
                    $post['requirements_structured'] = $structured_reqs;

                    // Extract specific requirement types for easier access
                    if (!empty($structured_reqs['technical_skills'])) {
                        $post['required_technical_skills'] = $structured_reqs['technical_skills'];
                    }
                    if (!empty($structured_reqs['certifications'])) {
                        $post['required_certifications'] = $structured_reqs['certifications'];
                    }
                    if (!empty($structured_reqs['experience_level'])) {
                        $post['required_experience_level'] = $structured_reqs['experience_level'];
                    }
                }
            }
        }
        unset($post); // Break reference

        return $posts;
    }

    private function format_tag_label($tag)
    {
        return ucwords(str_replace('_', ' ', $tag));
    }

    private function map_seniority_to_years($seniority)
    {
        $map = [
            'analyst' => 0,
            'associate' => 2,
            'vp' => 4,
            'director' => 7,
            'md' => 12,
            'partner' => 15,
            'c_level' => 15
        ];
        return $map[$seniority] ?? 0;
    }

    /**
     * Classify role type from text
     */
    private function classify_role_type($text, $taxonomy)
    {
        $scores = [];
        $role_types = ['investment_management', 'investment_banking', 'private_equity', 'venture_capital', 'corporate_finance', 'consulting_transferable'];

        foreach ($role_types as $role_type) {
            if (!isset($taxonomy[$role_type])) continue;

            $type_score = 0;
            foreach ($taxonomy[$role_type]['keywords'] as $group => $group_data) {
                if (isset($group_data['phrases'])) {
                    foreach ($group_data['phrases'] as $phrase) {
                        if (stripos($text, $phrase) !== false) {
                            $type_score += 3;
                        }
                    }
                }
                if (isset($group_data['terms'])) {
                    foreach ($group_data['terms'] as $term) {
                        if (stripos($text, $term) !== false) {
                            $type_score += 1;
                        }
                    }
                }
            }
            $scores[$role_type] = $type_score;
        }

        arsort($scores);
        $top_types = array_slice(array_keys($scores), 0, 2, true);

        // Return primary and secondary types
        return [
            'primary' => $top_types[0] ?? 'unknown',
            'secondary' => $top_types[1] ?? null,
            'score' => $scores[$top_types[0]] ?? 0
        ];
    }

    /**
     * Calculate experience match score
     */
    private function calculate_experience_match($cv_years, $jd_seniority, $qualification_status)
    {
        switch ($qualification_status) {
            case 'exact_match':
                return 100;
            case 'close_match':
                return 85;
            case 'under_qualified':
                return 40;
            case 'over_qualified':
                return 50;
            default:
                return 60;
        }
    }

    /**
     * Calculate role type alignment score
     */
    private function calculate_role_alignment($cv_role, $jd_role, $cv_text, $jd_text)
    {
        $cv_primary = $cv_role['primary'];
        $jd_primary = $jd_role['primary'];

        // Perfect match
        if ($cv_primary === $jd_primary) {
            return 100;
        }

        // Transferable roles matrix
        $transferable = [
            'investment_banking' => ['private_equity' => 85, 'corporate_finance' => 75, 'investment_management' => 70],
            'private_equity' => ['investment_banking' => 85, 'venture_capital' => 80, 'corporate_finance' => 75],
            'venture_capital' => ['private_equity' => 80, 'investment_banking' => 70],
            'consulting_transferable' => ['investment_banking' => 75, 'private_equity' => 75, 'corporate_finance' => 70],
            'investment_management' => ['investment_banking' => 60, 'private_equity' => 60],
            'corporate_finance' => ['investment_banking' => 70, 'private_equity' => 65]
        ];

        if (isset($transferable[$cv_primary][$jd_primary])) {
            return $transferable[$cv_primary][$jd_primary];
        }

        // Check if CV has secondary role matching JD
        if (isset($cv_role['secondary']) && $cv_role['secondary'] === $jd_primary) {
            return 75; // Bonus for versatility
        }

        // Poor match
        return 30;
    }

    /**
     * Calculate requirements match
     */
    private function calculate_requirements_match($cv_text, $post)
    {
        if (empty($post['requirements'])) {
            return 100; // No requirements specified
        }

        $requirements = is_string($post['requirements']) ? json_decode($post['requirements'], true) : $post['requirements'];
        if (!is_array($requirements) || empty($requirements)) {
            return 100;
        }

        $matched = 0;
        $total = count($requirements);

        foreach ($requirements as $req) {
            $req_lower = strtolower($req);
            // Check for substantial match (at least 70% of words)
            $req_words = explode(' ', $req_lower);
            $match_count = 0;
            foreach ($req_words as $word) {
                if (strlen($word) > 3 && stripos($cv_text, $word) !== false) {
                    $match_count++;
                }
            }
            if ($match_count / count($req_words) >= 0.5) {
                $matched++;
            }
        }

        return $total > 0 ? ($matched / $total) * 100 : 100;
    }

    /**
     * Calculate education and certification match
     */
    private function calculate_education_match($cv_text, $taxonomy)
    {
        $score = 0;
        $cv_lower = strtolower($cv_text);

        if (!isset($taxonomy['education_certifications'])) {
            return 0;
        }

        $edu_data = $taxonomy['education_certifications']['keywords'];

        // Check certifications (highest value)
        if (isset($edu_data['certifications'])) {
            foreach ($edu_data['certifications']['phrases'] as $cert) {
                if (stripos($cv_lower, strtolower($cert)) !== false) {
                    if (stripos($cert, 'charter') !== false || stripos($cert, 'Level III') !== false || stripos($cert, 'Level 3') !== false) {
                        $score += 40; // CFA Charter/Level 3
                    } elseif (stripos($cert, 'CFA') !== false) {
                        $score += 20; // Other CFA levels
                    } else {
                        $score += 15; // Other certifications
                    }
                }
            }
        }

        // Check degrees
        if (isset($edu_data['degrees'])) {
            foreach ($edu_data['degrees']['phrases'] as $degree) {
                if (stripos($cv_lower, strtolower($degree)) !== false) {
                    if (stripos($degree, 'MBA') !== false || stripos($degree, 'MSc') !== false || stripos($degree, 'Master') !== false) {
                        $score += 20; // Graduate degree
                    } else {
                        $score += 10; // Undergraduate
                    }
                }
            }
        }

        // Check universities
        if (isset($edu_data['universities'])) {
            foreach ($edu_data['universities']['phrases'] as $uni) {
                if (stripos($cv_lower, strtolower($uni)) !== false) {
                    $score += 10; // Top university
                }
            }
        }

        return min(100, $score);
    }

    /**
     * Calculate regional fit score
     */
    private function calculate_regional_fit($cv_text, $taxonomy)
    {
        $score = 0;
        $cv_lower = strtolower($cv_text);

        if (!isset($taxonomy['private_equity_specific'])) {
            return 0;
        }

        $private_equity_data = $taxonomy['private_equity_specific']['keywords'];

        // Check for private equity experience
        if (isset($private_equity_data['regions'])) {
            foreach ($private_equity_data['regions']['phrases'] as $region) {
                if (stripos($cv_lower, strtolower($region)) !== false) {
                    $score += 40;
                    break; // Only count once
                }
            }
        }

        // Check for market knowledge
        if (isset($private_equity_data['markets'])) {
            foreach ($private_equity_data['markets']['phrases'] as $market) {
                if (stripos($cv_lower, strtolower($market)) !== false) {
                    $score += 30;
                    break;
                }
            }
        }

        // Check for Arabic language
        if (isset($taxonomy['languages']['keywords']['arabic'])) {
            foreach ($taxonomy['languages']['keywords']['arabic']['phrases'] as $lang) {
                if (stripos($cv_lower, strtolower($lang)) !== false) {
                    $score += 30;
                    break;
                }
            }
        }

        return min(100, $score);
    }

    /**
     * Calculate career trajectory score
     */
    private function calculate_trajectory_score($cv_text)
    {
        $score = 50; // Neutral baseline

        // Look for progression keywords
        $progression_keywords = ['promoted', 'promotion', 'advanced to', 'elevated to', 'appointed'];
        foreach ($progression_keywords as $keyword) {
            if (stripos($cv_text, $keyword) !== false) {
                $score += 20;
                break;
            }
        }

        // Check for stable tenure (longer roles are better)
        $year_count = preg_match_all('/\d{4}\s*[-–—to]+\s*\d{4}/i', $cv_text);
        if ($year_count <= 2) {
            $score += 20; // Stable career (few job changes)
        } elseif ($year_count >= 5) {
            $score -= 20; // Job hopper
        }

        return min(100, max(0, $score));
    }

    /**
     * Apply recency weighting for most recent role
     */
    private function apply_recency_weighting($cv_text, $jd_text, $taxonomy)
    {
        // Extract the most recent role (text before first date range or first 1000 chars)
        $recent_role = '';
        if (preg_match('/(.*?)(?:\d{4}\s*[-–—to]+)/s', $cv_text, $match)) {
            $recent_role = substr($match[1], 0, 1500);
        } else {
            $recent_role = substr($cv_text, 0, 1500);
        }

        $recent_role_lower = strtolower($recent_role);

        // Calculate keyword match for recent role only
        $recent_score = $this->calculate_frequency_weighted_keywords($recent_role_lower, $jd_text, $taxonomy);

        // If recent role scores high, give bonus (up to +15%)
        if ($recent_score > 70) {
            return 0.15;
        } elseif ($recent_score > 50) {
            return 0.10;
        } elseif ($recent_score > 30) {
            return 0.05;
        }

        return 0;
    }

    /**
     * Get user's introduction usage limits
     */
    private function get_intro_limits($user_id)
    {
        return [
            'is_premium' => false,
            'monthly_limit' => 10,
            'reset_date' => date('Y-m-01') // Reset on 1st of each month
        ];
    }

    /**
     * Get user's introduction usage count for current month
     */
    private function get_intro_usage_count($user_id)
    {
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_introduction_requests';

        // Check if table exists
        if ($wpdb->get_var("SHOW TABLES LIKE '{$table}'") !== $table) {
            return 0;
        }

        $first_of_month = date('Y-m-01 00:00:00');

        $count = $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$table} WHERE user_id = %d AND created_at >= %s",
            $user_id,
            $first_of_month
        ));

        return intval($count);
    }

    /**
     * Request introduction from MENA Careers team
     */
    public function request_introduction()
    {
        $user_id = $this->verify_request();

        $post_id = isset($_POST['post_id']) ? absint($_POST['post_id']) : 0;
        $recruiter_id = isset($_POST['recruiter_id']) ? absint($_POST['recruiter_id']) : 0;
        $note = isset($_POST['note']) ? sanitize_textarea_field($_POST['note']) : '';
        $match_score = isset($_POST['match_score']) ? intval($_POST['match_score']) : 0;
        $cv_id = isset($_POST['cv_id']) ? sanitize_text_field($_POST['cv_id']) : '';
        $intro_message = isset($_POST['intro_message']) ? sanitize_textarea_field($_POST['intro_message']) : '';
        $schedule_option = isset($_POST['schedule_option']) ? sanitize_text_field($_POST['schedule_option']) : 'asap';
        $selected_keywords = isset($_POST['selected_keywords']) ? array_filter(array_map('sanitize_text_field', (array) $_POST['selected_keywords'])) : [];

        if (!$post_id || !$recruiter_id) {
            wp_send_json_error(['message' => 'Post ID and Recruiter ID are required'], 400);
            return;
        }

        // Check match quality - only allow for matches 60% or higher
        if ($match_score < 60) {
            wp_send_json_error(['message' => 'Introduction requests are only available for matches 60% or higher'], 400);
            return;
        }

        // Check usage limits
        $limits = $this->get_intro_limits($user_id);
        $current_usage = $this->get_intro_usage_count($user_id);

        if ($current_usage >= $limits['monthly_limit']) {
            $upgrade_url = $limits['is_premium'] ? '' : home_url('/membership/');
            wp_send_json_error([
                'message' => 'You have reached your monthly introduction limit',
                'current_usage' => $current_usage,
                'monthly_limit' => $limits['monthly_limit'],
                'is_premium' => $limits['is_premium'],
                'upgrade_url' => $upgrade_url
            ]);
            return;
        }

        // Get user info
        $user = get_userdata($user_id);
        $user_email = $user->user_email;
        $user_name = $user->display_name;

        $cv_label = '';
        if ($cv_id && class_exists('SFFC_CRM_CV_Manager')) {
            $cv_manager = new SFFC_CRM_CV_Manager();
            $cv_entry = $cv_manager->get_cv_by_id($user_id, $cv_id);
            if ($cv_entry) {
                $cv_label = isset($cv_entry['label']) ? $cv_entry['label'] : '';
            }
        }

        // Get post info
        $post_model = new SFFC_CRM_Post();
        $post = $post_model->get($post_id);

        if (!$post) {
            wp_send_json_error(['message' => 'Post not found'], 404);
            return;
        }

        // Get job details — get() returns ARRAY_A so use array syntax
        $job_title   = $post['role_title'] ?? 'Untitled Role';
        $job_company = $post['company']    ?? 'Unknown Company';

        // Send notification email to MENA Careers team
        $admin_email = get_option('admin_email');
        $subject = 'Introduction Request: ' . $user_name . ' for ' . $job_title;

        $message = "A user has requested an introduction.\n\n";
        $message .= "User: {$user_name} ({$user_email})\n";
        $message .= "Role: {$job_title}\n";
        $message .= "Company: {$job_company}\n";
        $message .= "Match Score: {$match_score}%\n";
        $message .= "Recruiter: " . ($post['recruiter_name'] ?? 'N/A') . "\n";
        $message .= "Recruiter ID: {$recruiter_id}\n";
        $message .= "Post ID: {$post_id}\n\n";

        if ($note) {
            $message .= "User Note:\n{$note}\n\n";
        }

        if ($intro_message) {
            $message .= "AI Intro Preview:\n{$intro_message}\n\n";
        }

        if ($cv_label || $cv_id) {
            $message .= 'Selected CV: ' . ($cv_label ? $cv_label : $cv_id) . "\n";
        }

        if (!empty($selected_keywords)) {
            $message .= 'Keyword Focus: ' . implode(', ', $selected_keywords) . "\n";
        }

        if ($schedule_option) {
            $message .= 'Preferred Send Window: ' . $schedule_option . "\n\n";
        }

        $message .= "View in admin: " . admin_url('admin.php?page=sffc-introductions');

        wp_mail($admin_email, $subject, $message);

        // Log the introduction request
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_introduction_requests';

        // Create table if it doesn't exist
        $this->ensure_intro_requests_table();

        // Insert the request
        $inserted = $wpdb->insert($table, [
            'user_id' => $user_id,
            'job_id' => $post_id,
            'recruiter_id' => $recruiter_id,
            'message' => $note,
            'compatibility_score' => $match_score,
            'status' => 'pending_review',
            'pitch_message' => $intro_message,
            'cv_id' => $cv_id ?: null,
            'schedule_preference' => $schedule_option,
            'keywords' => !empty($selected_keywords) ? wp_json_encode($selected_keywords) : null,
            'created_at' => current_time('mysql')
        ]);

        if ($inserted === false) {
            error_log('Failed to insert introduction request: ' . $wpdb->last_error);
        }

        // Add to pipeline with 'interested' stage (now labeled as "Introductions")
        $pipeline_model = new SFFC_CRM_Pipeline();
        $pipeline_item = $pipeline_model->find_by_recruiter_and_post($user_id, $recruiter_id, $post_id);

        if (!$pipeline_item) {
            // Create new pipeline item
            $pipeline_model->create([
                'user_id' => $user_id,
                'recruiter_id' => $recruiter_id,
                'post_id' => $post_id,
                'stage' => 'interested',
                'source' => 'platform',
                'notes' => $note ? 'Introduction requested: ' . $note : 'Introduction requested'
            ]);
        } else if ($pipeline_item['stage'] !== 'interested') {
            // If already in pipeline but different stage, optionally update
            // (For now we'll leave it in its current stage)
        }

        // Return updated usage info
        $new_usage = $current_usage + 1;
        $remaining = $limits['monthly_limit'] - $new_usage;

        // Build enriched row data so JS can inject the row immediately without
        // a second round-trip to sffc_crm_get_intro_requests.
        $new_intro_id   = $wpdb->insert_id;
        $r_name         = is_array($post) ? ($post['recruiter_name']  ?? '') : ($post->recruiter_name  ?? '');
        $r_firm         = is_array($post) ? ($post['recruiter_firm']  ?? '') : ($post->recruiter_firm  ?? '');
        $r_photo        = is_array($post) ? ($post['recruiter_photo'] ?? '') : ($post->recruiter_photo ?? '');
        $p_company      = is_array($post) ? ($post['company']         ?? '') : ($post->company         ?? '');
        $p_location     = is_array($post) ? ($post['location']        ?? '') : ($post->location        ?? '');
        $p_title        = is_array($post) ? ($post['role_title']      ?? '') : ($post->role_title      ?? '');
        if (! $p_title) {
            $p_title = $job_title;
        }

        $initials = 'S';
        if ($r_name) {
            $parts    = preg_split('/\s+/', trim($r_name));
            $initials = strtoupper(substr($parts[0], 0, 1));
            if (count($parts) > 1) {
                $initials .= strtoupper(substr(end($parts), 0, 1));
            }
        }

        wp_send_json_success([
            'message' => 'Introduction request sent successfully',
            'request' => [
                'id'                  => $new_intro_id,
                'job_id'              => $post_id,
                'recruiter_id'        => $recruiter_id,
                'compatibility_score' => $match_score,
                'status'              => 'pending_review',
                'status_label'        => 'Under Review',
                'job_title'           => $p_title,
                'job_company'         => $p_company,
                'job_location'        => $p_location,
                'recruiter_name'      => $r_name,
                'recruiter_firm'      => $r_firm,
                'recruiter_photo'     => $r_photo,
                'recruiter_initials'  => $initials,
                'created_at_formatted' => 'just now',
            ],
            'usage' => [
                'current'    => $new_usage,
                'limit'      => $limits['monthly_limit'],
                'remaining'  => $remaining,
                'is_premium' => $limits['is_premium'],
            ],
        ]);
    }

    public function update_intro_request()
    {
        $user_id = $this->verify_request();

        $intro_id = isset($_POST['intro_id']) ? intval($_POST['intro_id']) : 0;
        $status = isset($_POST['status']) ? sanitize_key($_POST['status']) : '';

        if (!$intro_id || !$status) {
            wp_send_json_error(['message' => __('Missing introduction ID or status', 'senna-finance')], 400);
        }

        $status_labels = $this->get_intro_status_labels();
        if (!array_key_exists($status, $status_labels)) {
            wp_send_json_error(['message' => __('Invalid status option', 'senna-finance')], 400);
        }

        $this->ensure_intro_requests_table();
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_introduction_requests';
        $own_request = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$table} WHERE id = %d AND user_id = %d",
            $intro_id,
            $user_id
        ));

        if (!$own_request) {
            wp_send_json_error(['message' => __('Request not found', 'senna-finance')], 404);
        }

        $updated = $wpdb->update(
            $table,
            [
                'status' => $status,
                'updated_at' => current_time('mysql')
            ],
            ['id' => $intro_id]
        );

        if ($updated === false) {
            wp_send_json_error(['message' => __('Failed to update status', 'senna-finance')]);
        }

        wp_send_json_success([
            'message' => __('Introduction updated', 'senna-finance'),
            'status' => $status,
            'status_label' => $status_labels[$status]
        ]);
    }

    public function remove_intro_request()
    {
        $user_id = $this->verify_request();

        $intro_id = isset($_POST['intro_id']) ? intval($_POST['intro_id']) : 0;
        if (!$intro_id) {
            wp_send_json_error(['message' => __('Missing introduction ID', 'senna-finance')], 400);
        }

        $this->ensure_intro_requests_table();
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_introduction_requests';
        $own_request = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$table} WHERE id = %d AND user_id = %d",
            $intro_id,
            $user_id
        ));

        if (!$own_request) {
            wp_send_json_error(['message' => __('Request not found', 'senna-finance')], 404);
        }

        $updated = $wpdb->update(
            $table,
            [
                'status' => 'withdrawn',
                'updated_at' => current_time('mysql')
            ],
            ['id' => $intro_id]
        );

        if ($updated === false) {
            wp_send_json_error(['message' => __('Failed to remove request', 'senna-finance')]);
        }

        wp_send_json_success([
            'message' => __('Introduction withdrawn', 'senna-finance')
        ]);
    }

    /**
     * Ensure introduction requests table exists
     */
    private function ensure_intro_requests_table()
    {
        global $wpdb;
        $table_name = $wpdb->prefix . 'sffc_introduction_requests';

        // Ensure table exists / update schema
        $charset_collate = $wpdb->get_charset_collate();
        $sql = "CREATE TABLE {$table_name} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            user_id bigint(20) NOT NULL,
            job_id bigint(20) NOT NULL,
            recruiter_id bigint(20) DEFAULT NULL,
            message text,
            compatibility_score int DEFAULT 0,
            status varchar(50) DEFAULT 'pending_review',
            pitch_message text,
            cv_id varchar(191) DEFAULT NULL,
            schedule_preference varchar(50) DEFAULT 'asap',
            keywords text,
            recruiter_response text,
            recruiter_feedback text,
            candidate_notified tinyint(1) DEFAULT 0,
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            reviewed_at datetime NULL,
            sent_at datetime NULL,
            responded_at datetime NULL,
            updated_at datetime NULL,
            PRIMARY KEY (id),
            KEY user_id (user_id),
            KEY job_id (job_id),
            KEY recruiter_id (recruiter_id),
            KEY status (status),
            KEY created_at (created_at)
        ) {$charset_collate};";

        require_once(ABSPATH . 'wp-admin/includes/upgrade.php');
        dbDelta($sql);
    }

    private function ensure_smart_apply_requests_table()
    {
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_smart_apply_requests';
        $exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table));
        if ($exists === $table) {
            return;
        }

        $charset_collate = $wpdb->get_charset_collate();
        require_once(ABSPATH . 'wp-admin/includes/upgrade.php');
        $sql = "CREATE TABLE {$table} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            user_id bigint(20) NOT NULL,
            job_id bigint(20) DEFAULT NULL,
            recruiter_id bigint(20) DEFAULT NULL,
            job_title varchar(255) DEFAULT NULL,
            company varchar(255) DEFAULT NULL,
            location varchar(255) DEFAULT NULL,
            recruiter_name varchar(255) DEFAULT NULL,
            match_score int DEFAULT 0,
            status varchar(50) DEFAULT 'pending_review',
            request_type varchar(20) DEFAULT 'role',
            notes text,
            preferences text,
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            KEY user_id (user_id),
            KEY job_id (job_id),
            KEY status (status),
            KEY request_type (request_type)
        ) {$charset_collate};";
        dbDelta($sql);
    }

    private function get_smart_apply_status_labels()
    {
        return [
            'pending_review'    => __('Queued', 'senna-finance'),
            'brief_received'    => __('Brief Received', 'senna-finance'),
            'in_progress'       => __('Running', 'senna-finance'),
            'submitted'         => __('Submitted', 'senna-finance'),
            'awaiting_feedback' => __('Awaiting Feedback', 'senna-finance'),
            'completed'         => __('Completed', 'senna-finance'),
            'cancelled'         => __('Cancelled', 'senna-finance'),
        ];
    }

    private function format_smart_apply_request($row, $labels = [])
    {
        if (empty($labels)) {
            $labels = $this->get_smart_apply_status_labels();
        }
        $status = $row['status'] ?? 'pending_review';
        $label = $labels[$status] ?? __('Queued', 'senna-finance');

        return [
            'id' => intval($row['id']),
            'job_id' => intval($row['job_id']),
            'recruiter_id' => intval($row['recruiter_id']),
            'job_title' => $row['job_title'] ?? '',
            'company' => $row['company'] ?? '',
            'location' => $row['location'] ?? '',
            'recruiter_name' => $row['recruiter_name'] ?? '',
            'match_score' => intval($row['match_score']),
            'status' => $status,
            'status_label' => $label,
            'request_type' => $row['request_type'] ?? 'role',
            'notes' => $row['notes'] ?? '',
            'preferences' => $row['preferences'] ?? '',
            'created_at' => $row['created_at'] ?? '',
            'created_at_formatted' => !empty($row['created_at']) ? date_i18n(get_option('date_format'), strtotime($row['created_at'])) : ''
        ];
    }

    private function get_smart_apply_count($user_id)
    {
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_smart_apply_requests';
        if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) !== $table) {
            return 0;
        }

        $count = $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$table} WHERE user_id = %d AND status != %s",
            $user_id,
            'cancelled'
        ));

        return intval($count);
    }

    public function add_smart_apply_request()
    {
        $user_id = $this->verify_request();

        $post_id = isset($_POST['post_id']) ? absint($_POST['post_id']) : 0;
        $recruiter_id = isset($_POST['recruiter_id']) ? absint($_POST['recruiter_id']) : 0;
        $match_score = isset($_POST['match_score']) ? intval($_POST['match_score']) : 0;
        $job_title = sanitize_text_field($_POST['job_title'] ?? '');
        $company = sanitize_text_field($_POST['company'] ?? '');
        $location = sanitize_text_field($_POST['location'] ?? '');
        $recruiter_name = sanitize_text_field($_POST['recruiter_name'] ?? '');
        $notes = sanitize_textarea_field($_POST['notes'] ?? '');

        if (!$post_id) {
            wp_send_json_error(['message' => __('Missing role information', 'senna-finance')], 400);
        }

        $this->ensure_smart_apply_requests_table();
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_smart_apply_requests';

        $existing = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE user_id = %d AND job_id = %d AND request_type = %s LIMIT 1",
            $user_id,
            $post_id,
            'role'
        ), ARRAY_A);

        if ($existing) {
            wp_send_json_success([
                'already_added' => true,
                'item' => $this->format_smart_apply_request($existing),
                'job_id' => $post_id,
                'total' => $this->get_smart_apply_count($user_id)
            ]);
        }

        $match_score = max(0, min(100, $match_score));

        $inserted = $wpdb->insert($table, [
            'user_id' => $user_id,
            'job_id' => $post_id,
            'recruiter_id' => $recruiter_id ?: null,
            'job_title' => $job_title,
            'company' => $company,
            'location' => $location,
            'recruiter_name' => $recruiter_name,
            'match_score' => $match_score,
            'status' => 'pending_review',
            'request_type' => 'role',
            'notes' => $notes
        ]);

        if ($inserted === false) {
            wp_send_json_error(['message' => __('Unable to add Smart message request', 'senna-finance')]);
        }

        $row = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$table} WHERE id = %d", $wpdb->insert_id), ARRAY_A);
        $formatted = $this->format_smart_apply_request($row);

        $user = get_userdata($user_id);
        $user_name = $user ? $user->display_name : __('MENA Careers member', 'senna-finance');
        $user_email = $user ? $user->user_email : '';
        $admin_email = get_option('admin_email');
        $subject = sprintf('[MENA Careers] Smart message request from %s', $user_name);
        $message = "A user added a role to Smart message.\n\n";
        $message .= "User: {$user_name} ({$user_email})\n";
        $message .= "Role: " . ($job_title ?: __('Untitled Role', 'senna-finance')) . "\n";
        if ($company) {
            $message .= "Company: {$company}\n";
        }
        if ($location) {
            $message .= "Location: {$location}\n";
        }
        if ($match_score) {
            $message .= "Match Score: {$match_score}%\n";
        }
        if ($recruiter_name) {
            $message .= "Recruiter: {$recruiter_name}\n";
        }
        if ($notes) {
            $message .= "Notes: {$notes}\n";
        }
        $message .= "Job ID: {$post_id}\n";
        $message .= "Manage queue: " . admin_url('admin.php?page=sffc-recruiter-outreach');
        wp_mail($admin_email, $subject, $message);

        wp_send_json_success([
            'item' => $formatted,
            'job_id' => $post_id,
            'total' => $this->get_smart_apply_count($user_id)
        ]);
    }

    public function get_smart_apply_requests()
    {
        $user_id = $this->verify_request();
        $context = isset($_POST['context']) ? sanitize_key($_POST['context']) : 'full';

        $this->ensure_smart_apply_requests_table();
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_smart_apply_requests';
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} WHERE user_id = %d ORDER BY created_at DESC",
            $user_id
        ), ARRAY_A);

        if ($context === 'map') {
            $job_ids = [];
            foreach ($rows as $row) {
                if (!empty($row['job_id']) && $row['status'] !== 'cancelled') {
                    $job_ids[] = (int) $row['job_id'];
                }
            }
            wp_send_json_success([
                'job_ids' => array_values(array_unique($job_ids)),
                'total' => $this->get_smart_apply_count($user_id)
            ]);
        }

        $labels = $this->get_smart_apply_status_labels();
        $items = array_map(function ($row) use ($labels) {
            return $this->format_smart_apply_request($row, $labels);
        }, $rows ?? []);

        $job_ids = [];
        foreach ($items as $item) {
            if (!empty($item['job_id']) && $item['status'] !== 'cancelled') {
                $job_ids[] = $item['job_id'];
            }
        }

        wp_send_json_success([
            'items' => $items,
            'statuses' => $labels,
            'job_ids' => array_values(array_unique($job_ids)),
            'total' => $this->get_smart_apply_count($user_id)
        ]);
    }

    public function update_smart_apply_request()
    {
        $user_id = $this->verify_request();
        $request_id = isset($_POST['request_id']) ? absint($_POST['request_id']) : 0;
        $status = isset($_POST['status']) ? sanitize_key($_POST['status']) : '';

        if (!$request_id || !$status) {
            wp_send_json_error(['message' => __('Missing request ID or status', 'senna-finance')], 400);
        }

        $labels = $this->get_smart_apply_status_labels();
        if (!isset($labels[$status])) {
            wp_send_json_error(['message' => __('Invalid status', 'senna-finance')], 400);
        }

        $this->ensure_smart_apply_requests_table();
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_smart_apply_requests';
        $owned = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$table} WHERE id = %d AND user_id = %d",
            $request_id,
            $user_id
        ));

        if (!$owned) {
            wp_send_json_error(['message' => __('Request not found', 'senna-finance')], 404);
        }

        $updated = $wpdb->update(
            $table,
            [
                'status' => $status,
                'updated_at' => current_time('mysql')
            ],
            ['id' => $request_id]
        );

        if ($updated === false) {
            wp_send_json_error(['message' => __('Unable to update request', 'senna-finance')]);
        }

        wp_send_json_success([
            'message' => __('Smart message request updated', 'senna-finance'),
            'status_label' => $labels[$status]
        ]);
    }

    public function remove_smart_apply_request()
    {
        $user_id = $this->verify_request();
        $request_id = isset($_POST['request_id']) ? absint($_POST['request_id']) : 0;

        if (!$request_id) {
            wp_send_json_error(['message' => __('Missing request ID', 'senna-finance')], 400);
        }

        $this->ensure_smart_apply_requests_table();
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_smart_apply_requests';
        $owned = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$table} WHERE id = %d AND user_id = %d",
            $request_id,
            $user_id
        ));

        if (!$owned) {
            wp_send_json_error(['message' => __('Request not found', 'senna-finance')], 404);
        }

        $updated = $wpdb->update(
            $table,
            [
                'status' => 'cancelled',
                'updated_at' => current_time('mysql')
            ],
            ['id' => $request_id]
        );

        if ($updated === false) {
            wp_send_json_error(['message' => __('Unable to remove request', 'senna-finance')]);
        }

        wp_send_json_success([
            'message' => __('Request removed', 'senna-finance'),
            'total' => $this->get_smart_apply_count($user_id)
        ]);
    }

    public function submit_smart_apply_brief()
    {
        $user_id = $this->verify_request();

        $role_focus = sanitize_text_field($_POST['role_focus'] ?? '');
        $target_locations = sanitize_text_field($_POST['target_locations'] ?? '');
        $compensation = sanitize_text_field($_POST['compensation'] ?? '');
        $additional_notes = sanitize_textarea_field($_POST['additional_notes'] ?? '');

        if (empty($role_focus)) {
            wp_send_json_error(['message' => __('Describe the type of roles you want MENA Careers to target', 'senna-finance')], 400);
        }

        $preferences = [
            'role_focus' => $role_focus,
            'target_locations' => $target_locations,
            'compensation' => $compensation,
            'notes' => $additional_notes
        ];

        $this->ensure_smart_apply_requests_table();
        global $wpdb;
        $table = $wpdb->prefix . 'sffc_smart_apply_requests';
        $inserted = $wpdb->insert($table, [
            'user_id' => $user_id,
            'request_type' => 'custom',
            'status' => 'pending_review',
            'preferences' => wp_json_encode($preferences)
        ]);

        if ($inserted === false) {
            wp_send_json_error(['message' => __('Unable to submit request', 'senna-finance')]);
        }

        $user = get_userdata($user_id);
        $user_name = $user ? $user->display_name : __('MENA Careers member', 'senna-finance');
        $user_email = $user ? $user->user_email : '';
        $admin_email = get_option('admin_email');
        $subject = sprintf('[MENA Careers] Smart message brief submitted by %s', $user_name);
        $message = "A custom Smart message brief was submitted.\n\n";
        $message .= "User: {$user_name} ({$user_email})\n";
        $message .= "Role focus: {$role_focus}\n";
        if ($target_locations) {
            $message .= "Locations: {$target_locations}\n";
        }
        if ($compensation) {
            $message .= "Compensation: {$compensation}\n";
        }
        if ($additional_notes) {
            $message .= "Notes: {$additional_notes}\n";
        }
        $message .= "Manage queue: " . admin_url('admin.php?page=sffc-recruiter-outreach');
        wp_mail($admin_email, $subject, $message);

        wp_send_json_success([
            'message' => __('Thanks! Your preferences were saved.', 'senna-finance'),
            'total' => $this->get_smart_apply_count($user_id)
        ]);
    }

    /**
     * Get user's introduction usage for current month
     */
    public function get_intro_usage()
    {
        $user_id = $this->verify_request();

        $limits = $this->get_intro_limits($user_id);
        $current_usage = $this->get_intro_usage_count($user_id);
        $remaining = $limits['monthly_limit'] - $current_usage;

        wp_send_json_success([
            'current' => $current_usage,
            'limit' => $limits['monthly_limit'],
            'remaining' => max(0, $remaining),
            'is_premium' => $limits['is_premium'],
            'reset_date' => date('F 1', strtotime($limits['reset_date']))
        ]);
    }

    private function get_intro_status_labels()
    {
        return [
            'pending_review' => __('Under Review', 'senna-finance'),
            'approved' => __('Approved', 'senna-finance'),
            'sent' => __('Sent to Recruiter', 'senna-finance'),
            'awaiting_response' => __('Awaiting Response', 'senna-finance'),
            'accepted' => __('Accepted', 'senna-finance'),
            'rejected' => __('Not Proceeding', 'senna-finance'),
            'expired' => __('Expired', 'senna-finance')
        ];
    }

    /**
     * Get user's introduction requests with status
     */
    public function get_intro_requests()
    {
        $user_id = $this->verify_request();

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_introduction_requests';

        // Check if table exists
        if ($wpdb->get_var("SHOW TABLES LIKE '{$table}'") !== $table) {
            wp_send_json_success(['items' => []]);
            return;
        }

        // Get user's intro requests (exclude withdrawn entries)
        $requests = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table} WHERE user_id = %d AND (status IS NULL OR status != 'withdrawn') ORDER BY created_at DESC",
            $user_id
        ), ARRAY_A);

        // Enrich with job and recruiter details
        $post_model = new SFFC_CRM_Post();
        $status_labels = $this->get_intro_status_labels();
        foreach ($requests as &$request) {
            $post = $post_model->get($request['job_id']);
            if ($post && is_array($post)) {
                // Job details
                $request['job_title'] = $post['role_title'] ?? 'Untitled Role';
                $request['job_company'] = $post['company'] ?? 'Unknown Company';
                $request['job_location'] = $post['location'] ?? '';
                $request['job_sector'] = $post['sector'] ?? '';
                $request['job_seniority'] = $post['seniority'] ?? '';

                // Recruiter details (from the joined recruiter table)
                $request['recruiter_name'] = $post['recruiter_name'] ?? 'Hiring Team';
                $request['recruiter_email'] = $post['recruiter_email'] ?? '';
                $request['recruiter_firm'] = $post['recruiter_firm'] ?? '';
                $request['recruiter_photo'] = $post['recruiter_photo'] ?? '';
                $request['recruiter_role'] = $post['recruiter_title'] ?? ''; // Note: recruiter_title from DB
                $request['recruiter_linkedin'] = $post['recruiter_linkedin'] ?? '';

                // Generate recruiter avatar/initials
                $name_parts = explode(' ', $request['recruiter_name']);
                $initials = '';
                if (count($name_parts) >= 2) {
                    $initials = strtoupper(substr($name_parts[0], 0, 1) . substr($name_parts[1], 0, 1));
                } else if (count($name_parts) === 1) {
                    $initials = strtoupper(substr($name_parts[0], 0, 2));
                }
                $request['recruiter_initials'] = $initials;
            } else {
                // Post not found
                $request['job_title'] = 'Role #' . $request['job_id'];
                $request['job_company'] = 'Unknown';
                $request['job_location'] = '';
                $request['job_sector'] = '';
                $request['job_seniority'] = '';
                $request['recruiter_name'] = 'Unknown';
                $request['recruiter_email'] = '';
                $request['recruiter_firm'] = '';
                $request['recruiter_role'] = '';
                $request['recruiter_linkedin'] = '';
                $request['recruiter_initials'] = 'UK';
            }

            // Format dates
            $request['created_at_formatted'] = human_time_diff(strtotime($request['created_at']), current_time('timestamp')) . ' ago';

            // Status labels
            $request['status_label'] = $status_labels[$request['status']] ?? $request['status'];
        }

        wp_send_json_success([
            'items' => $requests,
            'statuses' => $status_labels
        ]);
    }

    /**
     * Bulk request introductions
     */
    public function bulk_request_intros()
    {
        $user_id = $this->verify_request();

        $posts = isset($_POST['posts']) ? (array)$_POST['posts'] : [];

        if (empty($posts)) {
            wp_send_json_error(['message' => 'No posts provided'], 400);
            return;
        }

        // Check usage limits
        $limits = $this->get_intro_limits($user_id);
        $current_usage = $this->get_intro_usage_count($user_id);
        $remaining = $limits['monthly_limit'] - $current_usage;

        if (count($posts) > $remaining) {
            $upgrade_url = $limits['is_premium'] ? '' : home_url('/membership/');
            wp_send_json_error([
                'message' => 'You only have ' . $remaining . ' introduction requests remaining this month',
                'current_usage' => $current_usage,
                'monthly_limit' => $limits['monthly_limit'],
                'remaining' => $remaining,
                'is_premium' => $limits['is_premium'],
                'upgrade_url' => $upgrade_url
            ]);
            return;
        }

        // Create table if needed
        $this->ensure_intro_requests_table();

        global $wpdb;
        $table = $wpdb->prefix . 'sffc_introduction_requests';
        $post_model = new SFFC_CRM_Post();
        $user = get_userdata($user_id);
        $user_email = $user->user_email;
        $user_name = $user->display_name;
        $inserted_count = 0;

        // Process each post
        foreach ($posts as $post_data) {
            $post_id = isset($post_data['post_id']) ? absint($post_data['post_id']) : 0;
            $recruiter_id = isset($post_data['recruiter_id']) ? absint($post_data['recruiter_id']) : 0;
            $match_score = isset($post_data['match_score']) ? intval($post_data['match_score']) : 0;

            if (!$post_id || !$recruiter_id) {
                continue;
            }

            // Only allow for matches 60% or higher
            if ($match_score < 60) {
                continue;
            }

            // Get post info
            $post = $post_model->get($post_id);
            if (!$post) {
                continue;
            }

            // Insert the request
            $inserted = $wpdb->insert($table, [
                'user_id' => $user_id,
                'job_id' => $post_id,
                'recruiter_id' => $recruiter_id,
                'message' => '',
                'compatibility_score' => $match_score,
                'status' => 'pending_review',
                'created_at' => current_time('mysql')
            ]);

            if ($inserted) {
                $inserted_count++;

                // Add to pipeline with 'interested' stage (now labeled as "Introductions")
                $pipeline_model = new SFFC_CRM_Pipeline();
                $pipeline_item = $pipeline_model->find_by_recruiter_and_post($user_id, $recruiter_id, $post_id);

                if (!$pipeline_item) {
                    // Create new pipeline item
                    $pipeline_model->create([
                        'user_id' => $user_id,
                        'recruiter_id' => $recruiter_id,
                        'post_id' => $post_id,
                        'stage' => 'interested',
                        'source' => 'platform',
                        'notes' => 'Introduction requested (bulk)'
                    ]);
                }
            }
        }

        // Send notification email to MENA Careers team
        if ($inserted_count > 0) {
            $admin_email = get_option('admin_email');
            $subject = 'Bulk Introduction Request: ' . $user_name . ' (' . $inserted_count . ' requests)';
            $message = "A user has submitted {$inserted_count} introduction requests.\n\n";
            $message .= "User: {$user_name} ({$user_email})\n";
            $message .= "View in admin: " . admin_url('admin.php?page=sffc-introductions');
            wp_mail($admin_email, $subject, $message);
        }

        wp_send_json_success([
            'message' => $inserted_count . ' introduction request' . ($inserted_count != 1 ? 's' : '') . ' submitted',
            'count' => $inserted_count
        ]);
    }

    /**
     * Generate concierge intro message using Claude
     */
    public function generate_intro_message()
    {
        $user_id = $this->verify_request();

        $post_id = isset($_POST['post_id']) ? absint($_POST['post_id']) : 0;
        $recruiter_id = isset($_POST['recruiter_id']) ? absint($_POST['recruiter_id']) : 0;

        if (!$post_id || !$recruiter_id) {
            wp_send_json_error(['message' => 'Post ID and Recruiter ID are required'], 400);
        }

        if (!class_exists('SFFC_Claude_API_Manager')) {
            wp_send_json_error(['message' => 'AI concierge is unavailable'], 500);
        }

        $post_model = new SFFC_CRM_Post();
        $post = $post_model->get($post_id);
        if (!$post) {
            wp_send_json_error(['message' => 'Role not found'], 404);
        }

        $recruiter_model = new SFFC_CRM_Recruiter();
        $recruiter = $recruiter_model->get($recruiter_id);
        if (!$recruiter) {
            $recruiter = [
                'name' => $post->recruiter_name ?? 'Hiring Team',
                'first_name' => '',
                'firm' => $post->company ?? '',
                'title' => ''
            ];
        }

        $match_reasons = array_values(array_filter(array_map('sanitize_text_field', (array) ($_POST['match_reasons'] ?? []))));
        $match_warnings = array_values(array_filter(array_map('sanitize_text_field', (array) ($_POST['match_warnings'] ?? []))));
        $keyword_inputs = array_values(array_filter(array_map('sanitize_text_field', (array) ($_POST['keywords'] ?? []))));
        $match_score = isset($_POST['match_score']) ? intval($_POST['match_score']) : 0;

        $cv_excerpt = '';
        $cv_id = isset($_POST['cv_id']) ? sanitize_text_field($_POST['cv_id']) : '';
        if (class_exists('SFFC_CRM_CV_Manager')) {
            $cv_manager = new SFFC_CRM_CV_Manager();
            $cv_entry = null;
            if ($cv_id) {
                $cv_entry = $cv_manager->get_cv_by_id($user_id, $cv_id);
            }
            if (!$cv_entry) {
                $cv_entry = $cv_manager->get_default($user_id);
            }
            if (!empty($cv_entry['content'])) {
                $cv_excerpt = mb_substr(wp_strip_all_tags($cv_entry['content']), 0, 1500);
            }
        }

        $user = get_userdata($user_id);
        $candidate_name = $user ? $user->display_name : 'The candidate';

        $claude = SFFC_Claude_API_Manager::get_instance();
        if (!$claude || !$claude->is_available()) {
            wp_send_json_error(['message' => 'AI concierge is unavailable'], 500);
        }

        $rate_limiter = SFFC_CRM_Rate_Limiter::get_instance();
        $check = $rate_limiter->throttle('intro_generate', $user_id);
        if (is_wp_error($check)) {
            $rate_limiter->add_headers('intro_generate', $user_id);
            wp_send_json_error([
                'message' => $check->get_error_message(),
                'retry_after' => $check->get_error_data()['retry_after'] ?? 60,
            ], 429);
        }

        $strengths_block = $match_reasons ? '- ' . implode("\n- ", array_slice($match_reasons, 0, 5)) : '- Strong technical foundation in finance/risk';
        $concerns_block = $match_warnings ? '- ' . implode("\n- ", array_slice($match_warnings, 0, 3)) : '- None noted';
        $keyword_sentence = $keyword_inputs ? implode(', ', array_slice($keyword_inputs, 0, 5)) : 'financial modelling, stakeholder management, automation';

        $recruiter_name = $recruiter['name'] ?? ($post->recruiter_name ?? 'Hiring Team');
        $recruiter_first = $recruiter['first_name'] ?: explode(' ', trim($recruiter_name))[0];
        $job_title = $post->role_title ?? 'this opportunity';
        $company = $post->company ?? '';
        $location = $post->location ?? '';

        $prompt = "You are drafting a LinkedIn InMail message from {$candidate_name} to {$recruiter_first} about the {$job_title} role at {$company} {$location}.\n\n";
        $prompt .= "CRITICAL REQUIREMENTS:\n";
        $prompt .= "- Maximum 150 words (LinkedIn InMail character limit consideration)\n";
        $prompt .= "- Write in FIRST PERSON from the candidate's perspective (use 'I'/'my', NOT 'we'/'our')\n";
        $prompt .= "- Must be HIGHLY CONVINCING and attention-grabbing\n";
        $prompt .= "- Directly address the recruiter by first name\n";
        $prompt .= "- Reference 2-3 SPECIFIC requirements from the job description\n";
        $prompt .= "- Show clear value alignment with concrete examples\n";
        $prompt .= "- Professional but warm tone\n";
        $prompt .= "- End with clear call-to-action (brief conversation/call)\n";
        $prompt .= "- NO generic phrases like 'I came across your role' or 'I would be a great fit'\n";
        $prompt .= "- Lead with strongest credential or achievement relevant to the role\n\n";
        $prompt .= "STRUCTURE (3 short paragraphs only):\n";
        $prompt .= "1. Opening: Hook with most relevant credential + specific role reference\n";
        $prompt .= "2. Value: 2-3 concrete examples showing alignment with job requirements\n";
        $prompt .= "3. Close: Clear ask for brief conversation\n\n";
        $prompt .= "Match score: {$match_score}%.\n\n";
        if (!empty($cv_excerpt)) {
            $prompt .= "Candidate background:\n{$cv_excerpt}\n\n";
        }
        $prompt .= "Key strengths to highlight:\n{$strengths_block}\n\n";
        $prompt .= "Job requirements/keywords to address: {$keyword_sentence}.\n\n";
        $prompt .= "Remember: Be specific, be brief, be compelling. This needs to stand out in a busy LinkedIn inbox.";

        $api_response = $claude->call_api($prompt, [
            'model' => 'claude-haiku-4-5-20251001',
            'max_tokens' => 450,
            'temperature' => 0.4,
            'mode' => 'crm_matching'
        ]);

        if (empty($api_response['success']) || empty($api_response['content'][0]['text'])) {
            wp_send_json_error(['message' => 'Unable to generate concierge note right now'], 500);
        }

        $message = trim($api_response['content'][0]['text']);

        wp_send_json_success([
            'message' => $message
        ]);
    }

    /**
     * AI generate message for smart outreach
     */
    public function ai_generate()
    {
        $user_id = $this->verify_request();

        $context = isset($_POST['context']) ? sanitize_text_field($_POST['context']) : 'outreach';
        $post_id = isset($_POST['post_id']) ? absint($_POST['post_id']) : 0;
        $recruiter_id = isset($_POST['recruiter_id']) ? absint($_POST['recruiter_id']) : 0;

        if (!$post_id || !$recruiter_id) {
            wp_send_json_error(['message' => 'Post ID and Recruiter ID are required'], 400);
            return;
        }

        // Get post and recruiter data
        $post_model = new SFFC_CRM_Post();
        $post = $post_model->get($post_id);

        if (!$post) {
            wp_send_json_error(['message' => 'Post not found'], 404);
            return;
        }

        // Get user data
        $user = get_userdata($user_id);

        // Build context for AI
        $ai_context = [
            'user_name' => $user->display_name,
            'user_email' => $user->user_email,
            'job_title' => $post->role_title ?? 'this opportunity',
            'company' => $post->company ?? '',
            'recruiter_name' => $post->recruiter_name ?? 'the hiring team',
            'location' => $post->location ?? '',
            'sector' => $post->sector ?? ''
        ];

        // Generate subject and message using existing AI handler
        // This reuses the existing generate_message function
        $_POST['action'] = 'sffc_crm_generate_message';
        $_POST['context_data'] = json_encode($ai_context);
        $_POST['message_type'] = 'initial_outreach';

        $this->generate_message();
    }

    /**
     * Add recruiters to existing outreach list
     */
    public function add_recruiters_to_outreach_list()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $list_id = isset($_POST['list_id']) ? intval($_POST['list_id']) : 0;
        $recruiter_ids = isset($_POST['recruiter_ids']) ? array_map('intval', (array)$_POST['recruiter_ids']) : [];

        if (empty($list_id) || empty($recruiter_ids)) {
            wp_send_json_error(['message' => 'List ID and recruiter IDs are required']);
        }

        // Verify list belongs to user
        $table_lists = $wpdb->prefix . 'sffc_crm_outreach_lists';
        $list = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $table_lists WHERE id = %d AND user_id = %d",
            $list_id,
            $user_id
        ));

        if (!$list) {
            wp_send_json_error(['message' => 'List not found']);
        }

        // Get current max order
        $table_members = $wpdb->prefix . 'sffc_crm_outreach_list_members';
        $max_order = $wpdb->get_var($wpdb->prepare(
            "SELECT MAX(order_position) FROM $table_members WHERE list_id = %d",
            $list_id
        ));
        $order = ($max_order !== null) ? $max_order + 1 : 0;

        // Add recruiters (ignore duplicates)
        $added = 0;
        foreach ($recruiter_ids as $recruiter_id) {
            $inserted = $wpdb->query($wpdb->prepare(
                "INSERT IGNORE INTO $table_members (list_id, recruiter_id, added_at, order_position)
                 VALUES (%d, %d, %s, %d)",
                $list_id,
                $recruiter_id,
                current_time('mysql'),
                $order++
            ));
            if ($inserted) $added++;
        }

        // Update recruiter count
        $new_count = $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM $table_members WHERE list_id = %d",
            $list_id
        ));

        $wpdb->update(
            $table_lists,
            ['recruiter_count' => $new_count, 'updated_at' => current_time('mysql')],
            ['id' => $list_id],
            ['%d', '%s'],
            ['%d']
        );

        wp_send_json_success([
            'added' => $added,
            'message' => "$added recruiter(s) added to list"
        ]);
    }

