    /**
     * Get job outreach lists for current user
     */
    public function get_job_outreach_lists()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $table = $wpdb->prefix . 'sffc_crm_job_outreach_lists';

        // Check if table exists
        if ($wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $table)) !== $table) {
            wp_send_json_success([]);
            return;
        }

        $lists = $wpdb->get_results($wpdb->prepare(
            "SELECT l.*,
                    COUNT(m.id) as job_count,
                    SUM(CASE WHEN m.outreach_status = 'generated' THEN 1 ELSE 0 END) as generated_count,
                    SUM(CASE WHEN m.outreach_status = 'sent' THEN 1 ELSE 0 END) as sent_count,
                    SUM(CASE WHEN m.outreach_status = 'skipped' THEN 1 ELSE 0 END) as skipped_count,
                    MAX(COALESCE(m.updated_at, m.added_at)) as latest_activity_at
             FROM $table l
             LEFT JOIN {$wpdb->prefix}sffc_crm_job_outreach_list_members m ON l.id = m.list_id
             WHERE l.user_id = %d
             GROUP BY l.id
             ORDER BY l.updated_at DESC, l.created_at DESC",
            $user_id
        ), ARRAY_A);

        wp_send_json_success($lists ?: []);
    }

    /**
     * Create new job outreach list with jobs
     */
    public function create_job_outreach_list()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $list_name = isset($_POST['list_name']) ? sanitize_text_field($_POST['list_name']) : '';
        $description = isset($_POST['description']) ? sanitize_textarea_field($_POST['description']) : '';
        $items = $this->parse_job_outreach_items_request();

        if (empty($list_name)) {
            wp_send_json_error('List name is required');
        }

        $table_lists = $wpdb->prefix . 'sffc_crm_job_outreach_lists';
        $table_members = $wpdb->prefix . 'sffc_crm_job_outreach_list_members';

        // Create tables if they don't exist
        $this->create_job_outreach_tables();

        // Insert list
        $wpdb->insert(
            $table_lists,
            [
                'user_id' => $user_id,
                'list_name' => $list_name,
                'description' => $description,
                'created_at' => current_time('mysql')
            ],
            ['%d', '%s', '%s', '%s']
        );

        $list_id = $wpdb->insert_id;

        if (!$list_id) {
            wp_send_json_error('Failed to create list');
        }

        if (!empty($items)) {
            $this->store_job_outreach_items($list_id, $items, 0);
        }

        $this->refresh_job_outreach_list_summary($list_id);

        wp_send_json_success([
            'list_id' => $list_id,
            'message' => 'List created successfully',
            'list' => $this->get_job_outreach_list_snapshot($list_id, $user_id),
        ]);
    }

    /**
     * Add jobs to existing outreach list
     */
    public function add_jobs_to_outreach_list()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $list_id = isset($_POST['list_id']) ? intval($_POST['list_id']) : 0;
        $items = $this->parse_job_outreach_items_request();

        if (empty($list_id) || empty($items)) {
            wp_send_json_error('List ID and role items are required');
        }

        $table_lists = $wpdb->prefix . 'sffc_crm_job_outreach_lists';

        // Verify list belongs to user
        $list = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $table_lists WHERE id = %d AND user_id = %d",
            $list_id,
            $user_id
        ));

        if (!$list) {
            wp_send_json_error('List not found');
        }

        $start_index = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COALESCE(MAX(queue_index), -1) + 1 FROM {$wpdb->prefix}sffc_crm_job_outreach_list_members WHERE list_id = %d",
            $list_id
        ));
        $added = $this->store_job_outreach_items($list_id, $items, max(0, $start_index));
        $this->refresh_job_outreach_list_summary($list_id);

        wp_send_json_success([
            'message' => 'Jobs added to list',
            'added' => $added,
            'list' => $this->get_job_outreach_list_snapshot($list_id, $user_id),
        ]);
    }

    /**
     * Bulk save posts to watchlist
     */
    public function bulk_save_posts()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $post_ids = isset($_POST['post_ids']) ? array_map('intval', (array)$_POST['post_ids']) : [];

        if (empty($post_ids)) {
            wp_send_json_error('No posts provided');
        }

        $table = $wpdb->prefix . 'sffc_crm_saved_posts';
        $saved = 0;

        foreach ($post_ids as $post_id) {
            // Check if already saved
            $exists = $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM $table WHERE user_id = %d AND post_id = %d",
                $user_id,
                $post_id
            ));

            if (!$exists) {
                $wpdb->insert(
                    $table,
                    [
                        'user_id' => $user_id,
                        'post_id' => $post_id,
                        'saved_at' => current_time('mysql')
                    ],
                    ['%d', '%d', '%s']
                );
                $saved++;
            }
        }

        wp_send_json_success([
            'message' => 'Posts saved successfully',
            'saved' => $saved
        ]);
    }

    /**
     * Create job outreach list tables if they don't exist
     */
    /**
     * Get job outreach list details with jobs
     */
    public function get_job_outreach_list_details()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $list_id = isset($_POST['list_id']) ? intval($_POST['list_id']) : 0;

        if (empty($list_id)) {
            wp_send_json_error('List ID is required');
        }

        $table_lists = $wpdb->prefix . 'sffc_crm_job_outreach_lists';
        $table_members = $wpdb->prefix . 'sffc_crm_job_outreach_list_members';

        // Verify list belongs to user
        $list = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $table_lists WHERE id = %d AND user_id = %d",
            $list_id,
            $user_id
        ), ARRAY_A);

        if (!$list) {
            wp_send_json_error('List not found');
        }

        $jobs = $wpdb->get_results($wpdb->prepare(
            "SELECT m.*,
                    p.post_title as fallback_post_title
             FROM $table_members m
             LEFT JOIN {$wpdb->posts} p ON m.post_id = p.ID
             WHERE m.list_id = %d
             ORDER BY m.queue_index ASC, m.added_at ASC",
            $list_id
        ), ARRAY_A);

        $jobs = array_map(function ($job) {
            $reasons = json_decode((string) ($job['reasons'] ?? ''), true);
            if (!is_array($reasons)) {
                $reasons = [];
            }

            return [
                'id' => (int) ($job['id'] ?? 0),
                'post_id' => (int) ($job['post_id'] ?? 0),
                'crm_post_id' => (int) ($job['crm_post_id'] ?? 0),
                'recruiter_id' => (int) ($job['recruiter_id'] ?? 0),
                'queue_index' => (int) ($job['queue_index'] ?? 0),
                'role_title' => (string) ($job['role_title'] ?: ($job['fallback_post_title'] ?? '')),
                'company' => (string) ($job['company'] ?? ''),
                'location' => (string) ($job['location'] ?? ''),
                'recruiter_name' => (string) ($job['recruiter_name'] ?? ''),
                'recruiter_title' => (string) ($job['recruiter_title'] ?? ''),
                'recruiter_email' => (string) ($job['recruiter_email'] ?? ''),
                'recruiter_linkedin' => (string) ($job['recruiter_linkedin'] ?? ''),
                'recruiter_firm' => (string) ($job['recruiter_firm'] ?? ''),
                'match_score' => (int) ($job['match_score'] ?? 0),
                'insight' => (string) ($job['insight'] ?? ''),
                'reasons' => $reasons,
                'outreach_status' => (string) ($job['outreach_status'] ?? 'queued'),
                'target_channel' => (string) ($job['target_channel'] ?? 'email'),
                'generated_subject' => (string) ($job['generated_subject'] ?? ''),
                'generated_body' => (string) ($job['generated_body'] ?? ''),
                'generated_payload' => json_decode((string) ($job['generated_payload'] ?? ''), true) ?: [],
                'generated_with_claude' => !empty($job['generated_with_claude']),
                'last_generated_at' => (string) ($job['last_generated_at'] ?? ''),
                'sent_at' => (string) ($job['sent_at'] ?? ''),
                'skipped_at' => (string) ($job['skipped_at'] ?? ''),
                'added_at' => (string) ($job['added_at'] ?? ''),
                'updated_at' => (string) ($job['updated_at'] ?? ''),
            ];
        }, $jobs ?: []);

        $summary = [
            'total' => count($jobs),
            'generated' => count(array_filter($jobs, function ($job) {
                return ($job['outreach_status'] ?? '') === 'generated';
            })),
            'sent' => count(array_filter($jobs, function ($job) {
                return ($job['outreach_status'] ?? '') === 'sent';
            })),
            'skipped' => count(array_filter($jobs, function ($job) {
                return ($job['outreach_status'] ?? '') === 'skipped';
            })),
        ];

        wp_send_json_success([
            'list' => $list,
            'jobs' => $jobs ?: [],
            'summary' => $summary,
        ]);
    }

