    public function save_job_outreach_draft()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $list_id = isset($_POST['list_id']) ? absint($_POST['list_id']) : 0;
        $member_id = isset($_POST['member_id']) ? absint($_POST['member_id']) : 0;
        $subject = isset($_POST['subject']) ? sanitize_text_field(wp_unslash($_POST['subject'])) : '';
        $body = isset($_POST['body']) ? wp_kses_post(wp_unslash($_POST['body'])) : '';
        $target_channel = isset($_POST['target_channel']) ? sanitize_key(wp_unslash($_POST['target_channel'])) : 'email';
        $generated_with_claude = !empty($_POST['generated_with_claude']) ? 1 : 0;
        $payload = isset($_POST['generated_payload']) ? wp_unslash($_POST['generated_payload']) : '';

        if (!$list_id || !$member_id || $body === '') {
            wp_send_json_error(['message' => 'List, queue item, and generated body are required.'], 400);
        }

        $member = $this->get_job_outreach_list_member_for_user($user_id, $list_id, $member_id);
        if (!$member) {
            wp_send_json_error(['message' => 'Queue item not found.'], 404);
        }

        $table_members = $wpdb->prefix . 'sffc_crm_job_outreach_list_members';
        $updated = $wpdb->update(
            $table_members,
            [
                'generated_subject' => $subject,
                'generated_body' => $body,
                'generated_payload' => is_string($payload) ? $payload : wp_json_encode($payload),
                'generated_with_claude' => $generated_with_claude,
                'target_channel' => $target_channel ?: 'email',
                'outreach_status' => 'generated',
                'last_generated_at' => current_time('mysql'),
            ],
            [
                'id' => $member_id,
                'list_id' => $list_id,
            ],
            ['%s', '%s', '%s', '%d', '%s', '%s', '%s'],
            ['%d', '%d']
        );

        if ($updated === false) {
            wp_send_json_error(['message' => 'Unable to save the generated outreach draft.'], 500);
        }

        $this->refresh_job_outreach_list_summary($list_id);

        wp_send_json_success([
            'message' => 'Outreach draft saved to the queue.',
            'member' => $this->get_job_outreach_list_member_for_user($user_id, $list_id, $member_id),
            'list' => $this->get_job_outreach_list_snapshot($list_id, $user_id),
        ]);
    }

    public function update_job_outreach_member_status()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $list_id = isset($_POST['list_id']) ? absint($_POST['list_id']) : 0;
        $member_id = isset($_POST['member_id']) ? absint($_POST['member_id']) : 0;
        $status = isset($_POST['status']) ? sanitize_key(wp_unslash($_POST['status'])) : '';
        $allowed_statuses = ['queued', 'generated', 'sent', 'skipped', 'failed'];

        if (!$list_id || !$member_id || !in_array($status, $allowed_statuses, true)) {
            wp_send_json_error(['message' => 'Valid queue item status is required.'], 400);
        }

        $member = $this->get_job_outreach_list_member_for_user($user_id, $list_id, $member_id);
        if (!$member) {
            wp_send_json_error(['message' => 'Queue item not found.'], 404);
        }

        $table_members = $wpdb->prefix . 'sffc_crm_job_outreach_list_members';
        $update_data = [
            'outreach_status' => $status,
        ];
        if ($status === 'sent') {
            $update_data['sent_at'] = current_time('mysql');
        }
        if ($status === 'skipped') {
            $update_data['skipped_at'] = current_time('mysql');
        }

        $updated = $wpdb->update(
            $table_members,
            $update_data,
            [
                'id' => $member_id,
                'list_id' => $list_id,
            ]
        );

        if ($updated === false) {
            wp_send_json_error(['message' => 'Unable to update the queue item status.'], 500);
        }

        $this->refresh_job_outreach_list_summary($list_id);

        wp_send_json_success([
            'message' => 'Queue item updated.',
            'member' => $this->get_job_outreach_list_member_for_user($user_id, $list_id, $member_id),
            'list' => $this->get_job_outreach_list_snapshot($list_id, $user_id),
        ]);
    }

    private function create_job_outreach_tables()
    {
        global $wpdb;

        $lists_table = $wpdb->prefix . 'sffc_crm_job_outreach_lists';
        $members_table = $wpdb->prefix . 'sffc_crm_job_outreach_list_members';
        $lists_exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $lists_table)) === $lists_table;
        $members_exists = $wpdb->get_var($wpdb->prepare("SHOW TABLES LIKE %s", $members_table)) === $members_table;
        $has_generated_body = $members_exists && $wpdb->get_var("SHOW COLUMNS FROM {$members_table} LIKE 'generated_body'");
        $has_total_items = $lists_exists && $wpdb->get_var("SHOW COLUMNS FROM {$lists_table} LIKE 'total_items'");

        if ($lists_exists && $members_exists && $has_generated_body && $has_total_items) {
            return;
        }

        if (class_exists('SFFC_CRM_Database_Schema')) {
            SFFC_CRM_Database_Schema::get_instance()->force_schema_update();
            return;
        }
    }

    private function parse_job_outreach_items_request()
    {
        $items = [];
        if (isset($_POST['items'])) {
            $decoded = json_decode(wp_unslash($_POST['items']), true);
            if (is_array($decoded)) {
                $items = $decoded;
            }
        }

        if (empty($items) && !empty($_POST['post_ids']) && is_array($_POST['post_ids'])) {
            $items = array_map(function ($post_id) {
                return ['jobs_post_id' => absint($post_id)];
            }, (array) $_POST['post_ids']);
        }

        return array_values(array_filter($items, function ($item) {
            return is_array($item) && !empty($item);
        }));
    }

    private function store_job_outreach_items($list_id, array $items, $start_index = 0)
    {
        global $wpdb;

        $table_members = $wpdb->prefix . 'sffc_crm_job_outreach_list_members';
        $added = 0;
        $queue_index = max(0, (int) $start_index);

        foreach ($items as $item) {
            $post_id = absint($item['jobs_post_id'] ?? $item['post_id'] ?? 0);
            if ($post_id <= 0) {
                continue;
            }

            $exists = $wpdb->get_var($wpdb->prepare(
                "SELECT COUNT(*) FROM {$table_members} WHERE list_id = %d AND post_id = %d",
                $list_id,
                $post_id
            ));

            if ($exists) {
                continue;
            }

            $reasons = isset($item['reasons']) && is_array($item['reasons']) ? array_map('sanitize_text_field', $item['reasons']) : [];
            $inserted = $wpdb->insert(
                $table_members,
                [
                    'list_id' => $list_id,
                    'post_id' => $post_id,
                    'crm_post_id' => absint($item['crmPostId'] ?? $item['crm_post_id'] ?? 0),
                    'recruiter_id' => absint($item['recruiterId'] ?? $item['recruiter_id'] ?? 0),
                    'queue_index' => $queue_index,
                    'recruiter_name' => sanitize_text_field($item['recruiterName'] ?? $item['recruiter_name'] ?? ''),
                    'recruiter_title' => sanitize_text_field($item['recruiterTitle'] ?? $item['recruiter_title'] ?? ''),
                    'recruiter_email' => sanitize_email($item['recruiterEmail'] ?? $item['recruiter_email'] ?? ''),
                    'recruiter_linkedin' => esc_url_raw($item['recruiterLinkedIn'] ?? $item['recruiter_linkedin'] ?? ''),
                    'recruiter_firm' => sanitize_text_field($item['recruiterFirm'] ?? $item['recruiter_firm'] ?? ''),
                    'role_title' => sanitize_text_field($item['roleTitle'] ?? $item['role_title'] ?? get_the_title($post_id)),
                    'company' => sanitize_text_field($item['company'] ?? ''),
                    'location' => sanitize_text_field($item['location'] ?? ''),
                    'match_score' => absint($item['matchScore'] ?? $item['match_score'] ?? 0),
                    'insight' => sanitize_text_field($item['insight'] ?? ''),
                    'reasons' => !empty($reasons) ? wp_json_encode($reasons) : '',
                    'outreach_status' => 'queued',
                    'target_channel' => 'email',
                    'added_at' => current_time('mysql'),
                ],
                ['%d', '%d', '%d', '%d', '%d', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%s', '%d', '%s', '%s', '%s', '%s', '%s']
            );

            if ($inserted) {
                $added++;
                $queue_index++;
            }
        }

        return $added;
    }

    private function refresh_job_outreach_list_summary($list_id)
    {
        global $wpdb;

        $table_lists = $wpdb->prefix . 'sffc_crm_job_outreach_lists';
        $table_members = $wpdb->prefix . 'sffc_crm_job_outreach_list_members';
        $summary = $wpdb->get_row($wpdb->prepare(
            "SELECT COUNT(*) as total_items,
                    SUM(CASE WHEN outreach_status = 'generated' THEN 1 ELSE 0 END) as generated_items,
                    SUM(CASE WHEN outreach_status = 'sent' THEN 1 ELSE 0 END) as sent_items,
                    SUM(CASE WHEN outreach_status = 'skipped' THEN 1 ELSE 0 END) as skipped_items,
                    MAX(last_generated_at) as last_generated_at,
                    MAX(sent_at) as last_sent_at
             FROM {$table_members}
             WHERE list_id = %d",
            $list_id
        ), ARRAY_A);

        $wpdb->update(
            $table_lists,
            [
                'total_items' => (int) ($summary['total_items'] ?? 0),
                'generated_items' => (int) ($summary['generated_items'] ?? 0),
                'sent_items' => (int) ($summary['sent_items'] ?? 0),
                'skipped_items' => (int) ($summary['skipped_items'] ?? 0),
                'last_generated_at' => !empty($summary['last_generated_at']) ? $summary['last_generated_at'] : null,
                'last_sent_at' => !empty($summary['last_sent_at']) ? $summary['last_sent_at'] : null,
                'updated_at' => current_time('mysql'),
            ],
            ['id' => $list_id],
            ['%d', '%d', '%d', '%d', '%s', '%s', '%s'],
            ['%d']
        );
    }

    private function get_job_outreach_list_snapshot($list_id, $user_id)
    {
        global $wpdb;

        return $wpdb->get_row($wpdb->prepare(
            "SELECT l.*,
                    COUNT(m.id) as job_count,
                    SUM(CASE WHEN m.outreach_status = 'generated' THEN 1 ELSE 0 END) as generated_count,
                    SUM(CASE WHEN m.outreach_status = 'sent' THEN 1 ELSE 0 END) as sent_count,
                    SUM(CASE WHEN m.outreach_status = 'skipped' THEN 1 ELSE 0 END) as skipped_count
             FROM {$wpdb->prefix}sffc_crm_job_outreach_lists l
             LEFT JOIN {$wpdb->prefix}sffc_crm_job_outreach_list_members m ON l.id = m.list_id
             WHERE l.id = %d AND l.user_id = %d
             GROUP BY l.id",
            $list_id,
            $user_id
        ), ARRAY_A);
    }

    private function get_job_outreach_list_member_for_user($user_id, $list_id, $member_id)
    {
        global $wpdb;

        return $wpdb->get_row($wpdb->prepare(
            "SELECT m.*
             FROM {$wpdb->prefix}sffc_crm_job_outreach_list_members m
             INNER JOIN {$wpdb->prefix}sffc_crm_job_outreach_lists l ON l.id = m.list_id
             WHERE m.id = %d AND m.list_id = %d AND l.user_id = %d",
            $member_id,
            $list_id,
            $user_id
        ), ARRAY_A);
    }

    /**
     * Generate personalized outreach messages using Claude API
     * This is the CORE function that makes multi-recruiter outreach intelligent
     */
    public function generate_outreach_messages()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $recruiter_ids = isset($_POST['recruiter_ids']) ? array_map('intval', (array)$_POST['recruiter_ids']) : [];
        $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;

        if (empty($recruiter_ids)) {
            wp_send_json_error(['message' => 'Recruiter IDs are required']);
        }

        // Get user context (CV, background)
        $user_data = get_userdata($user_id);
        $first_name = get_user_meta($user_id, 'first_name', true) ?: $user_data->display_name;
        $last_name = get_user_meta($user_id, 'last_name', true) ?: '';
        $cv_data = get_user_meta($user_id, 'sffc_cv_data', true) ?: [];

        // Get Claude API manager
        $claude = SFFC_Claude_API_Manager::get_instance();

        $messages = [];
        $table_recruiters = $wpdb->prefix . 'sffc_crm_recruiters';

        foreach ($recruiter_ids as $recruiter_id) {
            // Get recruiter data
            $recruiter = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM $table_recruiters WHERE id = %d",
                $recruiter_id
            ), ARRAY_A);

            if (!$recruiter) continue;

            // Build prompt for Claude
            $prompt = $this->build_outreach_message_prompt($recruiter, $user_data, $cv_data, $post_id);

            // Call Claude API
            $response = $claude->call_api($prompt, [
                'model' => 'claude-3-haiku-20240307',
                'max_tokens' => 500,
                'temperature' => 0.8,
                'mode' => 'career'
            ]);

            $message_body = '';
            if (isset($response['content'][0]['text'])) {
                $message_body = trim($response['content'][0]['text']);
            } else {
                // Fallback if Claude fails
                $message_body = $this->get_fallback_outreach_message($recruiter, $first_name, $last_name);
            }

            // Build mailto URL
            $subject = "Exploring Opportunities in " . ($recruiter['sectors'] ? explode(',', $recruiter['sectors'])[0] : 'Finance');
            $mailto_url = 'mailto:' . rawurlencode($recruiter['email']) .
                '?subject=' . rawurlencode($subject) .
                '&body=' . rawurlencode($message_body);

            $messages[] = [
                'recruiter_id' => $recruiter_id,
                'recruiter_name' => $recruiter['name'],
                'recruiter_email' => $recruiter['email'],
                'recruiter_firm' => $recruiter['firm'],
                'subject' => $subject,
                'message' => $message_body,
                'mailto_url' => $mailto_url
            ];
        }

        wp_send_json_success([
            'messages' => $messages,
            'total' => count($messages)
        ]);
    }

    /**
     * Build prompt for Claude to generate personalized outreach message
     */
    private function build_outreach_message_prompt($recruiter, $user_data, $cv_data, $post_id = 0)
    {
        $recruiter_name = $recruiter['name'];
        $recruiter_firm = $recruiter['firm'] ?: 'their firm';
        $recruiter_title = $recruiter['title'] ?: 'recruiter';
        $recruiter_sectors = $recruiter['sectors'] ? explode(',', $recruiter['sectors'])[0] : 'finance';

        $candidate_name = $user_data->first_name ?: $user_data->display_name;
        $candidate_background = !empty($cv_data['summary']) ? $cv_data['summary'] : 'finance professional';

        $prompt = "Generate a professional, personalized outreach email to a recruiter.

Recruiter Details:
- Name: {$recruiter_name}
- Title: {$recruiter_title}
- Firm: {$recruiter_firm}
- Focus: {$recruiter_sectors}

Candidate Background:
- Name: {$candidate_name}
- Background: {$candidate_background}

Requirements:
1. Personalized opening that mentions the recruiter specifically
2. Brief reference to their firm or sector focus
3. Concise explanation of candidate's background (2-3 sentences max)
4. Clear ask for a 15-minute exploratory call
5. Professional but warm tone
6. 150-200 words maximum
7. Do NOT include subject line
8. Do NOT use placeholders - use actual details provided
9. Make it unique - avoid generic templates

Generate ONLY the email body text:";

        return $prompt;
    }

    /**
     * Fallback outreach message when Claude API is unavailable
     */
    private function get_fallback_outreach_message($recruiter, $first_name, $last_name)
    {
        $name = trim($first_name . ' ' . $last_name);
        if ($name === '') {
            $current_user = wp_get_current_user();
            if ($current_user instanceof WP_User && $current_user->exists()) {
                $name = trim((string) $current_user->first_name);
                if ($name === '') {
                    $name_parts = preg_split('/\s+/', trim((string) $current_user->display_name));
                    $name = trim((string) ($name_parts[0] ?? ''));
                }
            }
        }
        if ($name === '') {
            $name = 'Candidate';
        }
        $recruiter_first = explode(' ', $recruiter['name'])[0];
        $firm = $recruiter['firm'] ?: 'your firm';

        return "Hi {$recruiter_first},

I came across your profile and was impressed by your work at {$firm}. I'm currently exploring opportunities in finance and would love to connect with experienced recruiters who understand this market.

With my background in [YOUR EXPERIENCE], I believe I could be a strong fit for the roles you typically work on.

Would you be open to a brief 15-minute call to discuss potential opportunities and get your insights on the current market?

Thank you for considering my request.

Best regards,
{$name}";
    }

    /**
     * Track outreach sent from carousel
     */
    public function track_outreach_sent()
    {
        $user_id = $this->verify_request();
        global $wpdb;

        $recruiter_id = isset($_POST['recruiter_id']) ? intval($_POST['recruiter_id']) : 0;
        $list_id = isset($_POST['list_id']) ? intval($_POST['list_id']) : 0;
        $subject = isset($_POST['subject']) ? sanitize_text_field($_POST['subject']) : '';
        $message = isset($_POST['message']) ? wp_kses_post($_POST['message']) : '';

        if (!$recruiter_id) {
            wp_send_json_error(['message' => 'Missing recruiter ID'], 400);
        }

        // Get recruiter data
        $table_recruiters = $wpdb->prefix . 'sffc_crm_recruiters';
        $recruiter = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $table_recruiters WHERE id = %d",
            $recruiter_id
        ), ARRAY_A);

        if (!$recruiter) {
            wp_send_json_error(['message' => 'Recruiter not found'], 404);
        }

        // Insert outreach record
        $table_outreach = $wpdb->prefix . 'sffc_crm_outreach';
        $inserted = $wpdb->insert(
            $table_outreach,
            [
                'user_id' => $user_id,
                'recruiter_id' => $recruiter_id,
                'list_id' => $list_id > 0 ? $list_id : null,
                'subject' => $subject,
                'message' => $message,
                'sent_at' => current_time('mysql'),
                'channel' => 'email',
                'status' => 'sent'
            ],
            ['%d', '%d', '%d', '%s', '%s', '%s', '%s', '%s']
        );

        if (!$inserted) {
            wp_send_json_error(['message' => 'Failed to track outreach'], 500);
        }

        // Update recruiter status to contacted if not already
        if ($recruiter['status'] === 'new' || $recruiter['status'] === 'identified') {
            $wpdb->update(
                $table_recruiters,
                ['status' => 'contacted'],
                ['id' => $recruiter_id],
                ['%s'],
                ['%d']
            );
        }

        // Update list's last_outreach_at if part of a list
        if ($list_id > 0) {
            $table_lists = $wpdb->prefix . 'sffc_crm_outreach_lists';
            $wpdb->update(
                $table_lists,
                ['last_outreach_at' => current_time('mysql')],
                ['id' => $list_id, 'user_id' => $user_id],
                ['%s'],
                ['%d', '%d']
            );
        }

        // Log activity
        $table_activity = $wpdb->prefix . 'sffc_crm_activity';
        $wpdb->insert(
            $table_activity,
            [
                'user_id' => $user_id,
                'recruiter_id' => $recruiter_id,
                'activity_type' => 'outreach_sent',
                'description' => sprintf('Sent outreach email: "%s"', $subject),
                'metadata' => json_encode([
                    'list_id' => $list_id,
                    'channel' => 'email',
                    'subject' => $subject
                ]),
                'created_at' => current_time('mysql')
            ],
            ['%d', '%d', '%s', '%s', '%s', '%s']
        );

        wp_send_json_success([
            'message' => 'Outreach tracked successfully',
            'recruiter_id' => $recruiter_id,
            'status' => 'sent'
        ]);
    }

    /**
     * SMART KEYWORD FILTER - Advanced filters (hard requirements and keyword matching)
     * Note: Basic filters (seniority/experience) are done in main loop for performance
     * Returns true if match should proceed, false if it should be filtered out
     *
     * @param array $cv_parsed Pre-parsed CV data (raw_text, current_title, seniority, experience_years)
     * @param array $post Job post data (must have insights pre-computed)
     * @return bool True if match should proceed, false to filter out
     */
    private function smart_filter_match($cv_parsed, $post)
    {
        // Use pre-parsed CV data (massive performance improvement)
        $cv_text = $cv_parsed['raw_text'];

        // FILTER 1: Hard requirements (qualifications like CPA, ACCA, etc.)
        if (!$this->check_hard_requirements($cv_text, $post)) {
            return false; // Filter out
        }

        // FILTER 2: Must-have requirement keywords (tax, consolidation, etc.)
        $insights = $post['insights'] ?? [];
        $cv_lower = $cv_parsed['lower']; // Use pre-cached lowercase

        if (!empty($insights['must_have_keywords'])) {
            $required_keywords = $insights['must_have_keywords'];
            $hits = 0;
            foreach ($required_keywords as $keyword) {
                if (strpos($cv_lower, $keyword) !== false) {
                    $hits++;
                }
            }

            $minimum_hits = max(1, (int) ceil(count($required_keywords) * 0.6));
            if ($hits < $minimum_hits) {
                return false;
            }
        }

        if (!empty($insights['functional_tags'])) {
            $cv_tags = $this->extract_cv_functional_tags($cv_text);
            $overlap = array_intersect($insights['functional_tags'], $cv_tags);
            if (empty($overlap)) {
                return false;
            }
        }

        // Passed all filters
        return true;
    }

    /**
     * Extract current/latest role title from CV
     */
    private function extract_current_role_title($cv_text)
    {
        // Look for common CV section headers
        $patterns = [
            '/(?:WORK\s+EXPERIENCE|EXPERIENCE|EMPLOYMENT|PROFESSIONAL\s+EXPERIENCE).*?[\r\n]+.*?[\r\n]+\s*([A-Z][^\r\n]{10,80}?)[\r\n]/is',
            '/(?:WORK\s+EXPERIENCE|EXPERIENCE|EMPLOYMENT).*?[\r\n]+\s*([A-Z][^\r\n]{10,80}?)(?:\s+[-–—]\s*|\s+\()/is',
        ];

        foreach ($patterns as $pattern) {
            if (preg_match($pattern, $cv_text, $match)) {
                $title = trim($match[1]);
                // Clean up common artifacts
                $title = preg_replace('/^\s*[•\-\*]\s*/', '', $title);
                $title = preg_replace('/\s+/', ' ', $title);

                // Must be reasonable length and not a date/location
                if (strlen($title) >= 10 && strlen($title) <= 100 && !preg_match('/\d{4}/', $title)) {
                    return $title;
                }
            }
        }

        // Fallback: look for job title before first date range
        if (preg_match('/([A-Z][a-z]+(?:\s+[A-Z][a-z]+)*)\s+[-–—]\s+[A-Z].*?\d{2}\/\d{2}\/\d{2,4}/i', $cv_text, $match)) {
            return trim($match[1]);
        }

        return '';
    }

    /**
     * Classify seniority level from job title
     */
    private function classify_seniority_from_title($title)
    {
        $title_lower = strtolower($title);

        if (preg_match('/intern|internship|off-?cycle|spring|summer analyst|summer intern|placement|graduate program|graduate programme|graduate trainee|trainee/i', $title_lower)) {
            return 'intern';
        }

        // C-Level (highest priority)
        $c_level_keywords = ['chief', 'ceo', 'cfo', 'cto', 'coo', 'cio', 'head of', 'president', 'chairman'];
        foreach ($c_level_keywords as $keyword) {
            if (strpos($title_lower, $keyword) !== false) {
                return 'c_level';
            }
        }

        // Managing Director / Partner
        $md_keywords = ['managing director', 'md ', 'partner', 'principal'];
        foreach ($md_keywords as $keyword) {
            if (strpos($title_lower, $keyword) !== false) {
                return 'md';
            }
        }

        // Director
        $director_keywords = ['director', 'head'];
        foreach ($director_keywords as $keyword) {
            if (strpos($title_lower, $keyword) !== false && strpos($title_lower, 'managing') === false) {
                return 'director';
            }
        }

        // VP / Vice President
        $vp_keywords = ['vice president', 'vp ', ' vp', 'senior manager', 'lead manager'];
        foreach ($vp_keywords as $keyword) {
            if (strpos($title_lower, $keyword) !== false) {
                return 'vp';
            }
        }

        // Associate / Senior Analyst
        $associate_keywords = ['associate', 'senior analyst', 'sr analyst', 'senior associate', 'sr associate'];
        foreach ($associate_keywords as $keyword) {
            if (strpos($title_lower, $keyword) !== false) {
                return 'associate';
            }
        }

        // Analyst (catch-all for junior)
        $analyst_keywords = ['analyst', 'junior', 'assistant', 'coordinator', 'intern'];
        foreach ($analyst_keywords as $keyword) {
            if (strpos($title_lower, $keyword) !== false) {
                return 'analyst';
            }
        }

        // Manager (mid-level)
        if (strpos($title_lower, 'manager') !== false) {
            return 'vp'; // Treat manager as VP level
        }

        return 'unknown';
    }

    /**
     * Check if CV seniority is compatible with JD seniority
     */
    private function seniority_levels_compatible($cv_level, $jd_title_level, $jd_seniority_field)
    {
        // Seniority hierarchy (lower number = more junior)
        $hierarchy = [
            'analyst' => 1,
            'associate' => 2,
            'vp' => 3,
            'director' => 4,
            'md' => 5,
            'partner' => 5,
            'c_level' => 6,
            'unknown' => 2, // Default to associate level if unknown
            'other' => 3    // "Other" typically means mid-level (VP equivalent)
        ];

        $cv_rank = $hierarchy[$cv_level] ?? 2;
        $jd_rank = $hierarchy[$jd_title_level] ?? 2;

        // Also check the seniority field if available
        if (!empty($jd_seniority_field) && isset($hierarchy[$jd_seniority_field])) {
            // For "other", try to infer from years of experience in the JD
            if ($jd_seniority_field === 'other') {
                // Don't override - let the title-based ranking take precedence
                // Only use "other" as fallback if title-based rank is also unknown
                if ($jd_rank === 2) { // Only if we got "unknown" from title
                    $jd_rank = 3; // Treat as mid-level
                }
            } else {
                $jd_rank = max($jd_rank, $hierarchy[$jd_seniority_field]);
            }
        }

        // Allow matching within +/- 1 level
        // Analyst (1) can see: Analyst (1), Associate (2)
        // Associate (2) can see: Analyst (1), Associate (2), VP (3)
        // VP (3) can see: Associate (2), VP (3), Director (4)
        // BUT: Analyst (1) should NOT see C-Level (6)

        $difference = abs($jd_rank - $cv_rank);

        // Hard filter: If difference is 3+ levels, filter out
        if ($difference >= 3) {
            return false;
        }

        // Analysts shouldn't see manager-level (VP+) roles
        if ($cv_rank === 1 && $jd_rank >= 3) {
            return false;
        }

        // Associates shouldn't see director-level (4+) roles
        if ($cv_rank === 2 && $jd_rank >= 4) {
            return false;
        }

        // Don't allow juniors to see very senior roles
        if ($cv_rank <= 2 && $jd_rank >= 5) {
            return false;
        }

        return true;
    }

    /**
     * Check if experience years are compatible
     */
    private function experience_years_compatible($cv_years, $jd_seniority, $jd_title, $detected_years = 0)
    {
        // Extract required years from job title/description (ENHANCED detection)
        $required_years = max(0, intval($detected_years));

        // Look for explicit year requirements in title
        if (preg_match('/(\d+)\+?\s*years?/i', $jd_title, $match)) {
            $required_years = intval($match[1]);
        }

        // Check seniority field for minimum years (STRICTER requirements)
        $seniority_minimums = [
            'analyst' => 0,
            'associate' => 2,
            'vp' => 5,        // Increased from 4
            'director' => 8,   // Increased from 7
            'md' => 12,
            'partner' => 15,
            'c_level' => 15
        ];

        if (isset($seniority_minimums[$jd_seniority])) {
            $required_years = max($required_years, $seniority_minimums[$jd_seniority]);
        }

        // If no requirement found, allow
        if ($required_years == 0) {
            return true;
        }

        // STRICTER FILTERING: Prevent under-qualified matches
        // New logic: Must be within 1 year of minimum requirement (not 50% ratio)

        $gap = $required_years - $cv_years;

        // For analyst/associate: Allow 0.5 year buffer
        if (in_array($jd_seniority, ['analyst', 'associate'])) {
            if ($gap > 0.5) {
                return false; // Too junior
            }
        }
        // For VP: Must have at least required years (no buffer)
        elseif ($jd_seniority === 'vp') {
            if ($gap > 0) {
                return false; // Too junior - strict for VP roles
            }
        }
        // For senior roles: Must have at least required years
        elseif (in_array($jd_seniority, ['director', 'md', 'partner', 'c_level'])) {
            if ($gap > 0) {
                return false; // Too junior - strict for senior roles
            }
        }
        // For roles with explicit year requirements (e.g., "5+ years")
        else {
            if ($gap > 1) {
                return false; // Allow 1 year buffer for other roles
            }
        }

        // Prevent OVER-qualified matches (15+ years for analyst role)
        $over_qualified_threshold = [
            'analyst' => 5,     // Max 5 years for analyst
            'associate' => 8,   // Max 8 years for associate
            'vp' => 15,         // Max 15 years for VP
            'director' => 25,   // Max 25 years for director
        ];

        if (isset($over_qualified_threshold[$jd_seniority])) {
            if ($cv_years > $over_qualified_threshold[$jd_seniority]) {
                return false; // Too senior
            }
        }

        // Allow if within acceptable range
        return true;
    }

    /**
     * Check hard requirements (qualifications, certifications, domain expertise)
     */
    private function check_hard_requirements($cv_text, $post)
    {
        $cv_lower = strtolower($cv_text);
        $jd_text = strtolower($this->build_jd_text($post));
        $requirements = $post['requirements'] ?? [];

        if (is_string($requirements)) {
            $requirements = json_decode($requirements, true) ?: [];
        }

        // Combine requirements and JD text
        $full_requirements = $jd_text . ' ' . implode(' ', $requirements);
        $content_lower = strtolower($post['content'] ?? '');

        // CRITICAL DOMAIN EXPERTISE REQUIREMENTS
        // These are "must-have" skills mentioned in job description
        $critical_domain_requirements = [
            // Consolidation experience (finance operations)
            'consolidation' => [
                'required_phrases' => ['consolidation required', 'consolidation experience is required', 'consolidation is required', 'must have consolidation'],
                'cv_must_have' => ['consolidation', 'consolidating', 'consolidated financial']
            ],
            // Tax experience (finance compliance)
            'tax' => [
                'required_phrases' => ['tax required', 'tax experience is required', 'tax is required', 'must have tax', 'some experience in tax', 'tax exposure'],
                'cv_must_have' => ['tax', 'vat', 'taxation', 'tax planning', 'tax compliance']
            ],
            // Audit experience
            'audit' => [
                'required_phrases' => ['audit required', 'audit experience is required', 'audit background', 'audit is required'],
                'cv_must_have' => ['audit', 'auditing', 'auditor', 'external audit', 'internal audit']
            ],
        ];

        // Check critical domain requirements
        foreach ($critical_domain_requirements as $domain => $config) {
            // Check if ANY of the "required phrases" exist in the JD
            $is_required = false;
            foreach ($config['required_phrases'] as $phrase) {
                if (strpos($content_lower, $phrase) !== false || strpos($full_requirements, $phrase) !== false) {
                    $is_required = true;
                    break;
                }
            }

            if ($is_required) {
                // Check if CV has the required experience
                $has_experience = false;
                foreach ($config['cv_must_have'] as $cv_keyword) {
                    if (strpos($cv_lower, $cv_keyword) !== false) {
                        $has_experience = true;
                        break;
                    }
                }

                // If required but CV doesn't have it, filter out
                if (!$has_experience) {
                    error_log("CRM Match Filter: Missing critical domain expertise: {$domain}");
                    return false;
                }
            }
        }

        // PROFESSIONAL QUALIFICATIONS
        // Check for accounting qualifications (both "required" and "preferred")
        $accounting_qual_patterns = [
            'required' => ['qualified accountant', 'professional qualifications (e.g. ca, acca, cpa) required', 'cpa required', 'acca required', 'aca required'],
            'preferred' => ['professional qualifications (e.g. ca, acca, cpa) preferred', 'professional qualifications (e.g', 'ca, acca, cpa)', 'accounting qualification']
        ];

        $accounting_qual_required = false;
        // Check for "required" first
        foreach ($accounting_qual_patterns['required'] as $pattern) {
            if (strpos($content_lower, $pattern) !== false) {
                $accounting_qual_required = true;
                break;
            }
        }

        // If not required, check if "preferred" (we'll be lenient here)
        if (!$accounting_qual_required) {
            foreach ($accounting_qual_patterns['preferred'] as $pattern) {
                if (strpos($content_lower, $pattern) !== false) {
                    // For "preferred" qualifications, give partial credit if they have finance degree
                    // But still check if they have the actual qualification
                    $has_accounting_qual = (
                        strpos($cv_lower, 'acca') !== false ||
                        strpos($cv_lower, 'cpa') !== false ||
                        strpos($cv_lower, 'aca') !== false ||
                        strpos($cv_lower, 'chartered accountant') !== false ||
                        strpos($cv_lower, 'ca ') !== false
                    );

                    // If preferred and they don't have it, don't filter out completely
                    // Let Claude decide based on overall profile
                    break;
                }
            }
        } else {
            // Qualification is REQUIRED - must have it
            $has_accounting_qual = (
                strpos($cv_lower, 'acca') !== false ||
                strpos($cv_lower, 'cpa') !== false ||
                strpos($cv_lower, 'aca') !== false ||
                strpos($cv_lower, 'chartered accountant') !== false ||
                strpos($cv_lower, 'ca ') !== false ||
                strpos($cv_lower, ' ca,') !== false
            );

            if (!$has_accounting_qual) {
                error_log("CRM Match Filter: Missing required accounting qualification");
                return false;
            }
        }

        // Other hard requirements (CFA, MBA, etc.)
        $other_hard_requirements = [
            'cfa charter' => ['cfa charter', 'cfa level iii', 'cfa level 3'],
            'mba required' => ['mba', 'master of business administration'],
        ];

        foreach ($other_hard_requirements as $requirement_pattern => $cv_patterns) {
            if (strpos($full_requirements, $requirement_pattern) !== false) {
                $has_qualification = false;
                foreach ($cv_patterns as $cv_pattern) {
                    if (strpos($cv_lower, $cv_pattern) !== false) {
                        $has_qualification = true;
                        break;
                    }
                }

                if (!$has_qualification) {
                    error_log("CRM Match Filter: Missing requirement: {$requirement_pattern}");
                    return false;
                }
            }
        }

        return true; // Passed all hard requirements
    }

    /**
     * Apply Claude semantic scoring to matches (BATCHED for performance)
     */
    private function apply_semantic_scoring($cv_text, $matches)
    {
        $this->semantic_scoring_active = false;

        // Check if Claude API Manager is available
        if (!class_exists('SFFC_Claude_API_Manager')) {
            error_log('CRM Matches: SFFC_Claude_API_Manager class not found');
            return $matches; // Fallback to keyword scores
        }

        $claude = SFFC_Claude_API_Manager::get_instance();
        error_log('CRM Matches: Claude API Manager initialized, processing ' . count($matches) . ' matches');

        $this->semantic_scoring_active = true;

        // Separate cached and uncached matches
        $cached_matches = [];
        $uncached_matches = [];

        foreach ($matches as $match) {
            $cache_key = 'claude_crm_score_' . md5($cv_text . ($match['id'] ?? ''));
            $cached_score = get_transient($cache_key);

            if ($cached_score !== false) {
                // Use cached score
                $match['semantic_score'] = $cached_score['score'];
                $match['semantic_reasoning'] = $cached_score['reasoning'];
                $match['semantic_strengths'] = $cached_score['strengths'];
                $match['semantic_concerns'] = $cached_score['concerns'];
                $match['match_score'] = $cached_score['score'];
                if (!empty($cached_score['reasons'])) {
                    $match['match_reasons'] = $this->merge_reason_lists($match['match_reasons'] ?? [], $cached_score['reasons']);
                }
                if (!empty($cached_score['warnings'])) {
                    $match['match_warnings'] = $this->merge_reason_lists($match['match_warnings'] ?? [], $cached_score['warnings'], 3);
                }
                $cached_matches[] = $match;
            } else {
                $uncached_matches[] = $match;
            }
        }

        error_log('CRM Matches: ' . count($cached_matches) . ' cached, ' . count($uncached_matches) . ' need scoring');

        // Process uncached matches in slightly larger batches to reduce round-trips.
        $batch_size = 6;
        $batches = array_chunk($uncached_matches, $batch_size);

        foreach ($batches as $batch_index => $batch) {
            error_log('CRM Matches: Processing batch ' . ($batch_index + 1) . '/' . count($batches) . ' with ' . count($batch) . ' matches');

            // Try batch scoring first
            $batch_results = $this->call_claude_batch_scoring($cv_text, $batch, $claude);

            if ($batch_results && count($batch_results) === count($batch)) {
                // Batch succeeded - apply scores
                foreach ($batch as $index => $match) {
                    $result = $batch_results[$index];
                    $match['semantic_score'] = $result['score'];
                    $match['semantic_reasoning'] = $result['reasoning'];
                    $match['semantic_strengths'] = $result['strengths'];
                    $match['semantic_concerns'] = $result['concerns'];
                    $match['match_score'] = $result['score'];
                    if (!empty($result['reasons'])) {
                        $match['match_reasons'] = $this->merge_reason_lists($match['match_reasons'] ?? [], $result['reasons']);
                    }
                    if (!empty($result['warnings'])) {
                        $match['match_warnings'] = $this->merge_reason_lists($match['match_warnings'] ?? [], $result['warnings'], 3);
                    }

                    // Cache individually
                    $cache_key = 'claude_crm_score_' . md5($cv_text . ($match['id'] ?? ''));
                    set_transient($cache_key, $result, DAY_IN_SECONDS);

                    $cached_matches[] = $match;
                }
            } else {
                // Batch failed - fallback to individual scoring
                error_log('CRM Matches: Batch scoring failed, falling back to individual scoring');
                foreach ($batch as $match) {
                    $jd_text = $this->build_jd_text($match);
                    $claude_result = $this->call_claude_for_scoring($cv_text, $jd_text, $match, $claude);

                    if ($claude_result) {
                        $match['semantic_score'] = $claude_result['score'];
                        $match['semantic_reasoning'] = $claude_result['reasoning'];
                        $match['semantic_strengths'] = $claude_result['strengths'];
                        $match['semantic_concerns'] = $claude_result['concerns'];
                        $match['match_score'] = $claude_result['score'];
                        if (!empty($claude_result['reasons'])) {
                            $match['match_reasons'] = $this->merge_reason_lists($match['match_reasons'] ?? [], $claude_result['reasons']);
                        }
                        if (!empty($claude_result['warnings'])) {
                            $match['match_warnings'] = $this->merge_reason_lists($match['match_warnings'] ?? [], $claude_result['warnings'], 3);
                        }

                        // Cache for 24 hours
                        $cache_key = 'claude_crm_score_' . md5($cv_text . ($match['id'] ?? ''));
                        set_transient($cache_key, $claude_result, DAY_IN_SECONDS);
                    }

                    $cached_matches[] = $match;
                }
            }
        }

        // Re-sort by new scores
        usort($cached_matches, function ($a, $b) {
            return $b['match_score'] - $a['match_score'];
        });

        return $cached_matches;
    }

    /**
     * Call Claude API for semantic scoring
     */
    private function call_claude_for_scoring($cv_text, $jd_text, $post, $claude)
    {
        $prompt = "You are a private equity recruiter specializing in buy-side roles. Score this CV against this job description from 0-100.

CRITICAL SCORING RULES:
1. DOMAIN EXPERTISE MISMATCH = Auto score 0-25
   - Trading/Markets vs Operations/Compliance roles
   - Investment Banking vs Accounting/Tax roles
   - Portfolio Management vs Consolidation/Reporting roles

2. SENIORITY MISMATCH = Auto score 0-20
   - Analyst (0-3 yrs) vs Manager/Director roles (5-10+ yrs)
   - Junior vs C-Level/Head of roles

3. MISSING CRITICAL SKILLS = Major penalty (-30 to -50 points)
   - Job requires \"consolidation\" but CV has no consolidation experience
   - Job requires \"tax\" but CV has no tax/VAT experience
   - Job requires \"audit\" but CV has no audit background

4. YEARS OF EXPERIENCE GAP = Score penalty
   - CV has 4 years, job needs 8+ years = Max score 40

CV:
" . substr($cv_text, 0, 4000) . "

JOB DESCRIPTION:
Title: " . ($post['role_title'] ?? '') . "
Seniority: " . ($post['seniority'] ?? '') . "
" . substr($jd_text, 0, 2000) . "

ANALYSIS CHECKLIST:
- Does CV functional area match job? (e.g., equity derivatives ≠ consolidation/tax)
- Does CV have required domain expertise? (consolidation, tax, audit, etc.)
- Does experience level match? (years + seniority)
- Are qualifications met? (CPA, ACCA, CFA, etc.)

Provide your response in this exact JSON format:
{
  \"score\": 25,
  \"strengths\": [\"Finance background\", \"Quantitative skills\"],
  \"concerns\": [\"NO consolidation experience\", \"NO tax/VAT experience\", \"Wrong functional area: trading not operations\", \"Too junior: 4 years vs 5-8 required\"],
  \"reasoning\": \"Poor match. Candidate has equity derivatives/trading experience but job requires consolidation, tax, and finance operations expertise. Completely different functional areas. Also lacks required experience in consolidation and tax.\"
}

Be EXTREMELY strict on functional area mismatches. Equity derivatives analyst ≠ Finance operations/consolidation role.";

        try {
            // Use SFFC_Claude_API_Manager's call_api method
            $response = $claude->call_api($prompt, [
                'model' => 'claude-haiku-4-5-20251001',
                'max_tokens' => 500,
                'temperature' => 0.3,
                'mode' => 'crm_matching'
            ]);

            if (!empty($response['content'][0]['text'])) {
                $text = $response['content'][0]['text'];

                // Extract JSON from response
                if (preg_match('/\{[\s\S]*\}/', $text, $matches)) {
                    $result = json_decode($matches[0], true);

                    if (isset($result['score'])) {
                        $strengths = $result['strengths'] ?? [];
                        $concerns = $result['concerns'] ?? [];
                        return [
                            'score' => min(100, max(0, intval($result['score']))),
                            'strengths' => $strengths,
                            'concerns' => $concerns,
                            'reasoning' => $result['reasoning'] ?? '',
                            'reasons' => array_slice($strengths, 0, 3),
                            'warnings' => array_slice($concerns, 0, 2)
                        ];
                    }
                }
            }

            error_log('CRM Matches: Claude response missing expected format');
            return null;
        } catch (Exception $e) {
            error_log('CRM Matches: Claude API call failed - ' . $e->getMessage());
            return null;
        }
    }

    /**
     * Call Claude API for batch semantic scoring (Option 6.5)
     * Scores multiple matches in a single API call for better performance
     *
     * @param string $cv_text The CV text
     * @param array $matches Array of job matches to score (max 5 recommended)
     * @param object $claude SFFC_Claude_API_Manager instance
     * @return array|null Array of results matching input order, or null on failure
     */
    private function call_claude_batch_scoring($cv_text, $matches, $claude)
    {
        if (empty($matches)) {
            return null;
        }

        // Build batch prompt with all jobs
        $jobs_text = '';
        foreach ($matches as $index => $match) {
            $jd_text = $this->build_jd_text($match);
            $job_num = $index + 1;

            $jobs_text .= "\n--- JOB #{$job_num} ---\n";
            $jobs_text .= "ID: " . ($match['id'] ?? 'unknown') . "\n";
            $jobs_text .= "Title: " . ($match['role_title'] ?? '') . "\n";
            $jobs_text .= "Seniority: " . ($match['seniority'] ?? '') . "\n";
            $jobs_text .= substr($jd_text, 0, 1500) . "\n";
        }

        $prompt = "You are a private equity recruiter specializing in buy-side roles. Score this CV against " . count($matches) . " job descriptions.

CRITICAL SCORING RULES:
1. DOMAIN EXPERTISE MISMATCH = Auto score 0-25
   - Trading/Markets vs Operations/Compliance roles
   - Investment Banking vs Accounting/Tax roles
   - Portfolio Management vs Consolidation/Reporting roles

2. SENIORITY MISMATCH = Auto score 0-20
   - Analyst (0-3 yrs) vs Manager/Director roles (5-10+ yrs)
   - Junior vs C-Level/Head of roles

3. MISSING CRITICAL SKILLS = Major penalty (-30 to -50 points)
   - Job requires \"consolidation\" but CV has no consolidation experience
   - Job requires \"tax\" but CV has no tax/VAT experience
   - Job requires \"audit\" but CV has no audit background

4. YEARS OF EXPERIENCE GAP = Score penalty
   - CV has 4 years, job needs 8+ years = Max score 40

CV:
" . substr($cv_text, 0, 4000) . "

JOBS TO SCORE:
{$jobs_text}

FOR EACH JOB, CHECK:
- Does CV functional area match job? (e.g., equity derivatives ≠ consolidation/tax)
- Does CV have required domain expertise? (consolidation, tax, audit, etc.)
- Does experience level match? (years + seniority)
- Are qualifications met? (CPA, ACCA, CFA, etc.)

Provide your response as a JSON array with " . count($matches) . " objects in the EXACT same order as the jobs above.

CRITICAL: Return EXACTLY " . count($matches) . " results, one for each job in order (Job #1, Job #2, etc.).

EXAMPLE FORMAT:
[
  {
    \"job_number\": 1,
    \"score\": 25,
    \"strengths\": [\"Finance background\", \"Quantitative skills\"],
    \"concerns\": [\"NO consolidation experience\", \"NO tax experience\", \"Wrong functional area\"],
    \"reasoning\": \"Poor match. Candidate has trading experience but job requires operations/consolidation expertise. Different functional areas.\"
  },
  {
    \"job_number\": 2,
    \"score\": 85,
    \"strengths\": [\"Relevant PE experience\", \"Strong modeling\"],
    \"concerns\": [\"No GCC exposure\"],
    \"reasoning\": \"Strong match...\"
  }
]

Be EXTREMELY strict on functional area mismatches. Equity derivatives analyst ≠ Finance operations/consolidation role.";

        try {
            // Use SFFC_Claude_API_Manager's call_api method with higher token limit for batch
            $response = $claude->call_api($prompt, [
                'model' => 'claude-haiku-4-5-20251001',
                'max_tokens' => 1500, // More tokens needed for batch response
                'temperature' => 0.3,
                'mode' => 'crm_matching'
            ]);

            if (!empty($response['content'][0]['text'])) {
                $text = $response['content'][0]['text'];

                // Extract JSON array from response
                if (preg_match('/\[[\s\S]*\]/s', $text, $json_matches)) {
                    $results = json_decode($json_matches[0], true);

                    if (is_array($results) && count($results) === count($matches)) {
                        // Validate and normalize results
                        $normalized = [];
                        foreach ($results as $result) {
                            $strengths = $result['strengths'] ?? [];
                            $concerns = $result['concerns'] ?? [];
                            $normalized[] = [
                                'score' => min(100, max(0, intval($result['score'] ?? 0))),
                                'strengths' => $strengths,
                                'concerns' => $concerns,
                                'reasoning' => $result['reasoning'] ?? '',
                                'reasons' => array_slice($strengths, 0, 3),
                                'warnings' => array_slice($concerns, 0, 2)
                            ];
                        }

                        error_log('CRM Matches: Batch scoring succeeded for ' . count($normalized) . ' matches');
                        return $normalized;
                    } else {
                        error_log('CRM Matches: Batch response count mismatch - expected ' . count($matches) . ', got ' . (is_array($results) ? count($results) : 0));
                    }
                }
            }

            error_log('CRM Matches: Batch Claude response missing expected format');
            return null;
        } catch (Exception $e) {
            error_log('CRM Matches: Batch Claude API call failed - ' . $e->getMessage());
            return null;
        }
    }

    /**
     * Analyze role match - simplified CV analysis for role analyzer shortcode
     */
    public function analyze_role_match()
    {
        // Verify nonce
        if (!check_ajax_referer('sffc_crm_nonce', '_ajax_nonce', false)) {
            wp_send_json_error(['message' => 'Invalid security token'], 403);
        }

        $post_id = isset($_POST['post_id']) ? absint($_POST['post_id']) : 0;
        $user_id = get_current_user_id();

        if (!$post_id) {
            wp_send_json_error(['message' => 'Post ID is required'], 400);
        }

        // Allow CV text override from request (supports logged-out users)
        $cv_text_override = '';
        if (isset($_POST['cv_text'])) {
            $cv_text_override = $this->sanitize_cv_input(wp_unslash($_POST['cv_text']));
        }

        if (!empty($cv_text_override)) {
            $cv_text = $cv_text_override;
        } else {
            $cv_text = $this->get_gap_cv_text($user_id);
        }

        if (empty($cv_text)) {
            wp_send_json_error(['message' => 'Upload or paste your CV to run this analysis.'], 400);
        }

        $should_persist_cv = $user_id && !empty($cv_text_override) && !empty($_POST['persist_cv']);
        if ($should_persist_cv && class_exists('SFFC_CRM_CV_Manager')) {
            $cv_manager = new SFFC_CRM_CV_Manager();
            $cv_manager->save_cv($user_id, $cv_text, __('Role Analyzer Upload', 'senna-finance'));
        }

        // Get job description
        $post_model = new SFFC_CRM_Post();
        $post = $post_model->get_full_detail($post_id, $user_id);

        if (!$post) {
            wp_send_json_error(['message' => 'Unable to find that post'], 404);
        }

        // Enrich job with structured requirement metadata
        $enriched = $this->enrich_posts_with_requirements([$post]);
        if (!empty($enriched[0])) {
            $post = $enriched[0];
        }

        if (!isset($post['insights'])) {
            $post['insights'] = $this->extract_requirement_insights($post);
        }

        // Prepare parsed CV snapshot for downstream scoring/fallback logic
        $cv_parsed = $this->prepare_cv_snapshot_for_match($cv_text);
        if (empty($cv_parsed)) {
            wp_send_json_error(['message' => 'Unable to parse CV for analysis. Please upload a different file.'], 400);
        }

        if (!function_exists('sffc_build_crm_jd_text_for_analysis')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/functions-gap-analyzer.php';
        }

        $jd_text = sffc_build_crm_jd_text_for_analysis($post);

        // Use AI Analyzer class
        if (!class_exists('SFFC_AI_Analyzer')) {
            require_once SFFC_PLUGIN_DIR . 'includes/application-planner/class-ai-analyzer.php';
        }

        $analyzer = new SFFC_AI_Analyzer();
        $result = $analyzer->analyze_full($jd_text, $cv_text);

        $analysis_payload = null;
        $analysis_source = 'claude';
        $fallback_reason = null;

        if (!empty($result['success']) && !empty($result['data'])) {
            $analysis_payload = $this->normalize_ai_role_analysis($result['data']);
        }

        // Run advanced keyword fallback if Claude isn't available or parsing failed
        if (!$analysis_payload) {
            $analysis_source = 'keyword_fallback';
            $fallback_reason = $result['reason'] ?? 'ai_unavailable';

            $taxonomy = $this->load_keyword_taxonomy();
            $analysis_payload = $this->build_keyword_fallback_role_analysis($cv_parsed, $post, $taxonomy);
        }

        if (!$analysis_payload) {
            wp_send_json_error([
                'message' => 'Failed to analyze match. Please try again.',
                'reason' => $fallback_reason ?? ($result['reason'] ?? 'unknown')
            ]);
        }

        $analysis_payload['source'] = $analysis_source;
        if ($fallback_reason && $analysis_source === 'keyword_fallback') {
            $analysis_payload['fallback_reason'] = $fallback_reason;
        }

        wp_send_json_success([
            'analysis' => $analysis_payload,
            'job_title' => $post['role_title'] ?? '',
            'company' => $post['company'] ?? '',
        ]);
    }

    /**
     * Build a reusable CV snapshot for match calculations
     */
    private function prepare_cv_snapshot_for_match($cv_text)
    {
        if (empty($cv_text)) {
            return null;
        }

        $snapshot = [
            'raw_text' => $cv_text,
            'lower' => strtolower($cv_text),
            'current_title' => $this->extract_current_role_title($cv_text),
            'experience_years' => $this->extract_experience_years($cv_text),
        ];

        $snapshot['seniority'] = $this->classify_seniority_from_title($snapshot['current_title']);
        if ($snapshot['seniority'] === 'unknown' || empty($snapshot['seniority'])) {
            $snapshot['seniority'] = $this->infer_seniority_from_cv_text($cv_text);
        }

        return $snapshot;
    }

    /**
     * Normalize Claude analysis into CRM-style structure
     */
    private function normalize_ai_role_analysis($ai_data)
    {
        if (empty($ai_data) || !is_array($ai_data)) {
            return null;
        }

        $score_raw = $ai_data['executive_summary']['match_score'] ?? ($ai_data['scores']['overall'] ?? 0);
        $match_score = max(0, min(100, (int) round($score_raw)));

        $summary = trim($ai_data['executive_summary']['verdict'] ?? '');
        if ($summary === '' && !empty($ai_data['overall_assessment'])) {
            if (is_array($ai_data['overall_assessment'])) {
                $summary = implode(' ', array_slice(array_map('trim', $ai_data['overall_assessment']), 0, 2));
            } else {
                $summary = trim($ai_data['overall_assessment']);
            }
        }

        $match_reasons = [];
        if (!empty($ai_data['strengths_to_highlight']) && is_array($ai_data['strengths_to_highlight'])) {
            foreach ($ai_data['strengths_to_highlight'] as $reason) {
                $reason = is_string($reason) ? trim($reason) : '';
                if ($reason !== '') {
                    $match_reasons[] = $reason;
                }
            }
        }

        if (!empty($ai_data['skills_breakdown']['matched_skills'])) {
            foreach ((array) $ai_data['skills_breakdown']['matched_skills'] as $skill) {
                $skill_name = trim($skill['skill'] ?? '');
                $evidence = trim($skill['cv_evidence'] ?? '');
                if ($skill_name && $evidence) {
                    $match_reasons[] = sprintf('%s — %s', $skill_name, $evidence);
                } elseif ($skill_name) {
                    $match_reasons[] = $skill_name;
                }
            }
        }

        $gap_statements = [];
        if (!empty($ai_data['skills_breakdown']['missing_skills'])) {
            foreach ((array) $ai_data['skills_breakdown']['missing_skills'] as $gap) {
                $skill = trim($gap['skill'] ?? '');
                if ($skill === '') {
                    continue;
                }
                $importance = strtolower($gap['importance'] ?? '');
                $suggestion = trim($gap['suggestion'] ?? '');
                $label = $importance ? sprintf(__('Missing %s skill: %s', 'senna-finance'), $importance, $skill) : sprintf(__('Missing skill: %s', 'senna-finance'), $skill);
                if ($suggestion) {
                    $label .= ' — ' . $suggestion;
                }
                $gap_statements[] = $label;
            }
        }

        if (!empty($ai_data['requirements_analysis'])) {
            foreach ((array) $ai_data['requirements_analysis'] as $requirement) {
                $status = strtoupper($requirement['match_status'] ?? '');
                if (in_array($status, ['STRONG_MATCH', 'MATCHED'], true)) {
                    continue;
                }
                $req_text = trim($requirement['requirement'] ?? '');
                if ($req_text === '') {
                    continue;
                }
                $action = trim($requirement['action_needed'] ?? '');
                $label = sprintf(__('Gap: %s (%s)', 'senna-finance'), $req_text, $status ?: __('Needs attention', 'senna-finance'));
                if ($action) {
                    $label .= ' — ' . $action;
                }
                $gap_statements[] = $label;
            }
        }

        $critical_missing = [];
        if (!empty($ai_data['keyword_analysis']['critical_missing'])) {
            foreach ((array) $ai_data['keyword_analysis']['critical_missing'] as $keyword) {
                $keyword = is_string($keyword) ? trim($keyword) : '';
                if ($keyword !== '') {
                    $critical_missing[] = sprintf(__('Missing keyword: %s', 'senna-finance'), $keyword);
                }
            }
        }

        $warnings = array_slice(array_values(array_unique(array_merge($critical_missing, $gap_statements))), 0, 4);

        $recommendations = [];
        if (!empty($ai_data['experience_improvements']['priority_fixes'])) {
            foreach ((array) $ai_data['experience_improvements']['priority_fixes'] as $fix) {
                $fix = is_string($fix) ? trim($fix) : '';
                if ($fix !== '') {
                    $recommendations[] = $fix;
                }
            }
        }

        if (!empty($ai_data['cv_improvements'])) {
            foreach ((array) $ai_data['cv_improvements'] as $tip) {
                $tip = is_string($tip) ? trim($tip) : '';
                if ($tip !== '') {
                    $recommendations[] = $tip;
                }
            }
        }

        if (!empty($ai_data['keyword_analysis']['suggested_additions'])) {
            foreach ((array) $ai_data['keyword_analysis']['suggested_additions'] as $addition) {
                $addition = is_string($addition) ? trim($addition) : '';
                if ($addition !== '') {
                    $recommendations[] = sprintf(__('Add keyword: %s', 'senna-finance'), $addition);
                }
            }
        }

        if (!empty($ai_data['experience_improvements']['additional_experience_to_add'])) {
            foreach ((array) $ai_data['experience_improvements']['additional_experience_to_add'] as $item) {
                $item = is_string($item) ? trim($item) : '';
                if ($item !== '') {
                    $recommendations[] = sprintf(__('Consider adding: %s', 'senna-finance'), $item);
                }
            }
        }

        $keyword_summary = [
            'matched' => (int) ($ai_data['keyword_analysis']['matched_keywords'] ?? 0),
            'total' => (int) ($ai_data['keyword_analysis']['total_jd_keywords'] ?? 0),
            'match_percentage' => (int) round($ai_data['keyword_analysis']['match_percentage'] ?? 0),
            'critical_missing' => array_values(array_map('trim', $ai_data['keyword_analysis']['critical_missing'] ?? [])),
        ];

        $apply_allowed = $match_score >= 60;

        return [
            'match_score' => $match_score,
            'match_level' => $this->get_match_level_label($match_score),
            'summary' => $summary ?: $this->build_score_summary_text($match_score),
            'verdict' => $ai_data['executive_summary']['verdict'] ?? '',
            'risk_level' => $ai_data['executive_summary']['risk_level'] ?? '',
            'recommendation' => $ai_data['executive_summary']['recommendation'] ?? '',
            'match_reasons' => array_slice(array_values(array_unique($match_reasons)), 0, 4),
            'warnings' => $warnings,
            'strengths' => array_slice(array_values(array_unique($match_reasons)), 0, 6),
            'gaps' => array_slice(array_values(array_unique($gap_statements)), 0, 6),
            'recommendations' => array_slice(array_values(array_unique($recommendations)), 0, 6),
            'keyword_analysis' => $keyword_summary,
            'apply_allowed' => $apply_allowed,
            'apply_message' => $apply_allowed ? __('You meet the 60% minimum to apply.', 'senna-finance') : __('Reach at least 60% match to unlock Apply.', 'senna-finance'),
            'raw' => $ai_data,
        ];
    }

    /**
     * Build fallback analysis when Claude is unavailable
     */
    private function build_keyword_fallback_role_analysis($cv_parsed, $post, $taxonomy)
    {
        if (empty($cv_parsed) || empty($post)) {
            return null;
        }

        $score = (int) round($this->calculate_match_score($cv_parsed, $post, $taxonomy));
        $reasons = $this->build_match_reasons($cv_parsed, $post);
        $warnings = $this->build_match_warnings($cv_parsed, $post);
        $gap_data = $this->build_match_gaps($cv_parsed, $post);

        $gaps = [];
        $recommendations = [];

        if (!empty($gap_data)) {
            foreach ($gap_data as $gap) {
                $item = $gap['item'] ?? ($gap['type'] ?? '');
                $item = is_string($item) ? trim($item) : '';
                if ($item !== '') {
                    $gaps[] = $item;
                }
                if (!empty($gap['recommendation'])) {
                    $recommendations[] = $gap['recommendation'];
                }
            }
        }

        foreach ($warnings as $warning) {
            $recommendations[] = sprintf(__('Address: %s', 'senna-finance'), $warning);
        }

        $apply_allowed = $score >= 60;

        return [
            'match_score' => max(0, min(100, $score)),
            'match_level' => $this->get_match_level_label($score),
            'summary' => $this->build_score_summary_text($score),
            'verdict' => $this->build_score_summary_text($score),
            'risk_level' => $score >= 70 ? 'COMPETITIVE' : ($score >= 60 ? 'MODERATE' : ($score >= 40 ? 'HIGH_RISK' : 'CRITICAL')),
            'recommendation' => $apply_allowed ? 'APPLY' : 'IMPROVE_AND_RETRY',
            'match_reasons' => array_slice((array) $reasons, 0, 4),
            'warnings' => array_slice((array) $warnings, 0, 3),
            'strengths' => array_slice((array) $reasons, 0, 6),
            'gaps' => array_slice(array_values(array_unique(array_merge($warnings, $gaps))), 0, 6),
            'recommendations' => array_slice(array_values(array_unique($recommendations)), 0, 6),
            'keyword_analysis' => [
                'matched' => null,
                'total' => null,
                'match_percentage' => max(0, min(100, $score)),
                'critical_missing' => $warnings,
            ],
            'apply_allowed' => $apply_allowed,
            'apply_message' => $apply_allowed ? __('You meet the 60% minimum to apply.', 'senna-finance') : __('Reach at least 60% match to unlock Apply.', 'senna-finance'),
            'raw' => null,
        ];
    }

    /**
     * Translate numeric score into human-readable label
     */
    private function get_match_level_label($score)
    {
        if ($score >= 85) {
            return __('Excellent Match', 'senna-finance');
        }
        if ($score >= 70) {
            return __('Strong Match', 'senna-finance');
        }
        if ($score >= 60) {
            return __('Good Match', 'senna-finance');
        }
        if ($score >= 40) {
            return __('Moderate Match', 'senna-finance');
        }
        return __('Low Match', 'senna-finance');
    }

    /**
     * Handle profile avatar upload
     */
    public function upload_avatar()
    {
        if (!is_user_logged_in()) {
            wp_send_json_error(['message' => __('Please log in to update your profile images.', 'senna-finance')], 403);
        }

        $nonce = isset($_POST['nonce']) ? sanitize_text_field(wp_unslash($_POST['nonce'])) : '';
        if (!$nonce || !wp_verify_nonce($nonce, 'sffc_crm_avatar_nonce')) {
            wp_send_json_error(['message' => __('Invalid request. Please refresh and try again.', 'senna-finance')], 400);
        }

        $upload_kind = !empty($_FILES['cover_file']) ? 'cover' : 'avatar';
        $file_key = $upload_kind === 'cover' ? 'cover_file' : 'avatar_file';

        if (empty($_FILES[$file_key])) {
            wp_send_json_error(['message' => __('Please choose an image to upload.', 'senna-finance')], 400);
        }

        $file = $_FILES[$file_key];
        $max_size = $upload_kind === 'cover' ? 5 * 1024 * 1024 : 2 * 1024 * 1024;
        if (!empty($file['size']) && $file['size'] > $max_size) {
            wp_send_json_error([
                'message' => $upload_kind === 'cover'
                    ? __('Please upload a cover image that is 5MB or smaller.', 'senna-finance')
                    : __('Please upload an image that is 2MB or smaller.', 'senna-finance'),
            ], 413);
        }

        $allowed_mimes = [
            'jpg'  => 'image/jpeg',
            'jpeg' => 'image/jpeg',
            'png'  => 'image/png',
            'webp' => 'image/webp',
        ];

        $filetype = wp_check_filetype($file['name'], $allowed_mimes);
        if (empty($filetype['type'])) {
            wp_send_json_error(['message' => __('Unsupported file type. Please upload a JPG, PNG, or WebP image.', 'senna-finance')], 400);
        }

        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/media.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';

        $upload = wp_handle_upload($file, ['test_form' => false]);
        if (isset($upload['error'])) {
            wp_send_json_error(['message' => sprintf(__('Upload failed: %s', 'senna-finance'), $upload['error'])], 500);
        }

        $attachment = [
            'post_mime_type' => $upload['type'],
            'post_title'     => sanitize_file_name(pathinfo($file['name'], PATHINFO_FILENAME)),
            'post_content'   => '',
            'post_status'    => 'inherit',
        ];

        $attachment_id = wp_insert_attachment($attachment, $upload['file']);
        if (!is_wp_error($attachment_id)) {
            $metadata = wp_generate_attachment_metadata($attachment_id, $upload['file']);
            wp_update_attachment_metadata($attachment_id, $metadata);
        } else {
            $attachment_id = 0;
        }

        $image_size = $upload_kind === 'cover' ? 'large' : 'medium';
        $image_url = $attachment_id ? wp_get_attachment_image_url($attachment_id, $image_size) : '';
        if (!$image_url) {
            $image_url = $upload['url'];
        }

        $user_id = get_current_user_id();
        $meta_key = $upload_kind === 'cover'
            ? 'sffc_profile_cover'
            : (class_exists('SFFC_User_Preferences') ? SFFC_User_Preferences::META_PROFILE_AVATAR : 'sffc_profile_avatar');
        update_user_meta($user_id, $meta_key, esc_url_raw($image_url));

        wp_send_json_success([
            'kind' => $upload_kind,
            'url' => esc_url($image_url),
        ]);
    }

    /**
     * Quick helper to produce a short summary from the score bands
     */
    private function build_score_summary_text($score)
    {
        if ($score >= 85) {
            return __('You are a top-tier fit for this role.', 'senna-finance');
        }
        if ($score >= 70) {
            return __('Your background aligns well with the requirements.', 'senna-finance');
        }
        if ($score >= 60) {
            return __('You meet most requirements with a few gaps to close.', 'senna-finance');
        }
        if ($score >= 40) {
            return __('Partial fit detected. Strengthen missing keywords before applying.', 'senna-finance');
        }
        return __('Significant gaps detected. Tailor your CV before applying.', 'senna-finance');
    }

    /**
     * Sanitize CV input text
     */
    private function sanitize_cv_input($text)
    {
        if (empty($text)) {
            return '';
        }

        if (is_array($text)) {
            $text = implode("\n", $text);
        }

        $text = wp_strip_all_tags($text);
        $text = preg_replace("/\r\n?/", '\n', $text);
        $text = trim($text);

        return mb_substr($text, 0, 8000);
    }

    /**
     * Get signup plans (featured and annual) for multi-state auth form
     */
    public function get_signup_plans()
    {
        // Verify nonce
        $nonce = sanitize_text_field($_POST['nonce'] ?? '');
        if (!$nonce || !wp_verify_nonce($nonce, 'sffc_crm_nonce')) {
            wp_send_json_error(['message' => __('Invalid request. Please refresh and try again.', 'senna-finance')], 403);
        }

        // Get all membership plans
        $plans = get_option('sffc_dashboard_plans', []);

        $monthly_candidates = [];
        $annual_candidates = [];

        foreach ($plans as $plan) {
            $entry = [
                'name' => !empty($plan['name']) ? $plan['name'] : '',
                'price' => !empty($plan['price']) ? $plan['price'] : '',
                'price_amount' => !empty($plan['price_amount']) ? floatval($plan['price_amount']) : 0,
                'price_currency' => !empty($plan['price_currency']) ? $plan['price_currency'] : get_option('currency_detector_base_currency', 'USD'),
                'billing_cycle' => !empty($plan['billing_cycle']) ? $plan['billing_cycle'] : '',
                'shortcode' => !empty($plan['shortcode']) ? wp_unslash($plan['shortcode']) : '',
                'url' => !empty($plan['mp_url']) ? $plan['mp_url'] : '',
                'featured' => !empty($plan['featured_signup']),
            ];

            $has_annual_variant = (!empty($plan['annual_price']) || !empty($plan['annual_price_amount']) || !empty($plan['annual_shortcode']) || !empty($plan['annual_mp_url']));
            $legacy_annual_only = !empty($plan['is_annual']);

            if (!$legacy_annual_only || $has_annual_variant) {
                $entry['badge'] = 'Monthly';
                $monthly_candidates[] = $entry;
            }

            if ($has_annual_variant || $legacy_annual_only) {
                $annual_candidates[] = [
                    'name' => !empty($plan['name']) ? $plan['name'] : '',
                    'price' => !empty($plan['annual_price']) ? $plan['annual_price'] : $entry['price'],
                    'price_amount' => !empty($plan['annual_price_amount']) ? floatval($plan['annual_price_amount']) : $entry['price_amount'],
                    'price_currency' => $entry['price_currency'],
                    'billing_cycle' => !empty($plan['annual_billing_cycle']) ? $plan['annual_billing_cycle'] : (!empty($plan['billing_cycle']) ? $plan['billing_cycle'] : 'per year'),
                    'shortcode' => !empty($plan['annual_shortcode']) ? wp_unslash($plan['annual_shortcode']) : $entry['shortcode'],
                    'url' => !empty($plan['annual_mp_url']) ? $plan['annual_mp_url'] : $entry['url'],
                    'featured' => !empty($plan['featured_signup']),
                    'badge' => 'Yearly',
                ];
            }
        }

        $featured_plan = null;
        foreach ($monthly_candidates as $candidate) {
            if (!empty($candidate['featured'])) {
                $featured_plan = $candidate;
                break;
            }
        }
        if (!$featured_plan && !empty($monthly_candidates)) {
            $featured_plan = $monthly_candidates[0];
        }

        $annual_plan = null;
        foreach ($annual_candidates as $candidate) {
            if (!empty($candidate['featured'])) {
                $annual_plan = $candidate;
                break;
            }
        }
        if (!$annual_plan && !empty($annual_candidates)) {
            $annual_plan = $annual_candidates[0];
        }

        wp_send_json_success([
            'featured' => $featured_plan,
            'annual' => $annual_plan,
        ]);
    }

    public function analyze_signup_cv()
    {
        $nonce = sanitize_text_field($_POST['nonce'] ?? '');
        if (!$nonce || !wp_verify_nonce($nonce, 'sffc_crm_nonce')) {
            wp_send_json_error(['message' => __('Invalid request. Please refresh and try again.', 'senna-finance')], 403);
        }

        $full_name = sanitize_text_field((string) ($_POST['full_name'] ?? ''));
        $email = sanitize_email((string) ($_POST['email'] ?? ''));
        $roles = isset($_POST['roles']) && is_array($_POST['roles'])
            ? array_values(array_filter(array_map('sanitize_text_field', wp_unslash($_POST['roles']))))
            : [];
        $locations = isset($_POST['locations']) && is_array($_POST['locations'])
            ? array_values(array_filter(array_map('sanitize_text_field', wp_unslash($_POST['locations']))))
            : [];
        $seniority = sanitize_text_field((string) ($_POST['seniority'] ?? ''));
        $cv_text = trim(wp_strip_all_tags((string) wp_unslash($_POST['cv_text'] ?? '')));

        if (empty($full_name) || empty($email) || !is_email($email)) {
            wp_send_json_error(['message' => __('Please provide a valid name and email first.', 'senna-finance')], 400);
        }

        if (strlen($cv_text) < 250) {
            wp_send_json_error(['message' => __('Please paste more of your CV so MENA Careers can analyse it properly.', 'senna-finance')], 400);
        }

        $analysis = $this->generate_signup_cv_analysis($full_name, $roles, $locations, $seniority, $cv_text);

        wp_send_json_success([
            'analysis' => $analysis,
        ]);
    }

    private function generate_signup_cv_analysis($full_name, array $roles, array $locations, $seniority, $cv_text)
    {
        $claude = class_exists('SFFC_Claude_API_Manager') ? SFFC_Claude_API_Manager::get_instance() : null;
        $target_roles = !empty($roles) ? implode(', ', array_slice($roles, 0, 3)) : 'finance roles';
        $target_locations = !empty($locations) ? implode(', ', array_slice($locations, 0, 3)) : 'the markets selected';
        $seniority_label = $seniority ? $seniority : 'the level selected';

        if ($claude && method_exists($claude, 'send_message')) {
            $system_prompt = 'You are a high-conviction career strategist for finance professionals. '
                . 'Analyse the candidate CV against their target role, markets and seniority. '
                . 'Return JSON only with keys headline, summary, confidence, strengths, gaps, and proof_points. '
                . 'Requirements: summary max 40 words, strengths exactly 3 items, gaps exactly 3 items, proof_points exactly 3 items. '
                . 'No markdown, no backticks, no duplicated sentences, no generic fluff.';

            $user_prompt = wp_json_encode([
                'candidate_name' => $full_name,
                'target_roles' => $roles,
                'target_locations' => $locations,
                'target_seniority' => $seniority,
                'cv_text' => $cv_text,
            ]);

            $response = $claude->send_message($user_prompt, [
                'system_prompt' => $system_prompt,
            ], 'career');

            if (!empty($response['response'])) {
                $parsed = $this->parse_signup_cv_analysis_response($response['response']);
                if (!empty($parsed)) {
                    return $parsed;
                }
            }
        }

        return [
            'headline' => sprintf('You already have signal for %s.', $target_roles),
            'summary' => sprintf('Your CV points toward %s in %s, but MENA Careers can sharpen the positioning and remove avoidable friction before you apply.', $target_roles, $target_locations),
            'confidence' => 'Promising fit',
            'strengths' => [
                'You already show direct finance signal and tangible execution exposure.',
                'Your target markets and role direction are clear enough to build a focused search.',
                'There is enough evidence in the CV to produce stronger recruiter-facing messaging fast.',
            ],
            'gaps' => [
                'The CV will still need tighter positioning around the target role and level.',
                'The story likely needs clearer proof points tied to outcomes and commercial impact.',
                'Recruiter outreach and application strategy still need to be structured around the chosen market.',
            ],
            'proof_points' => [
                sprintf('Target role focus: %s', $target_roles),
                sprintf('Priority markets: %s', $target_locations),
                sprintf('Seniority lens: %s', $seniority_label),
            ],
        ];
    }

    private function parse_signup_cv_analysis_response($response)
    {
        $response = trim((string) $response);
        $response = preg_replace('/^```(?:json)?/i', '', $response);
        $response = preg_replace('/```$/', '', $response);

        $decoded = json_decode(trim($response), true);
        if (!is_array($decoded)) {
            if (preg_match('/\{.*\}/s', $response, $match)) {
                $decoded = json_decode($match[0], true);
            }
        }

        if (!is_array($decoded)) {
            return [];
        }

        $headline = sanitize_text_field((string) ($decoded['headline'] ?? ''));
        $summary = sanitize_text_field((string) ($decoded['summary'] ?? ''));
        $confidence = sanitize_text_field((string) ($decoded['confidence'] ?? 'Promising fit'));

        $strengths = isset($decoded['strengths']) && is_array($decoded['strengths'])
            ? array_values(array_filter(array_map('sanitize_text_field', $decoded['strengths'])))
            : [];
        $gaps = isset($decoded['gaps']) && is_array($decoded['gaps'])
            ? array_values(array_filter(array_map('sanitize_text_field', $decoded['gaps'])))
            : [];
        $proof_points = isset($decoded['proof_points']) && is_array($decoded['proof_points'])
            ? array_values(array_filter(array_map('sanitize_text_field', $decoded['proof_points'])))
            : [];

        $summary_seen = [];
        $summary = trim($summary);
        if ($summary !== '') {
            $summary_seen[strtolower($summary)] = true;
        }

        $dedupe = static function (array $items, array $seen = []) {
            $clean = [];
            foreach ($items as $item) {
                $key = strtolower(trim((string) $item));
                if ($key === '' || isset($seen[$key])) {
                    continue;
                }
                $seen[$key] = true;
                $clean[] = $item;
            }
            return $clean;
        };

        $strengths = array_slice($dedupe($strengths, $summary_seen), 0, 3);
        $gaps = array_slice($dedupe($gaps, $summary_seen), 0, 3);
        $proof_points = array_slice($dedupe($proof_points, $summary_seen), 0, 3);

        if ($headline === '' || $summary === '' || empty($strengths) || empty($gaps)) {
            return [];
        }

        return [
            'headline' => $headline,
            'summary' => $summary,
            'confidence' => $confidence,
            'strengths' => $strengths,
            'gaps' => $gaps,
            'proof_points' => $proof_points,
        ];
    }

    /**
     * Render MemberPress form from shortcode
     */
    public function render_membership_form()
    {
        // Verify nonce
        $nonce = sanitize_text_field($_POST['nonce'] ?? '');
        if (!$nonce || !wp_verify_nonce($nonce, 'sffc_crm_nonce')) {
            wp_send_json_error(['message' => __('Invalid request. Please refresh and try again.', 'senna-finance')], 403);
        }

        // Don't use wp_kses_post on shortcodes - it strips brackets
        // Instead, sanitize by stripping tags and validating shortcode format
        $shortcode = isset($_POST['shortcode']) ? sanitize_text_field($_POST['shortcode']) : '';

        if (empty($shortcode)) {
            wp_send_json_error(['message' => 'No shortcode provided', 'debug' => 'empty_shortcode'], 400);
            return;
        }

        // Remove escaped slashes that may be added during POST transmission
        $shortcode = stripslashes($shortcode);

        // Validate shortcode format
        if (!preg_match('/^\[[\w\-_]+/', $shortcode)) {
            wp_send_json_error(['message' => 'Invalid shortcode format', 'debug' => 'invalid_format', 'shortcode' => $shortcode], 400);
            return;
        }

        // Render the shortcode
        $html = do_shortcode($shortcode);

        // do_shortcode returns the original string if shortcode doesn't exist
        // So we check if it actually rendered something different
        if (empty($html) || $html === $shortcode) {
            wp_send_json_error([
                'message' => 'Failed to render membership form. Please ensure MemberPress is active and the shortcode is correct.',
                'debug' => 'render_failed',
                'shortcode' => $shortcode,
                'html_length' => strlen($html)
            ], 500);
            return;
        }

        wp_send_json_success([
            'html' => $html,
        ]);
    }

