            'target_roles' => isset($_POST['target_roles']) && is_array($_POST['target_roles'])
                ? array_map('sanitize_text_field', $_POST['target_roles'])
                : [],
            'target_sectors' => isset($_POST['target_sectors']) && is_array($_POST['target_sectors'])
