                : [],
            'target_seniority' => isset($_POST['target_seniority']) && is_array($_POST['target_seniority'])
                ? array_map('sanitize_text_field', $_POST['target_seniority'])
                : [],
            'target_locations' => isset($_POST['target_locations']) && is_array($_POST['target_locations'])
                ? array_map('sanitize_text_field', $_POST['target_locations'])
                : [],
            'target_countries' => isset($_POST['target_countries']) && is_array($_POST['target_countries'])
                ? array_map('sanitize_text_field', $_POST['target_countries'])
                : [],
            'salary_min' => isset($_POST['salary_min']) ? intval($_POST['salary_min']) : 0,
            'salary_max' => isset($_POST['salary_max']) ? intval($_POST['salary_max']) : 0,
            'salary_currency' => isset($_POST['salary_currency']) ? sanitize_text_field($_POST['salary_currency']) : 'GBP',
            'work_arrangement' => isset($_POST['work_arrangement']) && is_array($_POST['work_arrangement'])
                ? array_map('sanitize_text_field', $_POST['work_arrangement'])
                : [],
            'internship_duration' => isset($_POST['internship_duration']) ? sanitize_text_field($_POST['internship_duration']) : '',
            'start_date_pref' => isset($_POST['start_date_pref']) ? sanitize_text_field($_POST['start_date_pref']) : '',
            'university' => isset($_POST['university']) ? sanitize_text_field($_POST['university']) : '',
            'technical_skills' => isset($_POST['technical_skills']) && is_array($_POST['technical_skills'])
                ? array_map('sanitize_text_field', $_POST['technical_skills'])
                : [],
            'languages' => isset($_POST['languages']) && is_array($_POST['languages'])
                ? array_map('sanitize_text_field', $_POST['languages'])
                : [],
            'certifications' => isset($_POST['certifications']) && is_array($_POST['certifications'])
                ? array_map('sanitize_text_field', $_POST['certifications'])
                : [],
        ];

        // Save job preferences
        $success = sffc_crm_save_job_preferences($user_id, $preferences);

        // Save skills separately (they're not job preferences, but profile data)
