    public function save_user_criteria()
    {
        $user_id = $this->verify_request();

        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-user-criteria.php';
        $criteria_model = new SFFC_CRM_User_Criteria();

        $criteria_id = absint($_POST['criteria_id'] ?? 0);
        $name = sanitize_text_field(wp_unslash($_POST['name'] ?? ''));
        if ($name === '') {
            wp_send_json_error(['message' => __('Criteria name is required.', 'senna-finance')], 400);
        }

        $data = [
            'user_id' => $user_id,
            'name' => $name,
            'job_title' => sanitize_text_field(wp_unslash($_POST['job_title'] ?? '')),
            'sector' => isset($_POST['sector']) ? array_map('sanitize_text_field', (array) wp_unslash($_POST['sector'])) : [],
            'location' => $this->split_criteria_text_list($_POST['location'] ?? ''),
            'experience_level' => isset($_POST['experience_level']) ? array_map('sanitize_text_field', (array) wp_unslash($_POST['experience_level'])) : [],
            'years_experience' => sanitize_text_field(wp_unslash($_POST['years_experience'] ?? '')),
            'skills_keywords' => $this->split_criteria_text_list($_POST['skills_keywords'] ?? ''),
        ];

        $cv_file_id = $this->handle_criteria_upload('cv_file', ['pdf', 'doc', 'docx']);
        if ($cv_file_id) {
            $data['cv_file_id'] = $cv_file_id;
        } elseif (!empty($_POST['cv_file_id_existing'])) {
            $data['cv_file_id'] = $this->resolve_criteria_existing_document(wp_unslash($_POST['cv_file_id_existing']), $user_id);
        }

        $cover_file_id = $this->handle_criteria_upload('cover_letter_file', ['pdf', 'doc', 'docx']);
        if ($cover_file_id) {
            $data['cover_letter_file_id'] = $cover_file_id;
        } elseif (!empty($_POST['cover_letter_file_id_existing'])) {
            $data['cover_letter_file_id'] = $this->resolve_criteria_existing_document(wp_unslash($_POST['cover_letter_file_id_existing']), $user_id);
        }

        if ($criteria_id) {
            $saved = $criteria_model->update($criteria_id, $user_id, $data);
            $saved_id = $criteria_id;
        } else {
            $saved_id = $criteria_model->create($data);
            $saved = (bool) $saved_id;
        }

        if (!$saved) {
            wp_send_json_error(['message' => __('Unable to save criteria right now.', 'senna-finance')], 500);
        }

        wp_send_json_success([
            'message' => __('Criteria saved.', 'senna-finance'),
            'criteria_id' => $saved_id,
        ]);
    }

    public function delete_user_criteria()
    {
        $user_id = $this->verify_request();
        $criteria_id = absint($_POST['criteria_id'] ?? 0);

        if (!$criteria_id) {
            wp_send_json_error(['message' => __('Missing criteria ID.', 'senna-finance')], 400);
        }

        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-user-criteria.php';
        $criteria_model = new SFFC_CRM_User_Criteria();
        $deleted = $criteria_model->delete($criteria_id, $user_id);

        if (!$deleted) {
            wp_send_json_error(['message' => __('Unable to delete this criteria. Default criteria cannot be deleted.', 'senna-finance')], 400);
        }

        wp_send_json_success(['message' => __('Criteria deleted.', 'senna-finance')]);
    }

    private function split_criteria_text_list($value)
    {
        $value = is_array($value) ? implode(',', array_map('sanitize_text_field', $value)) : sanitize_textarea_field(wp_unslash($value));
        $decoded = json_decode($value, true);
        if (is_array($decoded)) {
            return array_values(array_filter(array_map('sanitize_text_field', $decoded)));
        }
        return array_values(array_filter(array_map('trim', preg_split('/[,|\r\n]+/', $value))));
    }

    private function validate_user_attachment($attachment_id, $user_id)
    {
        if (!$attachment_id) {
            return 0;
        }

        $attachment = get_post($attachment_id);
        if (!$attachment || $attachment->post_type !== 'attachment' || (int) $attachment->post_author !== (int) $user_id) {
            wp_send_json_error(['message' => __('Selected document is not available on your account.', 'senna-finance')], 400);
        }

        $mime_type = get_post_mime_type($attachment_id);
        $allowed = [
            'application/pdf',
            'application/msword',
            'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        ];
        if (!in_array($mime_type, $allowed, true)) {
            wp_send_json_error(['message' => __('Selected document must be a PDF, DOC, or DOCX file.', 'senna-finance')], 400);
        }

        return $attachment_id;
    }

    private function resolve_criteria_existing_document($value, $user_id)
    {
        $value = sanitize_text_field($value);
        if ($value === '') {
            return 0;
        }

        if (ctype_digit($value)) {
            return $this->validate_user_attachment((int) $value, $user_id);
        }

        if (strpos($value, 'profile:') !== 0) {
            wp_send_json_error(['message' => __('Selected document is not available on your account.', 'senna-finance')], 400);
        }

        $index = absint(substr($value, strlen('profile:')));
        $documents = get_user_meta($user_id, 'sffc_crm_documents', true);
        if (!is_array($documents) || empty($documents[$index]) || empty($documents[$index]['file'])) {
            wp_send_json_error(['message' => __('Selected document is not available on your account.', 'senna-finance')], 400);
        }

        $document = $documents[$index];
        $file_path = (string) $document['file'];
        if (!file_exists($file_path)) {
            wp_send_json_error(['message' => __('Selected document file could not be found.', 'senna-finance')], 400);
        }

        $file_type = wp_check_filetype($file_path);
        $allowed = [
            'application/pdf',
            'application/msword',
            'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        ];
        if (empty($file_type['type']) || !in_array($file_type['type'], $allowed, true)) {
            wp_send_json_error(['message' => __('Selected document must be a PDF, DOC, or DOCX file.', 'senna-finance')], 400);
        }

        $attachment_id = wp_insert_attachment([
            'guid' => esc_url_raw($document['url'] ?? ''),
            'post_mime_type' => $file_type['type'],
            'post_title' => sanitize_text_field($document['name'] ?? basename($file_path)),
            'post_content' => '',
            'post_status' => 'inherit',
            'post_author' => $user_id,
        ], $file_path);

        if (is_wp_error($attachment_id) || !$attachment_id) {
            wp_send_json_error(['message' => __('Unable to attach the selected document to this criteria.', 'senna-finance')], 500);
        }

        require_once ABSPATH . 'wp-admin/includes/image.php';
        wp_update_attachment_metadata($attachment_id, wp_generate_attachment_metadata($attachment_id, $file_path));

        return (int) $attachment_id;
    }

    private function handle_criteria_upload($field, $allowed_extensions)
    {
        if (empty($_FILES[$field]) || empty($_FILES[$field]['name'])) {
            return 0;
        }

        $file_name = sanitize_file_name($_FILES[$field]['name']);
        $extension = strtolower(pathinfo($file_name, PATHINFO_EXTENSION));
        if (!in_array($extension, $allowed_extensions, true)) {
            wp_send_json_error(['message' => __('Unsupported file type. Please upload PDF, DOC, or DOCX files.', 'senna-finance')], 400);
        }

        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-admin/includes/media.php';
        require_once ABSPATH . 'wp-admin/includes/image.php';

        $attachment_id = media_handle_upload($field, 0);
        if (is_wp_error($attachment_id)) {
            wp_send_json_error(['message' => $attachment_id->get_error_message()], 500);
        }

        return (int) $attachment_id;
    }

