    /**
     * Save generic profile data (for old UI compatibility)
     */
    public function save_profile()
    {
        $user_id = $this->verify_request();

        $is_dashboard_profile_request = !empty($_POST['headline'])
            || !empty($_POST['about'])
            || isset($_POST['alert_frequency'])
            || isset($_POST['target_roles'])
            || isset($_POST['technical_skills'])
            || isset($_POST['excluded_roles']);

        if ($is_dashboard_profile_request) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/class-crm-shortcodes.php';
            $shortcodes = SFFC_CRM_Shortcodes::get_instance();

            wp_send_json_success($shortcodes->save_crm_reddit_dashboard_profile($user_id, $_POST));
        }

        $data = isset($_POST['data']) ? $_POST['data'] : [];

        if (empty($data) || !is_array($data)) {
            wp_send_json_error(['message' => 'No data provided'], 400);
        }

        // Save each field to user meta
        foreach ($data as $label => $value) {
            // Convert label to meta key (e.g., "Internship Duration" -> "internship_duration")
            $meta_key = 'sffc_crm_' . strtolower(str_replace(' ', '_', $label));
            update_user_meta($user_id, $meta_key, sanitize_text_field($value));
        }

        wp_send_json_success(['message' => 'Profile updated successfully']);
    }

    /**
     * Upload document
     */
    public function upload_document()
    {
        $user_id = $this->verify_request();

        if (empty($_FILES['file'])) {
            wp_send_json_error(['message' => 'No file uploaded'], 400);
        }

        // Handle file upload
        require_once(ABSPATH . 'wp-admin/includes/file.php');
        require_once(ABSPATH . 'wp-admin/includes/image.php');
        require_once(ABSPATH . 'wp-admin/includes/media.php');

        $file = $_FILES['file'];
        $upload_overrides = [
            'test_form' => false,
            'mimes' => [
                'pdf' => 'application/pdf',
                'doc' => 'application/msword',
                'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
                'xls' => 'application/vnd.ms-excel',
                'xlsx' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            ]
        ];

        $movefile = wp_handle_upload($file, $upload_overrides);

        if ($movefile && !isset($movefile['error'])) {
            // Save document info to user meta
            $documents = get_user_meta($user_id, 'sffc_crm_documents', true) ?: [];
            $filename = sanitize_text_field($file['name']);
            $document_type = preg_match('/\b(cv|resume)\b/i', $filename) ? 'resume_cv' : 'supporting';
            $documents[] = [
                'name' => $filename,
                'url' => $movefile['url'],
                'file' => $movefile['file'],
                'uploaded' => current_time('mysql'),
                'document_type' => $document_type,
            ];
            update_user_meta($user_id, 'sffc_crm_documents', $documents);

            wp_send_json_success([
                'message' => 'Document uploaded successfully',
                'document' => end($documents)
            ]);
        } else {
            wp_send_json_error([
                'message' => $movefile['error'] ?? 'Upload failed'
            ], 500);
        }
    }

    /**
     * Delete document
     */
    public function delete_document()
    {
        $user_id = $this->verify_request();
        $document_name = sanitize_text_field($_POST['document_name'] ?? '');

        if (empty($document_name)) {
            wp_send_json_error(['message' => 'Document name required'], 400);
        }

        $documents = get_user_meta($user_id, 'sffc_crm_documents', true) ?: [];
        $updated_documents = [];

        foreach ($documents as $doc) {
            if ($doc['name'] !== $document_name) {
                $updated_documents[] = $doc;
            } else {
                // Delete physical file
                if (!empty($doc['file']) && file_exists($doc['file'])) {
                    @unlink($doc['file']);
                }
            }
        }

        update_user_meta($user_id, 'sffc_crm_documents', $updated_documents);
        wp_send_json_success(['message' => 'Document deleted successfully']);
    }

    public function set_document_type()
    {
        $user_id = $this->verify_request();
        $document_name = sanitize_text_field($_POST['document_name'] ?? '');
        $document_type = sanitize_key($_POST['document_type'] ?? '');

        if (!$document_name || !in_array($document_type, ['resume_cv', 'supporting'], true)) {
            wp_send_json_error(['message' => __('Document name and type are required.', 'senna-finance')], 400);
        }

        $documents = get_user_meta($user_id, 'sffc_crm_documents', true) ?: [];
        $updated = false;

        foreach ($documents as &$document) {
            if (($document['name'] ?? '') === $document_name) {
                $document['document_type'] = $document_type;
                $updated = true;
            } elseif ($document_type === 'resume_cv' && ($document['document_type'] ?? '') === 'resume_cv') {
                $document['document_type'] = 'supporting';
            }
        }
        unset($document);

        if (!$updated) {
            wp_send_json_error(['message' => __('Document not found.', 'senna-finance')], 404);
        }

        update_user_meta($user_id, 'sffc_crm_documents', $documents);

        wp_send_json_success([
            'message' => $document_type === 'resume_cv'
                ? __('Document marked as Resume/CV.', 'senna-finance')
                : __('Document updated.', 'senna-finance'),
            'document_type' => $document_type,
        ]);
    }

    public function request_intro_queue()
    {
        $user_id = $this->verify_request();

        $post_id = isset($_POST['post_id']) ? absint($_POST['post_id']) : 0;
        $recruiter_id = isset($_POST['recruiter_id']) ? absint($_POST['recruiter_id']) : 0;
        $source_type = sanitize_key($_POST['source_type'] ?? 'post');
        $posted_role_title = sanitize_text_field($_POST['role_title'] ?? '');
        $posted_company_name = sanitize_text_field($_POST['company_name'] ?? '');
        $posted_recruiter_name = sanitize_text_field($_POST['recruiter_name'] ?? '');
        $posted_recruiter_email = sanitize_email($_POST['recruiter_email'] ?? '');
        $posted_recruiter_linkedin = esc_url_raw($_POST['recruiter_linkedin'] ?? '');
        $criteria_id = isset($_POST['criteria_id']) ? absint($_POST['criteria_id']) : 0;
        $criteria = null;
        if ($criteria_id) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-user-criteria.php';
            $criteria_model = new SFFC_CRM_User_Criteria();
            $criteria = $criteria_model->get_by_id($criteria_id, $user_id);
        }

        if (!$recruiter_id || ($source_type === 'post' && !$post_id)) {
            wp_send_json_error(['message' => __('Role and recruiter are required.', 'senna-finance')], 400);
        }

        $documents = get_user_meta($user_id, 'sffc_crm_documents', true) ?: [];
        $has_resume_document = false;
        foreach ($documents as $document) {
            if (($document['document_type'] ?? '') === 'resume_cv') {
                $has_resume_document = true;
                break;
            }
        }
        if (!$has_resume_document && !empty($criteria['cv_file_id'])) {
            $has_resume_document = true;
        }

        if (!$has_resume_document) {
            wp_send_json_error([
                'message' => __('Upload or select a CV for this search criteria before requesting an intro.', 'senna-finance'),
            ], 400);
        }

        $this->ensure_linkedin_intro_queue_table();
        $this->add_application_queue_columns();

        global $wpdb;
        $table = $this->get_linkedin_intro_queue_table();
        $existing = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE user_id = %d AND recruiter_id = %d ORDER BY id DESC LIMIT 1",
            $user_id,
            $recruiter_id
        ), ARRAY_A);

        if ($existing && ($existing['status'] ?? '') !== 'cancelled') {
            wp_send_json_success([
                'message' => __('Intro already requested for this recruiter.', 'senna-finance'),
                'request_id' => (int) $existing['id'],
                'request' => [
                    'id' => (int) $existing['id'],
                    'recruiter_name' => $existing['recruiter_name'] ?? __('Hiring Team', 'senna-finance'),
                    'job_company' => $existing['company_name'] ?? '',
                    'job_title' => $existing['role_title'] ?? '',
                    'status' => $existing['status'] ?? 'pending_review',
                    'status_label' => __('Requested', 'senna-finance'),
                    'created_at_formatted' => !empty($existing['created_at']) ? wp_date(get_option('date_format'), strtotime($existing['created_at'])) : wp_date(get_option('date_format')),
                ],
            ]);
        }

        $post_model = new SFFC_CRM_Post();
        $post = $post_id ? $post_model->get($post_id) : null;
        if ($source_type === 'post' && !$post) {
            wp_send_json_error(['message' => __('Role not found.', 'senna-finance')], 404);
        }

        $resolved_recruiter_name = $post['recruiter_name'] ?? $posted_recruiter_name ?? __('Hiring Team', 'senna-finance');
        $resolved_recruiter_email = $post['recruiter_email'] ?? $posted_recruiter_email ?? '';
        $resolved_recruiter_linkedin = $post['recruiter_linkedin'] ?? $posted_recruiter_linkedin ?? '';
        $resolved_company_name = $post['company'] ?? $posted_company_name ?? '';
        $resolved_role_title = $post['role_title'] ?? $posted_role_title ?? __('Role', 'senna-finance');

        if ($existing && ($existing['status'] ?? '') === 'cancelled') {
            $inserted = $wpdb->update($table, [
                'post_id' => $post_id,
                'recruiter_name' => $resolved_recruiter_name,
                'recruiter_email' => $resolved_recruiter_email,
                'recruiter_linkedin' => $resolved_recruiter_linkedin,
                'company_name' => $resolved_company_name,
                'role_title' => $resolved_role_title,
                'status' => 'pending_review',
                'updated_at' => current_time('mysql'),
            ], [
                'id' => (int) $existing['id'],
            ]);
            $new_request_id = (int) $existing['id'];
        } else {
            $inserted = $wpdb->insert($table, [
                'user_id' => $user_id,
                'post_id' => $post_id,
                'recruiter_id' => $recruiter_id,
                'recruiter_name' => $resolved_recruiter_name,
                'recruiter_email' => $resolved_recruiter_email,
                'recruiter_linkedin' => $resolved_recruiter_linkedin,
                'company_name' => $resolved_company_name,
                'role_title' => $resolved_role_title,
                'status' => 'pending_review',
                'created_at' => current_time('mysql'),
                'updated_at' => current_time('mysql'),
            ]);
            $new_request_id = (int) $wpdb->insert_id;
        }

        if ($inserted === false) {
            wp_send_json_error(['message' => __('Unable to save intro request.', 'senna-finance')], 500);
        }

        $user = get_userdata($user_id);
        $admin_email = get_option('admin_email');
        $candidate_name = $user ? $user->display_name : 'User #' . $user_id;
        $subject = sprintf(
            __('New Recruiter Intro Request from %s — %s at %s', 'senna-finance'),
            $candidate_name,
            $resolved_role_title ?: __('Role', 'senna-finance'),
            $resolved_company_name ?: __('Company', 'senna-finance')
        );

        $admin_queue_url = admin_url('admin.php?page=sffc-crm-intros');
        $criteria_name = !empty($criteria['name']) ? $criteria['name'] : __('Profile preferences', 'senna-finance');
        $criteria_cv_title = !empty($criteria['cv_file_id']) ? get_the_title((int) $criteria['cv_file_id']) : '';
        $criteria_cv_url = !empty($criteria['cv_file_id']) ? wp_get_attachment_url((int) $criteria['cv_file_id']) : '';
        $criteria_cover_title = !empty($criteria['cover_letter_file_id']) ? get_the_title((int) $criteria['cover_letter_file_id']) : '';
        $criteria_cover_url = !empty($criteria['cover_letter_file_id']) ? wp_get_attachment_url((int) $criteria['cover_letter_file_id']) : '';
        $fallback_resume_name = '';
        $fallback_resume_url = '';
        foreach ($documents as $document) {
            if (($document['document_type'] ?? '') === 'resume_cv') {
                $fallback_resume_name = $document['name'] ?? '';
                $fallback_resume_url = $document['url'] ?? '';
                break;
            }
        }
        $cv_label = $criteria_cv_title ?: $fallback_resume_name;
        $cv_url = $criteria_cv_url ?: $fallback_resume_url;
        $cover_label = $criteria_cover_title;
        $cover_url = $criteria_cover_url;
        $request_time = wp_date(get_option('date_format') . ' ' . get_option('time_format'), current_time('timestamp'));

        $message = '<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
</head>
<body style="margin: 0; padding: 0; font-family: Inter, -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, Arial, sans-serif; background-color: #F6F5F2;">
    <table role="presentation" cellspacing="0" cellpadding="0" border="0" width="100%" style="background-color: #F6F5F2;">
        <tr>
            <td style="padding: 28px 16px;">
                <table role="presentation" cellspacing="0" cellpadding="0" border="0" width="100%" style="max-width: 680px; margin: 0 auto;">
                    <tr>
                        <td style="padding: 0 0 14px 0;">
                            <div style="font-size: 12px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; color: #0D6955;">MENA Careers Admin Queue</div>
                        </td>
                    </tr>
                    <tr>
                        <td style="background-color: #ffffff; border: 1px solid #E6E1D8; border-radius: 18px; overflow: hidden;">
                            <div style="padding: 26px 28px 22px; border-bottom: 1px solid #ECE7DE;">
                                <div style="display: inline-block; padding: 6px 10px; border-radius: 999px; background: #EAF7F1; color: #0D6955; font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.06em;">Action required</div>
                                <h1 style="margin: 14px 0 8px; color: #0D353E; font-size: 26px; line-height: 1.2; font-weight: 800;">New recruiter intro request</h1>
                                <p style="margin: 0; color: #66736F; font-size: 14px; line-height: 1.6;">A user requested an introduction to a recruiter. Review the candidate, recruiter, role, and materials below.</p>
                            </div>

                            <div style="padding: 22px 28px;">
                                <table role="presentation" cellspacing="0" cellpadding="0" border="0" width="100%">
                                    <tr>
                                        <td style="padding: 14px 0; border-bottom: 1px solid #F0ECE5;">
                                            <div style="color: #8A8176; font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.08em;">Candidate</div>
                                            <div style="margin-top: 5px; color: #0F1F18; font-size: 16px; font-weight: 800;">' . esc_html($candidate_name) . '</div>
                                            <div style="margin-top: 3px; color: #66736F; font-size: 13px;"><a href="mailto:' . esc_attr($user ? $user->user_email : '') . '" style="color: #0D6955; text-decoration: none;">' . esc_html($user ? $user->user_email : '') . '</a></div>
                                        </td>
                                    </tr>
                                    <tr>
                                        <td style="padding: 14px 0; border-bottom: 1px solid #F0ECE5;">
                                            <div style="color: #8A8176; font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.08em;">Role</div>
                                            <div style="margin-top: 5px; color: #0F1F18; font-size: 16px; font-weight: 800;">' . esc_html($resolved_role_title) . '</div>
                                            <div style="margin-top: 3px; color: #66736F; font-size: 13px;">' . esc_html($resolved_company_name ?: __('Company not provided', 'senna-finance')) . '</div>
                                        </td>
                                    </tr>
                                    <tr>
                                        <td style="padding: 14px 0; border-bottom: 1px solid #F0ECE5;">
                                            <div style="color: #8A8176; font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.08em;">Recruiter / Contact</div>
                                            <div style="margin-top: 5px; color: #0F1F18; font-size: 15px; font-weight: 750;">' . esc_html($resolved_recruiter_name ?: __('Hiring Team', 'senna-finance')) . '</div>
                                            <div style="margin-top: 3px; color: #66736F; font-size: 13px;">' . ($resolved_recruiter_email ? '<a href="mailto:' . esc_attr($resolved_recruiter_email) . '" style="color: #0D6955; text-decoration: none;">' . esc_html($resolved_recruiter_email) . '</a>' : esc_html__('No email captured', 'senna-finance')) . '</div>
                                        </td>
                                    </tr>
                                    <tr>
                                        <td style="padding: 14px 0; border-bottom: 1px solid #F0ECE5;">
                                            <div style="color: #8A8176; font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.08em;">Search Criteria</div>
                                            <div style="margin-top: 5px; color: #0F1F18; font-size: 15px; font-weight: 750;">' . esc_html($criteria_name) . '</div>
                                        </td>
                                    </tr>
                                    <tr>
                                        <td style="padding: 14px 0;">
                                            <div style="color: #8A8176; font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.08em;">Materials</div>
                                            <div style="margin-top: 8px;">
                                                <span style="display: inline-block; margin: 0 6px 6px 0; padding: 7px 10px; border-radius: 999px; background: ' . ($cv_label ? '#EAF7F1' : '#F7F3EC') . '; color: ' . ($cv_label ? '#0D6955' : '#8A8176') . '; font-size: 12px; font-weight: 800;">' . ($cv_label ? '✓ CV ready' : 'CV missing') . '</span>
                                                <span style="display: inline-block; margin: 0 6px 6px 0; padding: 7px 10px; border-radius: 999px; background: ' . ($cover_label ? '#EAF7F1' : '#F7F3EC') . '; color: ' . ($cover_label ? '#0D6955' : '#8A8176') . '; font-size: 12px; font-weight: 800;">' . ($cover_label ? '✓ Cover letter ready' : 'Cover letter not attached') . '</span>
                                            </div>
                                            ' . ($cv_url ? '<div style="margin-top: 6px; font-size: 13px;"><a href="' . esc_url($cv_url) . '" style="color: #0D6955; text-decoration: none; font-weight: 700;">View CV: ' . esc_html($cv_label) . '</a></div>' : '') . '
                                            ' . ($cover_url ? '<div style="margin-top: 6px; font-size: 13px;"><a href="' . esc_url($cover_url) . '" style="color: #0D6955; text-decoration: none; font-weight: 700;">View cover letter: ' . esc_html($cover_label) . '</a></div>' : '') . '
                                        </td>
                                    </tr>
                                </table>
                            </div>

                            <div style="padding: 20px 28px 26px; background: #FAF8F3; border-top: 1px solid #ECE7DE;">
                                <table role="presentation" cellspacing="0" cellpadding="0" border="0" width="100%">
                                    <tr>
                                        <td style="vertical-align: middle;">
                                            <div style="color: #8A8176; font-size: 12px; font-weight: 700;">Request ID #' . esc_html((string) $new_request_id) . '</div>
                                            <div style="margin-top: 3px; color: #66736F; font-size: 12px;">Received ' . esc_html($request_time) . '</div>
                                        </td>
                                        <td style="text-align: right; vertical-align: middle;">
                                            <a href="' . esc_url($admin_queue_url) . '" style="display: inline-block; background-color: #0D6955; color: #ffffff; text-decoration: none; padding: 13px 20px; border-radius: 10px; font-weight: 800; font-size: 14px;">Review in Admin</a>
                                        </td>
                                    </tr>
                                </table>
                            </div>
                        </td>
                    </tr>
                    <tr>
                        <td style="padding: 18px 0 0; text-align: center;">
                            <p style="margin: 0; color: #8A8176; font-size: 12px;">MENA Careers · Recruiter Intro Queue</p>
                        </td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>
</body>
</html>';

        $headers = ['Content-Type: text/html; charset=UTF-8'];
        wp_mail($admin_email, $subject, $message, $headers);

        wp_send_json_success([
            'message' => __('Recruiter intro requested successfully.', 'senna-finance'),
            'request_id' => $new_request_id,
            'request' => [
                'id' => $new_request_id,
                'recruiter_name' => $resolved_recruiter_name ?: __('Hiring Team', 'senna-finance'),
                'job_company' => $resolved_company_name,
                'job_title' => $resolved_role_title,
                'status' => 'pending_review',
                'status_label' => __('Requested', 'senna-finance'),
                'created_at_formatted' => wp_date(get_option('date_format')),
            ],
            'credit_summary' => $this->get_apply_all_credit_summary($user_id),
        ]);
    }

    public function submit_discovery_intro_request()
    {
        $user_id = $this->verify_request();

        $recruiter_id = isset($_POST['recruiter_id']) ? absint($_POST['recruiter_id']) : 0;
        $recruiter_name = sanitize_text_field(wp_unslash($_POST['recruiter_name'] ?? ''));
        $recruiter_title = sanitize_text_field(wp_unslash($_POST['recruiter_title'] ?? ''));
        $company_name = sanitize_text_field(wp_unslash($_POST['company_name'] ?? ''));
        $recruiter_email = sanitize_email(wp_unslash($_POST['recruiter_email'] ?? ''));
        $recruiter_linkedin = esc_url_raw(wp_unslash($_POST['recruiter_linkedin'] ?? ''));
        $recruiter_photo = esc_url_raw(wp_unslash($_POST['recruiter_photo'] ?? ''));
        $role_title = sanitize_text_field(wp_unslash($_POST['role_title'] ?? ''));
        $crm_post_id = isset($_POST['post_id']) ? absint($_POST['post_id']) : 0;
        $source_action = sanitize_key(wp_unslash($_POST['source_action'] ?? 'recruiter_discovery'));
        $stored_cv_url = esc_url_raw(wp_unslash($_POST['stored_cv_url'] ?? ''));
        $stored_cv_name = sanitize_text_field(wp_unslash($_POST['stored_cv_name'] ?? ''));
        $intro_context = sanitize_textarea_field(wp_unslash($_POST['intro_context'] ?? ''));

        if (!$recruiter_id || $recruiter_name === '' || $company_name === '') {
            wp_send_json_error(['message' => __('Recruiter details are missing.', 'senna-finance')], 400);
        }

        if ($stored_cv_url === '') {
            wp_send_json_error(['message' => __('Please select a stored CV before requesting an intro.', 'senna-finance')], 400);
        }

        $documents = get_user_meta($user_id, 'sffc_crm_documents', true) ?: [];
        $matched_cv = null;
        foreach ($documents as $document) {
            $document_url = esc_url_raw((string) ($document['url'] ?? ''));
            if ($document_url !== '' && $document_url === $stored_cv_url) {
                $matched_cv = $document;
                break;
            }
        }

        if (!$matched_cv) {
            wp_send_json_error(['message' => __('The selected CV could not be verified. Please choose a stored CV and try again.', 'senna-finance')], 400);
        }

        if ($stored_cv_name === '') {
            $stored_cv_name = trim((string) ($matched_cv['name'] ?? ''));
        }
        if ($stored_cv_name === '') {
            $stored_cv_name = __('Stored CV', 'senna-finance');
        }

        $this->ensure_job_applications_table();
        $this->ensure_job_applications_intro_columns();

        $recruiter_snapshot = $this->get_send_intro_hr_outreach_snapshot($recruiter_id);
        $post_snapshot = $this->get_send_intro_post_snapshot($crm_post_id, $role_title, $company_name);

        global $wpdb;
        $table = $this->get_job_applications_table_name();
        $synthetic_job_id = $this->get_send_intro_application_job_id($crm_post_id, $recruiter_id, $source_action);
        $resolved_recruiter_name = trim((string) ($recruiter_snapshot['name'] ?? '')) ?: $recruiter_name;
        $resolved_recruiter_title = trim((string) ($recruiter_snapshot['title'] ?? '')) ?: $recruiter_title;
        $resolved_company_name = trim((string) ($recruiter_snapshot['company_name'] ?? '')) ?: $company_name;
        $resolved_recruiter_email = sanitize_email((string) ($recruiter_snapshot['email'] ?? '')) ?: $recruiter_email;
        $resolved_recruiter_linkedin = esc_url_raw((string) ($recruiter_snapshot['linkedin'] ?? '')) ?: $recruiter_linkedin;
        $resolved_recruiter_photo = esc_url_raw((string) ($recruiter_snapshot['avatar_url'] ?? '')) ?: $recruiter_photo;
        $resolved_role_title = trim((string) ($post_snapshot['role_title'] ?? '')) ?: $role_title;
        $resolved_location = trim((string) ($post_snapshot['location'] ?? ''));
        $requested_at_mysql = current_time('mysql');
        $existing = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE user_id = %d AND job_id = %d AND workflow_type = %s LIMIT 1",
            $user_id,
            $synthetic_job_id,
            'send_intro'
        ), ARRAY_A);

        $request_data = [
            'user_id' => $user_id,
            'job_id' => $synthetic_job_id,
            'source_post_id' => $crm_post_id,
            'workflow_type' => 'send_intro',
            'stage' => 'queued',
            'recruiter_id' => $recruiter_id,
            'recruiter_name' => $resolved_recruiter_name,
            'recruiter_title' => $resolved_recruiter_title,
            'recruiter_email' => $resolved_recruiter_email,
            'recruiter_linkedin' => $resolved_recruiter_linkedin,
            'recruiter_avatar_url' => $resolved_recruiter_photo,
            'recruiter_location' => trim((string) ($recruiter_snapshot['location'] ?? '')),
            'recruiter_regions' => trim((string) ($recruiter_snapshot['regions'] ?? '')),
            'company_name' => $resolved_company_name,
            'job_title' => $resolved_role_title !== '' ? $resolved_role_title : __('Recruiter Discovery Intro', 'senna-finance'),
            'location' => $resolved_location,
            'stored_cv_url' => $stored_cv_url,
            'stored_cv_name' => $stored_cv_name,
            'source_action' => in_array($source_action, ['recruiter_discovery', 'hiring_strip', 'sidebar_recruiter', 'post_card', 'post_article'], true) ? $source_action : 'recruiter_discovery',
            'message_subject' => $resolved_role_title !== '' ? sprintf(__('Intro request for %s', 'senna-finance'), $resolved_role_title) : __('Recruiter intro request', 'senna-finance'),
            'message_body' => $intro_context,
            'attachment_urls' => $stored_cv_url,
            'application_url' => esc_url_raw((string) ($post_snapshot['application_url'] ?? '')),
            'resume_url' => $stored_cv_url,
            'submitted_at' => $requested_at_mysql,
            'applied_date' => $requested_at_mysql,
            'created_at' => $requested_at_mysql,
            'updated_at' => $requested_at_mysql,
            'notes' => $intro_context,
            'admin_message' => '',
            'post_snapshot' => wp_json_encode($post_snapshot),
            'recruiter_snapshot' => wp_json_encode($recruiter_snapshot),
        ];

        if ($existing) {
            $inserted = $wpdb->update($table, $request_data, ['id' => (int) $existing['id']]);
            $request_id = (int) $existing['id'];
        } else {
            $inserted = $wpdb->insert($table, $request_data);
            $request_id = (int) $wpdb->insert_id;
        }

        if ($inserted === false) {
            wp_send_json_error(['message' => __('Unable to save the intro request right now.', 'senna-finance')], 500);
        }

        $user = get_userdata($user_id);
        $candidate_name = $user ? $user->display_name : ('User #' . $user_id);
        $candidate_email = $user ? $user->user_email : '';
        $requested_at = wp_date(get_option('date_format') . ' ' . get_option('time_format'), current_time('timestamp'));
        $email_payload = [
            'request_id' => $request_id,
            'candidate_name' => $candidate_name,
            'candidate_email' => $candidate_email,
            'recruiter_name' => $resolved_recruiter_name,
            'recruiter_title' => $resolved_recruiter_title,
            'company_name' => $resolved_company_name,
            'recruiter_email' => $resolved_recruiter_email,
            'recruiter_linkedin' => $resolved_recruiter_linkedin,
            'stored_cv_url' => $stored_cv_url,
            'stored_cv_name' => $stored_cv_name,
            'intro_context' => $intro_context,
            'requested_at' => $requested_at,
        ];

        $admin_email = get_option('admin_email');
        if ($admin_email && is_email($admin_email)) {
            $this->send_discovery_intro_admin_email($admin_email, $email_payload);
        }
        if ($candidate_email && is_email($candidate_email)) {
            $this->send_discovery_intro_user_email($candidate_email, $email_payload);
        }

        wp_send_json_success([
            'message' => __('Your intro request has been received. MENA Careers will review it and be in touch shortly.', 'senna-finance'),
            'request_id' => $request_id,
            'request' => [
                'id' => $request_id,
                'source_post_id' => $crm_post_id,
                'name' => $resolved_recruiter_name,
                'title' => $resolved_recruiter_title,
                'company' => $resolved_company_name,
                'company_info' => $resolved_role_title,
                'email' => $resolved_recruiter_email,
                'linkedin' => $resolved_recruiter_linkedin,
                'avatar_url' => $resolved_recruiter_photo,
                'avatar_initial' => strtoupper(substr($resolved_recruiter_name !== '' ? $resolved_recruiter_name : 'R', 0, 1)),
                'status_label' => __('Queued', 'senna-finance'),
                'subject' => $request_data['message_subject'],
                'body' => $intro_context,
                'attachments' => $stored_cv_name,
                'sent_at' => wp_date(get_option('date_format'), strtotime($requested_at_mysql)),
            ],
        ]);
    }

    private function get_job_applications_table_name()
    {
        global $wpdb;
        return $wpdb->prefix . 'sffc_job_applications';
    }

    private function ensure_job_applications_table()
    {
        global $wpdb;

        $table_name = $this->get_job_applications_table_name();
        $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table_name)) === $table_name;
        if ($table_exists) {
            $this->ensure_job_applications_intro_columns();
            $this->ensure_job_applications_indexes();
            return;
        }

        $charset_collate = $wpdb->get_charset_collate();
        $sql = "CREATE TABLE {$table_name} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            user_id bigint(20) NOT NULL,
            job_id bigint(20) NOT NULL,
            source_post_id bigint(20) DEFAULT 0,
            workflow_type varchar(50) DEFAULT 'application',
            stage varchar(50) NOT NULL DEFAULT 'applied',
            applied_date datetime DEFAULT CURRENT_TIMESTAMP,
            stage_updated datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            updated_at datetime DEFAULT CURRENT_TIMESTAMP,
            notes text,
            source varchar(100),
            source_action varchar(100) DEFAULT NULL,
            company_name varchar(200),
            job_title varchar(200),
            location varchar(200),
            recruiter_id bigint(20) DEFAULT 0,
            recruiter_name varchar(255) DEFAULT NULL,
            recruiter_title varchar(255) DEFAULT NULL,
            recruiter_email varchar(255) DEFAULT NULL,
            recruiter_linkedin text DEFAULT NULL,
            recruiter_avatar_url text DEFAULT NULL,
            recruiter_location varchar(255) DEFAULT NULL,
            recruiter_regions text DEFAULT NULL,
            stored_cv_url text DEFAULT NULL,
            stored_cv_name varchar(255) DEFAULT NULL,
            message_subject text DEFAULT NULL,
            message_body longtext DEFAULT NULL,
            attachment_urls longtext DEFAULT NULL,
            application_url text DEFAULT NULL,
            submitted_at datetime DEFAULT NULL,
            confirmation_sent_at datetime DEFAULT NULL,
            resume_sent_at datetime DEFAULT NULL,
            cover_letter_sent_at datetime DEFAULT NULL,
            resume_url text DEFAULT NULL,
            cover_letter_url text DEFAULT NULL,
            admin_message longtext DEFAULT NULL,
            post_snapshot longtext DEFAULT NULL,
            recruiter_snapshot longtext DEFAULT NULL,
            salary_min int(11),
            salary_max int(11),
            PRIMARY KEY (id),
            KEY idx_user (user_id),
            KEY idx_job (job_id),
            KEY idx_stage (stage),
            KEY idx_workflow_type (workflow_type),
            KEY idx_date (applied_date),
            UNIQUE KEY unique_user_job_workflow_recruiter (user_id, job_id, workflow_type, recruiter_id)
        ) {$charset_collate};";

        require_once ABSPATH . 'wp-admin/includes/upgrade.php';
        dbDelta($sql);
        $this->ensure_job_applications_intro_columns();
        $this->ensure_job_applications_indexes();
    }

    private function ensure_job_applications_intro_columns()
    {
        global $wpdb;

        $table = $this->get_job_applications_table_name();
        if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
            return;
        }

        $columns = $wpdb->get_col("SHOW COLUMNS FROM `{$table}`");
        $columns_to_add = [
            'source_post_id' => "ALTER TABLE `{$table}` ADD COLUMN `source_post_id` bigint(20) DEFAULT 0 AFTER `job_id`",
            'workflow_type' => "ALTER TABLE `{$table}` ADD COLUMN `workflow_type` varchar(50) DEFAULT 'application' AFTER `source_post_id`",
            'created_at' => "ALTER TABLE `{$table}` ADD COLUMN `created_at` datetime DEFAULT CURRENT_TIMESTAMP AFTER `stage_updated`",
            'updated_at' => "ALTER TABLE `{$table}` ADD COLUMN `updated_at` datetime DEFAULT CURRENT_TIMESTAMP AFTER `created_at`",
            'source_action' => "ALTER TABLE `{$table}` ADD COLUMN `source_action` varchar(100) DEFAULT NULL AFTER `source`",
            'recruiter_id' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_id` bigint(20) DEFAULT 0 AFTER `location`",
            'recruiter_name' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_name` varchar(255) DEFAULT NULL AFTER `recruiter_id`",
            'recruiter_title' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_title` varchar(255) DEFAULT NULL AFTER `recruiter_name`",
            'recruiter_email' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_email` varchar(255) DEFAULT NULL AFTER `recruiter_title`",
            'recruiter_linkedin' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_linkedin` text DEFAULT NULL AFTER `recruiter_email`",
            'recruiter_avatar_url' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_avatar_url` text DEFAULT NULL AFTER `recruiter_linkedin`",
            'recruiter_location' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_location` varchar(255) DEFAULT NULL AFTER `recruiter_avatar_url`",
            'recruiter_regions' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_regions` text DEFAULT NULL AFTER `recruiter_location`",
            'stored_cv_url' => "ALTER TABLE `{$table}` ADD COLUMN `stored_cv_url` text DEFAULT NULL AFTER `recruiter_regions`",
            'stored_cv_name' => "ALTER TABLE `{$table}` ADD COLUMN `stored_cv_name` varchar(255) DEFAULT NULL AFTER `stored_cv_url`",
            'message_subject' => "ALTER TABLE `{$table}` ADD COLUMN `message_subject` text DEFAULT NULL AFTER `stored_cv_name`",
            'message_body' => "ALTER TABLE `{$table}` ADD COLUMN `message_body` longtext DEFAULT NULL AFTER `message_subject`",
            'attachment_urls' => "ALTER TABLE `{$table}` ADD COLUMN `attachment_urls` longtext DEFAULT NULL AFTER `message_body`",
            'application_url' => "ALTER TABLE `{$table}` ADD COLUMN `application_url` text DEFAULT NULL AFTER `attachment_urls`",
            'submitted_at' => "ALTER TABLE `{$table}` ADD COLUMN `submitted_at` datetime DEFAULT NULL AFTER `application_url`",
            'confirmation_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `confirmation_sent_at` datetime DEFAULT NULL AFTER `submitted_at`",
            'resume_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `resume_sent_at` datetime DEFAULT NULL AFTER `confirmation_sent_at`",
            'cover_letter_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `cover_letter_sent_at` datetime DEFAULT NULL AFTER `resume_sent_at`",
            'resume_url' => "ALTER TABLE `{$table}` ADD COLUMN `resume_url` text DEFAULT NULL AFTER `cover_letter_sent_at`",
            'cover_letter_url' => "ALTER TABLE `{$table}` ADD COLUMN `cover_letter_url` text DEFAULT NULL AFTER `resume_url`",
            'admin_message' => "ALTER TABLE `{$table}` ADD COLUMN `admin_message` longtext DEFAULT NULL AFTER `cover_letter_url`",
            'post_snapshot' => "ALTER TABLE `{$table}` ADD COLUMN `post_snapshot` longtext DEFAULT NULL AFTER `admin_message`",
            'recruiter_snapshot' => "ALTER TABLE `{$table}` ADD COLUMN `recruiter_snapshot` longtext DEFAULT NULL AFTER `post_snapshot`",
        ];

        foreach ($columns_to_add as $column_name => $sql) {
            if (in_array($column_name, $columns, true)) {
                continue;
            }
            $wpdb->query($sql);
            $columns[] = $column_name;
        }
    }

    private function ensure_job_applications_indexes()
    {
        global $wpdb;

        $table = $this->get_job_applications_table_name();
        if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) {
            return;
        }

        $indexes = $wpdb->get_results("SHOW INDEX FROM `{$table}`", ARRAY_A) ?: [];
        $index_names = [];
        foreach ($indexes as $index) {
            $index_names[(string) ($index['Key_name'] ?? '')] = true;
        }

        if (!empty($index_names['unique_user_job']) && empty($index_names['unique_user_job_workflow_recruiter'])) {
            $wpdb->query("ALTER TABLE `{$table}` DROP INDEX `unique_user_job`");
            $index_names['unique_user_job'] = false;
        }

        if (empty($index_names['unique_user_job_workflow_recruiter'])) {
            $wpdb->query("ALTER TABLE `{$table}` ADD UNIQUE KEY `unique_user_job_workflow_recruiter` (`user_id`, `job_id`, `workflow_type`, `recruiter_id`)");
        }
    }

    private function get_send_intro_hr_outreach_snapshot($recruiter_id)
    {
        $recruiter_id = (int) $recruiter_id;
        if ($recruiter_id <= 0) {
            return [];
        }

        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-hr-outreach.php';

        $model = new SFFC_CRM_HR_Outreach();
        $record = $model->get($recruiter_id);
        if (!is_array($record)) {
            return [];
        }

        return [
            'id' => (int) ($record['id'] ?? 0),
            'name' => trim((string) ($record['contact_name'] ?? '')),
            'title' => trim((string) ($record['contact_title'] ?? '')),
            'company_name' => trim((string) ($record['company_name'] ?? '')),
            'email' => sanitize_email((string) ($record['contact_email'] ?? '')),
            'linkedin' => esc_url_raw((string) ($record['contact_linkedin'] ?? '')),
            'avatar_url' => esc_url_raw((string) ($record['contact_photo'] ?? '')),
            'location' => trim((string) ($record['location'] ?? '')),
            'regions' => trim((string) ($record['regions'] ?? '')),
        ];
    }

    private function get_send_intro_post_snapshot($crm_post_id, $fallback_role_title = '', $fallback_company_name = '')
    {
        $snapshot = [
            'source_post_id' => (int) $crm_post_id,
            'role_title' => trim((string) $fallback_role_title),
            'company_name' => trim((string) $fallback_company_name),
            'location' => '',
            'application_url' => '',
            'source_url' => '',
            'permalink' => '',
        ];

        if ((int) $crm_post_id <= 0 || !class_exists('SFFC_CRM_Post')) {
            return $snapshot;
        }

        $post_model = new SFFC_CRM_Post();
        $post = $post_model->get((int) $crm_post_id);
        if (!is_array($post)) {
            return $snapshot;
        }

        $snapshot['role_title'] = trim((string) ($post['role_title'] ?? $snapshot['role_title']));
        $snapshot['company_name'] = trim((string) ($post['company'] ?? $snapshot['company_name']));
        $snapshot['location'] = trim((string) ($post['location'] ?? ''));
        $snapshot['application_url'] = esc_url_raw((string) ($post['application_url'] ?? ''));
        $snapshot['source_url'] = esc_url_raw((string) ($post['source_url'] ?? ''));
        if (function_exists('get_permalink')) {
            $snapshot['permalink'] = esc_url_raw((string) get_permalink((int) $crm_post_id));
        }

        return $snapshot;
    }

    private function get_send_intro_application_job_id($crm_post_id, $recruiter_id, $source_action)
    {
        $seed = implode('|', [
            (int) $crm_post_id,
            (int) $recruiter_id,
            sanitize_key((string) $source_action),
            'send_intro',
        ]);

        return 700000000 + abs((int) sprintf('%u', crc32($seed)));
    }

    public function submit_intro_campaign()
    {
        $user_id = $this->verify_request();

        $target_role = sanitize_text_field(wp_unslash($_POST['target_role'] ?? ''));
        $target_location = sanitize_text_field(wp_unslash($_POST['target_location'] ?? ''));
        $target_seniority = sanitize_text_field(wp_unslash($_POST['target_seniority'] ?? ''));
        $stored_cv_url = esc_url_raw(wp_unslash($_POST['stored_cv_url'] ?? ''));
        $stored_cv_name = sanitize_text_field(wp_unslash($_POST['stored_cv_name'] ?? ''));
        $target_company = sanitize_text_field(wp_unslash($_POST['target_company'] ?? ''));
        $target_sector = sanitize_text_field(wp_unslash($_POST['target_sector'] ?? ''));
        $intro_context = sanitize_textarea_field(wp_unslash($_POST['intro_context'] ?? ''));

        if ($target_role === '' || $target_location === '' || $target_seniority === '') {
            wp_send_json_error(['message' => __('Please complete the role, location, and seniority fields before submitting.', 'senna-finance')], 400);
        }

        if ($stored_cv_url === '') {
            wp_send_json_error(['message' => __('Please select a stored CV before requesting an intro campaign.', 'senna-finance')], 400);
        }

        $documents = get_user_meta($user_id, 'sffc_crm_documents', true) ?: [];
        $matched_cv = null;
        foreach ($documents as $document) {
            $document_url = esc_url_raw((string) ($document['url'] ?? ''));
            if ($document_url !== '' && $document_url === $stored_cv_url) {
                $matched_cv = is_array($document) ? $document : [];
                break;
            }
        }

        if (!$matched_cv) {
            wp_send_json_error(['message' => __('The selected CV could not be verified. Please choose a stored CV and try again.', 'senna-finance')], 400);
        }

        if ($stored_cv_name === '') {
            $stored_cv_name = trim((string) ($matched_cv['name'] ?? ''));
        }
        if ($stored_cv_name === '') {
            $stored_cv_name = __('Stored CV', 'senna-finance');
        }

        $this->ensure_linkedin_intro_queue_table();
        $this->add_intro_campaign_columns();

        global $wpdb;
        $table = $this->get_linkedin_intro_queue_table();
        $synthetic_post_id = (int) floor(microtime(true) * 1000) + wp_rand(100, 999);

        $request_data = [
            'user_id' => $user_id,
            'post_id' => $synthetic_post_id,
            'recruiter_id' => 0,
            'recruiter_name' => '',
            'recruiter_email' => '',
            'recruiter_linkedin' => '',
            'company_name' => $target_company,
            'role_title' => $target_role,
            'status' => 'pending_review',
            'request_type' => 'campaign',
            'target_role' => $target_role,
            'target_location' => $target_location,
            'target_seniority' => $target_seniority,
            'stored_cv_url' => $stored_cv_url,
            'stored_cv_name' => $stored_cv_name,
            'target_company' => $target_company,
            'target_sector' => $target_sector,
            'intro_context' => $intro_context,
            'source_action' => 'intro_campaign_form',
            'updated_at' => current_time('mysql'),
            'created_at' => current_time('mysql'),
        ];

        $inserted = $wpdb->insert($table, $request_data);
        if ($inserted === false) {
            wp_send_json_error(['message' => __('Unable to save the intro campaign right now.', 'senna-finance')], 500);
        }

        $request_id = (int) $wpdb->insert_id;
        $user = get_userdata($user_id);
        $candidate_name = $user ? $user->display_name : ('User #' . $user_id);
        $candidate_email = $user ? $user->user_email : '';
        $requested_at = wp_date(get_option('date_format') . ' ' . get_option('time_format'), current_time('timestamp'));
        $email_payload = [
            'request_id' => $request_id,
            'candidate_name' => $candidate_name,
            'candidate_email' => $candidate_email,
            'target_role' => $target_role,
            'target_location' => $target_location,
            'target_seniority' => $target_seniority,
            'target_company' => $target_company,
            'target_sector' => $target_sector,
            'stored_cv_url' => $stored_cv_url,
            'stored_cv_name' => $stored_cv_name,
            'intro_context' => $intro_context,
            'requested_at' => $requested_at,
        ];

        $admin_email = get_option('admin_email');
        if ($admin_email && is_email($admin_email)) {
            $this->send_intro_campaign_admin_email($admin_email, $email_payload);
        }
        if ($candidate_email && is_email($candidate_email)) {
            $this->send_intro_campaign_user_email($candidate_email, $email_payload);
        }

        wp_send_json_success([
            'message' => __('Your intro campaign has been submitted. MENA Careers will review it and start preparing recruiter outreach.', 'senna-finance'),
            'request_id' => $request_id,
        ]);
    }

    public function track_message_email_credit()
    {
        $user_id = $this->verify_request();
        $recruiter_email = sanitize_email(wp_unslash($_POST['recruiter_email'] ?? ''));
        $recruiter_name = sanitize_text_field(wp_unslash($_POST['recruiter_name'] ?? ''));
        $post_id = absint($_POST['post_id'] ?? 0);
        $role_title = sanitize_text_field(wp_unslash($_POST['role_title'] ?? ''));
        $company_name = sanitize_text_field(wp_unslash($_POST['company_name'] ?? ''));

        if (!$recruiter_email) {
            wp_send_json_error(['message' => __('Recruiter email is required.', 'senna-finance')], 400);
        }

        $this->ensure_credit_events_table();

        global $wpdb;
        $table = $this->get_credit_events_table();
        $week_start = wp_date('Y-m-d 00:00:00', strtotime('monday this week', current_time('timestamp')));
        $existing_event_id = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$table}
             WHERE user_id = %d
             AND event_type = %s
             AND recruiter_email = %s
             AND created_at >= %s
             ORDER BY id DESC
             LIMIT 1",
            $user_id,
            'message_email',
            $recruiter_email,
            $week_start
        ));

        if (!$existing_event_id) {
            $credit_summary = $this->get_recruiter_contact_credit_summary($user_id);
            if (empty($credit_summary['has_plan']) || (int) ($credit_summary['remaining'] ?? 0) <= 0) {
                wp_send_json_error([
                    'message' => __('No recruiter contact credits remaining for this week.', 'senna-finance'),
                    'credit_summary' => $credit_summary,
                ], 403);
            }

            $inserted = $wpdb->insert($table, [
                'user_id' => $user_id,
                'event_type' => 'message_email',
                'post_id' => $post_id,
                'recruiter_email' => $recruiter_email,
                'recruiter_name' => $recruiter_name,
                'role_title' => $role_title,
                'company_name' => $company_name,
                'credits' => 1,
                'created_at' => current_time('mysql'),
            ]);

            if ($inserted === false) {
                wp_send_json_error([
                    'message' => __('Unable to record this email credit. Please try again.', 'senna-finance'),
                    'debug' => WP_DEBUG ? $wpdb->last_error : '',
                ], 500);
            }
        }

        wp_send_json_success([
            'message' => $existing_event_id ? __('Email credit already recorded for this contact this week.', 'senna-finance') : __('Email credit recorded.', 'senna-finance'),
            'credit_charged' => !$existing_event_id,
            'credit_summary' => $this->get_recruiter_contact_credit_summary($user_id),
        ]);
    }

    public function cancel_intro_queue()
    {
        $user_id = $this->verify_request();
        $intro_id = isset($_POST['intro_id']) ? absint($_POST['intro_id']) : 0;

        if (!$intro_id) {
            wp_send_json_error(['message' => __('Missing intro request.', 'senna-finance')], 400);
        }

        $this->ensure_linkedin_intro_queue_table();
        $this->add_application_queue_columns();

        global $wpdb;
        $updated = $wpdb->update(
            $this->get_linkedin_intro_queue_table(),
            [
                'status' => 'cancelled',
                'updated_at' => current_time('mysql'),
            ],
            [
                'id' => $intro_id,
                'user_id' => $user_id,
            ]
        );

        if ($updated === false) {
            wp_send_json_error(['message' => __('Unable to cancel intro request.', 'senna-finance')], 500);
        }

        wp_send_json_success(['message' => __('Intro request cancelled.', 'senna-finance')]);
    }

    /**
     * Handle Application Pack document requests
     */
    public function request_application_pack()
    {
        if (!check_ajax_referer('sffc_crm_nonce', 'nonce', false)) {
            wp_send_json_error(['message' => __('Invalid security token', 'senna-finance')], 403);
        }

        $user_id = get_current_user_id();
        if (!$user_id) {
            wp_send_json_error(['message' => __('Please create a MENA Careers account to request an Application Pack.', 'senna-finance')], 401);
        }

        $post_id = absint($_POST['post_id'] ?? 0);
        $criteria_id = absint($_POST['criteria_id'] ?? 0);
        $recruiter_id = absint($_POST['recruiter_id'] ?? 0);
        $role_title = sanitize_text_field(wp_unslash($_POST['role_title'] ?? ''));
        $company = sanitize_text_field(wp_unslash($_POST['company_name'] ?? ($_POST['company'] ?? '')));
        $location = sanitize_text_field(wp_unslash($_POST['location'] ?? ''));
        $recruiter_name = sanitize_text_field(wp_unslash($_POST['recruiter_name'] ?? ''));
        $recruiter_email = sanitize_email(wp_unslash($_POST['recruiter_email'] ?? ''));
        $recruiter_linkedin = esc_url_raw(wp_unslash($_POST['recruiter_linkedin'] ?? ''));
        $role_url = esc_url_raw(wp_unslash($_POST['role_url'] ?? ''));
        $cv_id = sanitize_text_field(wp_unslash($_POST['cv_id'] ?? ''));
        $custom_request = sanitize_textarea_field(wp_unslash($_POST['custom_request'] ?? ''));
        $application_type = sanitize_text_field(wp_unslash($_POST['application_type'] ?? 'standard'));

        if (!$post_id) {
            wp_send_json_error(['message' => __('Missing role reference.', 'senna-finance')], 400);
        }

        if (!class_exists('SFFC_CRM_CV_Manager') && defined('SFFC_PLUGIN_DIR')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-cv.php';
        }
        if (!class_exists('SFFC_CRM_Post') && defined('SFFC_PLUGIN_DIR')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php';
        }
        if (!class_exists('SFFC_CRM_User_Criteria') && defined('SFFC_PLUGIN_DIR')) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-user-criteria.php';
        }

        if ((!$role_title || !$company || !$recruiter_name || !$recruiter_email) && class_exists('SFFC_CRM_Post')) {
            $post_model = new SFFC_CRM_Post();
            $post = $post_model->get($post_id);
            if ($post) {
                $role_title = $role_title ?: sanitize_text_field($post['role_title'] ?? '');
                $company = $company ?: sanitize_text_field($post['company'] ?? '');
                $location = $location ?: sanitize_text_field($post['location'] ?? '');
                $recruiter_name = $recruiter_name ?: sanitize_text_field($post['recruiter_name'] ?? '');
                $recruiter_email = $recruiter_email ?: sanitize_email($post['recruiter_email'] ?? '');
            }
        }

        $criteria_name = __('Profile preferences', 'senna-finance');
        $cv_label = '';
        $cv_url = '';
        $cv_content = '';
        $cover_label = '';
        $cover_url = '';
        $criteria = null;
        $supporting_documents = [];

        // Get CV from CV Manager if cv_id is provided
        if ($cv_id && class_exists('SFFC_CRM_CV_Manager')) {
            $cv_manager = new SFFC_CRM_CV_Manager();
            $cv_entry = $cv_manager->get_cv_by_id($user_id, $cv_id);
            if ($cv_entry) {
                $cv_label = isset($cv_entry['label']) ? $cv_entry['label'] : 'Selected CV';
                $cv_content = isset($cv_entry['content']) ? $cv_entry['content'] : '';
            }
        }

        if ($criteria_id && class_exists('SFFC_CRM_User_Criteria')) {
            $criteria_model = new SFFC_CRM_User_Criteria();
            $criteria = $criteria_model->get_by_id($criteria_id, $user_id);
            if ($criteria) {
                $criteria_name = !empty($criteria['name']) ? sanitize_text_field($criteria['name']) : $criteria_name;
                if (!empty($criteria['cv_file_id']) && empty($cv_label)) {
                    $cv_label = get_the_title((int) $criteria['cv_file_id']);
                    $cv_url = wp_get_attachment_url((int) $criteria['cv_file_id']);
                }
                if (!empty($criteria['cover_letter_file_id'])) {
                    $cover_label = get_the_title((int) $criteria['cover_letter_file_id']);
                    $cover_url = wp_get_attachment_url((int) $criteria['cover_letter_file_id']);
                }
            }
        }

        $document_bundle = $this->get_application_pack_document_bundle($user_id, $criteria, [
            'cv_id' => $cv_id,
            'cv_label' => $cv_label,
            'cv_url' => $cv_url,
            'cv_content' => $cv_content,
            'cover_label' => $cover_label,
            'cover_url' => $cover_url,
        ]);
        $cv_label = $document_bundle['cv_label'];
        $cv_url = $document_bundle['cv_url'];
        $cv_content = $document_bundle['cv_content'];
        $cover_label = $document_bundle['cover_label'];
        $cover_url = $document_bundle['cover_url'];
        $supporting_documents = $document_bundle['supporting_documents'];

        $pack_items = $application_type === 'tailored'
            ? [
                __('Tailored CV', 'senna-finance'),
                __('Cover letter', 'senna-finance'),
                __('Expert review', 'senna-finance'),
                __('Application questions prepared', 'senna-finance'),
            ]
            : [
                __('CV fit check', 'senna-finance'),
                __('Tailored CV bullet improvements', 'senna-finance'),
                __('Cover letter outline', 'senna-finance'),
                __('Recruiter outreach message', 'senna-finance'),
                __('Interview prep questions', 'senna-finance'),
            ];

        $this->ensure_application_pack_table();

        global $wpdb;
        $table = $this->get_application_pack_table();
        $user = get_userdata($user_id);
        $user_email = $user ? $user->user_email : '';
        $user_name = $user ? $user->display_name : __('Guest User', 'senna-finance');
        $now = current_time('mysql');

        $existing_id = (int) $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$table} WHERE user_id = %d AND post_id = %d AND status IN ('requested', 'preparing') ORDER BY id DESC LIMIT 1",
            $user_id,
            $post_id
        ));

        $data = [
            'user_id' => $user_id,
            'user_name' => $user_name,
            'user_email' => $user_email,
            'post_id' => $post_id,
            'recruiter_id' => $recruiter_id,
            'recruiter_name' => $recruiter_name,
            'recruiter_email' => $recruiter_email,
            'recruiter_linkedin' => $recruiter_linkedin,
            'role_title' => $role_title,
            'company_name' => $company,
            'location' => $location,
            'criteria_id' => $criteria_id,
            'criteria_name' => $criteria_name,
            'pack_items' => wp_json_encode($pack_items),
            'cv_label' => $cv_label,
            'cv_url' => $cv_url,
            'cover_label' => $cover_label,
            'cover_url' => $cover_url,
            'status' => 'requested',
            'updated_at' => $now,
            'application_type' => $application_type,
            'cv_id' => $cv_id,
            'admin_notes' => wp_json_encode([
                'custom_request' => $custom_request,
                'supporting_documents' => $supporting_documents,
            ]),
        ];

        if ($existing_id) {
            $saved = $wpdb->update($table, $data, ['id' => $existing_id]);
            $request_id = $existing_id;
        } else {
            $data['created_at'] = $now;
            $saved = $wpdb->insert($table, $data);
            $request_id = (int) $wpdb->insert_id;
        }

        if ($saved === false && stripos((string) $wpdb->last_error, 'Unknown column') !== false) {
            $this->repair_application_pack_table_columns();
            if ($existing_id) {
                $saved = $wpdb->update($table, $data, ['id' => $existing_id]);
                $request_id = $existing_id;
            } else {
                $saved = $wpdb->insert($table, $data);
                $request_id = (int) $wpdb->insert_id;
            }
        }

        if ($saved === false) {
            error_log('Application Pack DB Error: ' . $wpdb->last_error);
            wp_send_json_error(['message' => __('Unable to save this Application Pack request.', 'senna-finance')], 500);
        }

        $admin_email = get_option('admin_email');
        if ($admin_email) {
            $this->send_application_pack_admin_email([
                'request_id' => $request_id,
                'user_name' => $user_name,
                'user_email' => $user_email,
                'role_title' => $role_title,
                'company_name' => $company,
            'recruiter_name' => $recruiter_name,
            'recruiter_email' => $recruiter_email,
            'criteria_name' => $criteria_name,
            'pack_items' => $pack_items,
            'role_url' => $role_url,
            'location' => $location,
            'cv_label' => $cv_label,
            'cv_url' => $cv_url,
            'cv_content' => $cv_content,
            'cover_label' => $cover_label,
            'cover_url' => $cover_url,
            'supporting_documents' => $supporting_documents,
            'custom_request' => $custom_request,
            'created_at' => $now,
            'application_type' => $application_type,
        ]);
        }

        if ($user_email) {
            $this->send_application_pack_user_confirmation([
                'user_name' => $user_name,
                'user_email' => $user_email,
                'role_title' => $role_title,
                'company_name' => $company,
                'location' => $location,
                'recruiter_name' => $recruiter_name,
                'pack_items' => $pack_items,
                'cv_label' => $cv_label,
                'role_url' => $role_url,
                'request_id' => $request_id,
                'created_at' => $now,
                'application_type' => $application_type,
            ]);
        }

        wp_send_json_success([
            'message' => __('Tailored materials requested. We emailed you a confirmation and queued this for the MENA Careers team.', 'senna-finance'),
            'request_id' => $request_id,
            'status' => 'requested',
        ]);
    }

    private function user_has_paid_crm_membership($user_id)
    {
        $user_id = absint($user_id);
        if (!$user_id) {
            return false;
        }

        if (user_can($user_id, 'manage_options')) {
            return true;
        }

        if (class_exists('SFFC_CRM_MemberPress_Integration')) {
            $crm_integration = SFFC_CRM_MemberPress_Integration::get_instance();
            $tier = $crm_integration->get_crm_tier($user_id);

            if (in_array($tier, ['insider', 'pro'], true)) {
                return true;
            }

            if (in_array($tier, ['basic', 'free'], true)) {
                return false;
            }
        }

        if (class_exists('SFFC_MemberPress_Integration')) {
            $mepr = SFFC_MemberPress_Integration::get_instance();
            if ($mepr->has_premium_access($user_id, 'insider') || $mepr->has_premium_access($user_id, 'pro')) {
                return true;
            }
        }

        return false;
    }

    private function get_application_pack_table()
    {
        global $wpdb;
        return $wpdb->prefix . 'sffc_crm_application_packs';
    }

    private function ensure_application_pack_table()
    {
        global $wpdb;

        require_once ABSPATH . 'wp-admin/includes/upgrade.php';

        $table = $this->get_application_pack_table();
        $charset_collate = $wpdb->get_charset_collate();
        $sql = "CREATE TABLE {$table} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            user_id bigint(20) DEFAULT 0,
            user_name varchar(200) DEFAULT NULL,
            user_email varchar(255) DEFAULT NULL,
            post_id bigint(20) DEFAULT 0,
            recruiter_id bigint(20) DEFAULT 0,
            recruiter_name varchar(200) DEFAULT NULL,
            recruiter_email varchar(255) DEFAULT NULL,
            recruiter_linkedin varchar(500) DEFAULT NULL,
            role_title varchar(255) DEFAULT NULL,
            company_name varchar(255) DEFAULT NULL,
            location varchar(255) DEFAULT NULL,
            criteria_id bigint(20) DEFAULT 0,
            criteria_name varchar(255) DEFAULT NULL,
            pack_items text DEFAULT NULL,
            cv_label varchar(255) DEFAULT NULL,
            cv_url text DEFAULT NULL,
            cv_id varchar(100) DEFAULT NULL,
            cover_label varchar(255) DEFAULT NULL,
            cover_url text DEFAULT NULL,
            application_type varchar(50) DEFAULT 'standard',
            status varchar(50) DEFAULT 'requested',
            admin_notes text DEFAULT NULL,
            delivered_at datetime DEFAULT NULL,
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            KEY idx_user (user_id),
            KEY idx_post (post_id),
            KEY idx_status (status),
            KEY idx_created (created_at),
            KEY idx_app_type (application_type)
        ) {$charset_collate};";

        dbDelta($sql);
        $this->repair_application_pack_table_columns();
    }

    private function repair_application_pack_table_columns()
    {
        global $wpdb;

        $table = $this->get_application_pack_table();
        $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($table))) === $table;
        if (!$table_exists) {
            return;
        }

        $columns = $wpdb->get_col("SHOW COLUMNS FROM {$table}");
        $columns = is_array($columns) ? $columns : [];
        $column_definitions = [
            'recruiter_linkedin' => "ALTER TABLE {$table} ADD COLUMN recruiter_linkedin varchar(500) DEFAULT NULL AFTER recruiter_email",
            'cv_id' => "ALTER TABLE {$table} ADD COLUMN cv_id varchar(100) DEFAULT NULL AFTER cv_url",
            'application_type' => "ALTER TABLE {$table} ADD COLUMN application_type varchar(50) DEFAULT 'standard' AFTER cover_url",
            'admin_notes' => "ALTER TABLE {$table} ADD COLUMN admin_notes text DEFAULT NULL AFTER status",
            'delivered_at' => "ALTER TABLE {$table} ADD COLUMN delivered_at datetime DEFAULT NULL AFTER admin_notes",
        ];

        foreach ($column_definitions as $column => $sql) {
            if (!in_array($column, $columns, true)) {
                $wpdb->query($sql);
            }
        }

        $indexes = $wpdb->get_results("SHOW INDEX FROM {$table}", ARRAY_A);
        $has_application_type_index = false;
        if (is_array($indexes)) {
            foreach ($indexes as $index) {
                if (($index['Column_name'] ?? '') === 'application_type') {
                    $has_application_type_index = true;
                    break;
                }
            }
        }

        if (!$has_application_type_index && in_array('application_type', $columns, true)) {
            $wpdb->query("ALTER TABLE {$table} ADD KEY idx_app_type (application_type)");
        }
    }

    private function get_application_pack_document_bundle($user_id, $criteria = null, array $seed = [])
    {
        $documents = get_user_meta($user_id, 'sffc_crm_documents', true);
        $documents = is_array($documents) ? $documents : [];

        $cv_label = (string) ($seed['cv_label'] ?? '');
        $cv_url = (string) ($seed['cv_url'] ?? '');
        $cv_content = (string) ($seed['cv_content'] ?? '');
        $cover_label = (string) ($seed['cover_label'] ?? '');
        $cover_url = (string) ($seed['cover_url'] ?? '');
        $supporting_documents = [];
        $selected_cv_label = trim((string) ($seed['cv_label'] ?? ''));
        $primary_resume_document = null;
        $matching_resume_document = null;

        foreach ($documents as $document) {
            $document_name = sanitize_text_field($document['name'] ?? '');
            $document_url = esc_url_raw($document['url'] ?? '');
            $document_type = sanitize_key($document['document_type'] ?? 'supporting');

            if (!$document_name || !$document_url || $document_type !== 'resume_cv') {
                continue;
            }

            if ($primary_resume_document === null) {
                $primary_resume_document = [
                    'name' => $document_name,
                    'url' => $document_url,
                ];
            }

            if ($selected_cv_label !== '' && strcasecmp($selected_cv_label, $document_name) === 0) {
                $matching_resume_document = [
                    'name' => $document_name,
                    'url' => $document_url,
                ];
                break;
            }
        }

        $preferred_resume_document = $matching_resume_document ?: $primary_resume_document;
        if ($preferred_resume_document) {
            $cv_label = $preferred_resume_document['name'];
            $cv_url = $preferred_resume_document['url'];
        }

        if (!empty($criteria['cv_file_id']) && !$cv_url) {
            $criteria_cv_label = get_the_title((int) $criteria['cv_file_id']);
            $criteria_cv_url = wp_get_attachment_url((int) $criteria['cv_file_id']);
            if (!$cv_label && $criteria_cv_label) {
                $cv_label = $criteria_cv_label;
            }
            if (!$cv_url && $criteria_cv_url) {
                $cv_url = $criteria_cv_url;
            }
        }

        if (!empty($criteria['cover_letter_file_id'])) {
            $criteria_cover_label = get_the_title((int) $criteria['cover_letter_file_id']);
            $criteria_cover_url = wp_get_attachment_url((int) $criteria['cover_letter_file_id']);
            if (!$cover_label && $criteria_cover_label) {
                $cover_label = $criteria_cover_label;
            }
            if (!$cover_url && $criteria_cover_url) {
                $cover_url = $criteria_cover_url;
            }
        }

        foreach ($documents as $document) {
            $document_name = sanitize_text_field($document['name'] ?? '');
            $document_url = esc_url_raw($document['url'] ?? '');
            $document_type = sanitize_key($document['document_type'] ?? 'supporting');

            if (!$document_name || !$document_url) {
                continue;
            }

            if ($document_type === 'resume_cv') {
                continue;
            }

            $supporting_documents[] = [
                'name' => $document_name,
                'url' => $document_url,
                'type' => $document_type ?: 'supporting',
            ];
        }

        return [
            'cv_label' => $cv_label,
            'cv_url' => $cv_url,
            'cv_content' => $cv_content,
            'cover_label' => $cover_label,
            'cover_url' => $cover_url,
            'supporting_documents' => $supporting_documents,
        ];
    }

