    /**
     * Handle Express Interest click - Track application
     */
    public function express_interest()
    {
        // Nonce verification
        if (!check_ajax_referer('sffc_crm_nonce', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid security token'], 403);
        }

        $user_id = get_current_user_id();
        if (!$user_id) {
            wp_send_json_error(['message' => 'Please log in'], 401);
        }

        $post_id = absint($_POST['post_id'] ?? 0);
        $recruiter_email = sanitize_email($_POST['recruiter_email'] ?? '');
        $recruiter_name = sanitize_text_field($_POST['recruiter_name'] ?? '');
        $role_title = sanitize_text_field($_POST['role_title'] ?? '');
        $company = sanitize_text_field($_POST['company'] ?? '');

        if (!$post_id) {
            wp_send_json_error(['message' => 'Invalid post'], 400);
        }

        // Use existing intro requests table with status 'applied'
        $this->ensure_linkedin_intro_queue_table();
        $this->add_application_queue_columns();

        global $wpdb;
        $table = $this->get_linkedin_intro_queue_table();

        // Check if already applied
        $existing = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE user_id = %d AND post_id = %d ORDER BY id DESC LIMIT 1",
            $user_id,
            $post_id
        ), ARRAY_A);

        if ($existing) {
            wp_send_json_success([
                'message' => 'Application already tracked',
                'application_id' => (int) $existing['id'],
            ]);
        }

        // Prepare insert data with only core columns that always exist
        $insert_data = [
            'user_id' => $user_id,
            'post_id' => $post_id,
            'recruiter_id' => 0,
            'recruiter_name' => $recruiter_name,
            'recruiter_email' => $recruiter_email,
            'company_name' => $company,
            'role_title' => $role_title,
            'status' => 'applied',
            'created_at' => current_time('mysql'),
            'updated_at' => current_time('mysql'),
        ];

        // Check if optional columns exist before adding them
        $columns = $wpdb->get_col("SHOW COLUMNS FROM {$table}");

        if (in_array('materials_status', $columns)) {
            $insert_data['materials_status'] = 'not_requested';
        }

        if (in_array('tracking_status', $columns)) {
            $insert_data['tracking_status'] = 'applied';
        }

        $express_interest_optional = [
            'source_action' => 'express_interest',
            'queue_status' => 'queued',
            'queue_position' => 0,
        ];
        foreach ($express_interest_optional as $column => $value) {
            if (in_array($column, $columns, true)) {
                $insert_data[$column] = $value;
            }
        }

        // Insert new application
        $inserted = $wpdb->insert($table, $insert_data);

        if ($inserted === false) {
            // Log the actual error for debugging
            error_log('Express Interest DB Error: ' . $wpdb->last_error);
            wp_send_json_error([
                'message' => 'Unable to track application. Please try again or contact support.',
                'debug' => WP_DEBUG ? $wpdb->last_error : ''
            ], 500);
        }

        $application_id = (int) $wpdb->insert_id;

        // Send admin notification
        $user = get_userdata($user_id);
        $admin_email = get_option('admin_email');
        $subject = sprintf('[Applied] %s - %s at %s', $user->display_name, $role_title, $company);
        $message = "A user expressed interest in a role.\n\n";
        $message .= "User: {$user->display_name}\n";
        $message .= "Email: {$user->user_email}\n";
        $message .= "Role: {$role_title}\n";
        $message .= "Company: {$company}\n";
        $message .= "Recruiter: {$recruiter_name} ({$recruiter_email})\n";
        wp_mail($admin_email, $subject, $message);

        wp_send_json_success([
            'message' => 'Application tracked successfully',
            'application_id' => $application_id,
        ]);
    }

    public function remove_application()
    {
        // Nonce verification
        if (!check_ajax_referer('sffc_crm_nonce', 'nonce', false)) {
            wp_send_json_error(['message' => 'Invalid security token'], 403);
        }

        $user_id = get_current_user_id();
        if (!$user_id) {
            wp_send_json_error(['message' => 'Please log in'], 401);
        }

        $application_id = absint($_POST['application_id'] ?? 0);
        if (!$application_id) {
            wp_send_json_error(['message' => 'Invalid application ID'], 400);
        }

        global $wpdb;
        $table = $this->get_linkedin_intro_queue_table();

        // Verify ownership before deleting
        $application = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE id = %d AND user_id = %d",
            $application_id,
            $user_id
        ), ARRAY_A);

        if (!$application) {
            wp_send_json_error(['message' => 'Application not found or access denied'], 404);
        }

        // Delete the application
        $deleted = $wpdb->delete($table, [
            'id' => $application_id,
            'user_id' => $user_id
        ], ['%d', '%d']);

        if ($deleted === false) {
            wp_send_json_error(['message' => 'Unable to remove application'], 500);
        }

        wp_send_json_success([
            'message' => 'Application removed successfully',
        ]);
    }

    public function save_application_queue()
    {
        if (!check_ajax_referer('sffc_crm_nonce', 'nonce', false)) {
            wp_send_json_error(['message' => __('Invalid security token', 'senna-finance')], 403);
        }

        $user_id = get_current_user_id();
        if (!$user_id) {
            wp_send_json_error(['message' => __('Please log in', 'senna-finance')], 401);
        }

        $post_id = absint($_POST['post_id'] ?? 0);
        $queue_status = sanitize_key($_POST['queue_status'] ?? 'queued');
        $allowed_statuses = ['queued', 'cancelled'];

        if (!$post_id || !in_array($queue_status, $allowed_statuses, true)) {
            wp_send_json_error(['message' => __('Invalid application queue request.', 'senna-finance')], 400);
        }

        $this->ensure_linkedin_intro_queue_table();
        $this->add_application_queue_columns();

        global $wpdb;
        $table = $this->get_linkedin_intro_queue_table();
        $columns = $wpdb->get_col("SHOW COLUMNS FROM {$table}");

        $criteria_id = absint($_POST['criteria_id'] ?? 0);
        $role_title = sanitize_text_field(wp_unslash($_POST['role_title'] ?? ''));
        $company = sanitize_text_field(wp_unslash($_POST['company'] ?? ''));
        $recruiter_name = sanitize_text_field(wp_unslash($_POST['recruiter_name'] ?? ''));
        $recruiter_email = sanitize_email(wp_unslash($_POST['recruiter_email'] ?? ''));
        $application_url = esc_url_raw(wp_unslash($_POST['application_url'] ?? ''));
        $queue_position = absint($_POST['queue_position'] ?? 0);
        $cv_file_id = 0;
        $cover_letter_file_id = 0;

        if ($criteria_id) {
            require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-user-criteria.php';
            $criteria_model = new SFFC_CRM_User_Criteria();
            $criteria = $criteria_model->get_by_id($criteria_id, $user_id);
            if ($criteria) {
                $cv_file_id = (int) ($criteria['cv_file_id'] ?? 0);
                $cover_letter_file_id = (int) ($criteria['cover_letter_file_id'] ?? 0);
            }
        }

        if (!$role_title || !$company || !$application_url) {
            if (!class_exists('SFFC_CRM_Post')) {
                require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php';
            }
            $post_model = new SFFC_CRM_Post();
            $post = $post_model->get($post_id);
            if ($post) {
                $role_title = $role_title ?: sanitize_text_field($post['role_title'] ?? '');
                $company = $company ?: sanitize_text_field($post['company'] ?? '');
                $recruiter_name = $recruiter_name ?: sanitize_text_field($post['recruiter_name'] ?? '');
                $recruiter_email = $recruiter_email ?: sanitize_email($post['recruiter_email'] ?? '');
                $application_url = $application_url ?: esc_url_raw($post['application_url'] ?? '');
            }
        }

        $existing = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM {$table} WHERE user_id = %d AND post_id = %d ORDER BY id DESC LIMIT 1",
            $user_id,
            $post_id
        ), ARRAY_A);
        $is_new_queued_application = $queue_status === 'queued' && (!$existing || ($existing['source_action'] ?? '') !== 'kanban_drag' || ($existing['queue_status'] ?? '') !== 'queued');

        $data = [
            'user_id' => $user_id,
            'post_id' => $post_id,
            'recruiter_id' => 0,
            'recruiter_name' => $recruiter_name,
            'recruiter_email' => $recruiter_email,
            'company_name' => $company,
            'role_title' => $role_title,
            'status' => $queue_status === 'queued' ? 'queued' : 'cancelled',
            'updated_at' => current_time('mysql'),
        ];

        $optional_data = [
            'tracking_status' => $queue_status === 'queued' ? 'queued' : 'cancelled',
            'criteria_id' => $criteria_id,
            'cv_file_id' => $cv_file_id,
            'cover_letter_file_id' => $cover_letter_file_id,
            'application_url' => $application_url,
            'source_action' => 'kanban_drag',
            'queue_status' => $queue_status,
            'queue_position' => $queue_position,
        ];

        foreach ($optional_data as $column => $value) {
            if (in_array($column, $columns, true)) {
                $data[$column] = $value;
            }
        }

        if ($queue_status === 'queued' && in_array('materials_status', $columns, true)) {
            $data['materials_status'] = $cv_file_id ? 'materials_ready' : 'not_requested';
        }

        if ($existing) {
            $saved = $wpdb->update($table, $data, [
                'id' => (int) $existing['id'],
                'user_id' => $user_id,
            ]);
            $application_id = (int) $existing['id'];
        } else {
            $data['created_at'] = current_time('mysql');
            $saved = $wpdb->insert($table, $data);
            $application_id = (int) $wpdb->insert_id;
        }

        if ($saved === false) {
            error_log('Application Queue DB Error: ' . $wpdb->last_error);
            wp_send_json_error([
                'message' => __('Unable to save this application queue change.', 'senna-finance'),
                'debug' => WP_DEBUG ? $wpdb->last_error : '',
            ], 500);
        }

        if ($is_new_queued_application) {
            $this->send_application_queue_admin_email([
                'application_id' => $application_id,
                'user_id' => $user_id,
                'role_title' => $role_title,
                'company' => $company,
                'recruiter_name' => $recruiter_name,
                'recruiter_email' => $recruiter_email,
                'application_url' => $application_url,
                'criteria_id' => $criteria_id,
                'cv_file_id' => $cv_file_id,
                'cover_letter_file_id' => $cover_letter_file_id,
            ]);
            $this->handle_user_application_queue_email($application_id, $user_id);
        }

        wp_send_json_success([
            'message' => $queue_status === 'queued' ? __('Application queued.', 'senna-finance') : __('Application removed from queue.', 'senna-finance'),
            'application_id' => $application_id,
            'queue_status' => $queue_status,
            'credit_summary' => $this->get_apply_all_credit_summary($user_id),
        ]);
    }

    private function extract_memberpress_product_id_from_shortcode($shortcode)
    {
        if (empty($shortcode)) {
            return 0;
        }

        $shortcode = stripslashes((string) $shortcode);
        if (preg_match('/\[mepr-membership-registration-form[^\]]*\bid=[\'"]?(\d+)[\'"]?/i', $shortcode, $matches)) {
            return absint($matches[1]);
        }

        return 0;
    }

    private function get_active_memberpress_product_ids($user_id)
    {
        $user_id = absint($user_id);
        if (!$user_id || !class_exists('MeprUser')) {
            return [];
        }

        $product_ids = [];
        try {
            $mepr_user = new MeprUser($user_id);
            $active_products = $mepr_user->active_product_subscriptions('products');
            if (is_array($active_products)) {
                foreach ($active_products as $product) {
                    if (is_object($product) && !empty($product->ID)) {
                        $product_ids[] = (int) $product->ID;
                    } elseif (is_numeric($product)) {
                        $product_ids[] = (int) $product;
                    }
                }
            }

            $active_subscriptions = $mepr_user->active_product_subscriptions('subscriptions', true);
            if (is_array($active_subscriptions)) {
                foreach ($active_subscriptions as $subscription) {
                    if (is_object($subscription) && !empty($subscription->product_id)) {
                        $product_ids[] = (int) $subscription->product_id;
                    }
                }
            }
        } catch (Throwable $e) {
            if (defined('WP_DEBUG') && WP_DEBUG) {
                error_log('SFFC Apply All AJAX credit lookup failed: ' . $e->getMessage());
            }
        }

        return array_values(array_unique(array_filter(array_map('absint', $product_ids))));
    }

    private function get_memberpress_product_price_amount($product_id)
    {
        $product_id = absint($product_id);
        if (!$product_id || !class_exists('MeprProduct')) {
            return 0.0;
        }

        try {
            $product = new MeprProduct($product_id);
            return isset($product->price) ? (float) $product->price : 0.0;
        } catch (Throwable $e) {
            if (defined('WP_DEBUG') && WP_DEBUG) {
                error_log('SFFC Apply All AJAX product price lookup failed: ' . $e->getMessage());
            }
        }

        return 0.0;
    }

    private function get_free_apply_all_plan(array $source_plan = [])
    {
        return [
            'name' => !empty($source_plan['name']) ? $source_plan['name'] : __('Free Plan', 'senna-finance'),
            'slug' => !empty($source_plan['slug']) ? $source_plan['slug'] : 'free',
            'matches_per_week' => 5,
            'memberpress_product_id' => !empty($source_plan['memberpress_product_id']) ? (int) $source_plan['memberpress_product_id'] : 0,
            'price_amount' => 0.0,
            'is_free_plan' => true,
        ];
    }

    private function is_apply_all_paid_plan(array $plan)
    {
        return isset($plan['price_amount']) && (float) $plan['price_amount'] > 0;
    }

    private function has_active_paid_memberpress_plan(array $active_product_ids)
    {
        foreach ($active_product_ids as $product_id) {
            if ($this->get_memberpress_product_price_amount($product_id) > 0) {
                return true;
            }
        }

        return false;
    }

    private function is_recruiter_contact_credit_plan(array $plan)
    {
        $signup_path = (string) ($plan['signup_path'] ?? '');

        return !empty($plan['recruiter_contact_pricing'])
            || in_array($signup_path, ['one_contact', 'extra_contacts', 'ongoing_contacts'], true);
    }

    private function get_user_apply_all_plan($user_id)
    {
        $plans = get_option('sffc_dashboard_plans', []);
        if ((empty($plans) || !is_array($plans)) && class_exists('SFFC_PE_News_Dashboard')) {
            $dashboard = SFFC_PE_News_Dashboard::get_instance();
            if ($dashboard && method_exists($dashboard, 'get_default_subscription_plans')) {
                $plans = $dashboard->get_default_subscription_plans();
            }
        }

        $normalized_plans = [];
        foreach ((array) $plans as $plan) {
            if (empty($plan['name'])) {
                continue;
            }
            $shortcode = isset($plan['shortcode']) ? (string) $plan['shortcode'] : '';
            $product_id = !empty($plan['memberpress_product_id'])
                ? absint($plan['memberpress_product_id'])
                : $this->extract_memberpress_product_id_from_shortcode($shortcode);
            $price_amount = isset($plan['price_amount']) && $plan['price_amount'] !== ''
                ? (float) $plan['price_amount']
                : $this->get_memberpress_product_price_amount($product_id);
            $normalized_plans[] = [
                'name' => sanitize_text_field($plan['name']),
                'slug' => sanitize_title($plan['slug'] ?? $plan['name']),
                'matches_per_week' => isset($plan['matches_per_week']) ? max(0, (int) $plan['matches_per_week']) : 0,
                'memberpress_product_id' => $product_id,
                'price_amount' => $price_amount,
            ];
        }

        if (empty($normalized_plans)) {
            $active_product_ids = $this->get_active_memberpress_product_ids($user_id);
            return $this->has_active_paid_memberpress_plan($active_product_ids) ? null : $this->get_free_apply_all_plan();
        }

        if (user_can($user_id, 'manage_options')) {
            usort($normalized_plans, function ($a, $b) {
                return (int) ($b['matches_per_week'] ?? 0) <=> (int) ($a['matches_per_week'] ?? 0);
            });
            return $normalized_plans[0];
        }

        $active_product_ids = $this->get_active_memberpress_product_ids($user_id);
        if (empty($active_product_ids)) {
            return $this->get_free_apply_all_plan();
        }

        $matched_plans = array_values(array_filter($normalized_plans, function ($plan) use ($active_product_ids) {
            $product_id = (int) ($plan['memberpress_product_id'] ?? 0);
            return $product_id && in_array($product_id, $active_product_ids, true);
        }));

        if (empty($matched_plans)) {
            return $this->has_active_paid_memberpress_plan($active_product_ids) ? null : $this->get_free_apply_all_plan();
        }

        $paid_plans = array_values(array_filter($matched_plans, function ($plan) {
            return $this->is_apply_all_paid_plan($plan);
        }));
        if (empty($paid_plans)) {
            return $this->get_free_apply_all_plan($matched_plans[0]);
        }

        usort($paid_plans, function ($a, $b) {
            return (int) ($b['matches_per_week'] ?? 0) <=> (int) ($a['matches_per_week'] ?? 0);
        });

        return $paid_plans[0];
    }

    private function get_dashboard_membership_plans_for_recruiter_contacts()
    {
        $plans = get_option('sffc_dashboard_plans', []);
        if ((empty($plans) || !is_array($plans)) && class_exists('SFFC_PE_News_Dashboard')) {
            $dashboard = SFFC_PE_News_Dashboard::get_instance();
            if ($dashboard && method_exists($dashboard, 'get_default_subscription_plans')) {
                $plans = $dashboard->get_default_subscription_plans();
            }
        }

        $normalized_plans = [];
        foreach ((array) $plans as $plan) {
            if (empty($plan['name'])) {
                continue;
            }
            $shortcode = isset($plan['shortcode']) ? (string) $plan['shortcode'] : '';
            $product_id = !empty($plan['memberpress_product_id'])
                ? absint($plan['memberpress_product_id'])
                : $this->extract_memberpress_product_id_from_shortcode($shortcode);
            $price_amount = isset($plan['price_amount']) && $plan['price_amount'] !== ''
                ? (float) $plan['price_amount']
                : $this->get_memberpress_product_price_amount($product_id);
            $normalized_plans[] = [
                'name' => sanitize_text_field($plan['name']),
                'slug' => sanitize_title($plan['slug'] ?? $plan['name']),
                'matches_per_week' => isset($plan['matches_per_week']) ? max(0, (int) $plan['matches_per_week']) : 0,
                'memberpress_product_id' => $product_id,
                'price_amount' => $price_amount,
                'signup_path' => (string) ($plan['signup_path'] ?? ''),
                'recruiter_contact_pricing' => !empty($plan['recruiter_contact_pricing']) ? 1 : 0,
            ];
        }

        $filtered = array_values(array_filter($normalized_plans, [$this, 'is_recruiter_contact_credit_plan']));

        return !empty($filtered) ? $filtered : $normalized_plans;
    }

    private function get_user_recruiter_contact_plan($user_id)
    {
        $plans = $this->get_dashboard_membership_plans_for_recruiter_contacts();
        if (empty($plans)) {
            return null;
        }

        if (user_can($user_id, 'manage_options')) {
            usort($plans, function ($a, $b) {
                return (int) ($b['matches_per_week'] ?? 0) <=> (int) ($a['matches_per_week'] ?? 0);
            });
            return $plans[0];
        }

        $active_product_ids = $this->get_active_memberpress_product_ids($user_id);
        if (empty($active_product_ids)) {
            return null;
        }

        $matched_plans = array_values(array_filter($plans, function ($plan) use ($active_product_ids) {
            $product_id = (int) ($plan['memberpress_product_id'] ?? 0);
            return $product_id && in_array($product_id, $active_product_ids, true);
        }));

        if (empty($matched_plans)) {
            return null;
        }

        $paid_plans = array_values(array_filter($matched_plans, function ($plan) {
            return $this->is_apply_all_paid_plan($plan);
        }));

        if (empty($paid_plans)) {
            return null;
        }

        usort($paid_plans, function ($a, $b) {
            return (int) ($b['matches_per_week'] ?? 0) <=> (int) ($a['matches_per_week'] ?? 0);
        });

        return $paid_plans[0];
    }

    private function get_recruiter_contact_credit_summary($user_id)
    {
        $user_id = absint($user_id);
        $plan = $user_id ? $this->get_user_recruiter_contact_plan($user_id) : null;
        $limit = $plan ? max(0, (int) ($plan['matches_per_week'] ?? 0)) : 0;
        $used = 0;

        if ($user_id) {
            global $wpdb;
            $events_table = $this->get_credit_events_table();
            $events_table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $events_table));
            if ($events_table_exists === $events_table) {
                $week_start = wp_date('Y-m-d 00:00:00', strtotime('monday this week', current_time('timestamp')));
                $used = (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COALESCE(SUM(credits), 0) FROM {$events_table}
                     WHERE user_id = %d
                     AND event_type = %s
                     AND created_at >= %s",
                    $user_id,
                    'message_email',
                    $week_start
                ));
            }
        }

        $percent = $limit > 0 ? min(100, (int) round(($used / $limit) * 100)) : 0;

        return [
            'plan_name' => $plan['name'] ?? '',
            'plan_slug' => $plan['slug'] ?? '',
            'limit' => $limit,
            'used' => $used,
            'remaining' => $limit > 0 ? max(0, $limit - $used) : 0,
            'percent' => $percent,
            'has_plan' => !empty($plan),
        ];
    }

    private function get_apply_all_credit_summary($user_id)
    {
        $user_id = absint($user_id);
        $plan = $user_id ? $this->get_user_apply_all_plan($user_id) : null;
        $limit = $plan ? max(0, (int) ($plan['matches_per_week'] ?? 0)) : 0;
        $used = 0;

        if ($user_id) {
            global $wpdb;
            $table = $this->get_linkedin_intro_queue_table();
            $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table));
            if ($table_exists === $table) {
                $columns = $wpdb->get_col("SHOW COLUMNS FROM {$table}");
                if (in_array('source_action', $columns, true) && in_array('queue_status', $columns, true) && in_array('created_at', $columns, true)) {
                    $week_start = wp_date('Y-m-d 00:00:00', strtotime('monday this week', current_time('timestamp')));
                    $used = (int) $wpdb->get_var($wpdb->prepare(
                        "SELECT COUNT(*) FROM {$table}
                         WHERE user_id = %d
                         AND source_action = 'kanban_drag'
                         AND (queue_status IS NULL OR queue_status != 'cancelled')
                         AND created_at >= %s",
                        $user_id,
                        $week_start
                    ));
                }
            }
        }

        if ($user_id) {
            global $wpdb;
            $events_table = $this->get_credit_events_table();
            $events_table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $events_table));
            if ($events_table_exists === $events_table) {
                $week_start = wp_date('Y-m-d 00:00:00', strtotime('monday this week', current_time('timestamp')));
                $used += (int) $wpdb->get_var($wpdb->prepare(
                    "SELECT COALESCE(SUM(credits), 0) FROM {$events_table}
                     WHERE user_id = %d
                     AND event_type = %s
                     AND created_at >= %s",
                    $user_id,
                    'message_email',
                    $week_start
                ));
            }
        }

        $percent = $limit > 0 ? min(100, (int) round(($used / $limit) * 100)) : 0;

        return [
            'plan_name' => $plan['name'] ?? '',
            'plan_slug' => $plan['slug'] ?? '',
            'limit' => $limit,
            'used' => $used,
            'remaining' => $limit > 0 ? max(0, $limit - $used) : 0,
            'percent' => $percent,
            'has_plan' => !empty($plan),
        ];
    }

