    private function handle_user_application_queue_email($application_id, $user_id)
    {
        global $wpdb;

        $table = $this->get_linkedin_intro_queue_table();
        $columns = $wpdb->get_col("SHOW COLUMNS FROM {$table}");
        if (!in_array('user_queue_confirmation_sent_at', $columns, true) || !in_array('user_queue_digest_sent_at', $columns, true)) {
            return;
        }

        $window_start = wp_date('Y-m-d H:i:s', current_time('timestamp') - (15 * MINUTE_IN_SECONDS));
        $recent_confirmation_id = $wpdb->get_var($wpdb->prepare(
            "SELECT id FROM {$table}
             WHERE user_id = %d
             AND source_action = 'kanban_drag'
             AND queue_status = 'queued'
             AND user_queue_confirmation_sent_at IS NOT NULL
             AND user_queue_confirmation_sent_at >= %s
             ORDER BY user_queue_confirmation_sent_at DESC
             LIMIT 1",
            $user_id,
            $window_start
        ));

        if (!$recent_confirmation_id) {
            $application = $wpdb->get_row($wpdb->prepare(
                "SELECT * FROM {$table} WHERE id = %d AND user_id = %d",
                $application_id,
                $user_id
            ), ARRAY_A);
            if ($application && $this->send_user_application_queue_confirmation($user_id, $application)) {
                $wpdb->update($table, [
                    'user_queue_confirmation_sent_at' => current_time('mysql'),
                ], [
                    'id' => $application_id,
                    'user_id' => $user_id,
                ]);
            }
            return;
        }

        $scheduled_at = current_time('mysql');
        $wpdb->update($table, [
            'user_queue_digest_scheduled_at' => $scheduled_at,
        ], [
            'id' => $application_id,
            'user_id' => $user_id,
        ]);

        if (!wp_next_scheduled('sffc_crm_send_application_queue_digest', [$user_id])) {
            wp_schedule_single_event(time() + (10 * MINUTE_IN_SECONDS), 'sffc_crm_send_application_queue_digest', [$user_id]);
        }
    }

    private function send_user_application_queue_confirmation($user_id, $application)
    {
        $user = get_userdata($user_id);
        if (!$user || empty($user->user_email)) {
