        }

        $role_title = $application['role_title'] ?: __('your matched role', 'senna-finance');
        $company = $application['company_name'] ?: __('the company', 'senna-finance');
        $subject = sprintf(__('Your first application is queued: %s', 'senna-finance'), $role_title);
        $dashboard_url = add_query_arg('tab', 'matches', home_url('/terminal/'));
        $role_url = !empty($application['application_url']) ? $application['application_url'] : '';
        $first_name = $user->first_name ?: $user->display_name;

        $message = '<!doctype html><html><body style="margin:0;padding:0;background:#f6f5f2;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Arial,sans-serif;color:#0f1f18;">'
            . '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f6f5f2;"><tr><td style="padding:28px 16px;">'
            . '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:620px;margin:0 auto;background:#fff;border:1px solid #e6e1d8;border-radius:16px;overflow:hidden;">'
            . '<tr><td style="padding:26px;border-bottom:1px solid #ece7de;">'
            . '<div style="display:inline-block;padding:6px 10px;border-radius:999px;background:#eaf7f1;color:#0d6955;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;">Application queued</div>'
            . '<h1 style="margin:14px 0 8px;color:#0d353e;font-size:25px;line-height:1.2;">' . esc_html($first_name) . ', your first application is queued</h1>'
            . '<p style="margin:0;color:#66736f;font-size:14px;line-height:1.6;">We saved your first matched role in MENA Careers. If you add more roles in the next few minutes, we will send one combined update instead of separate emails.</p>'
            . '</td></tr>'
            . '<tr><td style="padding:22px 26px;">'
            . '<div style="padding:16px;border:1px solid #ece7de;border-radius:14px;background:#faf8f3;">'
            . '<div style="color:#8a8176;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;">Queued role</div>'
            . '<div style="margin-top:7px;color:#0f1f18;font-size:17px;font-weight:800;">' . esc_html($role_title) . '</div>'
            . '<div style="margin-top:4px;color:#66736f;font-size:13px;">' . esc_html($company) . '</div>'
            . '</div>'
            . ($role_url ? '<p style="margin:16px 0 0;"><a href="' . esc_url($role_url) . '" style="color:#0d6955;font-weight:800;text-decoration:none;">View live role</a></p>' : '')
            . '</td></tr>'
            . '<tr><td style="padding:20px 26px;background:#faf8f3;border-top:1px solid #ece7de;text-align:right;">'
            . '<a href="' . esc_url($dashboard_url) . '" style="display:inline-block;background:#0d6955;color:#fff;text-decoration:none;padding:12px 18px;border-radius:10px;font-weight:800;font-size:14px;">Open Applications</a>'
            . '</td></tr>'
            . '</table></td></tr></table></body></html>';

        return $this->send_application_queue_user_email($user->user_email, $subject, $message, [
            'application_id' => (string) ($application['id'] ?? ''),
            'email_type' => 'application_queue_first',
        ]);
    }

    public function send_application_queue_digest($user_id)
    {
        $user_id = absint($user_id);
        if (!$user_id) {
            return;
        }

        $this->ensure_linkedin_intro_queue_table();
        $this->add_application_queue_columns();

        global $wpdb;
        $table = $this->get_linkedin_intro_queue_table();
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT * FROM {$table}
             WHERE user_id = %d
             AND source_action = 'kanban_drag'
             AND queue_status = 'queued'
             AND user_queue_confirmation_sent_at IS NULL
             AND user_queue_digest_sent_at IS NULL
             ORDER BY created_at ASC
             LIMIT 25",
            $user_id
        ), ARRAY_A);

        if (empty($rows)) {
            return;
        }

        if (!$this->send_user_application_queue_digest_email($user_id, $rows)) {
            return;
        }

        $ids = array_map('intval', wp_list_pluck($rows, 'id'));
        if (empty($ids)) {
            return;
        }

        $wpdb->query(
            "UPDATE {$table}
             SET user_queue_digest_sent_at = '" . esc_sql(current_time('mysql')) . "'
             WHERE user_id = " . (int) $user_id . '
             AND id IN (' . implode(',', $ids) . ')'
        );
    }

    private function send_user_application_queue_digest_email($user_id, $applications)
    {
        $user = get_userdata($user_id);
        if (!$user || empty($user->user_email) || empty($applications)) {
            return false;
        }

        $count = count($applications);
        $subject = sprintf(_n('%d more application was added to your queue', '%d more applications were added to your queue', $count, 'senna-finance'), $count);
        $dashboard_url = add_query_arg('tab', 'matches', home_url('/terminal/'));
        $first_name = $user->first_name ?: $user->display_name;
        $items = '';

        foreach ($applications as $application) {
            $role_title = $application['role_title'] ?: __('Matched role', 'senna-finance');
            $company = $application['company_name'] ?: __('Company', 'senna-finance');
            $role_url = !empty($application['application_url']) ? $application['application_url'] : '';
            $items .= '<tr><td style="padding:13px 0;border-bottom:1px solid #f0ece5;">'
                . '<div style="color:#0f1f18;font-size:15px;font-weight:800;">' . esc_html($role_title) . '</div>'
                . '<div style="margin-top:3px;color:#66736f;font-size:13px;">' . esc_html($company) . '</div>'
                . ($role_url ? '<div style="margin-top:6px;"><a href="' . esc_url($role_url) . '" style="color:#0d6955;font-size:13px;font-weight:800;text-decoration:none;">View role</a></div>' : '')
                . '</td></tr>';
        }

        $message = '<!doctype html><html><body style="margin:0;padding:0;background:#f6f5f2;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Arial,sans-serif;color:#0f1f18;">'
            . '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f6f5f2;"><tr><td style="padding:28px 16px;">'
            . '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:620px;margin:0 auto;background:#fff;border:1px solid #e6e1d8;border-radius:16px;overflow:hidden;">'
            . '<tr><td style="padding:26px;border-bottom:1px solid #ece7de;">'
            . '<div style="display:inline-block;padding:6px 10px;border-radius:999px;background:#eaf7f1;color:#0d6955;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;">Queue update</div>'
            . '<h1 style="margin:14px 0 8px;color:#0d353e;font-size:25px;line-height:1.2;">' . esc_html($first_name) . ', ' . esc_html(sprintf(_n('%d more role is queued', '%d more roles are queued', $count, 'senna-finance'), $count)) . '</h1>'
            . '<p style="margin:0;color:#66736f;font-size:14px;line-height:1.6;">We grouped your additional Applications updates into one email so your inbox stays clean.</p>'
            . '</td></tr>'
            . '<tr><td style="padding:8px 26px 20px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0">' . $items . '</table></td></tr>'
            . '<tr><td style="padding:20px 26px;background:#faf8f3;border-top:1px solid #ece7de;text-align:right;">'
            . '<a href="' . esc_url($dashboard_url) . '" style="display:inline-block;background:#0d6955;color:#fff;text-decoration:none;padding:12px 18px;border-radius:10px;font-weight:800;font-size:14px;">Open Applications</a>'
            . '</td></tr>'
            . '</table></td></tr></table></body></html>';

        return $this->send_application_queue_user_email($user->user_email, $subject, $message, [
            'user_id' => (string) $user_id,
            'email_type' => 'application_queue_digest',
        ]);
    }

    private function send_application_queue_user_email($recipient_email, $subject, $html_message, array $custom_args = [])
    {
        if (class_exists('SFFC_CRM_SendGrid_Service')) {
            $sendgrid = SFFC_CRM_SendGrid_Service::get_instance();
            if ($sendgrid && $sendgrid->is_configured()) {
                $result = $sendgrid->send_email($subject, $html_message, $recipient_email, null, $custom_args, ['application_queue'], 'application_queue');
                if (!is_wp_error($result)) {
                    return true;
                }
            }
        }

        $headers = function_exists('sffc_crm_build_email_headers')
            ? sffc_crm_build_email_headers('application_queue')
            : ['Content-Type: text/html; charset=UTF-8'];

        return (bool) wp_mail($recipient_email, $subject, $html_message, $headers);
    }

    private function get_linkedin_intro_queue_table()
    {
        global $wpdb;
        return $wpdb->prefix . 'sffc_crm_intro_requests';
    }

    private function get_credit_events_table()
    {
        global $wpdb;
        return $wpdb->prefix . 'sffc_crm_credit_events';
    }

    private function ensure_credit_events_table()
    {
        global $wpdb;
        $table_name = $this->get_credit_events_table();
        $charset_collate = $wpdb->get_charset_collate();
        $sql = "CREATE TABLE {$table_name} (
            id bigint(20) NOT NULL AUTO_INCREMENT,
            user_id bigint(20) NOT NULL,
            event_type varchar(80) NOT NULL,
            post_id bigint(20) DEFAULT 0,
            recruiter_email varchar(255) DEFAULT NULL,
            recruiter_name varchar(255) DEFAULT NULL,
            role_title varchar(255) DEFAULT NULL,
            company_name varchar(255) DEFAULT NULL,
            credits int(11) DEFAULT 1,
            created_at datetime DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            KEY idx_user_event_created (user_id, event_type, created_at),
            KEY idx_recruiter_email (recruiter_email)
        ) {$charset_collate};";

        require_once(ABSPATH . 'wp-admin/includes/upgrade.php');
        dbDelta($sql);
    }

