    private function add_application_queue_columns()
    {
        global $wpdb;

        $table = $this->get_linkedin_intro_queue_table();
        $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table;
        if (!$table_exists) {
            return;
        }

        $columns_to_add = [
            'criteria_id' => "ALTER TABLE `{$table}` ADD COLUMN `criteria_id` bigint(20) DEFAULT NULL AFTER `email_template`",
            'cv_file_id' => "ALTER TABLE `{$table}` ADD COLUMN `cv_file_id` bigint(20) DEFAULT NULL AFTER `criteria_id`",
            'cover_letter_file_id' => "ALTER TABLE `{$table}` ADD COLUMN `cover_letter_file_id` bigint(20) DEFAULT NULL AFTER `cv_file_id`",
            'application_url' => "ALTER TABLE `{$table}` ADD COLUMN `application_url` text DEFAULT NULL AFTER `cover_letter_file_id`",
            'source_action' => "ALTER TABLE `{$table}` ADD COLUMN `source_action` varchar(80) DEFAULT NULL AFTER `application_url`",
            'queue_status' => "ALTER TABLE `{$table}` ADD COLUMN `queue_status` varchar(50) DEFAULT NULL AFTER `source_action`",
            'queue_position' => "ALTER TABLE `{$table}` ADD COLUMN `queue_position` int(11) DEFAULT 0 AFTER `queue_status`",
            'submitted_at' => "ALTER TABLE `{$table}` ADD COLUMN `submitted_at` datetime DEFAULT NULL AFTER `queue_position`",
            'user_queue_confirmation_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `user_queue_confirmation_sent_at` datetime DEFAULT NULL AFTER `submitted_at`",
            'user_queue_digest_scheduled_at' => "ALTER TABLE `{$table}` ADD COLUMN `user_queue_digest_scheduled_at` datetime DEFAULT NULL AFTER `user_queue_confirmation_sent_at`",
            'user_queue_digest_sent_at' => "ALTER TABLE `{$table}` ADD COLUMN `user_queue_digest_sent_at` datetime DEFAULT NULL AFTER `user_queue_digest_scheduled_at`",
        ];

        $existing_columns = $wpdb->get_col("SHOW COLUMNS FROM `{$table}`");
        foreach ($columns_to_add as $column_name => $sql) {
            if (in_array($column_name, $existing_columns, true)) {
                continue;
            }
            $wpdb->query($sql);
            $existing_columns[] = $column_name;
        }

        if (in_array('queue_status', $existing_columns, true) && in_array('source_action', $existing_columns, true)) {
            $wpdb->query("ALTER TABLE `{$table}` ALTER COLUMN `queue_status` SET DEFAULT NULL");
            $wpdb->query("UPDATE `{$table}` SET `queue_status` = NULL WHERE `queue_status` = 'queued' AND (`source_action` IS NULL OR `source_action` = '')");
        }

        $this->maybe_add_application_queue_index($table, 'idx_criteria', 'criteria_id');
        $this->maybe_add_application_queue_index($table, 'idx_queue_status', 'queue_status');
    }

    private function add_intro_campaign_columns()
    {
        global $wpdb;

        $table = $this->get_linkedin_intro_queue_table();
        $table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) === $table;
        if (!$table_exists) {
            return;
        }

        $columns_to_add = [
            'request_type' => "ALTER TABLE `{$table}` ADD COLUMN `request_type` varchar(50) DEFAULT 'intro' AFTER `post_id`",
            'target_role' => "ALTER TABLE `{$table}` ADD COLUMN `target_role` varchar(255) DEFAULT NULL AFTER `request_type`",
            'target_location' => "ALTER TABLE `{$table}` ADD COLUMN `target_location` varchar(255) DEFAULT NULL AFTER `target_role`",
            'target_seniority' => "ALTER TABLE `{$table}` ADD COLUMN `target_seniority` varchar(100) DEFAULT NULL AFTER `target_location`",
            'stored_cv_url' => "ALTER TABLE `{$table}` ADD COLUMN `stored_cv_url` text DEFAULT NULL AFTER `target_seniority`",
            'stored_cv_name' => "ALTER TABLE `{$table}` ADD COLUMN `stored_cv_name` varchar(255) DEFAULT NULL AFTER `stored_cv_url`",
            'target_company' => "ALTER TABLE `{$table}` ADD COLUMN `target_company` varchar(255) DEFAULT NULL AFTER `stored_cv_name`",
            'target_sector' => "ALTER TABLE `{$table}` ADD COLUMN `target_sector` varchar(191) DEFAULT NULL AFTER `target_company`",
            'intro_context' => "ALTER TABLE `{$table}` ADD COLUMN `intro_context` longtext DEFAULT NULL AFTER `target_sector`",
            'reached_recruiters' => "ALTER TABLE `{$table}` ADD COLUMN `reached_recruiters` longtext DEFAULT NULL AFTER `intro_context`",
            'campaign_admin_notes' => "ALTER TABLE `{$table}` ADD COLUMN `campaign_admin_notes` longtext DEFAULT NULL AFTER `reached_recruiters`",
        ];

        $existing_columns = $wpdb->get_col("SHOW COLUMNS FROM `{$table}`");
        foreach ($columns_to_add as $column_name => $sql) {
            if (in_array($column_name, $existing_columns, true)) {
                continue;
            }
            $wpdb->query($sql);
            $existing_columns[] = $column_name;
        }

        if (in_array('request_type', $existing_columns, true)) {
            $wpdb->query("UPDATE `{$table}` SET `request_type` = 'intro' WHERE `request_type` IS NULL OR `request_type` = ''");
        }
    }

    private function maybe_add_application_queue_index($table, $index_name, $column_name)
    {
        global $wpdb;

        $index_exists = $wpdb->get_var($wpdb->prepare(
            "SELECT INDEX_NAME FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = %s AND TABLE_NAME = %s AND INDEX_NAME = %s LIMIT 1",
            DB_NAME,
            $table,
            $index_name
        ));

        if (!$index_exists) {
            $wpdb->query("ALTER TABLE `{$table}` ADD KEY `{$index_name}` (`{$column_name}`)");
        }
    }

