    /**
     * Save "Open to" preferences
     */
    public function save_open_to()
    {
        $user_id = $this->verify_request();
        $open_to_types = isset($_POST['open_to_types']) && is_array($_POST['open_to_types'])
            ? array_map('sanitize_text_field', $_POST['open_to_types'])
            : [];

        if (empty($open_to_types)) {
            wp_send_json_error(['message' => 'Please select at least one option'], 400);
        }

        update_user_meta($user_id, 'sffc_crm_open_to_types', $open_to_types);
        wp_send_json_success(['message' => 'Preferences saved successfully']);
    }

    /**
     * Submit expert request
     */
    public function submit_expert_request()
    {
        $user_id = $this->verify_request();

        $service = isset($_POST['service']) ? sanitize_text_field($_POST['service']) : '';
        $other_details = isset($_POST['other_details']) ? sanitize_textarea_field($_POST['other_details']) : '';

        if (empty($service)) {
            wp_send_json_error(['message' => 'Please select a service'], 400);
        }

        // Validate service type
        $allowed_services = ['hirevue_prep', 'application_help', 'interview_prep', 'other'];
        if (!in_array($service, $allowed_services)) {
            wp_send_json_error(['message' => 'Invalid service type'], 400);
        }

        // If service is "other", ensure details are provided
        if ($service === 'other' && empty($other_details)) {
            wp_send_json_error(['message' => 'Please provide details for your request'], 400);
        }

        // Get user info
        $user = get_userdata($user_id);
        $user_email = $user->user_email;
        $user_name = $user->display_name;

        // Map service to label
        $service_labels = [
            'hirevue_prep' => 'HireVue Prep',
            'application_help' => 'Application Help',
            'interview_prep' => 'Interview Prep',
            'other' => 'Other'
        ];
        $service_label = $service_labels[$service] ?? $service;

        // Store the request
        $requests = get_user_meta($user_id, 'sffc_crm_expert_requests', true) ?: [];
        $requests[] = [
            'service' => $service,
            'service_label' => $service_label,
            'other_details' => $other_details,
            'requested_at' => current_time('mysql'),
            'status' => 'pending'
        ];
        update_user_meta($user_id, 'sffc_crm_expert_requests', $requests);

        // Send notification email to admin
        $admin_email = get_option('admin_email');
        $subject = sprintf('[%s] New Expert Request: %s', get_bloginfo('name'), $service_label);

        $message = sprintf(
            "New expert request from %s (%s)\n\n" .
                "Service: %s\n" .
                "%s" .
                "Requested: %s\n\n" .
                "User Profile: %s",
            $user_name,
            $user_email,
            $service_label,
            ($service === 'other' && !empty($other_details) ? "Details: $other_details\n" : ''),
            current_time('Y-m-d H:i:s'),
            admin_url('user-edit.php?user_id=' . $user_id)
        );

        wp_mail($admin_email, $subject, $message);

        // Send confirmation email to user
        $user_subject = sprintf('[%s] Expert Request Received', get_bloginfo('name'));
        $user_message = sprintf(
            "Hi %s,\n\n" .
                "We've received your request for %s.\n\n" .
                "%s" .
                "Our team will review your request and get back to you within 24-48 hours.\n\n" .
                "Thank you,\n%s Team",
            $user_name,
            $service_label,
            ($service === 'other' && !empty($other_details) ? "Details: $other_details\n\n" : ''),
            get_bloginfo('name')
        );

        wp_mail($user_email, $user_subject, $user_message);

        wp_send_json_success(['message' => 'Expert request submitted successfully']);
    }

    public function review_email_request()
    {
        if (!is_user_logged_in()) {
            wp_send_json_error([
                'message' => __('Please sign in so our team can review your draft.', 'senna-finance'),
            ], 403);
        }

        $nonce = isset($_POST['nonce']) ? sanitize_text_field(wp_unslash($_POST['nonce'])) : '';
        if (!wp_verify_nonce($nonce, 'sffc_crm_nonce')) {
            wp_send_json_error(['message' => __('Security check failed.', 'senna-finance')]);
        }

        $body = isset($_POST['body']) ? sanitize_textarea_field(wp_unslash($_POST['body'])) : '';
        if (empty($body)) {
            wp_send_json_error(['message' => __('Please include your email draft so we can review it.', 'senna-finance')]);
        }

        $subject_line = isset($_POST['subject']) ? sanitize_text_field(wp_unslash($_POST['subject'])) : '';
        $recruiter_email = isset($_POST['recruiter_email']) ? sanitize_email(wp_unslash($_POST['recruiter_email'])) : '';
        $recruiter_name = isset($_POST['recruiter_name']) ? sanitize_text_field(wp_unslash($_POST['recruiter_name'])) : '';
        $recruiter_title = isset($_POST['recruiter_title']) ? sanitize_text_field(wp_unslash($_POST['recruiter_title'])) : '';
        $company = isset($_POST['company']) ? sanitize_text_field(wp_unslash($_POST['company'])) : '';
        $role = isset($_POST['role']) ? sanitize_text_field(wp_unslash($_POST['role'])) : '';
        $message_type = isset($_POST['message_type']) ? sanitize_text_field(wp_unslash($_POST['message_type'])) : 'manual';

        $user = wp_get_current_user();
        $admin_email = get_option('admin_email');

        if (empty($admin_email) || !is_email($admin_email)) {
            wp_send_json_error(['message' => __('Admin email is not configured yet.', 'senna-finance')]);
        }

        $email_subject = sprintf(
            __('Email assessment requested: %s', 'senna-finance'),
            $role ? $role : ($company ? sprintf(__('Opportunity at %s', 'senna-finance'), $company) : __('CRM outreach', 'senna-finance'))
        );

        $message_lines = [];
        $message_lines[] = sprintf('Assessment request from %s (%s)', $user->display_name, $user->user_email);
        $message_lines[] = sprintf('User ID: %d', $user->ID);
        $message_lines[] = '----------------------------------------';
        if ($company) {
            $message_lines[] = sprintf('Company: %s', $company);
        }
        if ($role) {
            $message_lines[] = sprintf('Role: %s', $role);
        }
        if ($recruiter_name) {
            $message_lines[] = sprintf('Recruiter: %s', $recruiter_name);
        }
        if ($recruiter_title) {
            $message_lines[] = sprintf('Recruiter Title: %s', $recruiter_title);
        }
        if ($recruiter_email) {
            $message_lines[] = sprintf('Recruiter Email: %s', $recruiter_email);
        }
        $message_lines[] = sprintf('Message type: %s', $message_type);
        if ($subject_line) {
            $message_lines[] = sprintf('Suggested Subject: %s', $subject_line);
        }
        $message_lines[] = '';
        $message_lines[] = 'Draft:';
        $message_lines[] = $body;

        $headers = [];
        if ($user->user_email && is_email($user->user_email)) {
            $headers[] = 'Reply-To: ' . $user->user_email;
        }

        wp_mail($admin_email, $email_subject, implode("\n", $message_lines), $headers);

        wp_send_json_success([
            'message' => __('Thanks! A coach will review your email and follow up shortly.', 'senna-finance'),
        ]);
    }

    public function request_post_prep()
    {
        if (!is_user_logged_in()) {
            wp_send_json_error([
                'message' => __('Please sign in to request prep materials.', 'senna-finance'),
            ], 403);
        }

        $nonce = isset($_POST['nonce']) ? sanitize_text_field(wp_unslash($_POST['nonce'])) : '';
        if (!wp_verify_nonce($nonce, 'sffc_crm_nonce')) {
            wp_send_json_error(['message' => __('Security check failed.', 'senna-finance')]);
        }

        $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;
        if (!$post_id) {
            wp_send_json_error(['message' => __('Missing role reference.', 'senna-finance')]);
        }

        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php';
        $post_model = new SFFC_CRM_Post();
        $post = $post_model->get($post_id);

        if (!$post) {
            wp_send_json_error(['message' => __('We could not find that role anymore.', 'senna-finance')]);
        }

        $user = wp_get_current_user();
        $admin_email = get_option('admin_email');
        $role_name = $post['role_title'] ?: ($post['role_display'] ?? __('CRM role', 'senna-finance'));
        $company_name = $post['company'] ?: __('Unknown company', 'senna-finance');
        $recruiter_name = $post['recruiter_name'] ?: __('Unknown recruiter', 'senna-finance');

        $subject = sprintf(__('Prep request: %s @ %s', 'senna-finance'), $role_name, $company_name);

        $message = '';
        $message .= sprintf("User: %s (%s)\n", $user->display_name, $user->user_email);
        $message .= sprintf("User ID: %d\n", $user->ID);
        $message .= "------------------------------\n";
        $message .= sprintf("Role: %s\n", $role_name);
        $message .= sprintf("Company: %s\n", $company_name);
        $message .= sprintf("Recruiter: %s\n", $recruiter_name);
        if (!empty($post['location'])) {
            $message .= sprintf("Location: %s\n", $post['location']);
        }
        if (!empty($post['source_url'])) {
            $message .= sprintf("Source URL: %s\n", $post['source_url']);
        }
        $message .= sprintf("Admin edit link: %s\n", admin_url('admin.php?page=sffc-crm-posts&action=edit&id=' . $post_id));

        wp_mail($admin_email, $subject, $message);

        wp_send_json_success([
            'message' => __('Thanks! Our prep team has been notified.', 'senna-finance'),
        ]);
    }

    /**
     * Handle prep material request from modal
     */
    public function request_prep_materials()
    {
        // Verify nonce
        if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'sffc_ajax_nonce')) {
            wp_send_json_error([
                'message' => __('Security check failed', 'senna-finance')
            ]);
        }

        // Check if user is logged in
        if (!is_user_logged_in()) {
            wp_send_json_error([
                'message' => __('Please log in to request prep materials', 'senna-finance')
            ]);
        }

        // Get user and post data
        $user_id = get_current_user_id();
        $user = wp_get_current_user();
        $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;

        if (!$post_id) {
            wp_send_json_error([
                'message' => __('Invalid post ID', 'senna-finance')
            ]);
        }

        // Get post details from database
        global $wpdb;
        $table_name = $wpdb->prefix . 'sffc_crm_posts';
        $post = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $table_name WHERE id = %d",
            $post_id
        ), ARRAY_A);

        if (!$post) {
            wp_send_json_error([
                'message' => __('Post not found', 'senna-finance')
            ]);
        }

        // Send email to admin
        $admin_email = get_option('admin_email');
        $subject = sprintf('[MENA Careers] Prep Material Request - %s', $post['role_title']);

        $message = sprintf("A user has requested prep materials:\n\n");
        $message .= sprintf("User: %s (%s)\n", $user->display_name, $user->user_email);
        $message .= sprintf("User ID: %d\n\n", $user_id);
        $message .= sprintf("Post: %s\n", $post['role_title']);
        $message .= sprintf("Company: %s\n", $post['company']);
        $message .= sprintf("Post ID: %d\n\n", $post_id);
        $message .= sprintf("Admin edit link: %s\n", admin_url('admin.php?page=sffc-crm-posts&action=edit&id=' . $post_id));

        $sent = wp_mail($admin_email, $subject, $message);

        if (!$sent) {
            wp_send_json_error([
                'message' => __('Failed to send request. Please try again.', 'senna-finance')
            ]);
        }

        wp_send_json_success([
            'message' => __('Request sent! We will send you the prep materials shortly.', 'senna-finance')
        ]);
    }

    /**
     * Handle specific prep material request (CV, Cover Letter, etc.)
     */
    public function request_specific_prep_material()
    {
        // Verify nonce
        if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'sffc_ajax_nonce')) {
            wp_send_json_error([
                'message' => __('Security check failed', 'senna-finance')
            ]);
        }

        // Check if user is logged in
        if (!is_user_logged_in()) {
            wp_send_json_error([
                'message' => __('Please log in to request prep materials', 'senna-finance')
            ]);
        }

        // Get user and post data
        $user_id = get_current_user_id();
        $user = wp_get_current_user();
        $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;
        $material_type = isset($_POST['material_type']) ? sanitize_text_field($_POST['material_type']) : '';
        $material_name = isset($_POST['material_name']) ? sanitize_text_field($_POST['material_name']) : '';

        if (!$post_id || !$material_type || !$material_name) {
            wp_send_json_error([
                'message' => __('Invalid request data', 'senna-finance')
            ]);
        }

        // Get post details from database
        global $wpdb;
        $table_name = $wpdb->prefix . 'sffc_crm_posts';
        $post = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $table_name WHERE id = %d",
            $post_id
        ), ARRAY_A);

        if (!$post) {
            wp_send_json_error([
                'message' => __('Post not found', 'senna-finance')
            ]);
        }

        // Material type labels for email
        $material_labels = [
            'cv_template' => 'CV Template',
            'cover_letter' => 'Cover Letter',
            'interview_questions' => 'Interview Questions',
            'case_study' => 'Mock Case Study'
        ];

        $material_label = isset($material_labels[$material_type]) ? $material_labels[$material_type] : $material_name;

        // Send email to admin
        $admin_email = get_option('admin_email');
        $subject = sprintf('[MENA Careers] Prep Material Request - %s - %s', $material_label, $post['role_title']);

        $message = sprintf("A user has requested a specific prep material:\n\n");
        $message .= sprintf("User: %s (%s)\n", $user->display_name, $user->user_email);
        $message .= sprintf("User ID: %d\n\n", $user_id);
        $message .= sprintf("Requested Material: %s\n", $material_label);
        $message .= sprintf("Material Type: %s\n\n", $material_type);
        $message .= sprintf("Post: %s\n", $post['role_title']);
        $message .= sprintf("Company: %s\n", $post['company']);
        $message .= sprintf("Post ID: %d\n\n", $post_id);
        $message .= sprintf("IMPORTANT: Please send the %s to %s within 24 hours.\n\n", $material_label, $user->user_email);
        $message .= sprintf("Admin edit link: %s\n", admin_url('admin.php?page=sffc-crm-posts&action=edit&id=' . $post_id));

        $sent = wp_mail($admin_email, $subject, $message);

        if (!$sent) {
            wp_send_json_error([
                'message' => __('Failed to send request. Please try again.', 'senna-finance')
            ]);
        }

        wp_send_json_success([
            'message' => sprintf(__('Request sent! You should receive the %s within 24 hours.', 'senna-finance'), $material_label)
        ]);
    }

    public function submit_question()
    {
        // Check for both the specific QA nonce and the general CRM nonce
        $nonce_valid = check_ajax_referer('sffc_crm_submit_question', 'nonce', false) ||
            check_ajax_referer('sffc_crm_nonce', 'nonce', false);

        if (!$nonce_valid) {
            wp_send_json_error([
                'message' => __('Security verification failed.', 'senna-finance')
            ], 403);
        }

        if (!is_user_logged_in()) {
            wp_send_json_error([
                'message' => __('Please sign in to ask the team a question.', 'senna-finance')
            ], 401);
        }

        $question = isset($_POST['question']) ? wp_strip_all_tags(wp_unslash($_POST['question'])) : '';
        $question = trim($question);

        if (strlen($question) < 10) {
            wp_send_json_error([
                'message' => __('Give us a bit more detail so our mentors can help.', 'senna-finance')
            ], 400);
        }

        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-expert-qa.php';
        $model = new SFFC_CRM_Expert_QA();
        $current_user = wp_get_current_user();

        $question_id = $model->create_question([
            'user_id' => $current_user->ID,
            'user_name' => $current_user->display_name ?: $current_user->user_login,
            'user_email' => $current_user->user_email,
            'question' => $question,
        ]);

        if (!$question_id) {
            wp_send_json_error([
                'message' => __('Unable to record your question right now.', 'senna-finance')
            ], 500);
        }

        $admin_email = get_option('admin_email');
        if ($admin_email) {
            $subject = sprintf('[MENA Careers] New CRM Q&A question from %s', $current_user->display_name ?: $current_user->user_login);
            $body = sprintf("A new expert Q&A question has been submitted.%s%s", "\n\n", '');
            $body .= sprintf("Member: %s (%s)\n", $current_user->display_name ?: $current_user->user_login, $current_user->user_email);
            $body .= sprintf("Question ID: %d\n", $question_id);
            $body .= "Question:\n" . $question . "\n\n";
            $body .= sprintf("Answer it here: %s\n", admin_url('admin.php?page=sffc-crm-company-prep&action=qa&qa_action=edit&qa_id=' . $question_id));
            $body .= "\nThanks,\nMENA Careers";
            wp_mail($admin_email, $subject, $body);
        }

        wp_send_json_success([
            'message' => __('Question received. Our mentors will reply shortly.', 'senna-finance'),
            'question_id' => $question_id,
            'display_name' => $current_user->display_name ?: __('You', 'senna-finance'),
            'question' => $question,
        ]);
    }

    public function submit_mentorship_request()
    {
        global $wpdb;

        if (!check_ajax_referer('sffc_crm_nonce', 'nonce', false)) {
            wp_send_json_error([
                'message' => __('Security verification failed.', 'senna-finance')
            ], 403);
        }

        if (!is_user_logged_in()) {
            wp_send_json_error([
                'message' => __('Please sign in to request mentorship.', 'senna-finance')
            ], 401);
        }

        $request_type = isset($_POST['request_type']) ? sanitize_key(wp_unslash($_POST['request_type'])) : '';
        $allowed_types = [
            'mentor_session' => __('Book a Mentor Session', 'senna-finance'),
            'cv_linkedin_review' => __('CV / LinkedIn Review', 'senna-finance'),
            'mock_interview' => __('Mock Interviews', 'senna-finance'),
            'career_plan' => __('Career Plan', 'senna-finance'),
        ];

        if (!isset($allowed_types[$request_type])) {
            wp_send_json_error([
                'message' => __('Choose a mentorship request type.', 'senna-finance')
            ], 400);
        }

        $target_role = isset($_POST['target_role']) ? sanitize_text_field(wp_unslash($_POST['target_role'])) : '';
        $target_location = isset($_POST['target_location']) ? sanitize_text_field(wp_unslash($_POST['target_location'])) : '';
        $linkedin_url = isset($_POST['linkedin_url']) ? esc_url_raw(wp_unslash($_POST['linkedin_url'])) : '';
        $timeline = isset($_POST['timeline']) ? sanitize_text_field(wp_unslash($_POST['timeline'])) : '';
        $details = isset($_POST['details']) ? sanitize_textarea_field(wp_unslash($_POST['details'])) : '';

        if (strlen(trim($details)) < 10) {
            wp_send_json_error([
                'message' => __('Add a few details so our mentors know how to help.', 'senna-finance')
            ], 400);
        }

        $attachment_path = '';
        $attachment_name = '';
        if (!empty($_FILES['cv_file']['name'])) {
            if (!function_exists('wp_handle_upload')) {
                require_once ABSPATH . 'wp-admin/includes/file.php';
            }

            $file = $_FILES['cv_file'];
            $allowed_mimes = [
                'pdf' => 'application/pdf',
                'doc' => 'application/msword',
                'docx' => 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            ];
            $uploaded = wp_handle_upload($file, [
                'test_form' => false,
                'mimes' => $allowed_mimes,
            ]);

            if (!empty($uploaded['error'])) {
                wp_send_json_error([
                    'message' => sprintf(__('Unable to upload CV: %s', 'senna-finance'), $uploaded['error'])
                ], 400);
            }

            $attachment_path = $uploaded['file'] ?? '';
            $attachment_name = basename($attachment_path);
        }

        $user = wp_get_current_user();
        $table_name = $this->ensure_mentorship_sessions_table();
        if ($table_name === '') {
            wp_send_json_error([
                'message' => __('Unable to prepare mentorship booking storage right now.', 'senna-finance')
            ], 500);
        }

        $weekly_limit = (int) apply_filters('sffc_job_match_limit', 1, (int) $user->ID);
        $week_start = wp_date('Y-m-d H:i:s', strtotime('monday this week', current_time('timestamp')));
        $requested_this_week = $weekly_limit < 0 ? 0 : (int) $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$table_name} WHERE user_id = %d AND requested_at >= %s",
            (int) $user->ID,
            $week_start
        ));

        if ($weekly_limit >= 0 && $requested_this_week >= $weekly_limit) {
            wp_send_json_error([
                'message' => sprintf(
                    __('You have used your %d mentorship session request(s) for this week. Upgrade your plan or try again next week.', 'senna-finance'),
                    $weekly_limit
                ),
                'limit' => $weekly_limit,
                'used' => $requested_this_week,
                'remaining' => 0,
            ], 429);
        }

        $admin_email = get_option('admin_email');
        if (empty($admin_email) || !is_email($admin_email)) {
            wp_send_json_error([
                'message' => __('Admin email is not configured yet.', 'senna-finance')
            ], 500);
        }

        $request_label = $allowed_types[$request_type];
        $submitted_at = wp_date(get_option('date_format') . ' ' . get_option('time_format'));
        $reply_to = is_email($user->user_email) ? $user->user_email : '';
        $headers = ['Content-Type: text/html; charset=UTF-8'];
        if ($reply_to) {
            $headers[] = 'Reply-To: ' . sanitize_text_field($user->display_name) . ' <' . $reply_to . '>';
        }

        $inserted = $wpdb->insert(
            $table_name,
            [
                'user_id' => (int) $user->ID,
                'request_type' => $request_type,
                'request_label' => wp_strip_all_tags($request_label),
                'target_role' => $target_role,
                'target_location' => $target_location,
                'linkedin_url' => $linkedin_url,
                'timeline' => $timeline,
                'request_details' => $details,
                'cv_attachment_name' => $attachment_name,
                'cv_attachment_path' => $attachment_path,
                'status' => 'requested',
                'member_plan_limit' => $weekly_limit,
                'requested_at' => current_time('mysql'),
                'updated_at' => current_time('mysql'),
            ],
            [
                '%d',
                '%s',
                '%s',
                '%s',
                '%s',
                '%s',
                '%s',
                '%s',
                '%s',
                '%s',
                '%s',
                '%d',
                '%s',
                '%s',
            ]
        );

        if (!$inserted) {
            wp_send_json_error([
                'message' => __('Unable to save your mentorship request right now.', 'senna-finance')
            ], 500);
        }

        $session_id = (int) $wpdb->insert_id;

        $request_rows = [
            __('Request type', 'senna-finance') => $request_label,
            __('Member', 'senna-finance') => trim($user->display_name . ' (' . $user->user_email . ')'),
            __('User ID', 'senna-finance') => (string) $user->ID,
            __('Target role', 'senna-finance') => $target_role,
            __('Target location', 'senna-finance') => $target_location,
            __('LinkedIn URL', 'senna-finance') => $linkedin_url,
            __('Timeline', 'senna-finance') => $timeline,
            __('CV attachment', 'senna-finance') => $attachment_name,
            __('Session request ID', 'senna-finance') => (string) $session_id,
            __('Submitted', 'senna-finance') => $submitted_at,
        ];

        $admin_subject = sprintf('[MENA Careers] Mentorship request: %s', wp_strip_all_tags($request_label));
        $admin_message = $this->build_mentorship_email_html([
            'eyebrow' => __('New mentorship request', 'senna-finance'),
            'title' => $request_label,
            'intro' => __('A member submitted a mentorship request from the MENA Careers terminal.', 'senna-finance'),
            'rows' => $request_rows,
            'details_label' => __('Member notes', 'senna-finance'),
            'details' => $details,
            'footer' => __('Reply directly to this email to follow up with the member.', 'senna-finance'),
        ]);

        $attachments = $attachment_path ? [$attachment_path] : [];
        $admin_sent = wp_mail($admin_email, $admin_subject, $admin_message, $headers, $attachments);

        if (!$admin_sent) {
            wp_send_json_error([
                'message' => __('Unable to notify the mentorship team right now. Please try again.', 'senna-finance')
            ], 500);
        }

        if ($reply_to) {
            $member_subject = sprintf(__('We received your mentorship request: %s', 'senna-finance'), wp_strip_all_tags($request_label));
            $member_message = $this->build_mentorship_email_html([
                'eyebrow' => __('Mentorship request received', 'senna-finance'),
                'title' => __('Thanks, we have your request.', 'senna-finance'),
                'intro' => __('The MENA Careers team will review your request and follow up with next steps shortly.', 'senna-finance'),
                'rows' => [
                    __('Request type', 'senna-finance') => $request_label,
                    __('Target role', 'senna-finance') => $target_role,
                    __('Target location', 'senna-finance') => $target_location,
                    __('Timeline', 'senna-finance') => $timeline,
                    __('CV attachment', 'senna-finance') => $attachment_name ? __('Received', 'senna-finance') : '',
                    __('Submitted', 'senna-finance') => $submitted_at,
                ],
                'details_label' => __('Your notes', 'senna-finance'),
                'details' => $details,
                'footer' => __('You can reply to this email if you need to add more context.', 'senna-finance'),
            ]);
            wp_mail($reply_to, $member_subject, $member_message, ['Content-Type: text/html; charset=UTF-8']);
        }

        wp_send_json_success([
            'message' => __('Request sent. We emailed you a confirmation and notified the mentorship team.', 'senna-finance'),
            'session_id' => $session_id,
            'limit' => $weekly_limit,
            'used' => $weekly_limit < 0 ? null : $requested_this_week + 1,
            'remaining' => $weekly_limit < 0 ? null : max(0, $weekly_limit - ($requested_this_week + 1)),
        ]);
    }

    private function ensure_mentorship_sessions_table()
    {
        global $wpdb;

        $table_name = $wpdb->prefix . 'sffc_crm_mentorship_sessions';
        if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table_name)) === $table_name) {
            return $table_name;
        }

        if (class_exists('SFFC_CRM_Database_Schema')) {
            SFFC_CRM_Database_Schema::get_instance()->create_mentorship_sessions_table();
        }

        return $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table_name)) === $table_name ? $table_name : '';
    }

