                                continue;
                            } ?>
                            <tr>
                                <td style="width:180px;padding:10px 0;border-bottom:1px solid #edf2f4;color:#607178;font-size:13px;"><?php echo esc_html($label); ?></td>
                                <td style="padding:10px 0;border-bottom:1px solid #edf2f4;color:#102228;font-size:14px;font-weight:600;"><?php echo esc_html($value); ?></td>
