                        <?php endforeach; ?>
                    </table>
                    <?php if (!empty($args['details'])): ?>
                        <div style="margin-top:22px;">
                            <div style="font-size:13px;color:#607178;margin-bottom:8px;"><?php echo esc_html($args['details_label'] ?? 'Details'); ?></div>
                            <div style="background:#f7faf9;border:1px solid #e2ece8;border-radius:12px;padding:16px;color:#17252b;font-size:14px;line-height:1.65;white-space:pre-line;"><?php echo esc_html($args['details']); ?></div>
                        </div>
                    <?php endif; ?>
                    <p style="margin:22px 0 0;color:#607178;font-size:13px;line-height:1.6;"><?php echo esc_html($args['footer'] ?? ''); ?></p>
                </div>
            </div>
        </div>
        <?php
        return ob_get_clean();
    }

    /**
     * Register a new user via AJAX
     */
    public function register_user()
    {
        // Verify nonce
        if (!check_ajax_referer('sffc_crm_signup', 'nonce', false)) {
            wp_send_json_error([
                'message' => __('Security verification failed. Please refresh and try again.', 'senna-finance')
            ]);
        }

        // Get and sanitize input
        $first_name = sanitize_text_field($_POST['first_name'] ?? '');
        $last_name = sanitize_text_field($_POST['last_name'] ?? '');
        $email = sanitize_email($_POST['email'] ?? '');
        $password = $_POST['password'] ?? '';
        $terms = isset($_POST['terms']) && $_POST['terms'] === 'true';

        // Validate input
        if (empty($first_name)) {
            wp_send_json_error([
                'message' => __('First name is required.', 'senna-finance')
            ]);
        }

        if (empty($last_name)) {
            wp_send_json_error([
                'message' => __('Last name is required.', 'senna-finance')
            ]);
        }

        if (empty($email) || !is_email($email)) {
            wp_send_json_error([
                'message' => __('Please enter a valid email address.', 'senna-finance')
            ]);
        }

        if (empty($password) || strlen($password) < 8) {
            wp_send_json_error([
                'message' => __('Password must be at least 8 characters long.', 'senna-finance')
            ]);
        }

        if (!$terms) {
            wp_send_json_error([
                'message' => __('You must agree to the Terms of Service and Privacy Policy.', 'senna-finance')
            ]);
        }

        // Check if email already exists
        if (email_exists($email)) {
            if (class_exists('SFFC_CRM_Shortcodes') && method_exists(SFFC_CRM_Shortcodes::get_instance(), 'stop_membership_signup_reminders')) {
                SFFC_CRM_Shortcodes::get_instance()->stop_membership_signup_reminders($email);
            }

            wp_send_json_success([
                'status' => 'exists',
                'message' => __('This email already has a MENA Careers account. Continue to memberships to choose your plan.', 'senna-finance'),
                'redirect' => home_url('/memberships/'),
            ]);
        }

        if (class_exists('SFFC_CRM_Shortcodes') && method_exists(SFFC_CRM_Shortcodes::get_instance(), 'capture_membership_signup_lead')) {
            SFFC_CRM_Shortcodes::get_instance()->capture_membership_signup_lead([
                'email' => $email,
                'first_name' => $first_name,
                'last_name' => $last_name,
                'source' => 'crm_signup_form',
            ]);
        } else {
            update_option('sffc_membership_signup_lead_' . md5(strtolower($email)), [
                'email' => $email,
                'first_name' => $first_name,
                'last_name' => $last_name,
                'source' => 'crm_signup_form',
                'created_at' => time(),
            ], false);
        }

        wp_send_json_success([
            'status' => 'lead_captured',
            'message' => __('Thanks. Continue to memberships to choose the plan that fits your search.', 'senna-finance'),
            'redirect' => home_url('/memberships/'),
        ]);
    }

    /**
     * Check if user email exists and send new password if found
     */
    public function check_user_email()
    {
        // Verify nonce
        if (!check_ajax_referer('sffc_crm_signup', 'nonce', false)) {
            wp_send_json_error([
                'message' => __('Security verification failed. Please refresh and try again.', 'senna-finance')
            ]);
        }

        // Get and sanitize email
        $email = sanitize_email($_POST['email'] ?? '');

        // Validate email
        if (empty($email) || !is_email($email)) {
            wp_send_json_error([
                'message' => __('Please enter a valid email address.', 'senna-finance')
            ]);
        }

        // Check if user exists
        $user = get_user_by('email', $email);

        if ($user) {
            // User exists - generate new password
            $new_password = wp_generate_password(12, false);
            wp_set_password($new_password, $user->ID);

            // Destroy all sessions for this user (force re-login with new password)
            $sessions = WP_Session_Tokens::get_instance($user->ID);
            $sessions->destroy_all();

            // Build beautiful HTML email using design system
