            $txt3 = '#8c8c8c';
            $bdr = '#ebebeb';
            $amber = '#92400e';

            $logo_url = esc_url('https://media.joinsenna.com/2026/02/senna111-1024x280.png');

            // Icons
            $key_icon = '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="' . $forest . '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 2l-2 2m-7.61 7.61a5.5 5.5 0 1 1-7.778 7.778 5.5 5.5 0 0 1 7.777-7.777zm0 0L15.5 7.5m0 0l3 3L22 7l-3-3m-3.5 3.5L19 4"></path></svg>';
            $clock_icon = '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="' . $txt3 . '" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M12 6v6l4 2"></path></svg>';
            $shield_icon = '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="' . $txt3 . '" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg>';
            $check_icon = '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="' . $txt3 . '" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"></path></svg>';
            $strip_clock = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="' . $amber . '" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M12 6v6l4 2"></path></svg>';

            // Escaped labels
            $welcome_text = esc_html(sprintf(__('Welcome back, %s!', 'senna-finance'), $user_name));
            $headline = esc_html__('Your new password is ready', 'senna-finance');
            $body_text = esc_html__('You requested access to your account. Use this temporary password to log in:', 'senna-finance');
            $cta_label = esc_html__('Log in to MENA Careers', 'senna-finance');
            $expiry_text = esc_html__('This password is temporary', 'senna-finance');
            $sec1 = esc_html__('Change this password after logging in', 'senna-finance');
            $sec2 = esc_html__('Your old password has been disabled', 'senna-finance');
