            // Security rows
            $sec_rows = '';
            $sec_items = [
                [$clock_icon, $sec1],
                [$shield_icon, $sec2],
                [$check_icon, $sec3],
            ];
            foreach ($sec_items as $item) {
                $sec_rows .= '<tr>
  <td width="20" valign="top" style="padding-right:8px;padding-bottom:8px;">
    <div style="width:20px;height:20px;border-radius:10px;background:#f5f5f5;text-align:center;line-height:20px;">' . $item[0] . '</div>
  </td>
  <td style="' . $f . 'font-size:13px;color:' . $txt2 . ';line-height:1.5;padding-bottom:8px;">' . $item[1] . '</td>
</tr>';
            }

            $message = <<<HTML
<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#f4f2ee;padding:24px 0;">
<tr><td align="center">
<table role="presentation" cellpadding="0" cellspacing="0" width="560" style="max-width:560px;background:#ffffff;border-radius:10px;overflow:hidden;{$f}font-size:16px;color:#000;">

  <!-- Header -->
