  <!-- Body -->
  <tr><td style="padding:24px 24px 0;">
    <!-- Key icon -->
    <div style="width:44px;height:44px;border-radius:12px;background:#f0fdf4;border:1px solid #dcfce7;text-align:center;line-height:44px;margin-bottom:16px;">
