    <div style="{$f}font-size:14px;color:{$txt3};margin-bottom:6px;">{$welcome_text}</div>
    <!-- Headline -->
    <div style="{$f}font-size:20px;font-weight:700;color:{$txt1};line-height:1.25;">{$headline}</div>
