    </div>
    <!-- CTA -->
    <div style="margin-top:18px;">
      <a href="{$login_url}" style="display:inline-block;padding:12px 28px;border-radius:999px;background:{$forest};color:#ffffff;{$f}font-size:14px;font-weight:700;text-decoration:none;">{$cta_label}</a>
    </div>
    <!-- Spacing -->
    <div style="height:20px;"></div>
  </td></tr>

  <!-- Divider -->
  <tr><td style="height:1px;background:{$bdr};font-size:0;line-height:0;">&nbsp;</td></tr>

  <!-- Security section -->
  <tr><td style="padding:16px 24px;border-bottom:1px solid {$bdr};">
    <div style="{$f}font-size:12px;font-weight:600;color:{$txt3};letter-spacing:0.04em;text-transform:uppercase;margin-bottom:8px;">SECURITY</div>
    <table role="presentation" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse;">
      {$sec_rows}
    </table>
  </td></tr>

  <!-- Footer -->
  <tr><td style="padding:14px 24px;{$f}font-size:11px;color:{$txt3};line-height:1.6;">
    MENA Careers Finance &middot; support.team@joinsenna.com<br>
    This is an automated security email. Please do not reply.
  </td></tr>

</table>
</td></tr></table>
HTML;

            $subject = __('Your new password - MENA Careers', 'senna-finance');

            $headers = function_exists('sffc_crm_build_email_headers')
                ? sffc_crm_build_email_headers('security')
                : [
                    'Content-Type: text/html; charset=UTF-8',
                    'From: MENA Careers Finance <support.team@joinsenna.com>',
                ];

            $sent = wp_mail($user->user_email, $subject, $message, $headers);

            if ($sent) {
                wp_send_json_success([
                    'exists' => true,
                    'message' => __('Welcome back! A new password has been sent to your email.', 'senna-finance'),
                    'user_name' => $user->first_name ?: $user->display_name
                ]);
            } else {
                wp_send_json_error([
                    'message' => __('Failed to send email. Please try again or contact support.', 'senna-finance')
                ]);
            }
        } else {
            // User doesn't exist - proceed with registration
            wp_send_json_success([
                'exists' => false,
                'message' => __('Email available. Please complete your registration.', 'senna-finance')
            ]);
        }
    }

    /**
     * Console scan matches
     * Scans and returns matches based on user criteria
     */
    public function console_scan_matches()
    {
        global $wpdb;

        $user_id = get_current_user_id();
        $raw_criteria = isset($_POST['criteria']) ? wp_unslash($_POST['criteria']) : [];
        if (is_string($raw_criteria)) {
            $decoded_criteria = json_decode($raw_criteria, true);
            if (is_array($decoded_criteria)) {
                $raw_criteria = $decoded_criteria;
            } else {
                $raw_criteria = [];
            }
        }

        // Normalize criteria from Console criteria cards
        $criteria = [
            'job_title' => '',
            'job_titles' => [],
            'locations' => [],
            'sectors' => [],
            'seniority' => [],
            'recruiter_firms' => [],
            'skills_keywords' => [],
        ];

        // Job title (primary matching field)
        if (!empty($raw_criteria['job_title'])) {
            $criteria['job_title'] = sanitize_text_field($raw_criteria['job_title']);
            $criteria['job_titles'] = array_values(array_filter(array_map('trim', explode(',', $criteria['job_title']))));
        }

        // Location - handle both string (comma-separated) and array formats
        if (!empty($raw_criteria['location'])) {
            if (is_array($raw_criteria['location'])) {
                $criteria['locations'] = array_map('sanitize_text_field', $raw_criteria['location']);
            } else {
                // Parse comma-separated string
                $criteria['locations'] = array_map('trim', array_filter(explode(',', sanitize_text_field($raw_criteria['location']))));
            }
        }

        // Sector
        if (!empty($raw_criteria['sector'])) {
            $criteria['sectors'] = is_array($raw_criteria['sector']) ? array_map('sanitize_text_field', $raw_criteria['sector']) : [];
        }

        // Experience level / seniority
        $raw_seniority = $raw_criteria['experience_level'] ?? ($raw_criteria['seniority'] ?? []);
        if (!empty($raw_seniority)) {
            if (is_array($raw_seniority)) {
                $criteria['seniority'] = array_map('sanitize_text_field', $raw_seniority);
            } else {
                $criteria['seniority'] = array_map('trim', array_filter(explode(',', sanitize_text_field($raw_seniority))));
            }
        }

        // Recruiter firm / agency
        if (!empty($raw_criteria['recruiter_firm'])) {
            if (is_array($raw_criteria['recruiter_firm'])) {
                $criteria['recruiter_firms'] = array_map('sanitize_text_field', $raw_criteria['recruiter_firm']);
            } else {
                $criteria['recruiter_firms'] = array_map('trim', array_filter(explode(',', sanitize_text_field($raw_criteria['recruiter_firm']))));
            }
        }

        // Skills keywords
        if (!empty($raw_criteria['skills_keywords'])) {
            $criteria['skills_keywords'] = is_array($raw_criteria['skills_keywords']) ? array_map('sanitize_text_field', $raw_criteria['skills_keywords']) : [];
        }

        // Use the SAME query structure as get_preference_matches() which works
        // Build query using the same pattern that successfully returns posts
        require_once SFFC_PLUGIN_DIR . 'includes/crm/models/class-crm-post.php';
        $post_model = new SFFC_CRM_Post();

        // Get ALL posts using the model's get_feed method (which works)
        $all_posts = $post_model->get_feed([
            'per_page' => 200,
            'user_id' => $user_id
        ]);

        error_log("Console Scan Posts Fetched from Model: " . count($all_posts));

        if (empty($all_posts)) {
            // Return debug info even when no posts found
            wp_send_json_success([
                'matches' => [],
                'total' => 0,
                'debug' => [
                    'total_posts_fetched' => 0,
                    'total_scored' => 0,
                    'method' => 'Using SFFC_CRM_Post::get_feed() which works in other endpoints',
                    'criteria_used' => $criteria,
                    'table_prefix' => $wpdb->prefix,
                    'table_name' => $wpdb->prefix . 'sffc_crm_posts',
                    'top_10_scores' => [],
                    'message' => 'No posts found using get_feed() model method'
                ]
            ]);
            return;
        }

        // Score and filter posts
        $scored_matches = [];
        $debug_scores = []; // For debugging

        // Determine threshold based on whether job title is provided
        // If no job title, use lower threshold since max possible score without title is ~35
        $has_job_title = !empty($criteria['job_title']);
        $score_threshold = $has_job_title ? 40 : 20;

        foreach ($all_posts as $post) {
            if (!empty($criteria['recruiter_firms'])) {
                $post_firm = strtolower(trim((string) ($post['recruiter_firm'] ?? '')));
                $firm_matched = false;
                foreach ($criteria['recruiter_firms'] as $firm_filter) {
                    $firm_filter = strtolower(trim((string) $firm_filter));
                    if ($firm_filter === '' || strpos($firm_filter, 'all') === 0) {
                        $firm_matched = true;
                        break;
                    }
                    if ($post_firm !== '' && strpos($post_firm, $firm_filter) !== false) {
                        $firm_matched = true;
                        break;
                    }
                }

                if (!$firm_matched) {
                    continue;
                }
            }

            $score_data = $this->calculate_console_match_score($post, $criteria);
            if (count($criteria['job_titles']) > 1) {
                foreach ($criteria['job_titles'] as $criteria_title) {
                    $criteria_variant = $criteria;
                    $criteria_variant['job_title'] = $criteria_title;
                    $variant_score_data = $this->calculate_console_match_score($post, $criteria_variant);
                    if ((int) ($variant_score_data['score'] ?? 0) > (int) ($score_data['score'] ?? 0)) {
                        $score_data = $variant_score_data;
                    }
                }
            }
            $score = $score_data['score'];

            // Debug: collect all scores
            $debug_scores[] = [
                'title' => $post['role_title'],
                'score' => $score,
                'reasons' => $score_data['reasons']
            ];

            // FIX: Use dynamic threshold - lower when no job title specified
            if ($score < $score_threshold) {
                continue;
            }

            // Build URL for the match
            $match_url = $this->resolve_recommended_post_public_permalink($post);
            $internal_permalink = $this->resolve_recommended_post_internal_permalink($post);
            $apply_url = $this->normalize_recommended_post_fallback_url($post['application_url'] ?? '', $post);

            // Calculate has_recruiter based on recruiter_id presence
            $has_recruiter = !empty($post['recruiter_id']) && !empty($post['recruiter_name']);

            $scored_matches[] = [
                'id' => $post['id'],
                'jobs_post_id' => $post['jobs_post_id'] ?? 0,
                'wp_post_id' => $post['wp_post_id'] ?? 0,
                'role_title' => $post['role_title'],
                'company' => $post['company'],
                'location' => $post['location'] ?: $post['location_city'],
                'location_city' => $post['location_city'],
                'location_country' => $post['location_country'],
                'seniority' => $post['seniority'] ?? '',
                'sector' => $post['sector'] ?? '',
                'salary_text' => $post['salary_text'] ?? '',
                'salary_min' => isset($post['salary_min']) ? (int) $post['salary_min'] : null,
                'salary_max' => isset($post['salary_max']) ? (int) $post['salary_max'] : null,
                'salary_currency' => $post['salary_currency'] ?? '',
                'detected_years' => (int) $detected_years,
                'keywords' => $post['keywords'] ?? [],
                'skills_mentioned' => $post['skills_mentioned'] ?? [],
                'posted_at' => $post['posted_at'],
                'closing_date' => $post['closing_date'] ?? '',
                'content' => $post['content'] ?? '',
                'content_snippet' => $post['content_snippet'] ?? '',
                'company_logo' => $post['company_logo'],
                'has_recruiter' => $has_recruiter,
                'recruiter_id' => $post['recruiter_id'] ?? 0,
                'recruiter_name' => $post['recruiter_name'] ?? '',
                'recruiter_title' => $post['recruiter_title'] ?? '',
                'recruiter_photo' => $post['recruiter_photo'] ?? '',
                'recruiter_firm' => $post['recruiter_firm'] ?? '',
                'recruiter_linkedin' => $post['recruiter_linkedin'] ?? '',
                'recruiter_email' => $post['recruiter_email'] ?? '',
                'match_score' => $score,
                'reasons' => $score_data['reasons'],
                'insight' => $score_data['insight'],
                'jobseeker_notes' => $score_data['jobseeker_notes'] ?? null,
                'internal_permalink' => $internal_permalink,
                'permalink' => $match_url,
                'url' => $match_url,
                'apply_url' => $apply_url !== '' ? $apply_url : $match_url,
                'application_url' => $post['application_url'] ?? '',
                'source_url' => $post['source_url'] ?? '',
            ];
        }

        // Sort by score descending
        usort($scored_matches, function ($a, $b) {
            return $b['match_score'] - $a['match_score'];
        });

        // Check which matches have existing intro requests
        $this->ensure_linkedin_intro_queue_table();
        $intro_table = $this->get_linkedin_intro_queue_table();

        // Get all recruiter IDs from matches
        $recruiter_ids = array_filter(array_unique(array_column($scored_matches, 'recruiter_id')));

        if (!empty($recruiter_ids)) {
            $placeholders = implode(',', array_fill(0, count($recruiter_ids), '%d'));
            $query_params = array_merge([$user_id], $recruiter_ids);

            $intro_requests = $wpdb->get_results($wpdb->prepare(
                "SELECT DISTINCT recruiter_id
                FROM {$intro_table}
                WHERE user_id = %d
                AND recruiter_id IN ($placeholders)
                AND status NOT IN ('cancelled', 'rejected', 'expired')",
                ...$query_params
            ), ARRAY_A);

            $requested_recruiter_ids = array_column($intro_requests, 'recruiter_id');

            // Mark matches with intro_requested flag
            foreach ($scored_matches as &$match) {
                if (!empty($match['recruiter_id']) && in_array($match['recruiter_id'], $requested_recruiter_ids)) {
                    $match['intro_requested'] = true;
                } else {
                    $match['intro_requested'] = false;
                }
            }
            unset($match);
        } else {
            // No recruiters in matches, mark all as not requested
            foreach ($scored_matches as &$match) {
                $match['intro_requested'] = false;
            }
            unset($match);
        }

        if ($user_id && !empty($scored_matches)) {
            $console_items_table = $wpdb->prefix . 'sffc_crm_console_list_items';
            $console_items_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($console_items_table))) === $console_items_table;
            if ($console_items_exists) {
                $post_ids = array_filter(array_unique(array_map('absint', array_column($scored_matches, 'id'))));
                if (!empty($post_ids)) {
                    $placeholders = implode(',', array_fill(0, count($post_ids), '%d'));
                    $saved_post_ids = $wpdb->get_col($wpdb->prepare(
                        "SELECT DISTINCT post_id
                         FROM {$console_items_table}
                         WHERE user_id = %d
                         AND post_id IN ($placeholders)",
                        ...array_merge([$user_id], $post_ids)
                    ));
                    $saved_post_ids = array_map('intval', $saved_post_ids);
                    foreach ($scored_matches as &$match) {
                        $match['added_to_list'] = in_array((int) $match['id'], $saved_post_ids, true);
                    }
                    unset($match);
                }
            }

            $application_pack_table = $this->get_application_pack_table();
            $application_pack_table_exists = $wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $wpdb->esc_like($application_pack_table))) === $application_pack_table;
            if ($application_pack_table_exists) {
                $post_ids = array_filter(array_unique(array_map('absint', array_column($scored_matches, 'id'))));
                if (!empty($post_ids)) {
                    $placeholders = implode(',', array_fill(0, count($post_ids), '%d'));
                    $requested_post_ids = $wpdb->get_col($wpdb->prepare(
                        "SELECT DISTINCT post_id
                         FROM {$application_pack_table}
                         WHERE user_id = %d
                         AND post_id IN ($placeholders)
                         AND status IN ('requested', 'preparing', 'delivered')",
                        ...array_merge([$user_id], $post_ids)
                    ));
                    $requested_post_ids = array_map('intval', $requested_post_ids);
                    foreach ($scored_matches as &$match) {
                        $match['application_requested'] = in_array((int) $match['id'], $requested_post_ids, true);
                    }
                    unset($match);
                }
            }
        }

        foreach ($scored_matches as &$match) {
            if (!isset($match['application_requested'])) {
                $match['application_requested'] = false;
            }
        }
        unset($match);

        // Add debug info
        $response = [
            'matches' => array_slice($scored_matches, 0, 100),
            'total' => count($scored_matches),
            'debug' => [
                'total_posts_fetched' => count($all_posts),
                'total_scored' => count($debug_scores),
                'method' => 'Using SFFC_CRM_Post::get_feed() - same as working endpoints',
                'criteria_used' => $criteria,
                'top_10_scores' => array_slice($debug_scores, 0, 10),
                'intro_requests_checked' => !empty($recruiter_ids) ? count($requested_recruiter_ids) : 0
            ]
        ];

        wp_send_json_success($response);
    }

    /**
     * Calculate console match score with proper job title matching logic
     *
     * Scoring:
     * - 100% = Exact job title match (e.g., "compliance manager") + location match
     * - 90%  = Partial job title match (e.g., "compliance" but not "manager")
     * - 70%  = Related keywords match (KYC, Risk, AML, Transaction Monitoring, etc.)
     * - 65%  = Other criteria match (sector, seniority, recency)
     */
    private function calculate_console_match_score($post, $criteria)
    {
        $role_title_raw = strtolower(trim($post['role_title'] ?? ''));
        $criteria_title_raw = strtolower(trim($criteria['job_title'] ?? ''));

        $role_title = $this->normalize_job_text($role_title_raw);
        $criteria_title = $this->normalize_job_text($criteria_title_raw);

        $post_location = strtolower(trim(
            ($post['location'] ?? '') . ' ' .
                ($post['location_city'] ?? '') . ' ' .
                ($post['location_country'] ?? '')
        ));

        $score = 0;
        $reasons = [];
        $insight = '';

        $title_score = 0;
        $title_match_type = 'none';
        $location_matched = false;

        // =========================
        // 1. TITLE MATCHING (dominant factor)
        // =========================
        if (!empty($criteria_title)) {
            $criteria_tokens = $this->tokenize_job_text($criteria_title);
            $role_tokens = $this->tokenize_job_text($role_title);

            $generic_words = [
                'analyst',
                'associate',
                'manager',
                'director',
                'head',
                'lead',
                'senior',
                'junior',
                'vp',
                'avp',
                'officer',
                'specialist',
                'executive'
            ];

            $criteria_core_tokens = array_values(array_filter($criteria_tokens, function ($token) use ($generic_words) {
                return !in_array($token, $generic_words, true);
            }));

            $matched_all_tokens = count(array_diff($criteria_tokens, $role_tokens)) === 0;
            $matched_core_tokens = !empty($criteria_core_tokens) && count(array_diff($criteria_core_tokens, $role_tokens)) === 0;
            $core_overlap_count = count(array_intersect($criteria_core_tokens, $role_tokens));
            $token_overlap_count = count(array_intersect($criteria_tokens, $role_tokens));

            $related_keywords = $this->get_related_keywords($criteria_title_raw);
            $related_match_count = 0;
            foreach ($related_keywords as $keyword) {
                $keyword_norm = $this->normalize_job_text($keyword);
                if ($keyword_norm !== '' && strpos($role_title, $keyword_norm) !== false) {
                    $related_match_count++;
                }
            }

            // Exact normalized phrase
            if ($role_title === $criteria_title) {
                $title_score = 62;
                $title_match_type = 'exact_title';
                $reasons[] = __('Exact Role Match', 'senna-finance');
            }
            // Full phrase contained
            elseif (strpos($role_title, $criteria_title) !== false) {
                $title_score = 56;
                $title_match_type = 'contained_title';
                $reasons[] = __('Very Close Title Match', 'senna-finance');
            }
            // All tokens matched, reordered or expanded
            elseif ($matched_all_tokens && count($criteria_tokens) >= 2) {
                $title_score = 50;
                $title_match_type = 'all_tokens';
                $reasons[] = __('Strong Title Match', 'senna-finance');
            }
            // All meaningful/core tokens matched
            elseif ($matched_core_tokens) {
                $title_score = 44;
                $title_match_type = 'core_title';
                $reasons[] = __('Function Match', 'senna-finance');
            }
            // Strong keyword adjacency
            elseif ($core_overlap_count >= 2) {
                $title_score = 36;
                $title_match_type = 'adjacent_title';
                $reasons[] = __('Adjacent Role Match', 'senna-finance');
            }
            // One core token plus strong related ecosystem
            elseif ($core_overlap_count >= 1 && $related_match_count >= 2) {
                $title_score = 30;
                $title_match_type = 'specialist_related';
                $reasons[] = __('Specialist Match', 'senna-finance');
            }
            // Related keyword cluster only
            elseif ($related_match_count >= 2) {
                $title_score = 24;
                $title_match_type = 'related_keywords';
                $reasons[] = __('Related Function', 'senna-finance');
            }
            // Weak generic overlap only
            elseif ($token_overlap_count >= 1) {
                $title_score = 8;
                $title_match_type = 'weak_overlap';
                $reasons[] = __('Loose Title Overlap', 'senna-finance');
            } else {
                return [
                    'score' => 0,
                    'reasons' => [__('No Meaningful Title Match', 'senna-finance')],
                    'insight' => __('Not Relevant', 'senna-finance'),
                    'jobseeker_notes' => $post['jobseeker_notes'] ?? null,
                ];
            }

            // Penalize generic-only matches
            if ($title_match_type === 'weak_overlap') {
                $score -= 10;
            }

            $score += $title_score;
        } else {
            // FIX: If no job title specified, give base score so other criteria can still match
            // This allows location/sector/seniority-only searches to work
            $score += 25; // Base score when no title filter
            $reasons[] = __('Matches Other Criteria', 'senna-finance');
        }

        // =========================
        // 2. LOCATION
        // =========================
        if (!empty($criteria['locations']) && is_array($criteria['locations'])) {
            foreach ($criteria['locations'] as $loc) {
                $loc = strtolower(trim($loc));
                if ($loc !== '' && strpos($post_location, $loc) !== false) {
                    $location_matched = true;
                    $score += 12;
                    $reasons[] = sprintf(__('%s Location', 'senna-finance'), ucfirst($loc));
                    break;
                }
            }
        }

        // =========================
        // 3. SECTOR
        // =========================
        if (!empty($criteria['sectors']) && !empty($post['sector'])) {
            if (in_array($post['sector'], $criteria['sectors'], true)) {
                $score += 8;
                $reasons[] = __('Sector Match', 'senna-finance');
            }
        }

        // =========================
        // 4. SENIORITY
        // =========================
        if (!empty($criteria['seniority']) && !empty($post['seniority'])) {
            if (in_array($post['seniority'], $criteria['seniority'], true)) {
                $score += 7;
                $reasons[] = __('Seniority Match', 'senna-finance');
            }
        }

        // =========================
        // 5. RECENCY
        // =========================
        if (!empty($post['posted_at'])) {
            $posted_time = strtotime($post['posted_at']);
            if ($posted_time) {
                $days_old = (time() - $posted_time) / 86400;

                if ($days_old <= 2) {
                    $score += 5;
                    $reasons[] = __('Just Posted', 'senna-finance');
                } elseif ($days_old <= 7) {
                    $score += 3;
                } elseif ($days_old > 30) {
                    $score -= 3;
                }
            }
        }

        // =========================
        // 6. RECRUITER SIGNAL
        // =========================
        if (!empty($post['recruiter_name']) || !empty($post['has_recruiter'])) {
            $score += 2;
        }

        // =========================
        // 7. COMBINATION BONUSES
        // =========================
        if (in_array($title_match_type, ['exact_title', 'contained_title', 'all_tokens'], true) && $location_matched) {
            $score += 8;
        }

        if (in_array($title_match_type, ['core_title', 'adjacent_title'], true) && $location_matched) {
            $score += 4;
        }

        // Prevent weak title matches from looking too good
        if ($title_match_type === 'weak_overlap' && $score > 58) {
            $score = 58;
        }

        // Prevent related-only matches from becoming “perfect”
        if (in_array($title_match_type, ['related_keywords', 'specialist_related'], true) && $score > 74) {
            $score = 74;
        }

        $score = max(0, min(100, $score));

        // =========================
        // 8. INSIGHT LABELS
        // =========================
        if (!empty($post['response_badge'])) {
            $insight = $post['response_badge'];
        } else {
            if ($title_match_type === 'exact_title' && $location_matched && $score >= 85) {
                $insight = __('Perfect Match', 'senna-finance');
            } elseif (in_array($title_match_type, ['exact_title', 'contained_title', 'all_tokens'], true) && $score >= 78) {
                $insight = __('Exact Function Match', 'senna-finance');
            } elseif ($title_match_type === 'core_title' && $score >= 72) {
                $insight = __('Strong Functional Match', 'senna-finance');
            } elseif (in_array($title_match_type, ['adjacent_title', 'specialist_related'], true) && $score >= 64) {
                $insight = __('Strong Adjacent Match', 'senna-finance');
            } elseif ($title_match_type === 'related_keywords' && $score >= 55) {
                $insight = __('Specialist Match', 'senna-finance');
            } elseif ($title_match_type === 'weak_overlap') {
                $insight = __('Broad Match', 'senna-finance');
            } elseif ($score >= 60) {
                $insight = __('Worth Reviewing', 'senna-finance');
            } else {
                $insight = __('Stretch Match', 'senna-finance');
            }
        }

        return [
            'score' => $score,
            'reasons' => array_slice(array_values(array_unique($reasons)), 0, 4),
            'insight' => $insight,
            'jobseeker_notes' => $post['jobseeker_notes'] ?? null,
        ];
    }

    private function normalize_job_text($text)
    {
        $text = strtolower(trim($text));
        $text = str_replace(['&', '/', '-', ',', '(', ')'], ' ', $text);
        $text = preg_replace('/\s+/', ' ', $text);

        $replacements = [
            'fp&a' => 'financial planning analysis',
            'm&a' => 'mergers acquisitions',
            'aml' => 'anti money laundering',
            'kyc' => 'know your customer',
            'ecm' => 'equity capital markets',
            'dcm' => 'debt capital markets',
            'levfin' => 'leveraged finance',
            'equity research' => 'equity research',
            'investment banking' => 'investment banking',
        ];

        foreach ($replacements as $from => $to) {
            $text = str_replace($from, $to, $text);
        }

        return trim(preg_replace('/\s+/', ' ', $text));
    }

    private function tokenize_job_text($text)
    {
        $tokens = array_filter(explode(' ', $text));

        $stopwords = [
            'the',
            'and',
            'of',
            'for',
            'to',
            'in',
            'at',
            'on',
            'with'
        ];

        $tokens = array_values(array_filter($tokens, function ($token) use ($stopwords) {
            return strlen($token) > 1 && !in_array($token, $stopwords, true);
        }));

        return array_values(array_unique($tokens));
    }
    private function get_related_keywords($job_title)
    {
        $job_title = strtolower(trim($job_title));
        $related = [];

        // Normalize punctuation for easier matching
        $normalized = str_replace(['/', '-', '&', ',', '(', ')'], ' ', $job_title);
        $normalized = preg_replace('/\s+/', ' ', $normalized);

        // Helper: detect whether any term exists in the title
        $contains_any = function ($terms) use ($normalized) {
            foreach ($terms as $term) {
                if (strpos($normalized, strtolower($term)) !== false) {
                    return true;
                }
            }
            return false;
        };

        // Category triggers + keyword banks
        $category_map = [

            'compliance_fincrime' => [
                'triggers' => [
                    'compliance',
                    'kyc',
                    'aml',
                    'cdd',
                    'edd',
                    'fcc',
                    'financial crime',
                    'sanctions',
                    'screening',
                    'transaction monitoring',
                    'fraud',
                    'abc',
                    'anti bribery',
                    'corruption',
                    'mlro',
                    'regulatory compliance'
                ],
                'keywords' => [
                    'compliance',
                    'regulatory compliance',
                    'financial crime',
                    'financial crime compliance',
                    'kyc',
                    'aml',
                    'cdd',
                    'edd',
                    'onboarding',
                    'client onboarding',
                    'customer due diligence',
                    'enhanced due diligence',
                    'transaction monitoring',
                    'name screening',
                    'sanctions',
                    'pep screening',
                    'adverse media',
                    'anti-money laundering',
