            if ($contains_any($config['triggers'])) {
                $related = array_merge($related, $config['keywords']);
            }
        }

        // Extra title-specific expansions
        if ($contains_any(['analyst'])) {
            $related = array_merge($related, [
                'analyst',
                'analysis',
                'modelling',
                'reporting',
                'excel'
            ]);
        }

        if ($contains_any(['associate'])) {
            $related = array_merge($related, [
                'associate',
                'execution',
                'client management'
            ]);
        }

        if ($contains_any(['manager', 'senior manager', 'head', 'director', 'vp', 'vice president'])) {
            $related = array_merge($related, [
                'manager',
                'leadership',
                'stakeholder management',
                'team management',
                'strategy',
                'oversight'
            ]);
        }

        // Fallback: if nothing matched, use generic finance/business terms
        if (empty($related)) {
            $related = [
                'finance',
                'financial',
                'analysis',
                'reporting',
                'operations',
                'risk',
                'compliance',
                'accounting',
                'data',
                'strategy'
            ];
        }

        return array_values(array_unique($related));
